import React from "react";
import classNames from "classnames/bind";
import { resolveApprovalSlaState } from "config/approval-sla.utils";

export default function UniversalApprovalSlaBadge({ item }) {
  const sla = resolveApprovalSlaState(item);
  if (!sla.bucket) {
    return null;
  }

  return (
    <span
      className={classNames("lux-appr-sla-badge", sla.tone && `is-${sla.tone}`)}
      title={`SLA: ${sla.label}`}
    >
      {sla.label}
    </span>
  );
}
