import classNames from "classnames/bind";
import React, { Component } from "react";
import { validationUtils } from "_helpers";
import {
  addHoursToTimeValue,
  buildDefaultMarkForm,
  buildMarkFormFromAttendanceItem,
  buildAttendanceMarkPayload,
  getDayMeta,
} from "./attendance.utils";

class AttendanceMarkPopover extends Component {
  constructor(props) {
    super(props);
    this.state = {
      startTime: "09:00",
      hours: "8",
      checkoutTime: "17:00",
      checkoutAuto: true,
    };
  }

  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
    this.syncForm(this.props);
  }

  componentDidUpdate(prevProps) {
    if (
      this.props.show !== prevProps.show ||
      this.props.markDate !== prevProps.markDate ||
      this.props.employeeId !== prevProps.employeeId ||
      this.props.existingItem !== prevProps.existingItem
    ) {
      this.syncForm(this.props);
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  syncForm = (props) => {
    if (!props.show || !props.markDate) return;
    const defaults = props.existingItem
      ? buildMarkFormFromAttendanceItem(props.existingItem, props.markDate)
      : buildDefaultMarkForm(props.markDate);
    this.setState(defaults);
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.props.onClose();
    }
  };

  onStartTimeChange = (value) => {
    this.setState((prevState) => {
      const next = { startTime: value };
      if (prevState.checkoutAuto && prevState.hours) {
        next.checkoutTime = addHoursToTimeValue(value, prevState.hours);
      }
      return next;
    });
  };

  onHoursChange = (value) => {
    if (value !== "" && !validationUtils.validateDecimalNumberic(value)) return;
    this.setState((prevState) => ({
      hours: value,
      checkoutAuto: true,
      checkoutTime:
        value !== "" ? addHoursToTimeValue(prevState.startTime, value) : prevState.checkoutTime,
    }));
  };

  onCheckoutChange = (value) => {
    this.setState({ checkoutTime: value, checkoutAuto: false });
  };

  handleSubmit = (event) => {
    event.preventDefault();
    const { markDate, onSubmit } = this.props;
    const { startTime, hours, checkoutTime } = this.state;
    if (!markDate || !startTime) return;

    onSubmit(
      buildAttendanceMarkPayload(markDate, {
        startTime,
        hours,
        checkoutTime,
      })
    );
  };

  render() {
    const { show, employeeName, markDate, onClose, isLoading } = this.props;
    if (!show || !markDate) return null;

    const meta = getDayMeta(markDate);
    const { startTime, hours, checkoutTime } = this.state;

    return (
      <>
        <button
          type="button"
          className="lux-att-mark-popover__backdrop"
          aria-label="Close mark attendance"
          onClick={onClose}
        />
        <div
          className="lux-att-mark-popover"
          role="dialog"
          aria-modal="true"
          aria-labelledby="lux-att-mark-popover-title"
        >
          <header className="lux-att-mark-popover__head">
            <div>
              <span className="lux-att-mark-popover__eyebrow">Mark attendance</span>
              <h2 id="lux-att-mark-popover-title">{employeeName || "Employee"}</h2>
              <p>
                {markDate.format("dddd, MMMM D, YYYY")}
                {meta.isToday && <span className="lux-att-mark-popover__today">Today</span>}
                {meta.isWeekend && (
                  <span className="lux-att-mark-popover__optional">Optional day</span>
                )}
              </p>
            </div>
            <button type="button" className="lux-att-mark-popover__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-att-mark-popover__body" onSubmit={this.handleSubmit}>
            <div className="lux-att-mark-popover__intro">
              <i className="fe fe-clock" aria-hidden="true" />
              <span>Record when work started, hours logged, and checkout time for this day.</span>
            </div>

            <div className="lux-att-mark-popover__grid">
              <label className="lux-att-mark-popover__field is-highlight">
                <span>Start time</span>
                <input
                  type="time"
                  className="lux-att-mark-popover__input"
                  value={startTime}
                  required
                  onChange={(e) => this.onStartTimeChange(e.target.value)}
                />
                <em>Check-in / mark time</em>
              </label>

              <label className="lux-att-mark-popover__field is-highlight">
                <span>Hours</span>
                <input
                  type="number"
                  className="lux-att-mark-popover__input"
                  min={0}
                  max={24}
                  step={0.5}
                  placeholder="8"
                  value={hours}
                  onChange={(e) => this.onHoursChange(e.target.value)}
                />
                <em>Total hours worked</em>
              </label>

              <label className="lux-att-mark-popover__field is-highlight is-wide">
                <span>Checkout time</span>
                <input
                  type="time"
                  className="lux-att-mark-popover__input"
                  value={checkoutTime}
                  onChange={(e) => this.onCheckoutChange(e.target.value)}
                />
                <em>End of day — auto-updates when hours change</em>
              </label>
            </div>

            <footer className="lux-att-mark-popover__foot">
              <button type="button" className="lux-att-mark-popover__btn" onClick={onClose} disabled={isLoading}>
                Cancel
              </button>
              <button
                type="submit"
                className={classNames("lux-att-mark-popover__btn is-primary", { "is-loading": isLoading })}
                disabled={isLoading || !startTime}
              >
                <i className="fe fe-check" aria-hidden="true" />
                Save attendance
              </button>
            </footer>
          </form>
        </div>
      </>
    );
  }
}

export default AttendanceMarkPopover;
