import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";
import { AdminInsightStrip, AdminQuickNav } from "views/admin/components/AdminLuxShared";
import LuxActionButton from "views/common/lux/LuxActionButton";

export const BENEFITS_QUICK_LINKS = [
  {
    path: "/benefits/plans",
    label: "Plans",
    desc: "Medical, dental, vision catalog",
    icon: "fe fe-heart",
    tone: "green",
  },
  {
    path: "/benefits/enrollment",
    label: "Enrollment",
    desc: "Coverage and deduction mapping",
    icon: "fe fe-user-check",
    tone: "indigo",
  },
  {
    path: "/benefits/carrier-files",
    label: "Carrier files",
    desc: "File-based export and ack",
    icon: "fe fe-file-text",
    tone: "amber",
  },
  {
    path: "/benefits/reports",
    label: "Reports",
    desc: "Plan and enrollment aggregates",
    icon: "fe fe-bar-chart-2",
    tone: "blue",
  },
];

const STATUS_TONES = {
  ACTIVE: "green",
  APPROVED: "green",
  ACKNOWLEDGED: "green",
  GENERATED: "blue",
  SUBMITTED: "indigo",
  DRAFT: "slate",
  MANUAL_PENDING: "amber",
  REJECTED: "rose",
  INACTIVE: "slate",
  TRUE: "green",
  FALSE: "slate",
};

export function getBenefitsStatusTone(status) {
  if (status === true) return "green";
  if (status === false) return "slate";
  const key = String(status || "")
    .trim()
    .toUpperCase()
    .replace(/\s+/g, "_");
  return STATUS_TONES[key] || "slate";
}

export function BenefitsStatusBadge({ status, label }) {
  const text = label != null ? label : status == null || status === "" ? "—" : String(status);
  return (
    <span className={classNames("lux-doc-badge", `is-${getBenefitsStatusTone(status)}`)}>
      {text}
    </span>
  );
}

export default function BenefitsLuxPage({
  pageMeta,
  dataSource,
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  testId,
  children,
  className,
}) {
  useReportPageDataSource(dataSource);
  const meta = {
    tone: "green",
    icon: "fe fe-heart",
    eyebrow: "People · Benefits",
    titleLead: "Benefits",
    titleAccent: "workspace",
    lede: "Plans, enrollment, and carrier file exchange.",
    ...(pageMeta || {}),
  };

  return (
    <div
      className={classNames(
        "lux-register-page",
        "lux-benefits-module",
        "lux-benefits-lux",
        meta.tone && `is-${meta.tone}`,
        className
      )}
      {...(testId ? { "data-testid": testId } : {})}
    >
      <div className="lux-benefits-lux__ambient" aria-hidden="true">
        <span className="lux-benefits-lux__orb lux-benefits-lux__orb--a" />
        <span className="lux-benefits-lux__orb lux-benefits-lux__orb--b" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-benefits-lux__kpi-strip" />
        ) : null}
        <div className="lux-benefits-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function BenefitsActionButton(props) {
  return <LuxActionButton {...props} moduleClass="lux-benefits-action" />;
}

export function BenefitsLuxPanel({ title, meta, icon, accent, actions, children, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-benefits-lux__panel",
        accent && `is-${accent}`,
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-benefits-lux__panel-head">
        <div className="lux-benefits-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-benefits-lux__panel-body">{children}</div>
    </section>
  );
}

export function BenefitsInsightPanel({ insights = [] }) {
  return <AdminInsightStrip insights={insights} className="lux-benefits-lux__insights" />;
}

export function BenefitsQuickNav({
  links = BENEFITS_QUICK_LINKS,
  eyebrow = "Benefits workspace",
  title = "Navigate plans, enrollment, and carriers",
}) {
  return (
    <AdminQuickNav
      eyebrow={eyebrow}
      title={title}
      links={links}
      className="lux-benefits-lux__quick-nav"
      ariaLabel="Benefits navigation"
    />
  );
}

export function BenefitsField({ label, hint, children, className }) {
  return (
    <label className={classNames("lux-benefits-field", className)}>
      <span className="lux-benefits-field__label">{label}</span>
      {children}
      {hint ? <small className="lux-benefits-field__hint">{hint}</small> : null}
    </label>
  );
}

export function BenefitsFormGrid({ children, columns = 4 }) {
  return (
    <div
      className={classNames("lux-benefits-form-grid", columns === 3 && "is-3", columns === 2 && "is-2")}
    >
      {children}
    </div>
  );
}

export function BenefitsRegisterWrap({ children, className }) {
  return <div className={classNames("lux-benefits-register-wrap", className)}>{children}</div>;
}

export function BenefitsRegisterPrimary({ title, meta, icon = "fe fe-heart", tone = "green" }) {
  return (
    <div className="lux-benefits-register__primary">
      <span className={classNames("lux-benefits-register__avatar", `is-${tone}`)} aria-hidden="true">
        <i className={icon} />
      </span>
      <span className="lux-benefits-register__copy">
        <strong>{title || "—"}</strong>
        {meta ? <span>{meta}</span> : null}
      </span>
    </div>
  );
}

export function BenefitsToolbar({ query, onQueryChange, placeholder, countLabel, children }) {
  return (
    <div className="lux-benefits-toolbar">
      <div className="lux-appr-toolbar__search">
        <i className="fe fe-search" aria-hidden="true" />
        <input
          type="search"
          className="lux-appr-toolbar__search-input"
          placeholder={placeholder || "Search…"}
          value={query || ""}
          onChange={(e) => onQueryChange && onQueryChange(e.target.value)}
          aria-label={placeholder || "Search"}
        />
      </div>
      {children}
      {countLabel ? <span className="lux-appr-toolbar__count">{countLabel}</span> : null}
    </div>
  );
}

export function BenefitsMetricTiles({ tiles }) {
  if (!tiles || !tiles.length) return null;
  return (
    <div className="lux-benefits-metric-grid" role="list">
      {tiles.map((tile) => (
        <article
          key={tile.id || tile.label}
          className={classNames("lux-benefits-metric-card", tile.tone && `is-${tile.tone}`)}
          role="listitem"
        >
          <span className="lux-benefits-metric-card__label">{tile.label}</span>
          <strong className="lux-benefits-metric-card__value">{tile.value}</strong>
          {tile.hint ? <small>{tile.hint}</small> : null}
        </article>
      ))}
    </div>
  );
}

/** Compact in-page nav chips for alignment across benefits routes */
export function BenefitsSectionTabs({ active }) {
  return (
    <nav className="lux-benefits-tabs" aria-label="Benefits sections">
      {BENEFITS_QUICK_LINKS.map((item) => (
        <Link
          key={item.path}
          to={item.path}
          className={classNames("lux-benefits-tabs__item", {
            "is-active": active === item.path,
          })}
        >
          <i className={item.icon} aria-hidden="true" />
          <span>{item.label}</span>
        </Link>
      ))}
    </nav>
  );
}
