import moment from "moment";
import dateUtils from "_helpers/date.utils";

export function getWorkItemChecklistMeta(checklistStatus, checklistData) {
  const status = (checklistStatus || "").toUpperCase();
  if (status === "COMPLETED") {
    return { label: "Done", tone: "green", icon: "fe fe-check-circle" };
  }
  if (status === "INPROGRESS") {
    return { label: "In progress", tone: "amber", icon: "fe fe-loader" };
  }
  if (checklistData && Object.keys(checklistData).length > 0) {
    return { label: "Not started", tone: "slate", icon: "fe fe-square" };
  }
  return { label: "None", tone: "muted", icon: "fe fe-minus" };
}

export function getWorkItemHoursMeta(item) {
  const isDone = item.status === "COMPLETED" || item.status === "CLOSED";
  const plannedMins = Number(item.estDurationInMins) || 0;
  const loggedMins = Number(item.durationInMins) || 0;
  const primaryMins = isDone ? loggedMins : plannedMins;
  const value = dateUtils.minuteToHourString(primaryMins) || "0h 0m";
  const plannedLabel = dateUtils.minuteToHourString(plannedMins) || "0h 0m";
  const loggedLabel = dateUtils.minuteToHourString(loggedMins) || "0h 0m";
  const barPct =
    plannedMins > 0
      ? Math.min(100, Math.round((loggedMins / plannedMins) * 100))
      : loggedMins > 0
        ? 100
        : 0;
  const tone = isDone ? "green" : item.status === "INPROGRESS" ? "amber" : "indigo";
  const label = isDone ? "Logged" : "Planned";
  return {
    value,
    tone,
    label,
    isDone,
    plannedLabel,
    loggedLabel,
    barPct,
    secondary: isDone ? `Plan ${plannedLabel}` : loggedMins > 0 ? `Logged ${loggedLabel}` : null,
  };
}

export function formatWorkItemOwner(item) {
  return (
    (item.ownerDetails && item.ownerDetails.name) ||
    (item.employeeDetails && item.employeeDetails.name) ||
    "Unassigned"
  );
}

export function getWorkItemOwnerInitial(item) {
  const name = formatWorkItemOwner(item);
  return name ? name.charAt(0).toUpperCase() : "?";
}

export function getWorkItemTypeMeta(taskType) {
  if (taskType === "NON_PROJECT") {
    return { label: "Non-project", tone: "slate", icon: "fe fe-briefcase" };
  }
  if (taskType === "PROJECT") {
    return { label: "Billable", tone: "indigo", icon: "fe fe-dollar-sign" };
  }
  return null;
}

export function isWorkItemOverdue(item) {
  if (!item) return false;
  const status = (item.status || "").toUpperCase();
  if (status === "COMPLETED" || status === "CLOSED") return false;
  const due = item.estCompletionTime || item.taskEstCompletionTime;
  if (!due) return false;
  return moment(due).isBefore(moment(), "day");
}

export function getWorkItemPriorityValue(item) {
  return item && (item.taskPriority || item.priority);
}
