import React, { Component } from 'react';
import classNames from 'classnames/bind';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';

const FORMULAS = [
  { value: 'MONTHLY', label: 'Monthly accrual' },
  { value: 'ANNUAL_FRONT_LOAD', label: 'Front-load once per year' },
  { value: 'PRO_RATA', label: 'Pro-rata by day of year' },
  { value: 'WORKING_DAYS_1_N', label: '1 day per N working days' },
];

const CATEGORIES = [
  { value: 'ANNUAL', label: 'Annual' },
  { value: 'SICK', label: 'Sick' },
  { value: 'FAMILY', label: 'Family' },
  { value: 'UNPAID', label: 'Unpaid' },
  { value: 'GENERAL', label: 'General' },
];

const LAPSE_OPTIONS = [
  { value: 'CALENDAR_YEAR_END', label: 'Calendar year end' },
  { value: 'ANNIVERSARY', label: 'Hire anniversary' },
  { value: 'NEVER', label: 'Never lapse' },
];

const EMPTY_RULES = {
  leaveTypes: [],
  accruals: [],
  carryForward: [],
  lapse: [],
  eligibility: [],
  specialLeave: [],
  encashment: [],
};

function parseRules(json) {
  if (!json || (typeof json === 'string' && !json.trim())) {
    return { ...EMPTY_RULES };
  }
  try {
    const obj = typeof json === 'string' ? JSON.parse(json) : json;
    if (!obj || typeof obj !== 'object') return { ...EMPTY_RULES };
    return {
      countryCode: obj.countryCode || '',
      regionCode: obj.regionCode || '',
      leaveTypes: Array.isArray(obj.leaveTypes) ? obj.leaveTypes : [],
      accruals: Array.isArray(obj.accruals) ? obj.accruals : [],
      carryForward: Array.isArray(obj.carryForward) ? obj.carryForward : [],
      lapse: Array.isArray(obj.lapse) ? obj.lapse : [],
      eligibility: Array.isArray(obj.eligibility) ? obj.eligibility : [],
      specialLeave: Array.isArray(obj.specialLeave) ? obj.specialLeave : [],
      encashment: Array.isArray(obj.encashment) ? obj.encashment : [],
    };
  } catch (e) {
    return null;
  }
}

function stringifyRules(rules) {
  const clean = {
    countryCode: rules.countryCode || undefined,
    regionCode: rules.regionCode || undefined,
    leaveTypes: (rules.leaveTypes || []).map((t) => {
      const row = {
        code: t.code || '',
        name: t.name || '',
        paid: t.paid !== false,
        category: t.category || 'ANNUAL',
      };
      if (t.annualDays !== '' && t.annualDays != null) row.annualDays = Number(t.annualDays);
      return row;
    }),
    accruals: (rules.accruals || []).map((a) => {
      const row = {
        leaveTypeCode: a.leaveTypeCode || '',
        formula: a.formula || 'MONTHLY',
      };
      if (a.annualDays !== '' && a.annualDays != null) row.annualDays = Number(a.annualDays);
      if (a.monthlyDays !== '' && a.monthlyDays != null) row.monthlyDays = Number(a.monthlyDays);
      if (a.workingDaysDivisor !== '' && a.workingDaysDivisor != null) {
        row.workingDaysDivisor = Number(a.workingDaysDivisor);
      }
      if (a.forceFrontLoad === true) row.forceFrontLoad = true;
      if (Array.isArray(a.tenureThresholds) && a.tenureThresholds.length) {
        row.tenureThresholds = a.tenureThresholds
          .filter((t) => t && (t.minMonths !== '' || t.annualDays !== ''))
          .map((t) => ({
            minMonths: Number(t.minMonths) || 0,
            annualDays: Number(t.annualDays) || 0,
          }));
      }
      return row;
    }),
    carryForward: (rules.carryForward || []).map((c) => ({
      leaveTypeCode: c.leaveTypeCode || '',
      maxDays: c.maxDays === '' || c.maxDays == null ? 0 : Number(c.maxDays),
      expiryMonths:
        c.expiryMonths === '' || c.expiryMonths == null ? undefined : Number(c.expiryMonths),
    })),
    lapse: (rules.lapse || []).map((l) => ({
      leaveTypeCode: l.leaveTypeCode || '',
      lapseOn: l.lapseOn || 'CALENDAR_YEAR_END',
    })),
    eligibility: (rules.eligibility || []).map((e) => ({
      minServiceMonths:
        e.minServiceMonths === '' || e.minServiceMonths == null ? 0 : Number(e.minServiceMonths),
      employeeCategories: e.employeeCategories || undefined,
      notes: e.notes || undefined,
    })),
    specialLeave: rules.specialLeave || [],
    encashment: rules.encashment || [],
  };
  Object.keys(clean).forEach((k) => {
    if (clean[k] === undefined) delete clean[k];
  });
  return JSON.stringify(clean, null, 2);
}

/**
 * Form designer for version rules_json — friendly UI, JSON behind the scenes.
 */
export default class PolicyRulesDesigner extends Component {
  constructor(props) {
    super(props);
    const parsed = parseRules(props.value);
    this.state = {
      tab: 'leaveTypes',
      rules: parsed || { ...EMPTY_RULES },
      parseError: parsed ? null : 'Rules JSON is invalid — fix Advanced JSON or reset from a template.',
      showAdvanced: false,
      advancedText: typeof props.value === 'string' ? props.value : stringifyRules(parsed || EMPTY_RULES),
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.value !== this.props.value && this.props.value !== this.state.advancedText) {
      const parsed = parseRules(this.props.value);
      if (parsed) {
        this.setState({
          rules: parsed,
          parseError: null,
          advancedText: typeof this.props.value === 'string'
            ? this.props.value
            : stringifyRules(parsed),
        });
      } else {
        this.setState({
          parseError: 'Rules JSON is invalid — use Advanced JSON to repair.',
          advancedText: typeof this.props.value === 'string' ? this.props.value : '',
        });
      }
    }
  }

  emit = (rules) => {
    const text = stringifyRules(rules);
    this.setState({ rules, advancedText: text, parseError: null });
    if (this.props.onChange) this.props.onChange(text);
  };

  setMeta = (field, value) => {
    this.emit({ ...this.state.rules, [field]: value });
  };

  updateListItem = (listKey, index, field, value) => {
    const list = (this.state.rules[listKey] || []).slice();
    list[index] = { ...list[index], [field]: value };
    this.emit({ ...this.state.rules, [listKey]: list });
  };

  addListItem = (listKey, blank) => {
    const list = (this.state.rules[listKey] || []).slice();
    list.push(blank);
    this.emit({ ...this.state.rules, [listKey]: list });
  };

  removeListItem = (listKey, index) => {
    const list = (this.state.rules[listKey] || []).slice();
    list.splice(index, 1);
    this.emit({ ...this.state.rules, [listKey]: list });
  };

  leaveTypeCodes = () => {
    const codes = (this.state.rules.leaveTypes || [])
      .map((t) => t.code)
      .filter(Boolean);
    return codes.length ? codes : ['AL', 'SL', 'CL', 'EL'];
  };

  applyAdvanced = () => {
    const parsed = parseRules(this.state.advancedText);
    if (!parsed) {
      this.setState({ parseError: 'Advanced JSON could not be parsed.' });
      return;
    }
    this.emit(parsed);
    this.setState({ showAdvanced: false });
  };

  renderTabs() {
    const tabs = [
      { id: 'leaveTypes', label: 'Leave types', icon: 'fe fe-layers' },
      { id: 'accruals', label: 'Accrual', icon: 'fe fe-trending-up' },
      { id: 'carryForward', label: 'Carry forward', icon: 'fe fe-repeat' },
      { id: 'lapse', label: 'Lapse', icon: 'fe fe-clock' },
      { id: 'eligibility', label: 'Eligibility', icon: 'fe fe-user-check' },
    ];
    return (
      <div className="lux-glp-rules__tabs" role="tablist" aria-label="Rule sections">
        {tabs.map((t) => (
          <button
            key={t.id}
            type="button"
            role="tab"
            aria-selected={this.state.tab === t.id}
            className={classNames('lux-glp-rules__tab', { 'is-active': this.state.tab === t.id })}
            onClick={() => this.setState({ tab: t.id })}
          >
            <i className={t.icon} aria-hidden="true" />
            {t.label}
          </button>
        ))}
      </div>
    );
  }

  renderLeaveTypes() {
    const rows = this.state.rules.leaveTypes || [];
    const disabled = !!this.props.disabled;
    return (
      <div className="lux-glp-rules__section">
        <p className="lux-glp-rules__hint">
          Define leave codes employees can request. Annual days are the entitlement baseline.
        </p>
        {rows.map((row, idx) => (
          <div key={`lt-${idx}`} className="lux-glp-rules__card">
            <div className="lux-glp-rules__card-head">
              <strong>Leave type {idx + 1}</strong>
              {!disabled && (
                <button type="button" className="lux-glp-rules__remove" onClick={() => this.removeListItem('leaveTypes', idx)} aria-label="Remove leave type">
                  <i className="fe fe-trash-2" aria-hidden="true" />
                </button>
              )}
            </div>
            <div className="lux-glp-rules__grid">
              <label>Code
                <input disabled={disabled} value={row.code || ''} onChange={(e) => this.updateListItem('leaveTypes', idx, 'code', e.target.value.toUpperCase())} placeholder="EL" />
              </label>
              <label>Name
                <input disabled={disabled} value={row.name || ''} onChange={(e) => this.updateListItem('leaveTypes', idx, 'name', e.target.value)} placeholder="Earned Leave" />
              </label>
              <label>Annual days
                <input disabled={disabled} type="number" min="0" step="0.5" value={row.annualDays != null ? row.annualDays : ''} onChange={(e) => this.updateListItem('leaveTypes', idx, 'annualDays', e.target.value)} />
              </label>
              <label>Category
                <select disabled={disabled} value={row.category || 'ANNUAL'} onChange={(e) => this.updateListItem('leaveTypes', idx, 'category', e.target.value)}>
                  {CATEGORIES.map((c) => <option key={c.value} value={c.value}>{c.label}</option>)}
                </select>
              </label>
              <label className="lux-glp-rules__check">
                <input disabled={disabled} type="checkbox" checked={row.paid !== false} onChange={(e) => this.updateListItem('leaveTypes', idx, 'paid', e.target.checked)} />
                <span>Paid leave</span>
              </label>
            </div>
          </div>
        ))}
        {!disabled && (
          <AdminActionButton
            icon="fe fe-plus"
            variant="ghost"
            onClick={() => this.addListItem('leaveTypes', { code: '', name: '', annualDays: 12, paid: true, category: 'ANNUAL' })}
          >
            Add leave type
          </AdminActionButton>
        )}
      </div>
    );
  }

  renderAccruals() {
    const rows = this.state.rules.accruals || [];
    const codes = this.leaveTypeCodes();
    return (
      <div className="lux-glp-rules__section">
        <p className="lux-glp-rules__hint">
          How balances grow each period. Choose a formula — monthly is the most common.
        </p>
        {rows.map((row, idx) => (
          <div key={`ac-${idx}`} className="lux-glp-rules__card">
            <div className="lux-glp-rules__card-head">
              <strong>Accrual rule {idx + 1}</strong>
              <button type="button" className="lux-glp-rules__remove" onClick={() => this.removeListItem('accruals', idx)} aria-label="Remove accrual">
                <i className="fe fe-trash-2" aria-hidden="true" />
              </button>
            </div>
            <div className="lux-glp-rules__grid">
              <label>Leave type
                <select value={row.leaveTypeCode || ''} onChange={(e) => this.updateListItem('accruals', idx, 'leaveTypeCode', e.target.value)}>
                  <option value="">Select…</option>
                  {codes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </label>
              <label>Formula
                <select value={row.formula || 'MONTHLY'} onChange={(e) => this.updateListItem('accruals', idx, 'formula', e.target.value)}>
                  {FORMULAS.map((f) => <option key={f.value} value={f.value}>{f.label}</option>)}
                </select>
              </label>
              <label>Annual days
                <input type="number" min="0" step="0.5" value={row.annualDays != null ? row.annualDays : ''} onChange={(e) => this.updateListItem('accruals', idx, 'annualDays', e.target.value)} />
              </label>
              <label>Monthly days
                <input type="number" min="0" step="0.01" value={row.monthlyDays != null ? row.monthlyDays : ''} onChange={(e) => this.updateListItem('accruals', idx, 'monthlyDays', e.target.value)} placeholder="e.g. 1.5" />
              </label>
              {(row.formula || '') === 'WORKING_DAYS_1_N' && (
                <label>Working days divisor (N)
                  <input type="number" min="1" value={row.workingDaysDivisor != null ? row.workingDaysDivisor : 20} onChange={(e) => this.updateListItem('accruals', idx, 'workingDaysDivisor', e.target.value)} />
                </label>
              )}
              {(row.formula || '') === 'ANNUAL_FRONT_LOAD' && (
                <label className="lux-glp-rules__check">
                  <input type="checkbox" checked={row.forceFrontLoad === true} onChange={(e) => this.updateListItem('accruals', idx, 'forceFrontLoad', e.target.checked)} />
                  <span>Credit full annual amount immediately (any month)</span>
                </label>
              )}
            </div>
            <div className="lux-glp-rules__tenure">
              <div className="lux-glp-rules__card-head">
                <span>Tenure thresholds (optional)</span>
                <button
                  type="button"
                  className="lux-leave-register__action"
                  onClick={() => {
                    const thresholds = Array.isArray(row.tenureThresholds) ? row.tenureThresholds.slice() : [];
                    thresholds.push({ minMonths: 0, annualDays: row.annualDays || 12 });
                    this.updateListItem('accruals', idx, 'tenureThresholds', thresholds);
                  }}
                >
                  Add threshold
                </button>
              </div>
              {(row.tenureThresholds || []).map((t, tIdx) => (
                <div key={`th-${idx}-${tIdx}`} className="lux-glp-rules__grid lux-glp-rules__grid--compact">
                  <label>Min months
                    <input type="number" min="0" value={t.minMonths != null ? t.minMonths : ''} onChange={(e) => {
                      const thresholds = (row.tenureThresholds || []).slice();
                      thresholds[tIdx] = { ...thresholds[tIdx], minMonths: e.target.value };
                      this.updateListItem('accruals', idx, 'tenureThresholds', thresholds);
                    }}
                    />
                  </label>
                  <label>Annual days
                    <input type="number" min="0" step="0.5" value={t.annualDays != null ? t.annualDays : ''} onChange={(e) => {
                      const thresholds = (row.tenureThresholds || []).slice();
                      thresholds[tIdx] = { ...thresholds[tIdx], annualDays: e.target.value };
                      this.updateListItem('accruals', idx, 'tenureThresholds', thresholds);
                    }}
                    />
                  </label>
                  <button
                    type="button"
                    className="lux-glp-rules__remove"
                    aria-label="Remove threshold"
                    onClick={() => {
                      const thresholds = (row.tenureThresholds || []).slice();
                      thresholds.splice(tIdx, 1);
                      this.updateListItem('accruals', idx, 'tenureThresholds', thresholds);
                    }}
                  >
                    <i className="fe fe-x" aria-hidden="true" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
        <AdminActionButton
          icon="fe fe-plus"
          variant="ghost"
          onClick={() => this.addListItem('accruals', {
            leaveTypeCode: codes[0] || 'AL',
            formula: 'MONTHLY',
            annualDays: 18,
            monthlyDays: 1.5,
          })}
        >
          Add accrual rule
        </AdminActionButton>
      </div>
    );
  }

  renderCarryForward() {
    const rows = this.state.rules.carryForward || [];
    const codes = this.leaveTypeCodes();
    return (
      <div className="lux-glp-rules__section">
        <p className="lux-glp-rules__hint">
          How many unused days may roll into the next year, and how long they remain usable.
        </p>
        {rows.map((row, idx) => (
          <div key={`cf-${idx}`} className="lux-glp-rules__card">
            <div className="lux-glp-rules__card-head">
              <strong>Carry-forward {idx + 1}</strong>
              <button type="button" className="lux-glp-rules__remove" onClick={() => this.removeListItem('carryForward', idx)} aria-label="Remove">
                <i className="fe fe-trash-2" aria-hidden="true" />
              </button>
            </div>
            <div className="lux-glp-rules__grid">
              <label>Leave type
                <select value={row.leaveTypeCode || ''} onChange={(e) => this.updateListItem('carryForward', idx, 'leaveTypeCode', e.target.value)}>
                  <option value="">Select…</option>
                  {codes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </label>
              <label>Max days to carry
                <input type="number" min="0" step="0.5" value={row.maxDays != null ? row.maxDays : ''} onChange={(e) => this.updateListItem('carryForward', idx, 'maxDays', e.target.value)} />
              </label>
              <label>Expiry (months)
                <input type="number" min="0" value={row.expiryMonths != null ? row.expiryMonths : ''} onChange={(e) => this.updateListItem('carryForward', idx, 'expiryMonths', e.target.value)} placeholder="e.g. 12" />
              </label>
            </div>
          </div>
        ))}
        <AdminActionButton
          icon="fe fe-plus"
          variant="ghost"
          onClick={() => this.addListItem('carryForward', { leaveTypeCode: codes[0] || 'EL', maxDays: 30, expiryMonths: 12 })}
        >
          Add carry-forward rule
        </AdminActionButton>
      </div>
    );
  }

  renderLapse() {
    const rows = this.state.rules.lapse || [];
    const codes = this.leaveTypeCodes();
    return (
      <div className="lux-glp-rules__section">
        <p className="lux-glp-rules__hint">
          When unused balance expires (after carry-forward max is applied).
        </p>
        {rows.map((row, idx) => (
          <div key={`lp-${idx}`} className="lux-glp-rules__card">
            <div className="lux-glp-rules__card-head">
              <strong>Lapse rule {idx + 1}</strong>
              <button type="button" className="lux-glp-rules__remove" onClick={() => this.removeListItem('lapse', idx)} aria-label="Remove">
                <i className="fe fe-trash-2" aria-hidden="true" />
              </button>
            </div>
            <div className="lux-glp-rules__grid">
              <label>Leave type
                <select value={row.leaveTypeCode || ''} onChange={(e) => this.updateListItem('lapse', idx, 'leaveTypeCode', e.target.value)}>
                  <option value="">Select…</option>
                  {codes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </label>
              <label>Lapse when
                <select value={row.lapseOn || 'CALENDAR_YEAR_END'} onChange={(e) => this.updateListItem('lapse', idx, 'lapseOn', e.target.value)}>
                  {LAPSE_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                </select>
              </label>
            </div>
          </div>
        ))}
        <AdminActionButton
          icon="fe fe-plus"
          variant="ghost"
          onClick={() => this.addListItem('lapse', { leaveTypeCode: codes[0] || 'CL', lapseOn: 'CALENDAR_YEAR_END' })}
        >
          Add lapse rule
        </AdminActionButton>
      </div>
    );
  }

  renderEligibility() {
    const rows = this.state.rules.eligibility || [];
    return (
      <div className="lux-glp-rules__section">
        <p className="lux-glp-rules__hint">
          Who can use this policy — typically minimum service months before leave accrues.
        </p>
        <div className="lux-glp-rules__grid" style={{ marginBottom: '0.85rem' }}>
          <label>Country code
            <input value={this.state.rules.countryCode || ''} onChange={(e) => this.setMeta('countryCode', e.target.value.toUpperCase())} placeholder="IN" />
          </label>
          <label>Region / state
            <input value={this.state.rules.regionCode || ''} onChange={(e) => this.setMeta('regionCode', e.target.value.toUpperCase())} placeholder="KA" />
          </label>
        </div>
        {rows.map((row, idx) => (
          <div key={`el-${idx}`} className="lux-glp-rules__card">
            <div className="lux-glp-rules__card-head">
              <strong>Eligibility {idx + 1}</strong>
              <button type="button" className="lux-glp-rules__remove" onClick={() => this.removeListItem('eligibility', idx)} aria-label="Remove">
                <i className="fe fe-trash-2" aria-hidden="true" />
              </button>
            </div>
            <div className="lux-glp-rules__grid">
              <label>Min service (months)
                <input type="number" min="0" value={row.minServiceMonths != null ? row.minServiceMonths : ''} onChange={(e) => this.updateListItem('eligibility', idx, 'minServiceMonths', e.target.value)} />
              </label>
              <label>Notes
                <input value={row.notes || ''} onChange={(e) => this.updateListItem('eligibility', idx, 'notes', e.target.value)} placeholder="Optional" />
              </label>
            </div>
          </div>
        ))}
        <AdminActionButton
          icon="fe fe-plus"
          variant="ghost"
          onClick={() => this.addListItem('eligibility', { minServiceMonths: 0, notes: '' })}
        >
          Add eligibility rule
        </AdminActionButton>
      </div>
    );
  }

  render() {
    const { disabled } = this.props;
    const { tab, parseError, showAdvanced, advancedText } = this.state;

    return (
      <div className={classNames('lux-glp-rules', { 'is-disabled': disabled })} aria-label="Policy rules designer">
        {parseError && (
          <div className="lux-glp-banner is-error" role="alert">
            <i className="fe fe-alert-circle" aria-hidden="true" />
            <span>{parseError}</span>
          </div>
        )}

        {!parseError && this.renderTabs()}

        {!parseError && (
          <div className="lux-glp-rules__body" role="tabpanel">
            {tab === 'leaveTypes' && this.renderLeaveTypes()}
            {tab === 'accruals' && this.renderAccruals()}
            {tab === 'carryForward' && this.renderCarryForward()}
            {tab === 'lapse' && this.renderLapse()}
            {tab === 'eligibility' && this.renderEligibility()}
          </div>
        )}

        <div className="lux-glp-rules__advanced">
          <button
            type="button"
            className="lux-glp-rules__advanced-toggle"
            onClick={() => this.setState({ showAdvanced: !showAdvanced })}
          >
            <i className={showAdvanced ? 'fe fe-chevron-down' : 'fe fe-chevron-right'} aria-hidden="true" />
            Advanced JSON {showAdvanced ? '(hide)' : '(show)'}
          </button>
          {showAdvanced && (
            <div className="lux-glp-form">
              <label>
                Raw rules
                <textarea
                  value={advancedText}
                  disabled={disabled}
                  onChange={(e) => this.setState({ advancedText: e.target.value })}
                  aria-label="Advanced rules JSON"
                />
              </label>
              <AdminActionButton icon="fe fe-check" disabled={disabled} onClick={this.applyAdvanced}>
                Apply JSON to form
              </AdminActionButton>
            </div>
          )}
        </div>
      </div>
    );
  }
}
