import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import Skeleton from "react-loading-skeleton";
import dateUtils from "_helpers/date.utils";
import { buildTeamHeatmap, formatPlannerHours, UTIL_TONES } from "./plannerAnalytics.utils";
import { buildTeamHourlyGrid, formatHourRange } from "./plannerHourly.utils";
import PlannerViewHero from "./components/PlannerViewHero";
import PlannerUtilLegend from "./components/PlannerUtilLegend";
import PlannerLuxPanel, {
  buildPanelMetricsFromCell,
  buildPanelMetricsFromRow,
} from "./components/PlannerLuxPanel";
import { enrichWorkItemDetail } from "./plannerHourly.utils";
import PlannerAssignTray from "./components/PlannerAssignTray";
import { getEmployeeDailyCapacityMinutes } from "./plannerCapacity.utils";

const SORT_OPTIONS = [
  { id: "utilization", label: "Highest load" },
  { id: "name", label: "Name A–Z" },
  { id: "free", label: "Most available" },
  { id: "overbooked", label: "Overbooked days" },
];

export default class TeamCapacityRosterView extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      sortBy: "utilization",
      rosterFilter: "",
      selected: null,
    };
  }

  sortRows = (rows) => {
    const list = [...rows];
    switch (this.state.sortBy) {
      case "name":
        list.sort((a, b) => (a.employee.name || "").localeCompare(b.employee.name || ""));
        break;
      case "free":
        list.sort((a, b) => b.freeMinutes - a.freeMinutes);
        break;
      case "overbooked":
        list.sort((a, b) => b.overbookedDays - a.overbookedDays);
        break;
      default:
        list.sort((a, b) => b.horizonUtilization - a.horizonUtilization);
    }
    return list;
  };

  openSelection = (payload) => this.setState({ selected: payload });

  closePanel = () => this.setState({ selected: null });

  handleAssign = (employee, dayMoment, hour) => {
    const { onAssignRequest } = this.props;
    if (onAssignRequest) {
      onAssignRequest({ employee, dayMoment, hour });
    }
  };

  handleDropOnCell = (e, row, cell, hour) => {
    e.preventDefault();
    e.currentTarget.classList.remove("is-drop-target");
    const { onWorkItemDrop, canAssign } = this.props;
    if (!canAssign || !onWorkItemDrop) return;
    const id =
      e.dataTransfer.getData("application/x-planner-workitem") ||
      e.dataTransfer.getData("text/plain");
    if (!id) return;
    const dayMoment = cell.dayMoment || row.dayMoment;
    const allocated = hour != null ? (cell.allocated || 0) : cell.allocated;
    onWorkItemDrop({
      workItemId: id,
      employee: row.employee,
      dayMoment,
      hour: hour != null ? hour : null,
      allocatedMinutes: allocated,
    });
  };

  handleDragOverCell = (e) => {
    const { canAssign } = this.props;
    if (!canAssign) return;
    const types = e.dataTransfer.types || [];
    const hasItem =
      types.indexOf("application/x-planner-workitem") >= 0 ||
      types.indexOf("text/plain") >= 0;
    if (!hasItem) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    e.currentTarget.classList.add("is-drop-target");
  };

  handleDragLeaveCell = (e) => {
    e.currentTarget.classList.remove("is-drop-target");
  };

  formatCellTitle = (cell) => {
    if (cell.isOnLeave) return cell.leaveLabel || "Leave / PTO";
    if (cell.capacity <= 0) return `${cell.dateLabel} · No scheduled capacity`;
    const planned = formatPlannerHours(cell.allocated);
    const cap = formatPlannerHours(cell.capacity);
    const free = formatPlannerHours(cell.free);
    return `${cell.dateLabel}: ${cell.utilization}% planned · ${planned} / ${cap} · ${free} available`;
  };

  renderUtilRing = (pct, tone) => (
    <div className={`lux-planner-util-ring is-${tone}`} style={{ "--pct": Math.min(pct, 100) }}>
      <svg viewBox="0 0 36 36" aria-hidden>
        <path className="lux-planner-util-ring__bg" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
        <path className="lux-planner-util-ring__fill" strokeDasharray={`${Math.min(pct, 100)}, 100`} d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
      </svg>
      <span>{pct}%</span>
    </div>
  );

  buildLuxPanelProps = () => {
    const { selected } = this.state;
    const { history, canAssign, workItems, focusDayMoment } = this.props;
    if (!selected) return null;

    const { row, cell, hourCell } = selected;
    const uniqueItems = [];
    const seen = new Set();
    const pushItems = (list) => {
      (list || []).forEach((entry) => {
        if (seen.has(entry.item.id)) return;
        seen.add(entry.item.id);
        uniqueItems.push(entry);
      });
    };

    if (hourCell) {
      pushItems(hourCell.items);
    } else if (cell) {
      pushItems(cell.items);
    } else {
      row.dayCells.forEach((c) => pushItems(c.items));
    }

    const primary = uniqueItems.length > 0 ? uniqueItems[0] : null;
    const hourlyModel =
      cell || hourCell
        ? buildTeamHourlyGrid({
            employees: [row.employee],
            workItems,
            focusDayMoment: (cell && cell.dayMoment) || focusDayMoment,
            filterOptions: this.props.filterOptions,
          })[0]
        : null;

    const title = hourCell
      ? `${row.employee.name} · ${formatHourRange(hourCell.hour)}`
      : cell
        ? `${row.employee.name} · ${cell.dateLabel}`
        : row.employee.name;

    const subtitle = hourCell
      ? `${formatPlannerHours(hourCell.allocated)} booked · ${formatPlannerHours(hourCell.free)} free`
      : cell
        ? `${cell.utilization}% day utilization`
        : `${row.horizonUtilization}% across horizon`;

    const hasBandwidth = hourCell
      ? hourCell.hasBandwidth
      : cell
        ? cell.hasBandwidth
        : row.freeMinutes > 0;

    const actions = [];
    if (primary) {
      const d = enrichWorkItemDetail(primary.item, primary.minutes);
      if (d.item.taskId) {
        actions.push({
          key: "task",
          icon: "fe-layers",
          label: "Open deliverable",
          sublabel: d.taskName,
          variant: "primary",
          onClick: () => history.push(`/project/deliverable/${d.item.taskId}`),
        });
      }
      if (d.item.projectId) {
        actions.push({
          key: "project",
          icon: "fe-briefcase",
          label: "Open project",
          sublabel: d.projectName,
          variant: "ghost",
          onClick: () => history.push(`/project/details/${d.item.projectId}`),
        });
      }
    }
    if (canAssign && hasBandwidth) {
      actions.push({
        key: "assign",
        icon: "fe-user-plus",
        label: "Assign work here",
        sublabel: hourCell
          ? `Schedule on ${formatHourRange(hourCell.hour)}`
          : cell
            ? `Add to ${cell.dateLabel}`
            : `Use ${formatPlannerHours(row.freeMinutes)} capacity`,
        variant: "accent",
        onClick: () => {
          this.handleAssign(
            row.employee,
            (cell && cell.dayMoment) || focusDayMoment,
            hourCell && hourCell.hour
          );
          this.closePanel();
        },
      });
    }

    return {
      open: true,
      onClose: this.closePanel,
      title,
      subtitle,
      statusMeta: primary ? enrichWorkItemDetail(primary.item).statusMeta : undefined,
      metrics: hourCell
        ? [
            { label: "Slot load", value: `${hourCell.utilization}%` },
            { label: "Booked", value: formatPlannerHours(hourCell.allocated) },
            { label: "Free", value: formatPlannerHours(hourCell.free), tone: "good" },
          ]
        : cell
          ? buildPanelMetricsFromCell(cell)
          : buildPanelMetricsFromRow(row),
      hourlyModel: cell || hourCell ? hourlyModel : null,
      assignments: uniqueItems,
      primaryItem: primary,
      actions,
      bandwidthHint:
        hasBandwidth && canAssign
          ? "This slot has bandwidth — assign new work without overloading the team."
          : null,
      footer:
        canAssign && hasBandwidth ? (
          <button
            type="button"
            className="lux-planner-btn lux-planner-btn--primary lux-planner-btn--block"
            onClick={() => {
              this.handleAssign(
                row.employee,
                (cell && cell.dayMoment) || focusDayMoment,
                hourCell && hourCell.hour
              );
              this.closePanel();
            }}
          >
            <i className="fe fe-plus-circle" /> Assign to {row.employee.name}
          </button>
        ) : null,
    };
  };

  renderDayHeatmap = (heatmap, rows) => {
    const { canAssign, showActuals } = this.props;
    const dayCount = Math.max(heatmap.days.length, 1);
    return (
      <div
        className="lux-planner-heatmap-wrap"
        style={{
          "--heatmap-person-col": "248px",
          "--heatmap-days": String(dayCount),
        }}
      >
        <div className="lux-planner-heatmap" role="table" aria-label="Team capacity heatmap">
          <div className="lux-planner-heatmap__head-days" role="row">
            <div className="lux-planner-heatmap__head-corner" role="columnheader">
              Team member
            </div>
            {heatmap.days.map((d) => {
              const key = d.format("YYYY-MM-DD");
              return (
                <div
                  key={key}
                  className={classNames("lux-planner-heatmap__head-day", {
                    "is-weekend": d.isoWeekday() >= 6,
                    "is-holiday": heatmap.holidayKeys.has(key),
                    "is-today": d.isSame(dateUtils.getCurrentTime(), "day"),
                    "is-focus":
                      this.props.focusDayMoment && d.isSame(this.props.focusDayMoment, "day"),
                  })}
                  onClick={() => this.props.onFocusDayChange && this.props.onFocusDayChange(d)}
                  role="columnheader"
                  tabIndex={0}
                  onKeyDown={(e) =>
                    e.key === "Enter" &&
                    this.props.onFocusDayChange &&
                    this.props.onFocusDayChange(d)
                  }
                  title="Set focus day for hourly view"
                >
                  <span>{d.format("ddd")}</span>
                  <strong>{d.format("DD")}</strong>
                </div>
              );
            })}
          </div>

          {rows.map((row) => (
            <div key={row.employee.id} className="lux-planner-heatmap__row" role="row">
              <button
                type="button"
                className="lux-planner-heatmap__person"
                onClick={() => this.openSelection({ row })}
              >
                <span className="lux-planner-heatmap__avatar" aria-hidden>
                  {(row.employee.name || "?")
                    .trim()
                    .split(/\s+/)
                    .filter(Boolean)
                    .slice(0, 2)
                    .map((part) => part[0])
                    .join("")
                    .toUpperCase() || "?"}
                </span>
                <span className="lux-planner-heatmap__person-text">
                  <strong>{row.employee.name}</strong>
                  <span>
                    {row.employee.designation
                      ? `${row.employee.designation} · `
                      : ""}
                    {row.assignmentCount} items · {row.activeProjects} projects
                    {this.props.capacityOverrides
                      ? ` · ${Math.round(
                          getEmployeeDailyCapacityMinutes(
                            row.employee,
                            this.props.capacityOverrides
                          ) / 60
                        )}h/day`
                      : ""}
                  </span>
                </span>
                {this.renderUtilRing(row.horizonUtilization, row.tone)}
              </button>

              {row.dayCells.map((cell) => (
                <button
                  type="button"
                  key={cell.dayKey}
                  className={classNames("lux-planner-heatmap__cell", `is-${cell.tone}`, {
                    "is-weekend": cell.isWeekend,
                    "is-holiday": cell.isHoliday,
                    "is-empty": cell.allocated === 0 && !cell.isOnLeave && cell.capacity > 0,
                    "is-no-capacity": !cell.isOnLeave && cell.capacity <= 0,
                    "is-on-leave": cell.isOnLeave,
                    "is-focus":
                      this.props.focusDayMoment &&
                      cell.dayMoment.isSame(this.props.focusDayMoment, "day"),
                  })}
                  style={{
                    "--cell-color": UTIL_TONES[cell.tone]
                      ? UTIL_TONES[cell.tone].color
                      : "#0f766e",
                    "--cell-fill": cell.isOnLeave
                      ? "0%"
                      : `${Math.min(cell.utilization, 100)}%`,
                  }}
                  title={this.formatCellTitle(cell)}
                  aria-label={this.formatCellTitle(cell)}
                  onClick={() => this.openSelection({ row, cell })}
                  onDragOver={canAssign ? this.handleDragOverCell : undefined}
                  onDragLeave={canAssign ? this.handleDragLeaveCell : undefined}
                  onDrop={
                    canAssign ? (e) => this.handleDropOnCell(e, row, cell, null) : undefined
                  }
                >
                  <span className="lux-planner-heatmap__cell-fill" />
                  {cell.isOnLeave && (
                    <span className="lux-planner-heatmap__leave-mark" aria-hidden>
                      <i className="fe fe-sun" />
                    </span>
                  )}
                  {showActuals && cell.actualMinutes > 0 && !cell.isOnLeave && (
                    <span
                      className="lux-planner-heatmap__actual-bar"
                      style={{
                        width: `${Math.min(
                          100,
                          Math.round((cell.actualMinutes / Math.max(cell.capacity, 1)) * 100)
                        )}%`,
                      }}
                      title={`Logged ${formatPlannerHours(cell.actualMinutes)}`}
                    />
                  )}
                  {cell.items.length > 0 && (
                    <span className="lux-planner-heatmap__cell-count">{cell.items.length}</span>
                  )}
                  {cell.hasBandwidth &&
                    cell.free > 0 &&
                    cell.utilization > 0 &&
                    cell.utilization < 90 && (
                      <span className="lux-planner-heatmap__cell-free">
                        {formatPlannerHours(cell.free)}
                      </span>
                    )}
                  {canAssign && cell.hasBandwidth && (
                    <span
                      className="lux-planner-heatmap__assign"
                      title={`Assign to ${row.employee.name}`}
                      onClick={(e) => {
                        e.stopPropagation();
                        this.handleAssign(row.employee, cell.dayMoment);
                      }}
                    >
                      <i className="fe fe-plus" />
                    </span>
                  )}
                </button>
              ))}
            </div>
          ))}
        </div>
      </div>
    );
  };

  render() {
    const {
      employees,
      workItems,
      startMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      isLoading,
      focusDayMoment,
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
      assignTrayOpen,
      onAssignTrayToggle,
    } = this.props;

    const heatmap = buildTeamHeatmap({
      employees,
      workItems,
      startMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    });

    const text = (this.state.rosterFilter || "").trim().toLowerCase();
    let rows = heatmap.rows;
    if (text.length >= 2) {
      rows = rows.filter((r) => (r.employee.name || "").toLowerCase().includes(text));
    }
    rows = this.sortRows(rows);

    const panelProps = this.buildLuxPanelProps();

    return (
      <div className="lux-planner-roster">
        <PlannerViewHero
          eyebrow="Team roster"
          eyebrowVariant="planner-roster"
          title="Capacity table"
          description="Aligned day grid by person. Green is open, amber is full, red is overbooked. Click a cell for detail, or use + to assign."
          meta={`${rows.length} people · ${heatmap.days.length} days`}
        />

        <div className="lux-planner-roster__controls">
          <div className="lux-planner-roster__search">
            <i className="fe fe-search" aria-hidden />
            <input
              type="search"
              placeholder="Search team member…"
              value={this.state.rosterFilter}
              onChange={(e) => this.setState({ rosterFilter: e.target.value })}
              aria-label="Search team member"
            />
          </div>
          <div className="lux-planner-segment" role="group" aria-label="Sort roster">
            {SORT_OPTIONS.map((opt) => (
              <button
                key={opt.id}
                type="button"
                className={classNames({ "is-active": this.state.sortBy === opt.id })}
                onClick={() => this.setState({ sortBy: opt.id })}
              >
                {opt.label}
              </button>
            ))}
          </div>
          <PlannerUtilLegend compact />
        </div>

        <div className="lux-planner-roster__layout">
          <div className="lux-planner-roster__grid-pane">
            {isLoading ? (
              <Skeleton height={320} />
            ) : (
              <>
                {this.renderDayHeatmap(heatmap, rows)}
                <p className="lux-planner-roster__hint text-muted fsize12">
                  Tip: use <strong>By hour</strong> on the Gantt tab for 8am–6pm scheduling on{" "}
                  {focusDayMoment.format("DD MMM")}. Drag unassigned work from the tray onto open cells.
                </p>
              </>
            )}
          </div>
          <PlannerAssignTray
            workItems={workItems}
            open={assignTrayOpen}
            onToggle={onAssignTrayToggle}
            canAssign={this.props.canAssign}
          />
        </div>

        {panelProps && <PlannerLuxPanel {...panelProps} />}
      </div>
    );
  }
}
