import React, { Component } from "react";
import LoadingButton from "views/common/fragments/LoadingButton";
import { summarizePlannerTimeEntry } from "../plannerAssignForm.utils";

class PlannerAssignFormFooter extends Component {
  render() {
    const {
      hasFormError,
      onResetFormError,
      handleSubmit,
      initializeRequest,
      createButtonLabel,
      workItemStatus,
      timeEntry,
      dayCapacityMap,
      employeeLabel,
      workTypeLabel,
      isProcessing,
    } = this.props;

    const isCompleted = workItemStatus === "COMPLETED";
    const submitLabel = createButtonLabel || (isCompleted ? "Complete tasks" : "Assign tasks");
    const loadingLabel = isCompleted ? "Completing…" : "Assigning…";

    const summary = summarizePlannerTimeEntry(timeEntry, dayCapacityMap);
    const hasPlan = summary && summary.dayCount > 0;

    return (
      <footer className="lux-planner-assign-footer lux-create-footer">
        {hasFormError && (
          <div className="lux-create-footer__alert" role="alert">
            <i className="fe fe-alert-triangle" aria-hidden="true" />
            <span>Complete required fields before assigning work.</span>
            <button
              type="button"
              className="lux-create-footer__alert-dismiss"
              onClick={onResetFormError}
              aria-label="Dismiss"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        )}

        <div className="lux-planner-assign-footer__summary">
          <div className="lux-planner-assign-footer__summary-main">
            {hasPlan ? (
              <>
                <div className="lux-planner-assign-footer__stat">
                  <span className="lux-planner-assign-footer__stat-label">Days planned</span>
                  <strong>{summary.dayCount}</strong>
                </div>
                <div className="lux-planner-assign-footer__stat">
                  <span className="lux-planner-assign-footer__stat-label">This assignment</span>
                  <strong>{summary.totalDraftLabel}</strong>
                </div>
                {summary.hasOverUtilization ? (
                  <div
                    className="lux-planner-assign-footer__stat lux-planner-assign-footer__stat--warn"
                    role="status"
                  >
                    <span className="lux-planner-assign-footer__stat-label">Over capacity</span>
                    <strong>
                      {summary.overDayCount} day{summary.overDayCount === 1 ? "" : "s"} ·{" "}
                      {summary.totalOverLabel} excess
                    </strong>
                  </div>
                ) : (
                  <div className="lux-planner-assign-footer__stat lux-planner-assign-footer__stat--ok">
                    <span className="lux-planner-assign-footer__stat-label">Capacity</span>
                    <strong>Within daily limits</strong>
                  </div>
                )}
              </>
            ) : (
              <p className="lux-planner-assign-footer__empty">
                Set dates and daily hours to see a planning summary here.
              </p>
            )}
          </div>

          {(employeeLabel || workTypeLabel) && (
            <div className="lux-planner-assign-footer__context">
              {employeeLabel && (
                <span>
                  <i className="fe fe-user" aria-hidden="true" /> {employeeLabel}
                </span>
              )}
              {workTypeLabel && (
                <span>
                  <i className="fe fe-layers" aria-hidden="true" /> {workTypeLabel}
                </span>
              )}
            </div>
          )}
        </div>

        <div className="lux-create-footer__bar lux-planner-assign-footer__bar">
          <p className="lux-planner-assign-footer__hint">
            {summary && summary.hasOverUtilization
              ? isCompleted
                ? "Some days exceed capacity — review highlighted rows before recording completion."
                : "Some days exceed capacity — you can still assign, but review the highlighted rows."
              : isCompleted
                ? "Record completed work for the selected team member across the planned date range."
                : "Assign tasks to the selected team member for the planned date range."}
          </p>

          <div className="lux-create-footer__actions">
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--ghost"
              onClick={() => initializeRequest(false)}
              disabled={isProcessing}
            >
              <i className="fe fe-rotate-ccw" aria-hidden="true" /> Clear form
            </button>
            <LoadingButton
              isLoading={isProcessing}
              loadingText={loadingLabel}
              variant="primary"
              size="sm"
              className="lux-create-footer__submit lux-planner-assign-footer__submit"
              onClick={() => handleSubmit(false, false)}
            >
              <i className="fe fe-check-circle" aria-hidden="true" /> {submitLabel}
            </LoadingButton>
          </div>
        </div>
      </footer>
    );
  }
}

export default PlannerAssignFormFooter;
