import React, { useState } from "react";
import classNames from "classnames/bind";
import { AI_RECOMMENDATION_DECISIONS, AI_RECOMMENDATION_STATUSES } from "config/ai-work-intelligence.config";
import { canDecideRecommendation } from "config/ai-work-intelligence-security.utils";
import { AiActionButton, AiConfidenceBadge, AiConfidenceRing } from "views/ai/components/AiLuxShared";

export default function AgentRecommendationPanel({
  recommendations = [],
  activePersona,
  selectedRecommendationId,
  onSelectRecommendation,
  onDecide,
  busyId,
  loading,
  filterAgentId,
}) {
  const [rationale, setRationale] = useState("");
  const rows = recommendations.filter((rec) => !filterAgentId || rec.agentId === filterAgentId);
  const selected = rows.find((rec) => rec.id === selectedRecommendationId) || rows[0] || null;
  const canDecide = canDecideRecommendation(activePersona);

  if (loading) {
    return <div className="lux-ai-intel-recs__skeleton" aria-busy="true" />;
  }

  return (
    <div className="lux-ai-intel-recs">
      <div className="lux-ai-intel-recs__list">
        {rows.length ? (
          rows.map((rec) => (
            <button
              key={rec.id}
              type="button"
              className={classNames("lux-ai-intel-rec-card", {
                "is-selected": selected && selected.id === rec.id,
                [`is-${rec.status}`]: true,
              })}
              onClick={() => onSelectRecommendation(rec.id)}
            >
              <div className="lux-ai-intel-rec-card__top">
                <strong>{rec.title}</strong>
                <span className={classNames("lux-ai-intel-status", `is-${rec.status}`)}>{rec.status}</span>
              </div>
              <p>{rec.agentName}</p>
              <AiConfidenceBadge band={rec.confidenceBand} confidence={rec.confidence} />
            </button>
          ))
        ) : (
          <div className="lux-ai-intel-recs__empty">
            <i className="fe fe-inbox" aria-hidden="true" />
            <strong>No recommendations</strong>
            <p>Run an agent or clear filters to populate the decision queue.</p>
          </div>
        )}
      </div>

      {selected ? (
        <div className="lux-ai-intel-rec-detail">
          <header className="lux-ai-intel-rec-detail__head">
            <div className="lux-ai-intel-rec-detail__copy">
              <span className="lux-ai-intel-rec-detail__eyebrow">{selected.agentName}</span>
              <h3>{selected.title}</h3>
              <p>{selected.body}</p>
            </div>
            <AiConfidenceRing confidence={selected.confidence} band={selected.confidenceBand} />
          </header>

          <div className="lux-ai-intel-evidence">
            <h4>Evidence</h4>
            <ul>
              {(selected.evidence || []).map((item) => (
                <li key={`${selected.id}-${item.label}`}>
                  <strong>{item.label}</strong>
                  <span>{item.detail}</span>
                </li>
              ))}
            </ul>
          </div>

          {selected.status === AI_RECOMMENDATION_STATUSES.DRAFT && canDecide ? (
            <div className="lux-ai-intel-rec-detail__decision">
              <label className="lux-ai-intel-field">
                <span>Rationale (optional)</span>
                <textarea value={rationale} onChange={(event) => setRationale(event.target.value)} rows={3} />
              </label>
              <div className="lux-ai-intel-rec-detail__actions">
                <AiActionButton
                  variant="primary"
                  disabled={busyId === selected.id}
                  onClick={() => onDecide(selected.id, AI_RECOMMENDATION_DECISIONS.ACCEPT, rationale)}
                >
                  Accept
                </AiActionButton>
                <AiActionButton
                  variant="ghost"
                  disabled={busyId === selected.id}
                  onClick={() => onDecide(selected.id, AI_RECOMMENDATION_DECISIONS.DEFER, rationale)}
                >
                  Defer
                </AiActionButton>
                <AiActionButton
                  variant="ghost"
                  disabled={busyId === selected.id}
                  onClick={() => onDecide(selected.id, AI_RECOMMENDATION_DECISIONS.REJECT, rationale)}
                >
                  Reject
                </AiActionButton>
              </div>
            </div>
          ) : null}

          {selected.decidedAt ? (
            <footer className="lux-ai-intel-rec-detail__footer">
              <span>
                {selected.status} by {selected.decidedBy}
              </span>
              {selected.rationale ? <p>{selected.rationale}</p> : null}
            </footer>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
