import React, { Component } from "react";
import classNames from "classnames/bind";
import { benefitsService } from "_services/benefits/benefits.service";
import BenefitsLuxPage, {
  BenefitsActionButton,
  BenefitsLuxPanel,
  BenefitsQuickNav,
  BenefitsInsightPanel,
  BenefitsField,
  BenefitsFormGrid,
  BenefitsRegisterWrap,
  BenefitsRegisterPrimary,
  BenefitsToolbar,
  BenefitsStatusBadge,
  BenefitsSectionTabs,
} from "views/benefits/components/BenefitsLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class BenefitsCarrierFilesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    query: "",
    statusFilter: "ALL",
    form: { carrierName: "", periodKey: "", manualPending: false },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Benefits carrier files");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await benefitsService.listCarrierFiles();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load carrier files"),
      });
    }
  };

  handleExport = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.carrierName) return;
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.exportCarrierFile(form);
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { carrierName: "", periodKey: "", manualPending: false } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Export failed") });
    }
  };

  handleAck = async (fileRef) => {
    this.setState({ saving: true });
    await benefitsService.acknowledgeImport(fileRef, {
      contentSummary: "Manual carrier import acknowledged; FILE_BASED_NOT_LIVE_EDI",
    });
    this.setState({ saving: false });
    this.load();
  };

  getFiltered = () => {
    const { rows, query, statusFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return rows.filter((row) => {
      if (statusFilter !== "ALL" && String(row.status || "").toUpperCase() !== statusFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [row.fileRef, row.carrierName, row.periodKey, row.status, row.direction]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, rows, saving, form, query, statusFilter } = this.state;
    const filtered = this.getFiltered();
    const pending = rows.filter(
      (r) => r.status === "GENERATED" || r.status === "MANUAL_PENDING"
    ).length;

    const kpiCards = [
      {
        id: "files",
        label: "Carrier files",
        value: rows.length,
        hint: "Exchange records",
        tone: "amber",
        icon: "fe fe-file-text",
      },
      {
        id: "pending",
        label: "Pending ack",
        value: pending,
        hint: "Generated / manual",
        tone: pending ? "amber" : "green",
        icon: "fe fe-clock",
      },
      {
        id: "acked",
        label: "Acknowledged",
        value: rows.filter((r) => r.status === "ACKNOWLEDGED").length,
        hint: "Import confirmed",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "mode",
        label: "Mode",
        value: "File",
        hint: "Not live EDI",
        tone: "slate",
        icon: "fe fe-hard-drive",
      },
    ];

    return (
      <BenefitsLuxPage
        testId="benefits-carrier-files-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        kpiCards={kpiCards}
        pageMeta={{
          tone: "amber",
          icon: "fe fe-file-text",
          eyebrow: "People · Benefits",
          titleLead: "Carrier",
          titleAccent: "files",
          lede: "File-based carrier exchange only — export creates GENERATED or MANUAL_PENDING; acknowledge sets ACKNOWLEDGED. Does not claim live EDI.",
        }}
        onRefresh={this.load}
        refreshLoading={loading}
        heroActions={<><BenefitsActionButton to="/benefits/enrollment" icon="fe fe-user-check" variant="ghost">
              Enrollment
            </BenefitsActionButton>
          </>}
      >
        <BenefitsSectionTabs active="/benefits/carrier-files" />
        <BenefitsQuickNav />
        <BenefitsInsightPanel
          insights={[
            {
              id: "file",
              tone: "amber",
              icon: "fe fe-info",
              title: "File-based only",
              copy: "Exports do not transmit live EDI. Treat GENERATED as ready for manual carrier drop.",
              path: null,
            },
            {
              id: "enroll",
              tone: "indigo",
              icon: "fe fe-user-check",
              title: "Approve enrollments first",
              copy: "Carrier files usually follow approved coverage elections.",
              path: "/benefits/enrollment",
            },
            {
              id: "report",
              tone: "blue",
              icon: "fe fe-bar-chart-2",
              title: "Track exchange volume",
              copy: "Reports aggregate carrier file counts by status.",
              path: "/benefits/reports",
            },
          ]}
        />

        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load carrier files">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}

        <BenefitsLuxPanel
          title="Generate export"
          meta="Creates a file-exchange record for the selected carrier and period"
          icon="fe fe-download"
          accent="amber"
        >
          <form className="lux-benefits-form" onSubmit={this.handleExport}>
            <BenefitsFormGrid columns={4}>
              <BenefitsField label="Carrier name" className="is-span-2">
                <input
                  className="form-control"
                  placeholder="e.g. Acme Health"
                  value={form.carrierName}
                  onChange={(e) => this.setState({ form: { ...form, carrierName: e.target.value } })}
                  required
                />
              </BenefitsField>
              <BenefitsField label="Period" hint="YYYY-MM">
                <input
                  className="form-control"
                  placeholder="2026-07"
                  value={form.periodKey}
                  onChange={(e) => this.setState({ form: { ...form, periodKey: e.target.value } })}
                />
              </BenefitsField>
              <BenefitsField label="Manual pending">
                <label className="lux-benefits-switch">
                  <input
                    type="checkbox"
                    checked={form.manualPending}
                    onChange={(e) =>
                      this.setState({ form: { ...form, manualPending: e.target.checked } })
                    }
                  />
                  <span>Mark as MANUAL_PENDING</span>
                </label>
              </BenefitsField>
            </BenefitsFormGrid>
            <div className="lux-benefits-form__actions">
              <BenefitsActionButton
                type="submit"
                icon="fe fe-download"
                disabled={saving || !form.carrierName}
              >
                {saving ? "Generating…" : "Generate export"}
              </BenefitsActionButton>
            </div>
          </form>
        </BenefitsLuxPanel>

        <BenefitsLuxPanel
          title="Carrier file register"
          meta={`${filtered.length} of ${rows.length} file${rows.length === 1 ? "" : "s"}`}
          icon="fe fe-list"
          accent="blue"
        >
          <BenefitsToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search carrier, period, ref…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          >
            <div className="lux-hrms-dash__filter-group">
              {["ALL", "GENERATED", "MANUAL_PENDING", "ACKNOWLEDGED"].map((value) => (
                <button
                  key={value}
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": statusFilter === value,
                  })}
                  onClick={() => this.setState({ statusFilter: value })}
                >
                  {value === "ALL"
                    ? "All"
                    : value
                        .split("_")
                        .map((p) => p.charAt(0) + p.slice(1).toLowerCase())
                        .join(" ")}
                </button>
              ))}
            </div>
          </BenefitsToolbar>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading carrier files"
              description="Fetching file-exchange records."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No carrier files yet" : "No matching files"}
              description={
                rows.length === 0
                  ? "Generate an export to create a file-based carrier exchange record."
                  : "Try a different search or status filter."
              }
              showCreate={false}
            />
          ) : (
            <BenefitsRegisterWrap>
              <table className="lux-benefits-register">
                <thead>
                  <tr>
                    <th>File</th>
                    <th>Direction</th>
                    <th>Carrier</th>
                    <th>Period</th>
                    <th>Status</th>
                    <th>Records</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((r) => (
                    <tr key={r.fileRef || r.id}>
                      <td>
                        <BenefitsRegisterPrimary
                          title={r.fileRef || `File ${r.id}`}
                          meta={r.direction || "EXPORT"}
                          icon="fe fe-file-text"
                          tone="amber"
                        />
                      </td>
                      <td>
                        <span className="lux-benefits-chip">{r.direction || "—"}</span>
                      </td>
                      <td>{r.carrierName || "—"}</td>
                      <td>{r.periodKey || "—"}</td>
                      <td>
                        <BenefitsStatusBadge status={r.status} />
                      </td>
                      <td>{r.recordCount != null ? r.recordCount : "—"}</td>
                      <td>
                        {(r.status === "GENERATED" || r.status === "MANUAL_PENDING") && (
                          <BenefitsActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            disabled={saving}
                            onClick={() => this.handleAck(r.fileRef)}
                          >
                            Acknowledge import
                          </BenefitsActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </BenefitsRegisterWrap>
          )}
        </BenefitsLuxPanel>
      </BenefitsLuxPage>
    );
  }
}

export default BenefitsCarrierFilesPage;
