import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isResourcePlanningEnabled } from "config/resource-planning.config";
import {
  buildProficiencyDistribution,
  buildSkillCategoryBreakdown,
  buildSkillCategoryOptions,
  buildSkillMatrixInsights,
  buildSkillMatrixMetrics,
  filterSkillProfiles,
  PROFICIENCY_FILTER_OPTIONS,
} from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import {
  ResourcesActionButton,
  ResourcesHeroActions,
  ResourcesKpiStrip,
  ResourcesRegisterAtelier,
} from "views/resources/components/ResourcesLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import SkillsCategoryPanel from "views/resources/components/SkillsCategoryPanel";
import SkillsMatrixRegister from "views/resources/components/SkillsMatrixRegister";
import SkillsProficiencyPanel from "views/resources/components/SkillsProficiencyPanel";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class SkillsMatrixPage extends Component {
  state = {
    profiles: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    categoryFilter: "ALL",
    proficiencyFilter: "ALL",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Skills matrix");
    this.loadProfiles();
  }

  loadProfiles = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await resourcePlanningService.listSkillProfiles();
      this.setState({
        profiles: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load skills matrix.",
        profiles: [],
      });
    }
  };

  getFilteredProfiles = () => {
    const { profiles, query, categoryFilter, proficiencyFilter } = this.state;
    return filterSkillProfiles(profiles, {
      query,
      category: categoryFilter,
      proficiency: proficiencyFilter,
    });
  };

  render() {
    if (!isResourcePlanningEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Resources"
          reason="Resource planning is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, query, categoryFilter, proficiencyFilter, profiles } =
      this.state;
    const filtered = this.getFilteredProfiles();
    const metrics = buildSkillMatrixMetrics(profiles);
    const categories = buildSkillCategoryOptions(profiles);
    const insights = loading ? [] : buildSkillMatrixInsights(profiles, metrics);
    const categoryBreakdown = buildSkillCategoryBreakdown(profiles);
    const proficiencyDistribution = buildProficiencyDistribution(profiles);

    const kpiCards = [
      {
        id: "profiles",
        label: "Skill profiles",
        value: metrics.profileCount,
        hint: `${metrics.skillCount} unique skills tracked`,
        tone: "primary",
        icon: "fe fe-layers",
      },
      {
        id: "people",
        label: "People covered",
        value: metrics.employeeCount,
        hint: "Active proficiency records",
        tone: "slate",
        icon: "fe fe-users",
      },
      {
        id: "experts",
        label: "Expert ratings",
        value: metrics.expertCount,
        hint: "Ready for lead roles",
        tone: "green",
        icon: "fe fe-award",
      },
      {
        id: "certified",
        label: "Certified",
        value: metrics.certifiedCount,
        hint: "Verified credentials",
        tone: "violet",
        icon: "fe fe-shield",
      },
      {
        id: "gaps",
        label: "Upskill gaps",
        value: metrics.gapCount,
        hint: metrics.gapCount > 0 ? "Needs coaching" : "No critical gaps",
        tone: metrics.gapCount > 0 ? "rose" : "green",
        icon: "fe fe-trending-up",
      },
    ];

    return (
      <div
        className="lux-skills-page lux-register-page lux-skills-lux"
        data-testid="page-resources-skills"
      >
        <PageDataSourceReporter dataSource={dataSource} />
        <div className="lux-skills-lux__ambient" aria-hidden="true">
          <span className="lux-skills-lux__orb lux-skills-lux__orb--a" />
          <span className="lux-skills-lux__orb lux-skills-lux__orb--b" />
        </div>

        <LuxModuleIntro
          meta={DENSE_PAGE_META.skillsMatrix}
          className="lux-skills-hero"
          actions={
            <ResourcesHeroActions dataSource={dataSource}>
<ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Team capacity
              </ResourcesActionButton>
              <ResourcesActionButton
                to="/project/capacity?tab=roster"
                icon="fe fe-users"
                variant="primary"
              >
                View roster
              </ResourcesActionButton>
            </ResourcesHeroActions>
          }
          onRefresh={this.loadProfiles}
          refreshLoading={loading}
        />

        <div className="lux-skills-page__body">
          <ResourcesKpiStrip cards={kpiCards} loading={loading} className="lux-skills-kpi-strip" />

          {loadError && (
            <div className="lux-employee-360__error lux-skills__error" role="alert">
              <span>{loadError}</span>
              <ResourcesActionButton variant="ghost" onClick={this.loadProfiles}>
                Retry
              </ResourcesActionButton>
            </div>
          )}

          <AdminInsightStrip insights={insights} className="lux-skills-insights" />

          <div className="lux-skills-analytics-grid">
            <SkillsCategoryPanel
              breakdown={categoryBreakdown}
              loading={loading}
              activeCategory={categoryFilter}
              onCategorySelect={(value) => this.setState({ categoryFilter: value })}
            />
            <SkillsProficiencyPanel distribution={proficiencyDistribution} loading={loading} />
          </div>

          <ResourcesRegisterAtelier
            tone="violet"
            kickerIcon="fe fe-grid"
            kicker="Team register"
            title="Proficiency register"
            subtitle="Compact skill depth across the team — filter, triage gaps, and open Employee 360"
            pulseCards={[
              { id: "shown", label: "Shown", value: filtered.length, tone: "violet" },
              { id: "experts", label: "Expert", value: metrics.expertCount, tone: "green" },
              { id: "certified", label: "Certified", value: metrics.certifiedCount, tone: "sky" },
              {
                id: "gaps",
                label: "Gaps",
                value: metrics.gapCount,
                tone: metrics.gapCount > 0 ? "rose" : "green",
              },
            ]}
            actions={
              <ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Capacity planner
              </ResourcesActionButton>
            }
            search={{
              placeholder: "Search people, skills, or categories…",
              value: query,
              onChange: (event) => this.setState({ query: event.target.value }),
            }}
            filterGroups={[
              {
                id: "category",
                ariaLabel: "Category filters",
                value: categoryFilter,
                onChange: (value) => this.setState({ categoryFilter: value }),
                options: categories.map((value) => ({
                  value,
                  label: value === "ALL" ? "All categories" : value,
                })),
              },
              {
                id: "proficiency",
                ariaLabel: "Proficiency filters",
                variant: "priority",
                value: proficiencyFilter,
                onChange: (value) => this.setState({ proficiencyFilter: value }),
                options: PROFICIENCY_FILTER_OPTIONS,
              },
            ]}
          >
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading skills matrix"
                description="Building proficiency profiles and coverage analytics."
              />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-grid"
                title="No skill profiles match"
                description="Adjust filters or expand the team roster to populate the matrix."
              />
            ) : (
              <SkillsMatrixRegister rows={filtered} loading={loading} />
            )}
          </ResourcesRegisterAtelier>
        </div>
      </div>
    );
  }
}

export default SkillsMatrixPage;
