/**
 * F21-T7 — Persona-aware daily briefing draft from workspace home aggregation.
 */

const PERSONA_GREETING = {
  EMPLOYEE: "Your day at a glance",
  MANAGER: "Team operating pulse",
  HR_ADMIN: "People operations briefing",
  PAYROLL_MANAGER: "Payroll readiness pulse",
  FINANCE_MANAGER: "Finance and delivery signals",
  PROJECT_MANAGER: "Delivery focus for today",
  RESOURCE_MANAGER: "Capacity and staffing pulse",
  EXECUTIVE: "Enterprise operating summary",
  ADMIN: "Platform and compliance pulse",
};

export function buildWorkspaceDailyBriefing(dashboard, activePersona) {
  if (!dashboard) {
    return null;
  }

  const persona = activePersona || dashboard.activePersona || "EMPLOYEE";
  const metrics = dashboard.metrics || {};
  const priorities = [];
  const focusAreas = [];

  if (metrics.pendingApprovals > 0) {
    priorities.push({
      id: "approvals",
      tone: metrics.highPriorityApprovals > 0 ? "rose" : "mint",
      icon: "fe fe-inbox",
      title:
        metrics.highPriorityApprovals > 0
          ? `Clear ${metrics.highPriorityApprovals} urgent approval(s) first`
          : `Review ${metrics.pendingApprovals} pending approval(s)`,
      copy:
        metrics.highPriorityApprovals > 0
          ? "High-priority leave, timesheet, or attendance requests are aging in your inbox."
          : "Sign off requests across leave, timesheet, and attendance before end of day.",
      evidence: `${metrics.pendingApprovals} pending across ${metrics.approvalDomains || 1} domain(s)`,
      path: "/workspace/approvals",
    });
    focusAreas.push("Approvals");
  }

  if (metrics.highPriorityWork > 0) {
    priorities.push({
      id: "work",
      tone: "amber",
      icon: "fe fe-check-square",
      title: `Triage ${metrics.highPriorityWork} high-priority work item(s)`,
      copy: "Open queue items have due dates — start with approvals and timesheet tasks.",
      evidence: `${metrics.openWork} open item(s), ${metrics.dueSoonWork} due soon`,
      path: "/workspace/my-work",
    });
    focusAreas.push("My work");
  }

  if (metrics.unreadNotifications > 0) {
    priorities.push({
      id: "notifications",
      tone: metrics.highPriorityNotifications > 0 ? "blue" : "slate",
      icon: "fe fe-bell",
      title: `Catch up on ${metrics.unreadNotifications} unread alert(s)`,
      copy:
        metrics.highPriorityNotifications > 0
          ? `${metrics.highPriorityNotifications} notification(s) flagged as urgent.`
          : "Review alerts across people, payroll, and projects when queue is clear.",
      evidence: `${metrics.unreadNotifications} unread notification(s)`,
      path: "/workspace/notifications",
    });
    focusAreas.push("Notifications");
  }

  if (metrics.timesheetTasks > 0) {
    priorities.push({
      id: "timesheet",
      tone: "amber",
      icon: "fe fe-calendar",
      title: "Timesheet compliance check",
      copy: "A timesheet submission is due — submit hours before payroll lock.",
      evidence: `${metrics.timesheetTasks} open timesheet task(s)`,
      path: "/people/timesheet",
    });
    focusAreas.push("Timesheet compliance");
  }

  if (priorities.length === 0) {
    priorities.push({
      id: "clear",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "You're on track today",
      copy: "No urgent approvals, high-priority work, or unread alerts flagged in your workspace.",
      evidence: "Queue and inbox are manageable",
      path: "/workspace/my-work",
    });
    focusAreas.push("Steady state");
  }

  const headline = buildBriefingHeadline(metrics, persona);
  const confidence = computeBriefingConfidence(metrics, priorities.length);

  return {
    persona,
    greeting: PERSONA_GREETING[persona] || PERSONA_GREETING.EMPLOYEE,
    headline,
    generatedAt: new Date().toISOString(),
    confidence,
    focusAreas: focusAreas.slice(0, 4),
    priorities: priorities.slice(0, 4),
    disclaimer:
      "Draft briefing — recommendations are generated from workspace signals only. Live AI integration is planned for a future release.",
  };
}

export function buildBriefingHeadline(metrics, persona) {
  const urgent =
    (metrics.highPriorityApprovals || 0) +
    (metrics.highPriorityWork || 0) +
    (metrics.highPriorityNotifications || 0);

  if (urgent > 0) {
    return `${urgent} urgent signal(s) need attention today`;
  }
  if ((metrics.pendingApprovals || 0) > 0) {
    return `${metrics.pendingApprovals} approval(s) waiting in your inbox`;
  }
  if ((metrics.openWork || 0) > 0) {
    return `${metrics.openWork} open work item(s) in your queue`;
  }
  if (persona === "EXECUTIVE" || persona === "ADMIN") {
    return "Enterprise workspace is steady — review widgets for drift";
  }
  return "Your workspace is clear — focus on planned work";
}

export function computeBriefingConfidence(metrics, priorityCount) {
  let score = 0.55;
  if (metrics.pendingApprovals != null) score += 0.08;
  if (metrics.openWork != null) score += 0.08;
  if (metrics.unreadNotifications != null) score += 0.06;
  if (priorityCount > 0 && priorityCount <= 4) score += 0.1;
  return Math.min(0.92, Math.round(score * 100) / 100);
}
