import React from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

/**
 * Rich empty state for planner timeline / gantt lanes.
 */
export default function PlannerScheduleEmptyState({ title, detail, className }) {
  if (!title) return null;

  return (
    <LuxRegisterEmptyState
      variant="task-activities"
      className={["lux-register-empty--compact lux-planner-schedule-empty-rich", className]
        .filter(Boolean)
        .join(" ")}
      eyebrow="Planning horizon"
      title={title}
      description={detail}
      hints={[
        "Shift the week range or horizon to see more assignments",
        "Adjust team and employee filters in the header",
        "Assign work from the roster or timeline views",
      ]}
    />
  );
}
