import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { userActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { isAppLoginEnabled } from "../profile/profilePage.utils";

const MIN_PASSWORD_LENGTH = 9;

function SecurityField({ label, value, icon, readOnly }) {
  return (
    <div className="profile-security__field">
      <span className="profile-security__field-label">{label}</span>
      <span className={classNames("profile-security__field-value", { "is-readonly": readOnly })}>
        {icon && <i className={`${icon} profile-security__field-icon`} aria-hidden="true" />}
        {value || "—"}
      </span>
    </div>
  );
}

function PasswordInput({
  id,
  name,
  label,
  value,
  type,
  placeholder,
  onChange,
  onToggleVisibility,
  showToggle,
  autoComplete,
  disabled,
}) {
  return (
    <div className="profile-security__input-group">
      <label className="profile-security__input-label" htmlFor={id}>
        {label}
      </label>
      <div className="profile-security__input-wrap">
        <span className="profile-security__input-icon" aria-hidden="true">
          <i className="fe fe-lock" />
        </span>
        <input
          id={id}
          name={name}
          type={type}
          className="profile-security__input"
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          autoComplete={autoComplete}
          disabled={disabled}
        />
        {showToggle && (
          <button
            type="button"
            className="profile-security__input-toggle"
            onClick={onToggleVisibility}
            disabled={disabled}
            aria-label={type === "password" ? "Show password" : "Hide password"}
          >
            <i className={`fe ${type === "text" ? "fe-eye-off" : "fe-eye"}`} aria-hidden="true" />
          </button>
        )}
      </div>
    </div>
  );
}

class ProfilePageSideSecuritySettings extends PureComponent {
  constructor() {
    super();
    this.state = {
      passwordUpdateRequest: {
        newPassword: "",
        currentPassword: "",
        email: null,
        employeeId: null,
      },
      passwordError: false,
      passwordType: "password",
    };
  }

  componentDidMount() {
    const user = commonUtils.getCurrentUser();
    this.setState((prevState) => ({
      passwordUpdateRequest: {
        ...prevState.passwordUpdateRequest,
        employeeId: user && user.id,
        email: user && user.email,
      },
    }));
  }

  getAccountSnapshot = () => {
    const { selectedEmployeeInfo } = this.props;
    const user = commonUtils.getCurrentUser();
    const subject = selectedEmployeeInfo || user;

    const teamName =
      (subject &&
        subject.defaultUserTeamDetails &&
        subject.defaultUserTeamDetails.name) ||
      commonUtils.getCurrentUserTeamName();

    return {
      name: (subject && subject.name) || (user && user.name),
      email: (subject && subject.email) || (user && user.email),
      team: teamName,
    };
  };

  onChange = (e) => {
    const { name, value } = e.target;
    this.setState((prevState) => ({
      passwordError: false,
      passwordUpdateRequest: {
        ...prevState.passwordUpdateRequest,
        [name]: value,
      },
    }));
  };

  getLoginSubject = () => {
    const { selectedEmployeeInfo, currentUser } = this.props;
    return selectedEmployeeInfo || currentUser || commonUtils.getCurrentUser();
  };

  isPasswordChangeAllowed = () => isAppLoginEnabled(this.getLoginSubject());

  handleUpdatePassword = () => {
    if (!this.isPasswordChangeAllowed()) return;

    const { passwordUpdateRequest } = this.state;
    const valid =
      passwordUpdateRequest &&
      passwordUpdateRequest.newPassword &&
      passwordUpdateRequest.currentPassword &&
      passwordUpdateRequest.newPassword.length >= MIN_PASSWORD_LENGTH;

    if (valid) {
      store.dispatch(this.props.updatePassword(passwordUpdateRequest));
      this.setState({ passwordError: false });
      return;
    }
    this.setState({ passwordError: true });
  };

  togglePasswordType = () => {
    this.setState((prev) => ({
      passwordType: prev.passwordType === "text" ? "password" : "text",
    }));
  };

  renderAlerts(passwordChangeAllowed) {
    if (!passwordChangeAllowed) {
      return (
        <div className="profile-security__alerts" role="status">
          <p className="profile-security__alert is-warning">
            <i className="fe fe-slash" aria-hidden="true" />
            App login is disabled for this account. Password cannot be changed until an administrator
            re-enables app login under Platform access.
          </p>
        </div>
      );
    }

    const { updatePasswordSuccess, updatePasswordError } = this.props;
    const { passwordError } = this.state;

    if (!updatePasswordSuccess && !updatePasswordError && !passwordError) {
      return null;
    }

    return (
      <div className="profile-security__alerts" role="status">
        {updatePasswordSuccess && (
          <p className="profile-security__alert is-success">
            <i className="fe fe-check-circle" aria-hidden="true" />
            Password updated successfully.
          </p>
        )}
        {updatePasswordError && (
          <p className="profile-security__alert is-error">
            <i className="fe fe-alert-circle" aria-hidden="true" />
            Unable to update password. Check your current password and try again.
          </p>
        )}
        {passwordError && (
          <p className="profile-security__alert is-error">
            <i className="fe fe-alert-circle" aria-hidden="true" />
            New password must be at least {MIN_PASSWORD_LENGTH} characters and both fields are required.
          </p>
        )}
      </div>
    );
  }

  render() {
    const { passwordUpdateRequest, passwordType, passwordError } = this.state;
    const { updatePasswordSuccess } = this.props;
    const account = this.getAccountSnapshot();
    const passwordChangeAllowed = this.isPasswordChangeAllowed();
    const newPasswordLen = (passwordUpdateRequest.newPassword || "").length;
    const strengthPct = Math.min(100, Math.round((newPasswordLen / MIN_PASSWORD_LENGTH) * 100));

    return (
      <div className="profile-security-wrap">
        <div className="profile-security">
          <section className="profile-section profile-security__section">
            <header className="profile-section__head">
              <span className="profile-section__icon">
                <i className="fe fe-user" aria-hidden="true" />
              </span>
              <div>
                <h3 className="profile-section__title">Account identity</h3>
                <p className="profile-section__sub">
                  Sign-in details tied to this profile — contact an admin to change username or email
                </p>
              </div>
            </header>
            <div className="profile-section__body">
              <div className="profile-security__identity-grid">
                <SecurityField label="Display name" value={account.name} icon="fe fe-user" readOnly />
                <SecurityField label="Email" value={account.email} icon="fe fe-mail" readOnly />
                <SecurityField label="Default team" value={account.team} icon="fe fe-users" readOnly />
              </div>
            </div>
          </section>

          <section
            className={classNames(
              "profile-section profile-security__section profile-security__section--password",
              { "is-disabled": !passwordChangeAllowed }
            )}
          >
            <header className="profile-section__head">
              <span className="profile-section__icon profile-section__icon--shield">
                <i className="fe fe-shield" aria-hidden="true" />
              </span>
              <div>
                <h3 className="profile-section__title">Change password</h3>
                <p className="profile-section__sub">
                  {passwordChangeAllowed
                    ? "Use a strong password you do not reuse on other sites"
                    : "Unavailable while app login is disabled for this account"}
                </p>
              </div>
            </header>
            <div className="profile-section__body">
              {this.renderAlerts(passwordChangeAllowed)}

              <div className="profile-security__requirements" aria-hidden={!passwordChangeAllowed}>
                <span className="profile-security__requirements-label">Password strength</span>
                <div className="profile-security__strength">
                  <span
                    className={classNames("profile-security__strength-bar", {
                      "is-weak": newPasswordLen > 0 && newPasswordLen < MIN_PASSWORD_LENGTH,
                      "is-good": newPasswordLen >= MIN_PASSWORD_LENGTH,
                    })}
                    style={{ width: `${newPasswordLen ? strengthPct : 0}%` }}
                  />
                </div>
                <p className="profile-security__requirements-hint">
                  Minimum {MIN_PASSWORD_LENGTH} characters
                  {updatePasswordSuccess && !passwordError && " · last update saved"}
                </p>
              </div>

              <div className="profile-security__form">
                <PasswordInput
                  id="profile-current-password"
                  name="currentPassword"
                  label="Current password"
                  value={passwordUpdateRequest.currentPassword}
                  type="password"
                  placeholder="Enter current password"
                  onChange={this.onChange}
                  autoComplete="current-password"
                  disabled={!passwordChangeAllowed}
                />
                <PasswordInput
                  id="profile-new-password"
                  name="newPassword"
                  label="New password"
                  value={passwordUpdateRequest.newPassword}
                  type={passwordType}
                  placeholder="Enter new password"
                  onChange={this.onChange}
                  onToggleVisibility={this.togglePasswordType}
                  showToggle
                  autoComplete="new-password"
                  disabled={!passwordChangeAllowed}
                />
              </div>

              <footer className="profile-security__foot">
                <button
                  type="button"
                  className="profile-security__submit"
                  onClick={this.handleUpdatePassword}
                  disabled={!passwordChangeAllowed}
                >
                  <i className="fe fe-check" aria-hidden="true" />
                  Update password
                </button>
              </footer>
            </div>
          </section>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  updatePasswordSuccess: state.authentication.updatePasswordSuccess,
  updatePasswordError: state.authentication.updatePasswordError,
});

const mapDispatchToProps = (dispatch) => ({
  updatePassword: userActions.updatePassword,
});

export default connect(mapStateToProps, mapDispatchToProps)(ProfilePageSideSecuritySettings);
