import React, { Component } from "react";
import classNames from "classnames";

/**
 * F01-T2: Vertical module icon rail (left strip inside PageLeftMenu — no extra width).
 */
class ModuleMenuRail extends Component {
  railRef = React.createRef();

  componentDidMount() {
    this.initTooltips();
  }

  componentDidUpdate() {
    this.initTooltips();
  }

  componentWillUnmount() {
    this.destroyTooltips();
  }

  getTooltipApi = () => {
    if (typeof window === "undefined") {
      return null;
    }
    return window.jQuery || window.$ || null;
  };

  destroyTooltips = () => {
    const $ = this.getTooltipApi();
    if (!$ || !this.railRef.current) {
      return;
    }
    $(this.railRef.current)
      .find('[data-toggle="tooltip"]')
      .tooltip("dispose");
  };

  initTooltips = () => {
    const $ = this.getTooltipApi();
    if (!$ || !this.railRef.current || !$.fn || !$.fn.tooltip) {
      return;
    }

    const $els = $(this.railRef.current).find('[data-toggle="tooltip"]');
    $els.tooltip("dispose");
    $els.tooltip({
      placement: "right",
      container: "body",
      boundary: "window",
      trigger: "hover",
      template:
        '<div class="tooltip lux-module-rail-tooltip" role="tooltip">' +
        '<div class="arrow"></div>' +
        '<div class="tooltip-inner"></div></div>',
    });
  };

  render() {
    const { groups, activeModuleId, onSelectModule } = this.props;

    if (!groups || groups.length === 0) {
      return null;
    }

    return (
      <nav
        ref={this.railRef}
        className="lux-module-rail"
        aria-label="Enterprise modules"
      >
        <ul className="lux-module-rail__list">
          {groups.map((group) => {
            const isActive = group.id === activeModuleId;
            return (
              <li key={group.id} className="lux-module-rail__item">
                <button
                  type="button"
                  className={classNames("lux-module-rail__btn", { "is-active": isActive })}
                  onClick={() => onSelectModule(group.id)}
                  title={group.menuName}
                  aria-label={group.menuName}
                  aria-current={isActive ? "true" : undefined}
                  data-toggle="tooltip"
                  data-placement="right"
                  data-container="body"
                  data-ga-action="module_rail_select"
                  data-ga-category="navigation"
                  data-ga-label={group.id}
                >
                  <span className="lux-module-rail__icon" aria-hidden="true">
                    <i className={group.icon} />
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      </nav>
    );
  }
}

export default ModuleMenuRail;
