import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class MultiOptionSingleSelectInput extends Component {
  onChange = (isChecked, value) => {
    value = value.trim();
    if (isChecked === false) {
      value = null;
    }
    this.props.onChange({ ...this.props.questionConfig, answer: value });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);
    const groupName = `lux-fb-radio-${questionConfig.id}`;

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
          {questionConfig.questionOptions &&
            questionConfig.questionOptions.split(",").map((value) => {
              const trimmed = value.trim();
              return (
                <div key={trimmed} className="radioField">
                  <input
                    type="radio"
                    name={groupName}
                    className="radio"
                    id={`${groupName}-${trimmed}`}
                    onChange={(e) => this.onChange(e.target.checked, value)}
                    disabled={readonly}
                    checked={questionConfig.answer === trimmed}
                  />
                  <label htmlFor={`${groupName}-${trimmed}`}>{trimmed}</label>
                </div>
              );
            })}
        </div>
      </div>
    );
  }
}
export default MultiOptionSingleSelectInput;
