import React, { Component } from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import HowToUseLink from "views/common/fragments/HowToUseLink";
import ApplicationConfigTree from "./ApplicationConfigTree";
import { countTreeNodes, normalizeSearch } from "./appConfigTree.utils";

const TABS = [
  { id: "org", label: "Organization", icon: "fe-git-branch" },
  { id: "role", label: "Roles", icon: "fe-shield" },
];

class ApplicationConfigLeftMenu extends Component {
  treeRef = React.createRef();

  constructor() {
    super();
    this.state = {
      activeTab: "org",
      searchQuery: "",
      createParentItem: null,
      selectedMenuCategory: null,
    };
  }

  componentDidUpdate(prevProps) {
    if (
      this.props.appConfigMenuSelection &&
      prevProps.appConfigMenuSelection !== this.props.appConfigMenuSelection
    ) {
      const tab = this.props.appConfigMenuSelection.type === "role" ? "role" : "org";
      if (tab !== this.state.activeTab) {
        this.setState({ activeTab: tab });
      }
    }
  }

  handleTabChange = (tabId) => {
    this.setState({ activeTab: tabId, searchQuery: "", createParentItem: null });
  };

  handleSearchChange = (event) => {
    this.setState({ searchQuery: event.target.value });
  };

  clearSearch = () => {
    this.setState({ searchQuery: "" });
  };

  handleAppConfigMenuSelect = (id, type, category) => {
    if (!this.props.appConfigMenuSelection || id !== this.props.appConfigMenuSelection.id) {
      this.setState({ selectedMenuCategory: category, activeTab: type });
      this.props.handleAppConfigMenuSelect(id, type, category);
    }
  };

  handleCreateButtonClick = () => {
    const { appConfigMenuSelection } = this.props;
    if (!appConfigMenuSelection) return;
    this.setState({
      createParentItem: {
        id: appConfigMenuSelection.id,
        type: appConfigMenuSelection.type,
      },
    });
  };

  handleClearButtonClick = () => {
    this.setState({ createParentItem: null });
  };

  canCreate = () => {
    const { appConfigMenuSelection } = this.props;
    const { activeTab, selectedMenuCategory } = this.state;
    return (
      appConfigMenuSelection &&
      appConfigMenuSelection.type === activeTab &&
      appConfigMenuSelection.category != "Team" &&
      selectedMenuCategory !== "Team"
    );
  };

  getActiveMenuData = () => {
    const { activeTab } = this.state;
    if (activeTab === "role") {
      return this.props.roleMenuData;
    }
    return this.props.orgMenuData;
  };

  render() {
    const { activeTab, searchQuery } = this.state;
    const menuData = this.getActiveMenuData();
    const itemCount = countTreeNodes(menuData);
    const query = normalizeSearch(searchQuery);
    const selection = this.props.appConfigMenuSelection;

    return (
      <nav className="lux-ac-nav" aria-label="Configuration navigator">
        <header className="lux-ac-nav__header">
          <h3 className="lux-ac-nav__title">Configuration navigator</h3>
          <HowToUseLink
            href="/documentation/hrms/application-config.html"
            testId="appconfig-howto-link"
            className="lux-ac-nav__howto"
          />
        </header>

        <div className="lux-ac-nav__tabs" role="tablist" aria-label="Configuration type">
          {TABS.map((tab) => {
            const count =
              tab.id === "org"
                ? countTreeNodes(this.props.orgMenuData)
                : countTreeNodes(this.props.roleMenuData);
            return (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={activeTab === tab.id}
                className={`lux-ac-nav__tab${activeTab === tab.id ? " is-active" : ""}`}
                onClick={() => this.handleTabChange(tab.id)}
              >
                <i className={`fe ${tab.icon}`} aria-hidden="true" />
                <span>{tab.label}</span>
                <span className="lux-ac-nav__tab-count">{count}</span>
              </button>
            );
          })}
        </div>

        <div className="lux-ac-nav__toolbar">
          <label className="lux-ac-nav__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              value={searchQuery}
              onChange={this.handleSearchChange}
              placeholder={`Search ${activeTab === "org" ? "organization" : "roles"}...`}
              aria-label="Filter tree"
            />
            {searchQuery && (
              <button type="button" className="lux-ac-nav__search-clear" onClick={this.clearSearch} aria-label="Clear search">
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            )}
          </label>
          {this.canCreate() && (
            <button
              type="button"
              className="lux-ac-nav__add"
              title="Add child item"
              onClick={this.handleCreateButtonClick}
            >
              <i className="fe fe-plus" aria-hidden="true" />
            </button>
          )}
          <button
            type="button"
            className="lux-ac-nav__icon-btn"
            title="Expand all"
            onClick={() => this.treeRef.current && this.treeRef.current.expandAll()}
          >
            <i className="fe fe-maximize-2" aria-hidden="true" />
          </button>
          <button
            type="button"
            className="lux-ac-nav__icon-btn"
            title="Collapse all"
            onClick={() => this.treeRef.current && this.treeRef.current.collapseAll()}
          >
            <i className="fe fe-minimize-2" aria-hidden="true" />
          </button>
        </div>

        {selection && selection.type === activeTab && (
          <div className="lux-ac-nav__selection">
            <span className="lux-ac-nav__selection-label">Selected</span>
            <strong>{selection.id != null ? this.getSelectionName(menuData, selection.id) : "—"}</strong>
          </div>
        )}

        <div className="lux-ac-nav__tree-wrap">
          {menuData ? (
            <ApplicationConfigTree
              ref={this.treeRef}
              type={activeTab}
              rootNode={menuData}
              isRootTree
              selection={selection}
              searchQuery={searchQuery}
              createParentItem={this.state.createParentItem}
              onSelect={this.handleAppConfigMenuSelect}
              onCreateItem={this.props.handleCreateAppConfigItem}
              onClearCreate={this.handleClearButtonClick}
            />
          ) : (
            <div className="lux-ac-tree-empty" aria-busy="true" aria-label="Loading configuration tree">
              <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
                {[1, 2, 3, 4, 5, 6, 7, 8].map((key) => (
                  <Skeleton key={key} height={28} borderRadius={8} style={{ marginBottom: 8 }} />
                ))}
              </SkeletonTheme>
            </div>
          )}
        </div>

        <footer className="lux-ac-nav__footer">
          <span>
            {query ? "Filtered" : "Showing"} {itemCount} {activeTab === "org" ? "units" : "roles"}
          </span>
        </footer>
      </nav>
    );
  }

  getSelectionName = (node, id) => {
    if (!node) return "Item";
    if (node.id === id && node.name) return node.name;
    for (const child of node.nodes || []) {
      const name = this.getSelectionName(child, id);
      if (name !== "Item") return name;
    }
    return "Item";
  };
}

export default ApplicationConfigLeftMenu;
