import React, { Component } from "react";
import classNames from "classnames/bind";
import { approvalReminderService } from "_services/approvalReminder.service";
import { notificationActions } from "_actions";
import { store } from "_helpers";
import {
  buildReminderRequest,
  canUseApprovalReminder,
  formatReminderStatusMessage,
} from "_helpers/approvalReminder.utils";

class ApprovalRemindApproverButton extends Component {
  constructor(props) {
    super(props);
    this.state = {
      eligibility: null,
      loading: false,
      sending: false,
    };
  }

  componentDidMount() {
    this.loadEligibility();
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.requestType !== this.props.requestType ||
      prevProps.referenceId !== this.props.referenceId ||
      prevProps.employeeId !== this.props.employeeId ||
      prevProps.visible !== this.props.visible
    ) {
      this.loadEligibility();
    }
  }

  loadEligibility = () => {
    const { visible, requestType, referenceId, employeeId, permission } = this.props;
    if (!visible || !canUseApprovalReminder(permission)) {
      this.setState({ eligibility: null });
      return Promise.resolve(null);
    }
    if (!requestType || !referenceId || !employeeId) {
      this.setState({ eligibility: null });
      return Promise.resolve(null);
    }

    this.setState({ loading: true });
    return approvalReminderService
      .getEligibility(requestType, referenceId, employeeId)
      .then((response) => {
        const eligibility = (response && response.payload) || null;
        this.setState({ eligibility, loading: false });
        return eligibility;
      })
      .catch(() => {
        this.setState({ eligibility: null, loading: false });
        return null;
      });
  };

  handleRemind = () => {
    const { requestType, referenceId, employeeId, onReminded } = this.props;
    const { eligibility, sending, loading } = this.state;
    if (sending || loading || !eligibility || eligibility.canRemind === false) {
      return;
    }

    this.setState({ sending: true });
    approvalReminderService
      .sendReminder(buildReminderRequest(requestType, referenceId, employeeId))
      .then((response) => {
        const payload = (response && response.payload) || {};
        const message =
          payload.message || "Reminder sent to manager and assigned delegates.";
        store.dispatch(notificationActions.success(message));
        if (onReminded) {
          onReminded(payload);
        }
        return this.loadEligibility();
      })
      .catch((error) => {
        const message = (error && error.message) || error || "Unable to send reminder.";
        store.dispatch(notificationActions.error(message));
        return this.loadEligibility();
      })
      .finally(() => {
        this.setState({ sending: false });
      });
  };

  render() {
    const { visible, permission, className, compact } = this.props;
    const { eligibility, loading, sending } = this.state;

    if (!visible || !canUseApprovalReminder(permission)) {
      return null;
    }

    const disabled =
      loading ||
      sending ||
      !eligibility ||
      eligibility.canRemind === false;
    const statusMessage = formatReminderStatusMessage(eligibility, loading);
    const onCooldown = eligibility && eligibility.canRemind === false;

    if (compact) {
      return (
        <button
          type="button"
          className={classNames("lux-approval-remind-btn", className, {
            "is-loading": sending,
            "is-disabled": disabled,
            "is-cooldown": onCooldown,
          })}
          onClick={this.handleRemind}
          disabled={disabled}
          title={statusMessage || "Send a reminder to your manager and assigned delegates"}
        >
          <i className="fe fe-bell" aria-hidden="true" />
          {sending ? "Sending…" : "Remind approver"}
        </button>
      );
    }

    return (
      <div className={classNames("lux-approval-remind-card", className)}>
        <div className="lux-approval-remind-card__glow" aria-hidden="true" />
        <div className="lux-approval-remind-card__body">
          <div className="lux-approval-remind-card__icon" aria-hidden="true">
            <i className="fe fe-bell" />
          </div>
          <div className="lux-approval-remind-card__copy">
            <strong>Waiting on approval?</strong>
            <p>
              Send a gentle reminder to your manager and any colleagues covering for them.
            </p>
          </div>
          <button
            type="button"
            className={classNames("lux-approval-remind-card__btn", {
              "is-loading": sending,
              "is-disabled": disabled,
              "is-cooldown": onCooldown,
            })}
            onClick={this.handleRemind}
            disabled={disabled}
          >
            {sending ? (
              <>
                <i className="fe fe-loader" aria-hidden="true" />
                Sending…
              </>
            ) : (
              <>
                <i className="fe fe-send" aria-hidden="true" />
                Remind approver
              </>
            )}
          </button>
        </div>
        {statusMessage ? (
          <p
            className={classNames("lux-approval-remind-card__status", {
              "is-cooldown": onCooldown,
              "is-loading": loading,
            })}
            role="status"
          >
            <i
              className={classNames("fe", loading ? "fe-loader" : onCooldown ? "fe-clock" : "fe-info")}
              aria-hidden="true"
            />
            {statusMessage}
          </p>
        ) : null}
      </div>
    );
  }
}

export default ApprovalRemindApproverButton;
