import { shouldUseFeatureFlagsAdmin } from "config/tracopus-pilot.config";

export const FEATURE_FLAG_STATUSES = {
  ENABLED: "Enabled",
  DISABLED: "Disabled",
  PILOT: "Pilot",
};

export const FEATURE_FLAG_MODULES = {
  Admin: { label: "Admin", icon: "fe fe-settings", tone: "slate" },
  People: { label: "People", icon: "fe fe-users", tone: "violet" },
  Workspace: { label: "Workspace", icon: "fe fe-grid", tone: "blue" },
  Payroll: { label: "Payroll", icon: "fe fe-dollar-sign", tone: "green" },
  HRMS: { label: "HRMS", icon: "fe fe-briefcase", tone: "indigo" },
  Approvals: { label: "Approvals", icon: "fe fe-check-circle", tone: "amber" },
};

export function isFeatureFlagsAdminEnabled() {
  return shouldUseFeatureFlagsAdmin();
}

export function normalizeFeatureFlag(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    key: row.key || row.id,
    name: row.name || row.key || "Feature flag",
    module: row.module || "Admin",
    group: row.group || "",
    envKey: row.envKey || "",
    scope: row.scope || "org",
    risk: row.risk || "low",
    status: row.status || FEATURE_FLAG_STATUSES.DISABLED,
    enabled: row.enabled === true,
    adoptionPct: row.adoptionPct != null ? row.adoptionPct : 0,
    dependents: Array.isArray(row.dependents) ? row.dependents : [],
    description: row.description || "",
    owner: row.owner || "Platform",
    updatedAt: row.updatedAt || null,
  };
}
