import React, { Component } from "react";
import { dossierService } from "_services/dossier/dossier.service";
import DossierLuxPage, {
  DossierActionButton,
  DossierLuxPanel,
} from "views/dossiers/components/DossierLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class DossierSectionsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    sections: [],
    saving: false,
    form: { title: "", sortOrder: "0", required: false },
  };

  get dossierRef() {
    const match = this.props.match;
    return match && match.params ? match.params.id : undefined;
  }

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Dossier sections");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await dossierService.listSections(this.dossierRef);
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, sections: result.payload });
    } else {
      this.setState({
        loading: false,
        sections: [],
        loadError: result.error || new Error("Unable to load sections"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.title) return;
    this.setState({ saving: true });
    const result = await dossierService.createSection(this.dossierRef, {
      title: form.title,
      sortOrder: Number(form.sortOrder) || 0,
      required: form.required,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { title: "", sortOrder: "0", required: false } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, sections, saving, form } = this.state;
    const ref = this.dossierRef;
    return (
      <DossierLuxPage
        testId="dossier-sections-page"
        dataSource={sections.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "slate",
          icon: "fe fe-layers",
          eyebrow: "Projects · Dossier",
          titleLead: "Sections",
          titleAccent: ref || "",
          lede: "Structure dossier content into ordered, optionally required sections.",
        }}
        heroActions={
          <DossierActionButton
            to={`/dossiers/${encodeURIComponent(ref)}`}
            icon="fe fe-arrow-left"
            variant="ghost"
          >
            Dossier
          </DossierActionButton>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load sections">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <DossierLuxPanel title="Add section" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-4">
                <input
                  className="form-control"
                  placeholder="Section title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Sort"
                  value={form.sortOrder}
                  onChange={(e) => this.setState({ form: { ...form, sortOrder: e.target.value } })}
                />
              </div>
              <div className="col-md-2 form-check mt-2">
                <input
                  id="sec-required"
                  type="checkbox"
                  className="form-check-input"
                  checked={form.required}
                  onChange={(e) => this.setState({ form: { ...form, required: e.target.checked } })}
                />
                <label className="form-check-label" htmlFor="sec-required">
                  Required
                </label>
              </div>
              <div className="col-md-2">
                <DossierActionButton type="submit" disabled={saving}>
                  Add section
                </DossierActionButton>
              </div>
            </div>
          </form>
        </DossierLuxPanel>
        <DossierLuxPanel title="Sections" meta={`${sections.length} record${sections.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && sections.length === 0 ? (
            <LuxRegisterEmptyState
              title="No sections yet"
              description="Add a section to structure this dossier."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Sort</th>
                    <th>Required</th>
                  </tr>
                </thead>
                <tbody>
                  {sections.map((s) => (
                    <tr key={s.sectionRef}>
                      <td>{s.sectionRef}</td>
                      <td>{s.title}</td>
                      <td>{s.sortOrder}</td>
                      <td>{s.required ? "Yes" : "No"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </DossierLuxPanel>
      </DossierLuxPage>
    );
  }
}

export default DossierSectionsPage;
