import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { workItemActions } from "_actions";
import { store } from "_helpers";
import TaskBoardListRow from "./TaskBoardListRow";

const LIST_COLUMNS = [
  { key: "index", label: "#", icon: "fe-hash" },
  { key: "task", label: "Task", icon: "fe-layers" },
  { key: "column", label: "Column", icon: "fe-columns" },
  { key: "category", label: "Category", icon: "fe-tag" },
  { key: "schedule", label: "Schedule", icon: "fe-calendar" },
  { key: "status", label: "Status", icon: "fe-flag", center: true },
  { key: "actions", label: "Actions", icon: "fe-sliders", center: true },
];

class TaskBoardList extends Component {
  handleDeleteWorkItem = (workItemId, isDelete) => {
    store.dispatch(this.props.deleteWorkItem(workItemId, isDelete));
  };

  handleRemoveWorkItem = (workItemId) => {
    store.dispatch(this.props.removeWorkItem(workItemId));
  };


  render() {
    const count = this.props.items ? this.props.items.length : 0;
    const hasItems = count > 0;

    return (
      <div className="lux-bid-list-shell lux-taskboard-list-shell">
        <div className="lux-bid-list-shell__bar">
          <span className="lux-bid-list-shell__label">
            <i className="fe fe-list" aria-hidden="true" />
            Today&apos;s task register
          </span>
          <span className="lux-bid-list-shell__count">
            {this.props.isLoading ? <LuxListCountSkeleton /> : `${count} task${count === 1 ? "" : "s"}`}
          </span>
        </div>

        <div className="lux-taskboard-list" aria-label="Task list view">
          <div className="lux-taskboard-list__head" role="row">
            {LIST_COLUMNS.map((col) => (
              <div
                key={col.key}
                className={[
                  "lux-taskboard-list__head-cell",
                  `lux-taskboard-list__head-cell--${col.key}`,
                  col.center ? "is-center" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                role="columnheader"
              >
                <span className="lux-taskboard-list__head-label">
                  <i className={`fe ${col.icon}`} aria-hidden="true" />
                  {col.label}
                </span>
              </div>
            ))}
          </div>

          <div
            className={classNames("lux-taskboard-list__body", { "is-loading": this.props.isLoading })}
            role="list"
          >
            {this.props.isLoading && (
              <LuxRegisterListSkeletonRows
                variant="taskboard"
                
              />
            )}
            {!this.props.isLoading &&
              hasItems &&
              this.props.items.map((workItem, index) => (
                <TaskBoardListRow
                  key={workItem.id}
                  permission={this.props.permission}
                  workItem={workItem}
                  slNo={index + 1}
                  handleDeleteWorkItem={this.handleDeleteWorkItem}
                  handleRemoveWorkItem={this.handleRemoveWorkItem}
                  showTaskStatusUpdateModel={this.props.showTaskStatusUpdateModel}
                />
              ))}
          </div>
        </div>
      </div>
    );
  }
}

const mapDispatchToProps = {
  deleteWorkItem: workItemActions.deleteWorkItem,
  removeWorkItem: workItemActions.removeWorkItem,
};

export default connect(null, mapDispatchToProps)(TaskBoardList);
