import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isOrgChartEnabled } from "config/org-structure.config";
import {
  buildOrgChartInsights,
  buildOrgChartMetrics,
  buildOrgChartTree,
  filterOrgChartEmployees,
  getOrgDepartments,
} from "config/org-structure.utils";
import { orgStructureService } from "_services/orgStructure.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import OrgChartTree from "views/people/components/OrgChartTree";
import OrgPolicyAnalyticsPanel from "views/people/components/policy/OrgPolicyAnalyticsPanel";
import { policyHubService } from "_services/policyHub.service";
import { PeopleActionButton } from "views/people/components/PeopleLuxShared";
import { ORG_CHART_PAGE_META } from "config/people-module-nav.config";

class OrgChartPage extends Component {
  state = {
    employees: [],
    orgUnits: [],
    loading: true,
    loadError: null,
    dataSource: null,
    departmentFilter: "ALL",
    query: "",
    selectedId: null,
    analytics: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Organization chart");
    this.loadChart();
  }

  loadChart = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [result, analyticsResult] = await Promise.all([
        orgStructureService.getOrgChart(),
        policyHubService.getAnalytics(),
      ]);
      const payload = result.payload || {};
      const employees = payload.employees || [];
      this.setState({
        employees,
        orgUnits: payload.orgUnits || [],
        analytics: analyticsResult.payload || null,
        loading: false,
        dataSource: result.source || null,
        selectedId: employees.length ? employees[0].id : null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load organization chart.",
        employees: [],
        orgUnits: [],
      });
    }
  };

  getFilteredEmployees = () => {
    const { employees, departmentFilter, query } = this.state;
    return filterOrgChartEmployees(employees, { department: departmentFilter, query });
  };

  getSelectedNode = (tree) => {
    const { selectedId } = this.state;
    if (!selectedId) return null;
    const findNode = (nodes) => {
      for (let i = 0; i < nodes.length; i += 1) {
        if (nodes[i].id === selectedId) return nodes[i];
        const child = findNode(nodes[i].children || []);
        if (child) return child;
      }
      return null;
    };
    return findNode(tree);
  };

  renderKpiStrip = () => {
    const { employees, orgUnits, loading } = this.state;
    const metrics = buildOrgChartMetrics(employees, orgUnits);
    const cards = [
      { id: "headcount", label: "Headcount", value: metrics.headcount, hint: "Active employees", tone: "primary", icon: "fe fe-users" },
      { id: "departments", label: "Departments", value: metrics.departments, hint: `${metrics.orgUnits} org units`, tone: "blue", icon: "fe fe-grid" },
      { id: "span", label: "Avg span", value: metrics.avgSpan, hint: `Max ${metrics.maxSpan} reports`, tone: "amber", icon: "fe fe-git-branch" },
      { id: "depth", label: "Depth", value: metrics.maxDepth, hint: `${metrics.managers} managers`, tone: "green", icon: "fe fe-layers" },
    ];

    return (
      <div className="lux-hrms-dash__kpi-strip lux-org-chart-kpi-strip" role="list" aria-busy={loading}>
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-org-chart-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <div className="lux-org-chart-kpi__top">
              <span className="lux-hrms-dash__kpi-label">{card.label}</span>
              {card.icon && (
                <span className={classNames("lux-org-chart-kpi__icon", card.tone && `is-${card.tone}`)} aria-hidden="true">
                  <i className={card.icon} />
                </span>
              )}
            </div>
            <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>
    );
  };

  renderInsights = () => {
    const { employees, orgUnits, loading } = this.state;
    if (loading) return null;
    const insights = buildOrgChartInsights(employees, orgUnits);
    return (
      <div className="lux-org-chart-insights" role="list">
        {insights.map((insight) => (
          <article
            key={insight.id}
            className={classNames("lux-hrms-dash__alert lux-org-chart-insight", `is-${insight.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__alert-icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <span className="lux-org-chart-insight__copy">
              <strong>{insight.title}</strong>
              <small>{insight.copy}</small>
            </span>
          </article>
        ))}
      </div>
    );
  };

  render() {
    if (!isOrgChartEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Organization chart"
          reason="Org chart is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, departmentFilter, query, employees, orgUnits } = this.state;
    const filteredEmployees = this.getFilteredEmployees();
    const tree = buildOrgChartTree(filteredEmployees);
    const selectedNode = this.getSelectedNode(tree);
    const departments = ["ALL", ...getOrgDepartments(employees)];

    return (
      <div className="lux-org-chart-page lux-people-page lux-register-page">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
                  meta={ORG_CHART_PAGE_META}
                  actions={
                    <>
                      <PeopleActionButton to="/admin/org-structure" variant="ghost" icon="fe fe-layers">
                        Org structure
                      </PeopleActionButton>
                      <PeopleActionButton to="/people/policies" variant="primary" icon="fe fe-book">
                        Policies
                      </PeopleActionButton>
                    </>
                  }
                />

        <div className="lux-register-page__body">
        {this.renderKpiStrip()}

        {loadError ? (
          <LuxInlineAlert
            message={loadError}
            tone="danger"
            title="Unable to load org chart"
          />
        ) : null}

        {this.renderInsights()}

        <OrgPolicyAnalyticsPanel
          analytics={this.state.analytics}
          loading={loading}
          showOrg
          showPolicy={false}
        />

        <section className="lux-hrms-dash__panel lux-org-chart-panel">
          <header className="lux-hrms-dash__panel-head lux-org-chart-panel__head">
            <div>
              <h2 className="lux-hrms-dash__panel-title">Reporting hierarchy</h2>
              <p className="lux-hrms-dash__panel-sub">Select a node to inspect manager chain and direct reports</p>
            </div>
          </header>

          <div className="lux-org-chart-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search name, role, or department"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filteredEmployees.length}</strong> employee{filteredEmployees.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-appr-toolbar__group">
              <span className="lux-appr-toolbar__label">Department</span>
              <div className="lux-hrms-dash__filter-group">
                {departments.map((value) => (
                  <button
                    key={value}
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", {
                      "is-active": departmentFilter === value,
                    })}
                    onClick={() => this.setState({ departmentFilter: value })}
                  >
                    {value === "ALL" ? "All" : value}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading org chart"
                description="Building reporting hierarchy from employee records."
              />
            ) : tree.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-git-branch"
                title="No employees match"
                description="Try broadening department or search filters."
              />
            ) : (
              <OrgChartTree
                tree={tree}
                selectedId={this.state.selectedId}
                onSelect={(node) => this.setState({ selectedId: node.id })}
                selectedNode={selectedNode}
              />
            )}
          </div>
        </section>
        </div>
      </div>
    );
  }
}

export default OrgChartPage;
