import { classifyApprovalAging } from "config/approval-analytics.utils";
import { UNIVERSAL_APPROVAL_STATUSES } from "config/universal-approval.config";

const DEFAULT_SLA_HOURS = {
  LEAVE: 48,
  TIMESHEET: 24,
  ATTENDANCE_REGULARIZATION: 24,
  LIFECYCLE: 72,
  ONBOARDING: 72,
  OFFBOARDING: 72,
  EXPENSE: 48,
  STAFFING: 48,
  DOCUMENT: 72,
};

const REMINDER_REQUEST_TYPES = {
  LEAVE: "LEAVE",
  TIMESHEET: "TIMESHEET",
  ATTENDANCE_REGULARIZATION: "ATTENDANCE",
};

export function resolveDefaultSlaHours(domain) {
  return DEFAULT_SLA_HOURS[String(domain || "").toUpperCase()] || 48;
}

export function resolveApprovalSlaState(item, now = new Date()) {
  if (!item || item.status !== UNIVERSAL_APPROVAL_STATUSES.PENDING) {
    return { bucket: null, label: "—", tone: "slate" };
  }
  const bucket = classifyApprovalAging(item, now);
  if (bucket === "overdue") {
    return { bucket, label: "Overdue", tone: "danger" };
  }
  if (bucket === "dueSoon") {
    return { bucket, label: "Due soon", tone: "warning" };
  }
  return { bucket: bucket || "onTrack", label: "On track", tone: "success" };
}

export function resolveReminderRequestType(domain) {
  return REMINDER_REQUEST_TYPES[String(domain || "").toUpperCase()] || null;
}

export function buildApprovalEscalationHint(item, policySlaHours) {
  const slaHours = policySlaHours != null ? policySlaHours : resolveDefaultSlaHours(item && item.domain);
  const state = resolveApprovalSlaState(item);
  if (state.bucket === "overdue") {
    return `Past SLA window (${slaHours}h). Escalation rules may notify the next approver.`;
  }
  if (state.bucket === "dueSoon") {
    return `Within ${slaHours}h SLA window. Auto-escalation applies if not actioned.`;
  }
  return `Standard SLA: ${slaHours} hours from submission.`;
}
