import React, { Component } from "react";
import { vendorInvoicesService } from "_services/vendorInvoices.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";

class VendorCostsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    projectId: "",
    summary: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Vendor costs");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const { projectId } = this.state;
    const result = await vendorInvoicesService.listVendorCosts(
      projectId ? { projectId: Number(projectId) } : {}
    );
    let summary = null;
    if (projectId) {
      const sumResult = await vendorInvoicesService.getProjectCosts(Number(projectId));
      if (sumResult.source === "api") {
        summary = sumResult.payload;
      }
    }
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, summary, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        summary,
        loadError: result.error || new Error("Unable to load vendor costs"),
      });
    }
  };

  handleFilter = (event) => {
    event.preventDefault();
    this.loadData();
  };

  render() {
    const { loading, loadError, rows, projectId, summary } = this.state;
    return (
      <FinanceLuxPage
        testId="vendor-costs-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-dollar-sign",
          eyebrow: "Finance",
          titleLead: "Vendor",
          titleAccent: "costs",
          lede: "Posted project cost ledger entries from approved vendor invoices.",
        }}
        dataSource="api"
        demoLabel={null}
        loading={loading}
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load vendor costs."
          onDismiss={() => this.setState({ loadError: null })}
        />
        <FinanceLuxPanel title="Filter by project">
          <form onSubmit={this.handleFilter} className="d-flex flex-wrap gap-2 align-items-end">
            <label className="small mb-0">
              Project ID
              <input
                className="form-control form-control-sm"
                value={projectId}
                onChange={(e) => this.setState({ projectId: e.target.value })}
                data-testid="vcost-project-id"
              />
            </label>
            <FinanceActionButton type="submit" variant="primary">
              Load
            </FinanceActionButton>
          </form>
          {summary && (
            <p className="small mt-2 mb-0" data-testid="vcost-summary">
              Approved vendor cost: {summary.approvedVendorCostUsd} USD ({summary.ledgerEntryCount}{" "}
              entries)
            </p>
          )}
        </FinanceLuxPanel>
        <FinanceLuxPanel title="Cost ledger" className="mt-3">
          {loading ? (
            <p className="text-muted small mb-0">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-muted small mb-0">
              No ledger entries for team {commonUtils.getCurrentUserTeamId()}.
            </p>
          ) : (
            <div className="table-responsive">
              <table className="table table-sm" data-testid="vendor-costs-table">
                <thead>
                  <tr>
                    <th>Ledger</th>
                    <th>Project</th>
                    <th>Vendor</th>
                    <th>Invoice ID</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th>Source</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.ledgerRef || row.id}>
                      <td>{row.ledgerRef}</td>
                      <td>{row.projectId}</td>
                      <td>{row.vendorId}</td>
                      <td>{row.vendorInvoiceId}</td>
                      <td>
                        {row.currency || "USD"} {row.amount}
                      </td>
                      <td>{row.status}</td>
                      <td>{row.sourceType}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default VendorCostsPage;
