/**
 * W17-B — Revenue recognition FE service. Real API only (no mock fallback path).
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const revenueRecognitionService = {
  listPolicies,
  createPolicy,
  updatePolicy,
  listSchedules,
  generateSchedule,
  listEntries,
  createEntry,
  approveEntry,
  reverseEntry,
  lockPeriod,
  getPeriod,
  recognizedVsBilled,
  projectRecognizedSummary,
};

const API_ERROR = { payload: null, source: "api-error" };
const BASE = () => urlConfig.REVENUE_RECOGNITION_API_PATH;

function resolveUserTeamId(explicit) {
  if (explicit != null && explicit !== "") {
    return explicit;
  }
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function financeListTeamQuery(extra) {
  const query = { financeManager: true };
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds() || [];
  const currentId = commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds" || key === "financeManager") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function financeMutationParams(extra = {}) {
  return {
    userTeamId: resolveUserTeamId(extra.userTeamId),
    financeManager: true,
    ...Object.keys(extra).reduce((acc, key) => {
      if (key === "userTeamId") return acc;
      if (extra[key] != null && extra[key] !== "") {
        acc[key] = extra[key];
      }
      return acc;
    }, {}),
  };
}

async function listPolicies(extra = {}) {
  try {
    const response = await axiosUtils.getWithParam(`${BASE()}/policies`, financeListTeamQuery(extra));
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[RevRec] listPolicies unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function createPolicy(body = {}) {
  try {
    const response = await axiosUtils.post(
      `${BASE()}/policies?financeManager=true`,
      {
        ...body,
        userTeamId: body.userTeamId || resolveUserTeamId(),
        actorId: body.actorId || resolveActorId(),
      }
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

