async function approveEntry(entryRef, userTeamId) {
  return entryAction(entryRef, "approve", null, userTeamId);
}

async function reverseEntry(entryRef, reason, userTeamId) {
  return entryAction(entryRef, "reverse", reason, userTeamId);
}

async function entryAction(entryRef, action, reason, userTeamId) {
  try {
    const params = new URLSearchParams({
      userTeamId: String(resolveUserTeamId(userTeamId)),
      actorId: String(resolveActorId()),
      financeManager: "true",
    });
    if (reason) {
      params.set("reason", reason);
    }
    const response = await axiosUtils.post(
      `${BASE()}/entries/${encodeURIComponent(entryRef)}/${action}?${params.toString()}`,
      null
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

