/** Pure util for FE unit tests — mirrors backend schedule split. */
export function splitTimeBasedAmount(totalAmount, periodCount) {
  const count = Math.max(1, Number(periodCount) || 1);
  const total = Number(totalAmount) || 0;
  const each = Math.round((total / count) * 100) / 100;
  const lines = [];
  let allocated = 0;
  for (let i = 0; i < count; i += 1) {
    const amount = i === count - 1 ? Math.round((total - allocated) * 100) / 100 : each;
    allocated = Math.round((allocated + amount) * 100) / 100;
    lines.push({ sequenceNo: i + 1, amount });
  }
  return lines;
}
