import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { WorkspacePanelHead, WorkspaceActionButton } from "views/workspace/components/WorkspaceLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function priorityTone(priority) {
  return String(priority).toUpperCase() === "HIGH" ? "danger" : "slate";
}

export default function WorkspaceApprovalsShortcut({ items = [], loading, approvalsEnabled }) {
  if (approvalsEnabled === false) {
    return null;
  }

  return (
    <section className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--approvals" aria-label="My approvals shortcut">
      <WorkspacePanelHead
        title="My approvals"
        subtitle="Pending leave, timesheet, and attendance requests"
        actions={
          <WorkspaceActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="ghost">
            Open inbox
          </WorkspaceActionButton>
        }
      />
      <div className="lux-hrms-dash__panel-body">
        {loading ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact"
            title="Loading approvals"
            description="Aggregating your pending sign-off queue."
          />
        ) : items.length === 0 ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact"
            icon="fe fe-check-circle"
            title="Inbox clear"
            description="No pending approvals right now. New requests will appear here."
          />
        ) : (
          <ul className="lux-workspace-home-approvals__list" role="list">
            {items.map((item) => (
              <li key={item.id} className="lux-workspace-home-approvals__item" role="listitem">
                <Link to={item.path || "/workspace/approvals"} className="lux-workspace-home-approvals__link">
                  <span
                    className={classNames(
                      "lux-workspace-home-approvals__icon",
                      item.moduleTone && `is-${item.moduleTone}`
                    )}
                    aria-hidden="true"
                  >
                    <i className={item.domainIcon || "fe fe-inbox"} />
                  </span>
                  <span className="lux-workspace-home-approvals__copy">
                    <strong>{item.subject || item.domainLabel}</strong>
                    <small>
                      {item.requester}
                      {item.dueLabel ? ` · Due ${item.dueLabel}` : ""}
                    </small>
                  </span>
                  <span className="lux-workspace-home-approvals__meta">
                    <span className={classNames("lux-badge", `is-${priorityTone(item.priority)}`)}>
                      {item.priority || "NORMAL"}
                    </span>
                    <span className="lux-workspace-home-approvals__domain">{item.domainLabel}</span>
                  </span>
                  <i className="fe fe-chevron-right lux-workspace-home-approvals__chevron" aria-hidden="true" />
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}
