import React from "react";
import classNames from "classnames";
import {
  buildEmployee360AttentionItems,
  buildEmployee360OverviewMetrics,
  buildEmployee360ContextLine,
  getEmployeeDisplayName,
} from "config/employee360.utils";

function MetricCard({ metric }) {
  return (
    <article
      className={classNames("lux-employee-360__metric", metric.tone && `lux-employee-360__metric--${metric.tone}`)}
    >
      <span className="lux-employee-360__metric-label">{metric.label}</span>
      <strong className="lux-employee-360__metric-value">{metric.value}</strong>
      {metric.hint && <span className="lux-employee-360__metric-hint">{metric.hint}</span>}
    </article>
  );
}

export default function Employee360OverviewTab({ employee, summary, activePersona, activePersonaLabel }) {
  const metrics = buildEmployee360OverviewMetrics(employee, summary, activePersona);
  const attentionItems = buildEmployee360AttentionItems(summary);
  const contextLine = buildEmployee360ContextLine(employee);

  return (
    <div className="lux-employee-360__overview">
      <section className="lux-employee-360__panel">
        <h3 className="lux-employee-360__panel-title">Summary</h3>
        <p className="lux-employee-360__panel-desc">
          {getEmployeeDisplayName(employee)}
          {contextLine ? ` — ${contextLine}` : ""}
          {activePersonaLabel ? ` · Viewing as ${activePersonaLabel}` : ""}
        </p>
        <div className="lux-employee-360__metrics">
          {metrics.map((metric) => (
            <MetricCard key={metric.id} metric={metric} />
          ))}
        </div>
      </section>

      {attentionItems.length > 0 ? (
        <section className="lux-employee-360__panel" aria-label="What needs attention">
          <h3 className="lux-employee-360__panel-title">What needs attention</h3>
          <ul className="lux-employee-360__attention-list">
            {attentionItems.map((item) => (
              <li key={item.id || item.label} className="lux-employee-360__attention-item">
                <i className={item.icon || "fe fe-alert-circle"} aria-hidden="true" />
                <span>{item.label}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : (
        <section className="lux-employee-360__panel" aria-label="What needs attention">
          <h3 className="lux-employee-360__panel-title">What needs attention</h3>
          <p className="lux-employee-360__panel-desc">
            No pending approvals, expiring documents, or attendance exceptions for this employee right now.
          </p>
        </section>
      )}

      {summary && Array.isArray(summary.allocatedProjects) && summary.allocatedProjects.length > 0 && (
        <section className="lux-employee-360__panel">
          <h3 className="lux-employee-360__panel-title">Active allocations</h3>
          <ul className="lux-employee-360__chip-list">
            {summary.allocatedProjects.map((project) => (
              <li key={project} className="lux-employee-360__chip">{project}</li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}
