import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function formatUsd(value) {
  if (value == null) {
    return "—";
  }
  return `$${Number(value).toLocaleString()}`;
}

export default function CostToRevenueAnalyticsPanel({ analytics, loading }) {
  const projects = (analytics && analytics.projects) || [];
  const summary = (analytics && analytics.summary) || {};

  if (loading) {
    return <div className="lux-empfin-register__skeleton" aria-busy="true" />;
  }

  if (!projects.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No cost-to-revenue allocations"
        description="Project allocations appear when timesheets and billing rates are linked to employee finance profiles."
      />
    );
  }

  return (
    <div className="lux-empfin-costrev">
      <div className="lux-empfin-costrev__summary">
        <article className="lux-empfin-costrev__stat">
          <span>Portfolio margin</span>
          <strong>{summary.portfolioMarginPct != null ? `${summary.portfolioMarginPct}%` : "—"}</strong>
        </article>
        <article className="lux-empfin-costrev__stat">
          <span>Billable revenue</span>
          <strong>{formatUsd(summary.totalRevenueUsd)}</strong>
        </article>
        <article className="lux-empfin-costrev__stat">
          <span>Loaded cost</span>
          <strong>{formatUsd(summary.totalCostUsd)}</strong>
        </article>
        <article className="lux-empfin-costrev__stat">
          <span>Projects</span>
          <strong>{summary.projectCount || projects.length}</strong>
        </article>
      </div>
      <div className="lux-empfin-register-wrap">
        <table className="lux-empfin-register">
          <thead>
            <tr>
              <th>Project</th>
              <th>Revenue</th>
              <th>Loaded cost</th>
              <th>Hours</th>
              <th>Margin</th>
            </tr>
          </thead>
          <tbody>
            {projects.map((row) => (
              <tr
                key={row.projectId || row.projectName}
                className={classNames(row.marginPct != null && row.marginPct < 20 && "is-flagged")}
              >
                <td>
                  <div className="lux-empfin-register__title">{row.projectName}</div>
                  <div className="lux-empfin-register__meta">{row.employeeCount} employees allocated</div>
                </td>
                <td>{formatUsd(row.billableRevenueUsd)}</td>
                <td>{formatUsd(row.loadedCostUsd)}</td>
                <td>{row.allocatedHours || 0}</td>
                <td>
                  <strong>{row.marginPct != null ? `${row.marginPct}%` : "—"}</strong>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
