import React from "react";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import ProfileLeaveView from "views/hrms/components/profile/ProfileLeaveView";
import { buildLeaveTabStats } from "config/employee360Tab.utils";

export default function Employee360LeaveTab({ employee, summary }) {
  if (!employee) {
    return null;
  }

  const stats = buildLeaveTabStats(summary);

  return (
    <ProjectDetailsTabShell
      icon="fe fe-calendar"
      eyebrow="Time off"
      title="Leave"
      subtitle="Balances, history, and leave calculations for this employee."
      stats={stats}
      className="lux-employee-360__embed lux-employee-360__embed--leave"
    >
      <div className="lux-employee-360__embed-toolbar">
        <Link to="/people/leaves" className="lux-employee-360__embed-link">
          Open leave management
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
      </div>
      <ProfileLeaveView employee={employee} />
    </ProjectDetailsTabShell>
  );
}
