function governanceTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function recordGovernanceAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.PROJECT,
    entityRef: entityRef || headline,
    headline,
    metadata,
  });
}

async function listMilestonesFromApi(filters = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.PROJECT_GOVERNANCE_API_PATH}/milestones`,
    governanceTeamQuery({
      projectId: filters.projectId || undefined,
    })
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeMilestone(row)).filter(Boolean),
    source: "api",
  };
}

async function listMilestones(filters = {}) {

  if (shouldUseProjectGovernanceApi()) {
    try {
      return await listMilestonesFromApi(filters);
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

