async function validateDependencyPayload(payload = {}) {
  const existing = await listDependencies({ projectId: payload.projectId || undefined });
  const milestones = await listMilestones({ projectId: payload.projectId || undefined });
  const deps = (existing && existing.payload) || [];
  const rows = (milestones && milestones.payload) || [];

  const structural = validateDependencyLink(deps, payload);
  if (!structural.valid) {
    throw new Error(structural.reason);
  }

  const schedule = validateDependencySchedule(rows, payload);
  if (!schedule.valid) {
    throw new Error(schedule.reason);
  }
}

async function createDependency(payload = {}) {
  await validateDependencyPayload(payload);

  if (shouldUseProjectGovernanceApi()) {
    try {
      const response = await axiosUtils.post(
        `${urlConfig.PROJECT_GOVERNANCE_API_PATH}/dependencies?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        payload
      );
      const row = normalizeDependency((response && response.payload) || response);
      recordGovernanceAudit(
        AUDIT_ACTION_TYPES.CREATED,
        `Dependency linked: ${row.predecessorName} → ${row.successorName}`,
        row.id,
        { projectId: row.projectId, type: row.type }
      );
      return { payload: row, source: "api" };
    } catch (e) {
      // fall through
    }
  }

  throw new Error("Unable to complete governance action via API.");

}

