import React from "react";
import classNames from "classnames/bind";
import { PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default function GoalRegister({ goals, loading, onSelect }) {
  if (loading) {
    return (
      <div className="lux-perf-register">
        <div className="lux-perf-skeleton lux-perf-skeleton--row" />
        <div className="lux-perf-skeleton lux-perf-skeleton--row" />
      </div>
    );
  }
  if (!goals || !goals.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-target" aria-hidden="true" />
        <p>No goals match the current filters.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {goals.map((goal, index) => (
        <article key={goal.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", goal.tone && `is-${goal.tone}`)}>
            <i className="fe fe-target" aria-hidden="true" />
          </span>
          <button type="button" className="lux-perf-register__main lux-perf-register__main--button" onClick={() => onSelect && onSelect(goal)}>
            <span className="lux-perf-register__eyebrow">{goal.type} · {goal.cycleName}</span>
            <h3>{goal.title}</h3>
            <p>{goal.ownerName}</p>
            <div className="lux-perf-register__meta">
              <PerformanceStatusBadge status={goal.status} />
              <span>{goal.progress}% progress</span>
              {goal.dueDate ? <span>Due {goal.dueDate}</span> : null}
            </div>
            <div className="lux-perf-progress" aria-hidden="true">
              <span className="lux-perf-progress__fill" style={{ width: `${goal.progress}%` }} />
            </div>
          </button>
        </article>
      ))}
    </div>
  );
}
