/**
 * Per-route SEO title + description for the SPA.
 * Longest-prefix match on pathname. Authenticated app routes use noindex.
 */
import { SIDEBAR_GROUPS } from "./sidebar-menu.config";
import { DENSE_PAGE_META } from "./dense-page-meta.config";

const APP_LABEL = process.env.REACT_APP_LABEL || "Tracopus";

/** Dense-meta key overrides for important HR / delivery routes. */
const DENSE_BY_PREFIX = [
  { prefix: "/people/attendance", key: "attendance" },
  { prefix: "/hrms/attendance", key: "attendance" },
  { prefix: "/people/leaves", key: "leaveManagement" },
  { prefix: "/hrms/leaves", key: "leaveManagement" },
  { prefix: "/people/timesheet", key: "timesheet" },
  { prefix: "/hrms/timesheet", key: "timesheet" },
  { prefix: "/people/employees", key: "employees" },
  { prefix: "/hrms/employees", key: "employees" },
  { prefix: "/workspace/approvals", key: "approvals" },
  { prefix: "/workspace/my-work", key: "myWork" },
  { prefix: "/workspace/home", key: "workspaceHome" },
  { prefix: "/workspace/notifications", key: "notifications" },
  { prefix: "/project/list", key: "projectList" },
  { prefix: "/project/workitems", key: "workItems" },
  { prefix: "/project/deliverables", key: "taskList" },
  { prefix: "/project/dashboard", key: "projectDashboard" },
];

const PUBLIC_PREFIXES = ["/user/login", "/user/activate", "/user/forgot", "/document/", "/documentation"];

function titleFromDense(meta) {
  if (!meta) return null;
  const lead = meta.titleLead || "";
  const accent = meta.titleAccent || "";
  const combined = `${lead} ${accent}`.replace(/\s+/g, " ").trim();
  return combined || meta.eyebrow || null;
}

function collectSidebarEntries() {
  const items = [];
  (SIDEBAR_GROUPS || []).forEach((group) => {
    (group.items || []).forEach((item) => {
      if (!item || !item.path || !item.name) return;
      items.push({
        prefix: item.path,
        title: item.name,
        description: `${item.name} — ${APP_LABEL} workspace`,
      });
    });
  });
  return items;
}

function buildEntries() {
  const byPrefix = new Map();

  collectSidebarEntries().forEach((entry) => {
    byPrefix.set(entry.prefix, entry);
  });

  DENSE_BY_PREFIX.forEach(({ prefix, key }) => {
    const meta = DENSE_PAGE_META[key];
    if (!meta) return;
    const title = titleFromDense(meta) || key;
    byPrefix.set(prefix, {
      prefix,
      title,
      description: meta.lede || `${title} — ${APP_LABEL}`,
    });
  });

  byPrefix.set("/people/holidays", {
    prefix: "/people/holidays",
    title: "Holidays",
    description: "Org holiday calendars by location — leave day counting source of truth.",
  });
  byPrefix.set("/user/login", {
    prefix: "/user/login",
    title: "Sign in",
    description: `Sign in to ${APP_LABEL} — enterprise work intelligence.`,
    robots: "index, follow",
  });
  byPrefix.set("/user/", {
    prefix: "/user/",
    title: "Account",
    description: `${APP_LABEL} account access`,
    robots: "noindex, follow",
  });
  byPrefix.set("/error", {
    prefix: "/error",
    title: "Error",
    description: `${APP_LABEL} error`,
    robots: "noindex, nofollow",
  });

  return Array.from(byPrefix.values()).sort((a, b) => b.prefix.length - a.prefix.length);
}

export const PAGE_SEO_ENTRIES = buildEntries();

export function resolvePageSeo(pathname) {
  const path = String(pathname || "/").split("?")[0] || "/";
  const match = PAGE_SEO_ENTRIES.find(
    (entry) => path === entry.prefix || path.startsWith(`${entry.prefix}/`) || path.startsWith(entry.prefix)
  );

  const isPublic = PUBLIC_PREFIXES.some((p) => path === p || path.startsWith(p));
  const titleBase = (match && match.title) || humanizePath(path);
  const description =
    (match && match.description) || `${titleBase} — ${APP_LABEL} enterprise workspace.`;
  const robots =
    (match && match.robots) || (isPublic ? "index, follow" : "noindex, nofollow");

  return {
    path,
    title: `${titleBase} | ${APP_LABEL}`,
    description: String(description).slice(0, 160),
    robots,
    contentGroup: isPublic ? "public" : "app",
  };
}

function humanizePath(path) {
  const parts = path.split("/").filter(Boolean);
  if (!parts.length) return "Home";
  return parts[parts.length - 1]
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}
