import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LeaveImpactRecommendationPanel from "./LeaveImpactRecommendationPanel";

function RiskBadge({ level }) {
  const tone = String(level || "LOW").toLowerCase();
  return <span className={classNames("lux-leave-impact__risk", `is-${tone}`)}>{level || "LOW"} risk</span>;
}

export default function LeaveImpactDrawer({ open, impact, recommendation, loading, onClose }) {
  if (!open) {
    return null;
  }

  return createPortal(
    <div
      className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop lux-leave-impact__backdrop"
      role="presentation"
      onClick={onClose}
    >
      <aside
        className="lux-onb-drawer lux-leave-drawer lux-leave-impact__drawer lux-onb-drawer--warning"
        aria-label="Leave impact analysis"
        onClick={(event) => event.stopPropagation()}
      >
        <header className="lux-onb-drawer__head lux-leave-impact__header">
          <div className="lux-onb-drawer__head-main">
            <span className="lux-onb-drawer__category-icon" aria-hidden="true">
              <i className="fe fe-activity" />
            </span>
            <div className="lux-onb-drawer__head-copy">
              <span className="lux-leave-impact__eyebrow">Leave impact</span>
              <h2>{impact ? impact.employeeName : "Leave impact"}</h2>
              {impact && (
                <p className="lux-leave-impact__subtitle">
                  {impact.leaveTypeLabel} · {impact.dateRangeLabel} · {impact.days} day(s)
                </p>
              )}
            </div>
          </div>
          <button type="button" className="lux-onb-drawer__close lux-leave-impact__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-onb-drawer__body lux-leave-impact__body">
          {loading && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              icon="fe fe-loader"
              title="Analyzing impact"
              description="Checking team coverage and delivery overlap."
            />
          )}

          {!loading && !impact && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              icon="fe fe-alert-circle"
              title="Impact unavailable"
              description="Unable to load leave impact for this request."
            />
          )}

          {!loading && impact && (
            <>
              <div className="lux-leave-impact__metrics">
                <div className="lux-leave-impact__metric">
                  <span>Coverage risk</span>
                  <RiskBadge level={impact.riskLevel} />
                </div>
                <div className="lux-leave-impact__metric">
                  <span>Team coverage</span>
                  <strong>{impact.teamCoveragePct}%</strong>
                </div>
                <div className="lux-leave-impact__metric">
                  <span>Overlapping leave</span>
                  <strong>{impact.overlappingLeaveCount}</strong>
                </div>
                {impact.lwpExposure && (
                  <div className="lux-leave-impact__metric is-lwp">
                    <span>Payroll</span>
                    <strong>LWP exposure</strong>
                  </div>
                )}
              </div>

              <p className="lux-leave-impact__hint">{impact.deliveryImpactHint}</p>

              {impact.overlappingLeaves && impact.overlappingLeaves.length > 0 && (
                <section className="lux-leave-impact__section">
                  <h3>Overlapping team leave</h3>
                  <ul className="lux-leave-impact__list">
                    {impact.overlappingLeaves.map((row) => (
                      <li key={`${row.employeeName}-${row.dateRange}`}>
                        <strong>{row.employeeName}</strong> — {row.dateRange} ({row.leaveType})
                      </li>
                    ))}
                  </ul>
                </section>
              )}

              {impact.backupSuggestions && impact.backupSuggestions.length > 0 && (
                <section className="lux-leave-impact__section">
                  <h3>Suggested backup coverage</h3>
                  <ul className="lux-leave-impact__backups">
                    {impact.backupSuggestions.map((backup) => (
                      <li key={backup.employeeId}>
                        <strong>{backup.name}</strong>
                        <span>{backup.role}</span>
                        <small>{backup.reason}</small>
                      </li>
                    ))}
                  </ul>
                </section>
              )}

              <LeaveImpactRecommendationPanel recommendation={recommendation} />
            </>
          )}
        </div>
      </aside>
    </div>,
    document.body
  );
}
