import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class MultiOptionDropDownSingleSelectInput extends Component {
  onChange = (value) => {
    this.props.onChange({ ...this.props.questionConfig, answer: value.trim() });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
          <select
            id={`lux-fb-q-${questionConfig.id}`}
            onChange={(e) => this.onChange(e.target.value)}
            value={questionConfig.answer || ""}
            disabled={readonly}
          >
            <option value="">Select an option</option>
            {questionConfig.questionOptions &&
              questionConfig.questionOptions.split(",").map((value) => (
                <option key={value.trim()} value={value.trim()}>
                  {value.trim()}
                </option>
              ))}
          </select>
        </div>
      </div>
    );
  }
}
export default MultiOptionDropDownSingleSelectInput;
