function employeeFinanceListTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds
    ? commonUtils.getCurrentUserTeamIds() || []
    : [];
  const currentId = (extra && extra.userTeamId) || commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function employeeFinanceWriteTeamQuery(extra) {
  const query = {
    userTeamId:
      (extra && extra.userTeamId != null && extra.userTeamId !== "")
        ? extra.userTeamId
        : commonUtils.getCurrentUserTeamId(),
  };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function writeEmployeeFinanceAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.EMPLOYEE,
    entityRef: entityRef || headline,
    headline,
    metadata: {
      module: "EMPLOYEE_FINANCE",
      ...metadata,
    },
  });
}

async function getBenefitsOverview(filters = {}) {
  if (!shouldUseEmployeeFinanceApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.EMPLOYEE_FINANCE_API_PATH}/benefits/overview`,
    employeeFinanceListTeamQuery(filters)
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

