function employeeFinanceWriteQueryString(extra) {
  const query = employeeFinanceWriteTeamQuery({
    actorId: (extra && extra.actorId) || commonUtils.getCurrentUserId(),
    ...(extra || {}),
  });
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

