async function exportCompensation(filters = {}, options = {}) {
  const activePersona = options.activePersona || "ADMIN";
  if (!canExportEmployeeFinanceCompensation(activePersona)) {
    throw new Error("Compensation export is restricted for your role.");
  }
  const result = await listCompensationChanges(filters);
  const csv = exportCompensationCsv(result.payload || []);
  return {
    payload: csv,
    filename: `compensation-changes-${new Date().toISOString().slice(0, 10)}.csv`,
    source: result.source,
  };
}
