import React from "react";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";

/**
 * App-wide compact register atelier shell (staffing-requests / resources pattern).
 * tone: amber | violet | sky | indigo | teal | rose | green
 */
export function LuxRegisterAtelier({
  tone = "sky",
  kickerIcon = "fe fe-layers",
  kicker,
  title,
  subtitle,
  pulseCards = [],
  actions,
  search,
  filterGroups = [],
  children,
  className,
}) {
  return (
    <section
      className={classNames(
        "lux-register-atelier",
        "lux-res-atelier",
        tone && `is-${tone}`,
        className
      )}
    >
      {(kicker || title || subtitle || pulseCards.length > 0 || actions) && (
        <header className="lux-res-atelier__masthead">
          <div className="lux-res-atelier__masthead-copy">
            {kicker ? (
              <span className="lux-res-atelier__kicker">
                <i className={kickerIcon} aria-hidden="true" />
                {sanitizeUiCopy(kicker)}
              </span>
            ) : null}
            {title ? <h3>{title}</h3> : null}
            {subtitle ? <p>{sanitizeUiCopy(subtitle)}</p> : null}
          </div>
          <div className="lux-res-atelier__masthead-aside">
            {pulseCards.length > 0 ? (
              <div className="lux-res-atelier__pulse" aria-label="Section snapshot">
                {pulseCards.map((card) => (
                  <article
                    key={card.id || card.label}
                    className={classNames("lux-res-atelier__pulse-card", card.tone && `is-${card.tone}`)}
                  >
                    <em>{card.label}</em>
                    <strong>{card.value}</strong>
                  </article>
                ))}
              </div>
            ) : null}
            {actions}
          </div>
        </header>
      )}

      {(search || filterGroups.length > 0) && (
        <div className="lux-res-atelier__toolbar">
          {search ? (
            <label className="lux-res-atelier__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                placeholder={search.placeholder || "Search…"}
                value={search.value || ""}
                onChange={search.onChange}
              />
            </label>
          ) : null}
          {filterGroups.map((group) => (
            <div
              key={group.id || group.ariaLabel}
              className={classNames("lux-res-atelier__filters", group.variant && `is-${group.variant}`)}
              aria-label={group.ariaLabel}
            >
              {(group.options || []).map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  className={classNames("lux-res-atelier__chip", group.variant && `is-${group.variant}`, {
                    "is-active": group.value === opt.value,
                  })}
                  onClick={() => group.onChange && group.onChange(opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          ))}
        </div>
      )}

      <div className="lux-res-atelier__body">{children}</div>
    </section>
  );
}

export default LuxRegisterAtelier;
