import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientTicketsPage extends Component {
  state = {
    loading: false,
    submitting: false,
    error: null,
    message: null,
    tickets: [],
    projectId: "",
    title: "",
    description: "",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client tickets");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, error: null });
    try {
      const result = await clientPortalService.listTickets();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: "Unable to load tickets. Sign in at /client/login.",
          tickets: [],
        });
        return;
      }
      this.setState({
        loading: false,
        tickets: (result.payload && result.payload.tickets) || [],
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load tickets." });
    }
  };

  handleCreate = async () => {
    const { projectId, title, description } = this.state;
    this.setState({ submitting: true, message: null });
    try {
      const result = await clientPortalService.createTicket({
        projectId: Number(projectId),
        title: String(title || "").trim(),
        description: String(description || "").trim(),
      });
      if (!result || result.source === "api-error") {
        this.setState({ submitting: false, message: "Create failed." });
        return;
      }
      this.setState({
        submitting: false,
        message: `Created ${result.payload && result.payload.ticketRef}`,
        title: "",
        description: "",
      });
      this.load();
    } catch (e) {
      this.setState({ submitting: false, message: (e && e.message) || "Create failed." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage>
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, submitting, error, message, tickets, projectId, title, description } = this.state;
    return (
      <ClientLuxPage
        testId="client-tickets-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-message-square",
          eyebrow: "Client portal",
          titleLead: "Tickets",
          titleAccent: "inbox",
          lede: "Thin client portal tickets (CP-008).",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.load} disabled={loading}>
            Refresh
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load tickets">
            {error}
          </LuxInlineAlert>
        ) : null}
        {message ? (
          <LuxInlineAlert tone="info" title="Ticket update">
            {message}
          </LuxInlineAlert>
        ) : null}
        <ClientLuxPanel title="Create ticket" icon="fe fe-plus">
          <input
            className="form-control mb-2"
            placeholder="Project id"
            value={projectId}
            onChange={(e) => this.setState({ projectId: e.target.value })}
          />
          <input
            className="form-control mb-2"
            placeholder="Title"
            value={title}
            onChange={(e) => this.setState({ title: e.target.value })}
          />
          <textarea
            className="form-control mb-2"
            placeholder="Description"
            rows={2}
            value={description}
            onChange={(e) => this.setState({ description: e.target.value })}
          />
          <ClientActionButton variant="primary" onClick={this.handleCreate} disabled={submitting}>
            {submitting ? "Creating…" : "Create ticket"}
          </ClientActionButton>
        </ClientLuxPanel>
        <ClientLuxPanel title="Tickets" icon="fe fe-list" meta={`${tickets.length} open`}>
          {tickets.length === 0 && !loading && !error ? (
            <LuxRegisterEmptyState title="No tickets" description="Create a ticket for a permitted project." showCreate={false} />
          ) : (
            <ul className="lux-client-portal-list lux-client-portal-list--plain">
              {tickets.map((row) => (
                <li key={row.ticketRef || row.id}>
                  {row.ticketRef}: {row.title} [{row.status}]
                </li>
              ))}
            </ul>
          )}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientTicketsPage;
