function createAttendance(requestObj) {
    //console.log(requestObj)
    return dispatch => {
        dispatch(request());

        employeeService.createAttendance(requestObj)
            .then(
                attendance => {
                    dispatch(success(attendance.payload));
                    const status = attendance.payload && attendance.payload.status;
                    let message = 'Attendance marked successfully';
                    if (status === 'PENDING_APPROVAL') {
                        message = 'Attendance submitted for manager approval';
                    } else if (status === 'APPROVED') {
                        message = 'Attendance approved';
                    }
                    dispatch(notificationActions.success(message));
                },
                error => dispatch(failure(getApiErrorMessage(error)))
            );
    };

    function request() { return { type: employeeConstants.CREATE_ATTENDANCE_REQUEST } }
    function success(attendance) { return { type: employeeConstants.CREATE_ATTENDANCE_SUCCESS, attendance } }
    function failure(error) { return { type: employeeConstants.CREATE_ATTENDANCE_FAILURE, error } }
}

function approveAttendance(requestObj) {
    const { onSuccess, onError, removalRequest, ...serviceRequest } = requestObj;
    return dispatch => {
        dispatch(request());
        employeeService.approveAttendance(serviceRequest)
            .then(
                attendance => {
                    if (removalRequest) {
                        dispatch({ type: employeeConstants.DELETE_ATTENDANCE_SUCCESS, id: serviceRequest.id });
                    } else {
                        dispatch(success(attendance.payload));
                    }
                    if (onSuccess) onSuccess(attendance.payload);
                },
                error => {
                    const message = getApiErrorMessage(error);
                    dispatch(failure(message));
                    dispatch(notificationActions.error(message));
                    if (onError) onError(message);
                }
            );
    };

    function request() { return { type: employeeConstants.APPROVE_ATTENDANCE_REQUEST } }
    function success(attendance) { return { type: employeeConstants.APPROVE_ATTENDANCE_SUCCESS, attendance } }
    function failure(error) { return { type: employeeConstants.APPROVE_ATTENDANCE_FAILURE, error } }
}

