function syncEmployeeLeaves(employee, startDate, endDate, callbackFunction) {
    return dispatch => {
        dispatch(request(employee));

        employeeService.syncEmployeeLeaves(employee, startDate, endDate)
            .then(
                employeeLeavesSyncResponse => {
                    dispatch(success(employeeLeavesSyncResponse));
                    dispatch(notificationActions.success('Employee Leave Sync successful'));
                    callbackFunction(employeeLeavesSyncResponse);
                },
                error => {
                    dispatch(failure(getErrorMessage(error)));
                    dispatch(notificationActions.error(getErrorMessage(error)));
                     callbackFunction(null);
                }
            );
    };

    function request(employee) { return { type: employeeConstants.CREATE_EMPLOYEE_LEAVE_SYNC_REQUEST, employee } }
    function success(employeeLeavesSyncResponse) { return { type: employeeConstants.CREATE_EMPLOYEE_LEAVE_SYNC_SUCCESS, employeeLeavesSyncResponse } }
    function failure(error) { return { type: employeeConstants.CREATE_EMPLOYEE_LEAVE_SYNC_FAILURE, error } }
}

