export function getLuxPaletteId() {
  try {
    return localStorage.getItem(STORAGE_KEY) || DEFAULT_PALETTE;
  } catch (e) {
    return DEFAULT_PALETTE;
  }
}

export function applyLuxPalette(paletteId) {
  const palette = LUX_PALETTES[paletteId] || LUX_PALETTES[DEFAULT_PALETTE];
  const root = document.documentElement;

  root.setAttribute('data-lux-palette', palette.id);
  root.style.setProperty('--lux-primary', palette.primary);
  root.style.setProperty('--lux-primary-dark', palette.primaryDark);
  root.style.setProperty('--lux-primary-soft', palette.primarySoft);
  root.style.setProperty('--lux-accent', palette.accent);
  root.style.setProperty('--lux-primary-rgb', palette.primaryRgb);
  root.style.setProperty('--lux-accent-rgb', palette.accentRgb);
  root.style.setProperty('--app-color-primary', palette.primary);
  root.style.setProperty('--app-color-primary-hover', palette.primaryDark);
  root.style.setProperty('--app-color-primary-light', palette.accent);
  root.style.setProperty('--app-color-primary-soft', palette.primarySoft);
  root.style.setProperty('--app-color-focus-ring', `rgba(${palette.primaryRgb}, 0.25)`);

  document.body.classList.toggle('lux-shell-dark', !!palette.darkShell);

  try {
    localStorage.setItem(STORAGE_KEY, palette.id);
  } catch (e) {
    /* ignore storage errors */
  }

  return palette.id;
}

export function initLuxTheme() {
  return applyLuxPalette(getLuxPaletteId());
}
