import dateUtils from "_helpers/date.utils";
import { getEmployeeDailyCapacityMinutes } from "./plannerCapacity.utils";
import { isEmployeeOnLeave } from "./plannerLeave.utils";
import { getWorkItemEmployeeId, normalizeWorkItemStatus } from "./planner.utils";

export function getUnassignedWorkItems(workItems) {
  return (workItems || []).filter((item) => {
    const eid = getWorkItemEmployeeId(item);
    const st = normalizeWorkItemStatus(item.status);
    if (st === "COMPLETED" || st === "CLOSED") return false;
    return eid == null || eid === "";
  });
}

export function evaluateAssignConflict({
  employee,
  dayMoment,
  hour,
  additionalMinutes,
  currentAllocatedMinutes,
  capacityOverrides,
  leaveMap,
}) {
  const dayKey = dayMoment.format("YYYY-MM-DD");
  const warnings = [];
  const errors = [];

  if (isEmployeeOnLeave(leaveMap, employee.id, dayKey)) {
    errors.push({
      code: "ON_LEAVE",
      message: `${employee.name} is on leave or PTO this day.`,
    });
  }

  const dayCap = getEmployeeDailyCapacityMinutes(employee, capacityOverrides);
  const slotCap = hour != null ? 60 : dayCap;
  const after = (currentAllocatedMinutes || 0) + (additionalMinutes || 60);
  const util = Math.round((after / Math.max(slotCap, 1)) * 100);

  if (util > 100) {
    errors.push({
      code: "OVER_CAPACITY",
      message: `Assignment would reach ${util}% of ${hour != null ? "that hour" : "daily"} capacity.`,
    });
  } else if (util >= 90) {
    warnings.push({
      code: "NEAR_LIMIT",
      message: `Utilization would be ${util}% — little buffer remains.`,
    });
  }

  return {
    canAssign: errors.length === 0,
    utilization: util,
    warnings,
    errors,
  };
}

export function buildAssignPayloadFromDrop(workItem, employee, dayMoment, hour) {
  const startM = dayMoment.clone();
  if (hour != null) {
    startM.hour(hour).minute(0).second(0);
  } else {
    startM.hour(8).minute(0).second(0);
  }
  const duration = workItem.estDurationInMins || 60;
  return {
    ...workItem,
    employeeId: employee.id,
    estStartTime: startM.format(dateUtils.SERVER_DATE_FORMAT),
    estDurationInMins: duration,
  };
}
