import React, { Component } from "react";
import { Modal } from "views/common/plugins/model/Modal";
import { Effect } from "views/common/plugins/model";
import { history } from "_helpers";
import { getAssistPanelModalStyle } from "./assistDock.utils";
import { AI_WORK_INTELLIGENCE_QUICK_LINKS } from "config/ai-work-intelligence-nav.config";
import { AI_WORK_INTELLIGENCE_ROUTES } from "config/ai-work-intelligence.config";
import { isAiWorkIntelligenceEnabled } from "config/ai-work-intelligence.config";
import { buildAgentConsoleKpis, filterAgentsByPersona } from "config/ai-work-intelligence.utils";
import { canViewAiWorkIntelligence } from "config/ai-work-intelligence-security.utils";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";
import "./AgentConsoleAssistModal.css";

const DEFAULT_PERSONA = "EXECUTIVE";

class AgentConsoleAssistModal extends Component {
  state = {
    loading: true,
    loadError: null,
    overview: null,
    agents: [],
    kpiCards: [],
  };

  componentDidMount() {
    this.loadData();
  }

  navigateTo = (path) => {
    const { onRequestClose } = this.props;
    if (onRequestClose) {
      onRequestClose();
    }
    history.push(path);
  };

  loadData = async () => {
    const persona = DEFAULT_PERSONA;
    this.setState({ loading: true, loadError: null });
    try {
      const [overviewResult, agentsResult] = await Promise.all([
        aiWorkIntelligenceService.getAgentConsoleOverview({ persona }),
        aiWorkIntelligenceService.listAgents({ persona }),
      ]);
      const overviewPayload = overviewResult.payload || {};
      this.setState({
        loading: false,
        overview: overviewPayload.overview || null,
        agents: filterAgentsByPersona(agentsResult.payload || [], persona).slice(0, 4),
        kpiCards: buildAgentConsoleKpis(overviewPayload.overview),
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load agent console.",
      });
    }
  };

  renderMetrics() {
    const { loading, kpiCards } = this.state;
    if (loading) {
      return <div className="lux-agent-console-assist__metrics lux-agent-console-assist__metrics--loading" aria-busy="true" />;
    }
    return (
      <div className="lux-agent-console-assist__metrics" role="list">
        {kpiCards.map((card) => (
          <article key={card.id} className="lux-agent-console-assist__metric" role="listitem">
            <span className="lux-agent-console-assist__metric-icon" aria-hidden="true">
              <i className={card.icon} />
            </span>
            <div>
              <strong>{card.value}</strong>
              <span>{card.label}</span>
            </div>
          </article>
        ))}
      </div>
    );
  }

  renderAgents() {
    const { loading, agents } = this.state;
    if (loading) {
      return null;
    }
    if (!agents.length) {
      return (
        <p className="lux-agent-console-assist__empty">
          No agents are visible for your persona yet. Open the full console to review registry settings.
        </p>
      );
    }
    return (
      <div className="lux-agent-console-assist__agents">
        {agents.map((agent) => (
          <button
            key={agent.id}
            type="button"
            className="lux-agent-console-assist__agent"
            onClick={() => this.navigateTo(agent.route || AI_WORK_INTELLIGENCE_ROUTES.CONSOLE)}
          >
            <span className="lux-agent-console-assist__agent-icon" aria-hidden="true">
              <i className={agent.icon || "fe fe-cpu"} />
            </span>
            <div className="lux-agent-console-assist__agent-copy">
              <strong>{agent.name}</strong>
              <span>{agent.description}</span>
            </div>
            <i className="fe fe-chevron-right lux-agent-console-assist__agent-chevron" aria-hidden="true" />
          </button>
        ))}
      </div>
    );
  }

  render() {
    const { onRequestClose, dockAnchor } = this.props;
    const { loading, loadError, overview } = this.state;
    const enabled = isAiWorkIntelligenceEnabled();
    const canView = canViewAiWorkIntelligence(DEFAULT_PERSONA);
    const pending = overview && overview.pendingRecommendationCount != null
      ? overview.pendingRecommendationCount
      : 0;

    return (
      <Modal
        onRequestClose={onRequestClose}
        effect={Effect.ScaleUp}
        style={getAssistPanelModalStyle(dockAnchor, { width: "420px" })}
      >
        <div className="agent-console-assist-modal lux-assist-panel lux-assist-panel--agents">
          <div className="lux-assist-panel__hero lux-assist-panel__hero--agents">
            <div className="lux-assist-panel__hero-bg" aria-hidden="true" />
            <div className="lux-assist-panel__hero-top">
              <div className="lux-assist-panel__brand">
                <span className="lux-assist-panel__brand-icon lux-assist-panel__brand-icon--agents">
                  <i className="fe fe-cpu" />
                </span>
                <div>
                  <span className="lux-assist-panel__kicker">Human-in-the-loop</span>
                  <h4 className="lux-assist-panel__title mb-0">Agent console</h4>
                </div>
              </div>
              <button
                type="button"
                onClick={onRequestClose}
                className="lux-assist-panel__close"
                aria-label="Close agent console panel"
              >
                <i className="fa fa-times" />
              </button>
            </div>
            <p className="lux-assist-panel__hero-lead">
              Review agent drafts, inspect evidence, and record accept / defer / reject decisions.
            </p>
            {!loading && pending > 0 ? (
              <div className="lux-agent-console-assist__pending-badge">
                <i className="fe fe-inbox" aria-hidden="true" />
                {pending} pending recommendation{pending === 1 ? "" : "s"}
              </div>
            ) : null}
          </div>

          <div className="lux-assist-panel__body lux-agent-console-assist__body">
            {!enabled || !canView ? (
              <div className="lux-assist-panel__card">
                <strong>AI work intelligence is not available</strong>
                <p>Enable AI modules in application config or switch to an authorized persona.</p>
              </div>
            ) : (
              <>
                {loadError ? (
                  <div className="lux-agent-console-assist__error" role="alert">
                    {loadError}
                    <button type="button" className="lux-agent-console-assist__retry" onClick={this.loadData}>
                      Retry
                    </button>
                  </div>
                ) : null}

                <div className="lux-assist-panel__feature-grid">
                  <div className="lux-assist-panel__feature">
                    <i className="fe fe-shield" aria-hidden="true" />
                    <span>Evidence-backed</span>
                  </div>
                  <div className="lux-assist-panel__feature">
                    <i className="fe fe-percent" aria-hidden="true" />
                    <span>Confidence scoring</span>
                  </div>
                  <div className="lux-assist-panel__feature">
                    <i className="fe fe-user-check" aria-hidden="true" />
                    <span>Approver decisions</span>
                  </div>
                </div>

                {this.renderMetrics()}

                <div className="lux-assist-panel__quick-links">
                  <span className="lux-assist-panel__quick-label">AI workspaces</span>
                  <div className="lux-assist-panel__quick-grid">
                    {AI_WORK_INTELLIGENCE_QUICK_LINKS.slice(0, 6).map((link) => (
                      <button
                        key={link.id}
                        type="button"
                        className="lux-assist-panel__quick-chip"
                        onClick={() => this.navigateTo(link.to)}
                      >
                        <i className={link.icon} aria-hidden="true" />
                        {link.label}
                      </button>
                    ))}
                  </div>
                </div>

                {this.renderAgents()}

                <button
                  type="button"
                  className="lux-assist-panel__cta lux-agent-console-assist__cta"
                  onClick={() => this.navigateTo(AI_WORK_INTELLIGENCE_ROUTES.CONSOLE)}
                >
                  Open full agent console
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </button>
              </>
            )}
          </div>
        </div>
      </Modal>
    );
  }
}

export default AgentConsoleAssistModal;
