import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import OptimisticUpdateWrapper from "views/common/fragments/OptimisticUpdateWrapper";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  formatProjectClientLine,
  getProjectBillingLabel,
  getProjectHoursPct,
  getProjectPriorityTone,
  getProjectStatusMeta,
  getProjectTaskPct,
  getProjectTimelineMeta,
  getProjectTypeMeta,
} from "./projectList.utils";

function ProgressRing({ pct, label, tone, caption }) {
  const safePct = Math.min(100, Math.max(0, Number(pct) || 0));
  return (
    <div className="lux-project-card__ring-wrap">
      <div
        className={classNames("lux-project-card__ring", tone && `is-${tone}`)}
        style={{ "--lux-ring-pct": safePct }}
        role="img"
        aria-label={`${label} ${safePct}%`}
      >
        <span className="lux-project-card__ring-value">{safePct}%</span>
      </div>
      <span className="lux-project-card__ring-label">{label}</span>
      {caption && <span className="lux-project-card__ring-caption">{caption}</span>}
    </div>
  );
}

class ProjectInfoGrid extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.cardRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.cardRef.current && !this.cardRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  stopBubble = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveProject(this.props.item.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  canEdit = () => {
    const { item, permission } = this.props;
    return !item.archived && permission.editEnabled && item.status !== "COMPLETED" && item.status !== "CLOSED";
  };

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [];
    if (permission.viewEnabled) {
      primary.push({ key: "view", icon: "fe fe-eye", label: "View project", onClick: () => this.props.onViewProject(item.id) });
    }
    if (this.canEdit()) {
      primary.push({ key: "edit", icon: "fe fe-edit-2", label: "Edit project", onClick: () => this.props.handleEditProject(item.id, item.userTeamId) });
    }
    if (permission.duplicateEnabled) {
      primary.push({ key: "duplicate", icon: "fe fe-copy", label: "Duplicate", onClick: () => this.props.handleDuplicateProject(item.id, item.userTeamId) });
    }

    const secondary = [];
    secondary.push({
      key: "favorite",
      icon: "fe fe-star",
      label: item.favorite ? "Remove favorite" : "Add to favorites",
      onClick: () => this.props.handleFavoriteProject(item.id, !item.favorite),
    });
    if (permission.archiveEnabled) {
      secondary.push({
        key: "archive",
        icon: item.archived ? "fe fe-inbox" : "fe fe-archive",
        label: item.archived ? "Unarchive" : "Archive",
        onClick: () => this.props.handleArchiveProject(item.id, !item.archived),
      });
    }
    if (permission.deleteEnabled) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeleteProject(item.id, !item.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  renderMenuItem = (entry) => (
    <button
      key={entry.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", entry.tone && `is-${entry.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(entry.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", entry.tone && `is-${entry.tone}`)}>
        <i className={entry.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy"><strong>{entry.label}</strong></span>
    </button>
  );

  render() {
    const { item, permission } = this.props;
    const { menuOpen } = this.state;
    const isOptimistic = item.optimistic || item.creating || item.updating || item.deleting;
    const optimisticStatus = item.deleteError ? "error" : item.optimistic ? "pending" : "success";
    const statusMeta = getProjectStatusMeta(item.status);
    const typeMeta = getProjectTypeMeta(item.projectType);
    const clientLine = formatProjectClientLine(item);
    const taskPct = getProjectTaskPct(item);
    const hoursPct = getProjectHoursPct(item);
    const timeline = getProjectTimelineMeta(item);
    const billingLabel = getProjectBillingLabel(item.type);
    const priorityTone = getProjectPriorityTone(item.priority);
    const initials = commonUtils.getNameInitial(item.name);
    const projectLabel = item.name || item.itemIdUserTeamPrefix;
    const { primary, secondary } = this.getMenuSections();
    const taskDone = Number(item.completedTaskCount) || 0;
    const taskTotal = Number(item.taskTotalCount) || 0;
    const taskOpen = Math.max(taskTotal - taskDone, 0);
    const hoursCaption = item.estHours ? `${item.actualHours || 0}/${item.estHours}h` : "No estimate";
    const taskCaption = taskTotal ? `${taskDone}/${taskTotal} done` : "No tasks";
    const scheduleCaption =
      timeline.daysRemaining == null
        ? timeline.label
        : timeline.daysRemaining < 0
          ? `${Math.abs(timeline.daysRemaining)}d overdue`
          : `${timeline.daysRemaining}d left`;

    return (
      <div className="lux-project-grid__item">
        <OptimisticUpdateWrapper isOptimistic={isOptimistic} status={optimisticStatus}>
          <article
            ref={this.cardRef}
            className={classNames("lux-project-card", `is-status-${statusMeta.tone}`, {
              "is-archived": item.archived,
              "is-deleted": item.deleted,
              "is-favorite": item.favorite,
              "is-menu-open": menuOpen,
              "is-optimistic": isOptimistic,
              "has-menu": primary.length > 0 || secondary.length > 0,
            })}
          >
            <span className="lux-project-card__accent" aria-hidden="true" />
            <span className="lux-project-card__glow" aria-hidden="true" />

            <header className="lux-project-card__top">
              <div className="lux-project-card__top-badges">
                <span className="lux-project-card__ref">{item.itemIdUserTeamPrefix}</span>
                {typeMeta && (
                  <span className={classNames("lux-project-card__type", `is-${typeMeta.tone}`)}>{typeMeta.label}</span>
                )}
                <span className={classNames("lux-project-card__status-pill", `is-${statusMeta.tone}`)}>{statusMeta.label}</span>
              </div>
              <div className="lux-project-card__top-actions">
                <button
                  type="button"
                  className={classNames("lux-project-list__fav lux-project-card__fav", { "is-active": item.favorite })}
                  onClick={() => this.props.handleFavoriteProject(item.id, !item.favorite)}
                  aria-label={item.favorite ? "Remove favorite" : "Add to favorites"}
                >
                  <i className="fe fe-star" aria-hidden="true" />
                </button>
                {permission.viewEnabled && (
                  <button
                    type="button"
                    className="lux-project-card__action"
                    title="View project"
                    aria-label={`View ${projectLabel}`}
                    onClick={(event) => {
                      this.stopBubble(event);
                      this.props.onViewProject(item.id);
                    }}
                  >
                    <i className="fe fe-eye" aria-hidden="true" />
                  </button>
                )}
                {this.canEdit() && (
                  <button
                    type="button"
                    className="lux-project-card__action"
                    title="Edit project"
                    aria-label={`Edit ${projectLabel}`}
                    onClick={(event) => {
                      this.stopBubble(event);
                      this.props.handleEditProject(item.id, item.userTeamId);
                    }}
                  >
                    <i className="fe fe-edit-2" aria-hidden="true" />
                  </button>
                )}
                <button
                  ref={this.menuTriggerRef}
                  type="button"
                  className="lux-project-card__action lux-project-card__action--menu"
                  onClick={this.toggleMenu}
                  aria-expanded={menuOpen}
                  aria-haspopup="menu"
                  aria-label={`More actions for ${projectLabel}`}
                >
                  <i className="fe fe-more-horizontal" aria-hidden="true" />
                </button>
                <LuxListRowMenuPortal open={menuOpen} anchorRef={this.menuTriggerRef} className="lux-bid-list__menu-panel">
                  <header className="lux-emp-card__menu-head">
                    <span className="lux-emp-card__menu-head-icon" aria-hidden="true"><i className="fe fe-layers" /></span>
                    <div>
                      <span className="lux-emp-card__menu-eyebrow">Project</span>
                      <strong title={projectLabel}>{projectLabel}</strong>
                    </div>
                    <button type="button" className="lux-emp-card__menu-close" onClick={this.runMenuAction(null)} aria-label="Close menu">
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  </header>
                  <div className="lux-emp-card__menu-body">
                    {primary.map(this.renderMenuItem)}
                    {secondary.length > 0 && primary.length > 0 && <div className="lux-emp-card__menu-divider" aria-hidden="true" />}
                    {secondary.map(this.renderMenuItem)}
                  </div>
                </LuxListRowMenuPortal>
              </div>
            </header>

            <div className="lux-project-card__hero">
              <div className="lux-project-card__avatar-wrap">
                <span className="lux-project-card__initials" aria-hidden="true">{initials}</span>
                <span className={classNames("lux-project-card__status-dot", `is-${statusMeta.tone}`)} title={statusMeta.label} />
              </div>
              <div className="lux-project-card__identity">
                {permission.viewEnabled ? (
                  <NavLink to={`/project/details/${item.itemIdUserTeamPrefix}`} className="lux-project-card__title" title={projectLabel}>
                    <span className="lux-project-card__title-text">{projectLabel}</span>
                    <i className="fe fe-arrow-up-right" aria-hidden="true" />
                  </NavLink>
                ) : (
                  <strong className="lux-project-card__title">{projectLabel}</strong>
                )}
                {item.accountName && (
                  <span className="lux-project-card__account" title={item.accountName}>
                    <i className="fe fe-briefcase" aria-hidden="true" />
                    {item.accountName}
                  </span>
                )}
                {clientLine && <span className="lux-project-card__meta">{clientLine}</span>}
                <div className="lux-project-card__signals">
                  {item.deleted && (
                    <span className="lux-project-card__signal is-danger">
                      <i className="fe fe-trash-2" aria-hidden="true" />
                      Deleted
                    </span>
                  )}
                  {item.shared && (
                    <span className="lux-project-card__signal is-indigo">
                      <i className="fe fe-share-2" aria-hidden="true" />
                      Shared
                    </span>
                  )}
                  {item.purchaseOrderId && (
                    <span className="lux-project-card__signal is-sky">
                      <i className="fe fe-link" aria-hidden="true" />
                      PO linked
                    </span>
                  )}
                  {item.priority && (
                    <span className={classNames("lux-project-card__signal", `is-${priorityTone}`)}>
                      <i className="fe fe-flag" aria-hidden="true" />
                      {item.priority}
                    </span>
                  )}
                  {billingLabel && (
                    <span className="lux-project-card__signal is-teal">
                      <i className="fe fe-dollar-sign" aria-hidden="true" />
                      {billingLabel}
                    </span>
                  )}
                </div>
              </div>
            </div>

            <section className="lux-project-card__viz" aria-label="Project progress">
              <div className="lux-project-card__rings">
                <ProgressRing pct={taskPct} label="Tasks" tone="indigo" caption={taskCaption} />
                <ProgressRing pct={hoursPct} label="Hours" tone="teal" caption={hoursCaption} />
              </div>
              <div className="lux-project-card__charts">
                <div className="lux-project-card__chart">
                  <div className="lux-project-card__chart-head">
                    <span>Task delivery</span>
                    <strong>{taskPct}%</strong>
                  </div>
                  <div className="lux-project-card__stack-bar" aria-hidden="true">
                    <span className="is-done" style={{ flexGrow: Math.max(taskDone, 0.01) }} />
                    <span className="is-open" style={{ flexGrow: Math.max(taskOpen, taskTotal ? 0.01 : 1) }} />
                  </div>
                  <p className="lux-project-card__chart-foot">{taskCaption}</p>
                </div>
                <div className="lux-project-card__chart">
                  <div className="lux-project-card__chart-head">
                    <span>Schedule</span>
                    <strong className={classNames(`is-${timeline.tone}`)}>{timeline.label}</strong>
                  </div>
                  <div className="lux-project-card__timeline-bar" aria-hidden="true">
                    <span
                      className={classNames("lux-project-card__timeline-elapsed", timeline.tone && `is-${timeline.tone}`)}
                      style={{ width: `${timeline.elapsedPct}%` }}
                    />
                  </div>
                  <p className="lux-project-card__chart-foot">{scheduleCaption}</p>
                </div>
              </div>
            </section>

            <ul className="lux-project-card__facts">
              <li className="lux-project-card__fact">
                <span className="lux-project-card__fact-icon"><i className="fe fe-calendar" aria-hidden="true" /></span>
                <span className="lux-project-card__fact-copy">
                  <em>Created</em>
                  <strong>{dateUtils.convertDateFormat(item.createdDate) || "—"}</strong>
                </span>
              </li>
              <li className="lux-project-card__fact">
                <span className="lux-project-card__fact-icon"><i className="fe fe-play-circle" aria-hidden="true" /></span>
                <span className="lux-project-card__fact-copy">
                  <em>Start</em>
                  <strong>{dateUtils.convertDateFormat(item.estStartTime) || "—"}</strong>
                </span>
              </li>
              <li className="lux-project-card__fact">
                <span className="lux-project-card__fact-icon"><i className="fe fe-flag" aria-hidden="true" /></span>
                <span className="lux-project-card__fact-copy">
                  <em>Due</em>
                  <strong>{dateUtils.convertDateFormat(item.estCompletionTime) || "—"}</strong>
                </span>
              </li>
              {item.complexity && (
                <li className="lux-project-card__fact">
                  <span className="lux-project-card__fact-icon"><i className="fe fe-layers" aria-hidden="true" /></span>
                  <span className="lux-project-card__fact-copy">
                    <em>Complexity</em>
                    <strong>{item.complexity}</strong>
                  </span>
                </li>
              )}
            </ul>

            <footer className="lux-project-card__footer">
              {permission.viewEnabled ? (
                <NavLink to={`/project/details/${item.itemIdUserTeamPrefix}`} className="lux-project-card__cta">
                  Open project
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </NavLink>
              ) : (
                <span className="lux-project-card__cta is-static">Project overview</span>
              )}
              <span className="lux-project-card__footer-meta">
                {dateUtils.convertDateFormat(item.estStartTime) || "—"} → {dateUtils.convertDateFormat(item.estCompletionTime) || "—"}
              </span>
            </footer>
          </article>
        </OptimisticUpdateWrapper>
      </div>
    );
  }
}

export default ProjectInfoGrid;
