import { notificationActions } from "./notification.actions";
import { approvalDelegationService } from "_services/approvalDelegation.service";
import { getApiErrorMessage } from "_helpers";

export const approvalDelegationActions = {
  loadMine,
  createDelegation,
  updateDelegation,
  revokeDelegation,
};

/** Famstack often returns HTTP 200 with ServiceResponse.error — treat as failure. */
function extractServiceError(response) {
  if (!response || typeof response !== "object" || !response.error) {
    return null;
  }
  const first = Array.isArray(response.error) ? response.error[0] : response.error;
  if (!first) {
    return null;
  }
  if (typeof first === "string") {
    return first;
  }
  return first.message || first.code || "Request failed";
}

function assertServiceSuccess(response) {
  if (typeof response === "string") {
    throw new Error(response || "Request failed");
  }
  const serviceError = extractServiceError(response);
  if (serviceError) {
    const error = new Error(serviceError);
    error.response = { data: response, status: 200 };
    throw error;
  }
  return response;
}

function loadMine(delegatorId) {
  return (dispatch) => {
    dispatch(request());
    return approvalDelegationService
      .listMine(delegatorId)
      .then((response) => {
        assertServiceSuccess(response);
        const delegations = (response && response.payload) || [];
        dispatch(success(delegations));
        return delegations;
      })
      .catch((error) => {
        dispatch(failure(error));
        return Promise.reject(error);
      });
  };

  function request() {
    return { type: "APPROVAL_DELEGATIONS_MINE_REQUEST" };
  }
  function success(delegations) {
    return { type: "APPROVAL_DELEGATIONS_MINE_SUCCESS", delegations };
  }
  function failure(error) {
    return { type: "APPROVAL_DELEGATIONS_MINE_FAILURE", error };
  }
}

function createDelegation(delegatorId, payload) {
  return (dispatch) =>
    approvalDelegationService
      .create(delegatorId, payload)
      .then((response) => {
        assertServiceSuccess(response);
        dispatch(notificationActions.success("Approval delegation created."));
        return response && response.payload;
      })
      .catch((error) => {
        const message = getApiErrorMessage(error, "Unable to create delegation.");
        dispatch(notificationActions.error(message));
        return Promise.reject(error);
      });
}

function updateDelegation(delegatorId, delegationId, payload) {
  return (dispatch) =>
    approvalDelegationService
      .update(delegatorId, delegationId, payload)
      .then((response) => {
        assertServiceSuccess(response);
        dispatch(notificationActions.success("Approval delegation updated."));
        return response && response.payload;
      })
      .catch((error) => {
        const message = getApiErrorMessage(error, "Unable to update delegation.");
        dispatch(notificationActions.error(message));
        return Promise.reject(error);
      });
}

function revokeDelegation(delegatorId, delegationId) {
  return (dispatch) =>
    approvalDelegationService
      .revoke(delegatorId, delegationId)
      .then((response) => {
        assertServiceSuccess(response);
        dispatch(notificationActions.success("Approval delegation ended."));
        return response && response.payload;
      })
      .catch((error) => {
        const message = getApiErrorMessage(error, "Unable to revoke delegation.");
        dispatch(notificationActions.error(message));
        return Promise.reject(error);
      });
}
