import React from "react";
import CountUp from "react-countup";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { getLeaveTypeLabel } from "./leave.utils";

function toNum(value) {
  const n = parseFloat(value);
  return Number.isNaN(n) ? 0 : n;
}

function LeaveBalanceCalculationPanel({ breakdown, leaveTypes, loading, onViewLedger }) {
  if (loading) {
    return (
      <section className="lux-leave-subpanel lux-leave-calc" aria-busy="true">
        <div className="lux-leave-register__skeleton" />
      </section>
    );
  }

  if (!breakdown) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-leave-empty"
        icon="fe fe-pie-chart"
        title="Balance breakdown unavailable"
        description="HR can configure entitlements under Admin → Leave policies."
      />
    );
  }

  const typeById = {};
  (leaveTypes || []).forEach((type) => {
    typeById[type.id] = type;
  });

  const balances = breakdown.balances || [];
  const totalEntitlement = toNum(breakdown.totalEntitlement);
  const totalUsed = toNum(breakdown.totalUsed);
  const totalBalance = toNum(breakdown.totalBalance);

  return (
    <section className="lux-leave-subpanel lux-leave-calc" aria-label="Leave balance calculation">
      <header className="lux-leave-subpanel__head">
        <div>
          <span className="lux-leave-subpanel__eyebrow">Entitlements</span>
          <h3 className="lux-leave-subpanel__title">Balance breakdown</h3>
          <p className="lux-leave-subpanel__sub">Entitlement, usage, and remaining balance by leave type</p>
        </div>
      </header>

      <div className="lux-leave-calc__totals">
        <article className="lux-leave-calc__total">
          <span>Total entitlement</span>
          <strong>
            <CountUp end={totalEntitlement} decimals={totalEntitlement % 1 ? 1 : 0} duration={0.6} />
            <small> days</small>
          </strong>
        </article>
        <article className="lux-leave-calc__total">
          <span>Used</span>
          <strong>
            <CountUp end={totalUsed} decimals={totalUsed % 1 ? 1 : 0} duration={0.6} />
            <small> days</small>
          </strong>
        </article>
        <article className="lux-leave-calc__total is-balance">
          <span>Remaining</span>
          <strong>
            <CountUp end={totalBalance} decimals={totalBalance % 1 ? 1 : 0} duration={0.6} />
            <small> days</small>
          </strong>
        </article>
      </div>

      {balances.length === 0 ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-leave-empty"
          icon="fe fe-layers"
          title="No balance records"
          description="No balance records for this employee yet."
        />
      ) : (
        <div className="lux-leave-register-wrap">
          <table className="lux-leave-register">
            <thead>
              <tr>
                <th>Type</th>
                <th>Entitlement</th>
                <th>Used</th>
                <th>Pending</th>
                <th>Balance</th>
                <th aria-hidden="true" />
              </tr>
            </thead>
            <tbody>
              {balances.map((row) => {
                const type = typeById[row.leaveTypeId || row.leave_type_id];
                const code = (type && type.code) || "—";
                const label = getLeaveTypeLabel(code, type && type.name);
                const leaveTypeId = row.leaveTypeId || row.leave_type_id;
                return (
                  <tr key={leaveTypeId || code} className="lux-leave-register__row">
                    <td>
                      <span className="lux-leave-register__type">
                        <strong>{label}</strong>
                        <em>{code}</em>
                      </span>
                    </td>
                    <td>{toNum(row.entitlement)}</td>
                    <td>{toNum(row.used)}</td>
                    <td>{toNum(row.pending)}</td>
                    <td>
                      <strong className="lux-leave-calc__balance-val">{toNum(row.balance)}</strong>
                    </td>
                    <td>
                      {onViewLedger && leaveTypeId && (
                        <button
                          type="button"
                          className="lux-leave-register__action"
                          onClick={() => onViewLedger(leaveTypeId)}
                        >
                          Ledger
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export default LeaveBalanceCalculationPanel;
