export function getAnalyticsShellPageTitle(meta = {}) {
  if (!meta) {
    return "Analytics";
  }
  return [meta.titleLead, meta.titleAccent].filter(Boolean).join(" ").trim();
}

export function resolveDomainFromPath(pathname) {
  if (!pathname) {
    return null;
  }
  const entries = Object.entries(ANALYTICS_DOMAIN_META);
  for (let i = 0; i < entries.length; i += 1) {
    const [domain, meta] = entries[i];
    if (pathname.indexOf(meta.path) === 0) {
      return domain;
    }
  }
  return null;
}
