import React, { useEffect, useRef } from "react";
import classNames from "classnames/bind";
import {
  getDayAllDayEvents,
  getNowIndicatorTop,
  getTimeSlots,
  HOUR_END,
  HOUR_HEIGHT_PX,
  layoutDayTimedEvents,
} from "./customCalendar.utils";
import LuxCalendarEventChip from "./LuxCalendarEventChip";

function DayColumn({
  day,
  events,
  selectedEvent,
  onSelectEvent,
  showNowLine,
  singleDay,
}) {
  const allDay = getDayAllDayEvents(events, day.moment);
  const timed = layoutDayTimedEvents(events, day.moment);
  const nowTop = showNowLine ? getNowIndicatorTop(day.moment) : null;

  return (
    <div
      className={classNames("lux-custom-cal__day-col", {
        "is-today": day.isToday,
        "is-weekend": day.isWeekend,
        "is-single": singleDay,
      })}
    >
      <div className="lux-custom-cal__col-head">
        <span className="lux-custom-cal__col-weekday">
          {singleDay ? day.moment.format("dddd") : day.moment.format("ddd")}
        </span>
        <span className="lux-custom-cal__col-date">{day.moment.format("D")}</span>
        {day.isToday && <span className="lux-custom-cal__today-pill">Today</span>}
      </div>

      {allDay.length > 0 && (
        <div className="lux-custom-cal__allday-row">
          {allDay.map((ev) => (
            <LuxCalendarEventChip
              key={ev.id}
              event={ev}
              compact
              selected={selectedEvent && selectedEvent.id === ev.id}
              onSelect={onSelectEvent}
            />
          ))}
        </div>
      )}

      <div
        className="lux-custom-cal__slots"
        style={{ height: `${HOUR_END * HOUR_HEIGHT_PX}px` }}
      >
        {[...Array(HOUR_END)].map((_, h) => (
          <span key={h} className="lux-custom-cal__hour-line" style={{ top: h * HOUR_HEIGHT_PX }} />
        ))}
        {nowTop != null && (
          <span className="lux-custom-cal__now-line" style={{ top: nowTop }} aria-hidden="true">
            <span className="lux-custom-cal__now-dot" />
          </span>
        )}
        {timed.map(({ event, top, height, column, columns }) => (
          <div
            key={event.id}
            className="lux-custom-cal__timed-slot"
            style={{
              top,
              height,
              left: `${(column / columns) * 100}%`,
              width: `${100 / columns}%`,
            }}
          >
            <LuxCalendarEventChip
              event={event}
              compact
              selected={selectedEvent && selectedEvent.id === event.id}
              onSelect={onSelectEvent}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default function LuxCustomCalendarTimeGrid({
  days,
  events,
  selectedEvent,
  onSelectEvent,
  singleDay,
}) {
  const scrollRef = useRef(null);
  const slots = getTimeSlots();

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const nowLine = el.querySelector(".lux-custom-cal__now-line");
    if (nowLine && nowLine.scrollIntoView) {
      nowLine.scrollIntoView({ block: "center", behavior: "smooth" });
    }
  }, [days]);

  return (
    <div className={classNames("lux-custom-cal lux-custom-cal--time", { "is-single-day": singleDay })}>
      <div className="lux-custom-cal__time-scroll" ref={scrollRef}>
        <div className="lux-custom-cal__time-layout">
          <div className="lux-custom-cal__gutter">
            <span className="lux-custom-cal__gutter-label">Time</span>
            <div className="lux-custom-cal__gutter-slots" style={{ height: `${HOUR_END * HOUR_HEIGHT_PX}px` }}>
              {slots.map((slot) => (
                <span
                  key={slot.hour}
                  className="lux-custom-cal__gutter-hour"
                  style={{ top: slot.hour * HOUR_HEIGHT_PX }}
                >
                  {slot.label}
                </span>
              ))}
            </div>
          </div>
          <div className={classNames("lux-custom-cal__day-cols", { "is-single": singleDay })}>
            {days.map((day) => (
              <DayColumn
                key={day.moment.format("YYYY-MM-DD")}
                day={day}
                events={events}
                selectedEvent={selectedEvent}
                onSelectEvent={onSelectEvent}
                showNowLine
                singleDay={singleDay}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
