import React, { Component } from "react";
import classNames from "classnames/bind";
import {
  buildPendingApprovalGroupsForManager,
  formatPendingAttendanceSummary,
  getAttendanceStatusMeta,
  isAttendancePendingRemoval,
  summarizePendingApprovalsForManager,
} from "./attendance.utils";
import AttendanceApprovalCommentField from "./AttendanceApprovalCommentField";
import ApprovalActingForBadge from "../delegation/ApprovalActingForBadge";
import { getPendingInboxEyebrow } from "_helpers/approvalAuthority.utils";

class AttendancePendingApprovals extends Component {
  constructor(props) {
    super(props);
    this.state = { comments: {}, rejectErrors: {}, rejectItemErrors: {}, collapsed: false };
  }

  getComment = (employeeId) => this.state.comments[employeeId] || "";

  setComment = (employeeId, value) => {
    this.setState((prevState) => ({
      comments: { ...prevState.comments, [employeeId]: value },
      rejectErrors:
        prevState.rejectErrors[employeeId] && value.trim()
          ? { ...prevState.rejectErrors, [employeeId]: null }
          : prevState.rejectErrors,
      rejectItemErrors: value.trim() ? {} : prevState.rejectItemErrors,
    }));
  };

  getItemActionLabels = (item) =>
    isAttendancePendingRemoval(item)
      ? { approve: "Approve removal", reject: "Keep attendance" }
      : { approve: "Approve", reject: "Reject" };

  handleApproveItem = (group, item) => {
    const { onApprove, isLoading } = this.props;
    if (isLoading || !onApprove) return;
    onApprove(item.id, this.getComment(group.employeeId), item);
  };

  handleRejectItem = (group, item) => {
    const { onReject, isLoading } = this.props;
    if (isLoading || !onReject) return;
    const comment = this.getComment(group.employeeId).trim();
    if (!comment) {
      const message = isAttendancePendingRemoval(item)
        ? "Add a comment above explaining why this attendance should be kept."
        : "Add a rejection comment above before rejecting.";
      this.setState((prevState) => ({
        rejectItemErrors: { ...prevState.rejectItemErrors, [item.id]: message },
        rejectErrors: { ...prevState.rejectErrors, [group.employeeId]: message },
      }));
      return;
    }
    this.setState((prevState) => ({
      rejectItemErrors: { ...prevState.rejectItemErrors, [item.id]: null },
      rejectErrors: { ...prevState.rejectErrors, [group.employeeId]: null },
    }));
    onReject(item.id, comment, item);
  };

  toggleCollapsed = () => {
    this.setState((prevState) => ({ collapsed: !prevState.collapsed }));
  };

  getGroupActionLabels = (group) => {
    const removalCount = group.items.filter((item) => isAttendancePendingRemoval(item)).length;
    if (removalCount === group.items.length) {
      return { approve: "Approve removals", reject: "Keep all" };
    }
    if (removalCount === 0) {
      return { approve: "Approve all", reject: "Reject all" };
    }
    return { approve: "Approve all", reject: "Decline all" };
  };

  handleApproveAll = (group) => {
    const { onApprove, isLoading } = this.props;
    if (isLoading || !onApprove) return;
    const comment = this.getComment(group.employeeId);
    group.items.forEach((item) => onApprove(item.id, comment, item));
  };

  handleRejectAll = (group) => {
    const { onReject, isLoading } = this.props;
    if (isLoading || !onReject) return;
    const comment = this.getComment(group.employeeId).trim();
    if (!comment) {
      this.setState((prevState) => ({
        rejectErrors: {
          ...prevState.rejectErrors,
          [group.employeeId]: group.items.some((item) => isAttendancePendingRemoval(item))
            ? "Please explain why the attendance should be kept."
            : "Please enter a rejection reason before rejecting.",
        },
      }));
      return;
    }
    this.setState((prevState) => ({
      rejectErrors: { ...prevState.rejectErrors, [group.employeeId]: null },
    }));
    group.items.forEach((item) => onReject(item.id, comment, item));
  };

  renderCollapsedSummary = (summary) => (
    <button
      type="button"
      className="lux-att-pending__collapsed-bar"
      onClick={this.toggleCollapsed}
      aria-expanded="false"
      aria-label={`${summary.total} pending attendance requests. Click to expand.`}
    >
      <span className="lux-att-pending__collapsed-icon" aria-hidden="true">
        <i className="fe fe-calendar" />
      </span>
      <span className="lux-att-pending__collapsed-copy">
        <strong>
          {summary.total} pending attendance request{summary.total === 1 ? "" : "s"} need your review
        </strong>
        <em>
          {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
          {summary.approvalCount > 0
            ? ` · ${summary.approvalCount} approval${summary.approvalCount === 1 ? "" : "s"}`
            : ""}
          {summary.removalCount > 0
            ? ` · ${summary.removalCount} removal${summary.removalCount === 1 ? "" : "s"}`
            : ""}
        </em>
      </span>
      <span className="lux-att-pending__count">{summary.total}</span>
      <span className="lux-att-pending__collapsed-expand">
        Expand
        <i className="fe fe-chevron-down" aria-hidden="true" />
      </span>
    </button>
  );

  render() {
    const { employees, items, currentUserId, isLoading, onViewDetails, pendingOptions } = this.props;
    const { collapsed } = this.state;

    const pendingGroups = buildPendingApprovalGroupsForManager(
      employees,
      items,
      currentUserId,
      pendingOptions
    );
    if (!pendingGroups.length) return null;

    const summary = summarizePendingApprovalsForManager(
      employees,
      items,
      currentUserId,
      pendingOptions
    );
    const actingDelegations =
      (pendingOptions && pendingOptions.actingDelegations) || [];
    const inboxEyebrow = getPendingInboxEyebrow(pendingGroups);

    if (collapsed) {
      return (
        <section
          className="lux-att-pending lux-att-pending--collapsed"
          aria-label="Pending attendance approvals"
        >
          {this.renderCollapsedSummary(summary)}
        </section>
      );
    }

    return (
      <section className="lux-att-pending" aria-label="Pending attendance approvals">
        <header className="lux-att-pending__head">
          <div>
            {inboxEyebrow && <span className="lux-att-pending__eyebrow">{inboxEyebrow}</span>}
            <h3>Pending approvals</h3>
            <p>
              {summary.total} request{summary.total === 1 ? "" : "s"} across{" "}
              {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
            </p>
            <div className="lux-att-pending__summary-chips" aria-label="Pending request breakdown">
              {summary.approvalCount > 0 && (
                <span className="lux-att-pending__chip is-approval">
                  <i className="fe fe-clock" aria-hidden="true" />
                  {summary.approvalCount} approval{summary.approvalCount === 1 ? "" : "s"}
                </span>
              )}
              {summary.removalCount > 0 && (
                <span className="lux-att-pending__chip is-removal">
                  <i className="fe fe-minus-circle" aria-hidden="true" />
                  {summary.removalCount} removal{summary.removalCount === 1 ? "" : "s"}
                </span>
              )}
            </div>
          </div>
          <div className="lux-att-pending__head-actions">
            <span className="lux-att-pending__count">{summary.total}</span>
            <button
              type="button"
              className="lux-att-pending__toggle"
              onClick={this.toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse pending approvals"
            >
              Collapse
            </button>
          </div>
        </header>

        <div className="lux-att-pending__list">
          {pendingGroups.map((group) => {
            const actionLabels = this.getGroupActionLabels(group);
            return (
              <div key={group.employeeId} className="lux-att-pending__group">
                <h4 className="lux-att-pending__employee">
                  <span className="lux-att-pending__employee-avatar" aria-hidden="true">
                    {(group.employeeName || "?").charAt(0).toUpperCase()}
                  </span>
                  <span className="lux-att-pending__employee-copy">
                    <strong>{group.employeeName}</strong>
                    <em>
                      {group.requestCount} day{group.requestCount === 1 ? "" : "s"} pending approval
                    </em>
                  </span>
                  <ApprovalActingForBadge
                    record={group}
                    actingDelegations={actingDelegations}
                    employees={employees}
                  />
                </h4>

                <article className="lux-att-pending__card">
                  <ul
                    className="lux-att-pending__dates"
                    aria-label={`Pending days for ${group.employeeName}`}
                  >
                    {group.items.map((item) => {
                      const statusMeta = getAttendanceStatusMeta(item);
                      const itemActions = this.getItemActionLabels(item);
                      return (
                        <li
                          key={item.id}
                          className={classNames(
                            "lux-att-pending__date-row",
                            `is-${statusMeta.tone}`
                          )}
                        >
                          <span className="lux-att-pending__date-type" title={statusMeta.label}>
                            <i className={statusMeta.icon} aria-hidden="true" />
                          </span>
                          <div className="lux-att-pending__date-copy">
                            <strong>{formatPendingAttendanceSummary(item)}</strong>
                            <span>{statusMeta.label}</span>
                            {this.state.rejectItemErrors[item.id] && (
                              <em className="lux-att-pending__date-error" role="alert">
                                {this.state.rejectItemErrors[item.id]}
                              </em>
                            )}
                          </div>
                          <div className="lux-att-pending__date-actions">
                            <button
                              type="button"
                              className="lux-att-pending__btn is-ghost"
                              disabled={isLoading}
                              onClick={() => onViewDetails && onViewDetails(item)}
                            >
                              View
                            </button>
                            <button
                              type="button"
                              className={classNames("lux-att-pending__btn is-primary is-compact", {
                                "is-loading": isLoading,
                              })}
                              disabled={isLoading}
                              onClick={() => this.handleApproveItem(group, item)}
                            >
                              {itemActions.approve}
                            </button>
                            <button
                              type="button"
                              className={classNames("lux-att-pending__btn is-danger is-compact", {
                                "is-loading": isLoading,
                              })}
                              disabled={isLoading}
                              onClick={() => this.handleRejectItem(group, item)}
                            >
                              {itemActions.reject}
                            </button>
                          </div>
                        </li>
                      );
                    })}
                  </ul>

                  <AttendanceApprovalCommentField
                    value={this.getComment(group.employeeId)}
                    onChange={(value) => this.setComment(group.employeeId, value)}
                    disabled={isLoading}
                    required
                    error={this.state.rejectErrors[group.employeeId]}
                    id={`lux-att-pending-comment-${group.employeeId}`}
                  />

                  <div className="lux-att-pending__actions">
                    <button
                      type="button"
                      className={classNames("lux-att-pending__btn is-primary", {
                        "is-loading": isLoading,
                      })}
                      disabled={isLoading}
                      onClick={() => this.handleApproveAll(group)}
                    >
                      {actionLabels.approve}
                    </button>
                    <button
                      type="button"
                      className={classNames("lux-att-pending__btn is-danger", {
                        "is-loading": isLoading,
                      })}
                      disabled={isLoading}
                      onClick={() => this.handleRejectAll(group)}
                    >
                      {actionLabels.reject}
                    </button>
                  </div>
                </article>
              </div>
            );
          })}
        </div>
      </section>
    );
  }
}

export default AttendancePendingApprovals;
