import React, { Component } from "react";
import { connect } from "react-redux";
import { purchaseOrderActions } from "_actions";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import CreatePurchaseOrderSidebarSection from "./CreatePurchaseOrderSidebarSection";

class CreatePurchaseOrderSidebar extends Component {
  render() {
    const { editMode, duplicateMode, show } = this.props;
    const ready =
      show &&
      ((editMode && this.props.selectedPurchaseOrderInfo) ||
        (duplicateMode && this.props.selectedPurchaseOrderInfo) ||
        (!editMode && !duplicateMode));

    const title = editMode
      ? "Update purchase contract"
      : duplicateMode
      ? "Duplicate purchase contract"
      : "Create purchase contract";

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={this.props.closeActionHandler}
        panelId="createpurchaseOrdersidebar"
        className="lux-create-panel--po create_purchaseOrder_right_sidebar"
        kicker="Projects workspace"
        title={title}
        subtitle={
          editMode || duplicateMode
            ? "Full form or guided steps — same contract data."
            : "Use guided steps for a clean flow, or the full form for speed."
        }
      >
        {ready && (
          <CreatePurchaseOrderSidebarSection
            handleSubmit={this.props.handleSubmit}
            editMode={editMode}
            duplicateMode={duplicateMode}
            selectedPurchaseOrderInfo={this.props.selectedPurchaseOrderInfo}
            permission={this.props.permission}
          />
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  fieldConfig: state.purchaseOrders.fieldConfig,
  createConfig: state.purchaseOrders.createConfig,
  allPurchaseOrderTeamAccounts: state.accounts.allProjectTeamAccounts,
  employeeAppConfig: state.employees.createConfig,
  allUserTeams: state.appconfig.allTeams,
  allEmployees: state.employees.allEmployees,
  allRoles: state.appconfig.allRoles,
  creating: state.purchaseOrders.creating,
  updating: state.purchaseOrders.updating,
});

const mapDispatchToProps = (dispatch) => ({
  initializeCreatePurchaseOrder: purchaseOrderActions.initializeCreatePurchaseOrder,
});

export default connect(mapStateToProps, mapDispatchToProps)(CreatePurchaseOrderSidebar);
