/**
 * F08-T1 — Payroll schema field registry and validation helpers.
 */
import { PAYROLL_RUN_STATUSES } from "config/payroll.config";

export const PAYROLL_SCHEMA_TABLES = {
  SALARY_STRUCTURE: "ts_salary_structure_model",
  PAYROLL_COMPONENT: "ts_payroll_component_model",
  PAYROLL_GROUP: "ts_payroll_group_model",
  PAYROLL_RUN: "ts_payroll_run_model",
  PAYROLL_LINE: "ts_payroll_line_model",
  PAYROLL_EXCEPTION: "ts_payroll_exception_model",
};

export const PAYROLL_RUN_FINALIZED_STATUSES = [
  PAYROLL_RUN_STATUSES.FINALIZED,
  PAYROLL_RUN_STATUSES.LOCKED,
];

export function validateSalaryStructurePayload(payload) {
  const errors = [];
  if (!payload || !String(payload.name || "").trim()) {
    errors.push("Structure name is required.");
  }
  if (!payload || !String(payload.code || "").trim()) {
    errors.push("Structure code is required.");
  }
  return { valid: errors.length === 0, errors };
}

export function validatePayrollGroupPayload(payload) {
  const errors = [];
  if (!payload || !String(payload.name || "").trim()) {
    errors.push("Group name is required.");
  }
  if (!payload || !String(payload.payFrequency || "").trim()) {
    errors.push("Pay frequency is required.");
  }
  return { valid: errors.length === 0, errors };
}

export function validatePayrollRunPayload(payload) {
  const errors = [];
  if (!payload || !String(payload.name || "").trim()) {
    errors.push("Run name is required.");
  }
  if (!payload || !payload.groupId) {
    errors.push("Payroll group is required.");
  }
  if (!payload || !payload.periodStart || !payload.periodEnd) {
    errors.push("Pay period start and end dates are required.");
  }
  return { valid: errors.length === 0, errors };
}

export function isPayrollRunFinalized(run) {
  if (!run || !run.status) {
    return false;
  }
  return PAYROLL_RUN_FINALIZED_STATUSES.indexOf(run.status) >= 0;
}

export function mapPayrollRunToSchemaRow(run, userTeamId) {
  return {
    table: PAYROLL_SCHEMA_TABLES.PAYROLL_RUN,
    run_ref: run && run.id,
    name: run && run.name,
    group_id: run && run.groupId,
    group_name: run && run.groupName,
    period_start: run && run.periodStart,
    period_end: run && run.periodEnd,
    pay_date: run && run.payDate,
    status: run && run.status,
    employee_count: run && run.employeeCount,
    gross_total: run && run.grossTotal,
    net_total: run && run.netTotal,
    exception_count: run && run.exceptionCount,
    blocker_count: run && run.blockerCount,
    readiness_score: run && run.readinessScore,
    user_team_id: userTeamId,
  };
}
