import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

export default function EmployeeFinanceMarginRiskPanel({ flags = [], loading }) {
  if (loading) {
    return <div className="lux-empfin-risk__skeleton" aria-busy="true" />;
  }

  if (!flags.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No margin risk flags"
        description="Cost-to-Revenue Intelligence surfaces employees and projects below the margin threshold."
      />
    );
  }

  return (
    <div className="lux-empfin-risk">
      {flags.map((flag) => (
        <article
          key={flag.id}
          className={classNames("lux-empfin-risk__card", flag.severity && `is-${flag.severity.toLowerCase()}`)}
        >
          <div className="lux-empfin-risk__top">
            <span className="lux-empfin-chip is-violet">{flag.riskType.replace(/_/g, " ")}</span>
            <span className="lux-empfin-chip is-rose">{flag.severity}</span>
            <span className="lux-empfin-chip is-indigo">{flag.confidencePct}% confidence</span>
          </div>
          <h3>{flag.employeeName}</h3>
          {flag.projectName ? <p className="lux-empfin-risk__project">{flag.projectName}</p> : null}
          <p>{flag.recommendation}</p>
          <div className="lux-empfin-risk__meta">
            <span>{flag.evidence}</span>
            <span>{flag.marginPct}% margin · {flag.flaggedAt}</span>
          </div>
        </article>
      ))}
    </div>
  );
}
