import { notificationConstants } from '../_constants';
import { getApiErrorMessage } from '../_helpers/apiError.utils';

export const notificationActions = {
    success,
    info,
    warning,
    error,
    pageMessage,
    connectionError,
    clearConnectionError,
    clear
};

function success(message) {
    return { type: notificationConstants.SUCCESS, message, title: "Success" };
}
function info(message) {
    return { type: notificationConstants.INFO, message, title: "Info" };
}
function warning(message) {
    return { type: notificationConstants.WARNING, message: normalizeNotice(message), title: "Warning" };
}
function error(message) {
    return {
        type: notificationConstants.ERROR,
        message: getApiErrorMessage(message, "Something went wrong. Please try again."),
        title: "Error",
    };
}
function pageMessage(message) {
    return {
        type: notificationConstants.PAGEMESSAGE,
        message: getApiErrorMessage(message, "Something went wrong. Please try again."),
        title: "Error",
    };
}
function connectionError() {
    return { type: notificationConstants.CONNECTION_ERROR };
}
function clearConnectionError() {
    return { type: notificationConstants.CONNECTION_ERROR_CLEAR };
}
function clear() {
    return { type: notificationConstants.CLEAR };
}

function normalizeNotice(message) {
    if (message == null || message === "") {
        return message;
    }
    return getApiErrorMessage(message, typeof message === "string" ? message : "Something went wrong. Please try again.");
}
