import React, { Component } from "react";
import classNames from "classnames/bind";
import DateRangePicker from "react-daterange-picker";
import "react-daterange-picker/dist/css/react-calendar.css";
import originalMoment from "moment";
import { extendMoment } from "moment-range";
import LuxPageHeaderPopoverPortal from "./LuxPageHeaderPopoverPortal";

const moment = extendMoment(originalMoment);

class DateRangeSelector extends Component {
  constructor(props, context) {
    super(props, context);
    this.state = {
      isOpen: false,
      value: this.props.defaultDateRangeValue,
    };
    this.wrapRef = React.createRef();
    this.buttonRef = React.createRef();
    this.popoverRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick, true);
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.defaultDateRangeValue !== this.props.defaultDateRangeValue &&
      this.props.defaultDateRangeValue
    ) {
      this.setState({ value: this.props.defaultDateRangeValue });
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick, true);
  }

  handleOutsideClick = (event) => {
    if (!this.state.isOpen) return;
    const wrap = this.wrapRef.current;
    const popover = this.popoverRef.current;
    if (wrap && wrap.contains(event.target)) return;
    if (popover && popover.contains(event.target)) return;
    this.setState({ isOpen: false });
  };

  onSelect = (value, states) => {
    if (this.props.isLoading) return;
    this.setState({ value, states, isOpen: false });
    if (this.props.onDateRangeChange) {
      this.props.onDateRangeChange(value);
    }
  };

  onToggle = (event) => {
    event.stopPropagation();
    if (this.props.isLoading) return;
    this.setState((prev) => ({ isOpen: !prev.isOpen }));
  };

  renderSelectionValue = () => {
    const value = this.state.value;
    if (!value || !value.start || !value.end) {
      return "Select dates";
    }
    return (
      value.start.format("MMM D, YYYY") +
      " – " +
      value.end.format("MMM D, YYYY")
    );
  };

  render() {
    return (
      <div
        className={classNames("lux-page-header__date-range", {
          "is-open": this.state.isOpen,
        })}
        ref={this.wrapRef}
      >
        <button
          ref={this.buttonRef}
          type="button"
          className={classNames("lux-page-header__date-range-btn", {
            "is-open": this.state.isOpen,
          })}
          onClick={this.onToggle}
          disabled={this.props.isLoading}
          aria-expanded={this.state.isOpen}
          title={this.renderSelectionValue()}
        >
          <i className="fe fe-calendar" aria-hidden="true" />
          <span className="lux-page-header__date-range-value">{this.renderSelectionValue()}</span>
          <i className="fe fe-chevron-down" aria-hidden="true" />
        </button>

        <LuxPageHeaderPopoverPortal
          isOpen={this.state.isOpen}
          anchorRef={this.buttonRef}
          align="right"
          popoverRef={this.popoverRef}
          className="lux-page-header__date-range-popover"
        >
          <DateRangePicker
            firstOfWeek={1}
            numberOfCalendars={2}
            selectionType="range"
            value={this.state.value}
            onSelect={this.onSelect}
            singleDateRange={true}
          />
        </LuxPageHeaderPopoverPortal>
      </div>
    );
  }
}

export default DateRangeSelector;
