import React, { createContext, useContext, useEffect, useMemo, useState } from "react";

const PageChromeContext = createContext({
  pageDataSource: null,
  setPageDataSource: () => {},
});

export function PageChromeProvider({ children }) {
  const [pageDataSource, setPageDataSource] = useState(null);
  const value = useMemo(
    () => ({ pageDataSource, setPageDataSource }),
    [pageDataSource]
  );
  return <PageChromeContext.Provider value={value}>{children}</PageChromeContext.Provider>;
}

export function usePageChrome() {
  return useContext(PageChromeContext);
}

/** Publish the active page data source to the global header chrome. */
export function normalizePageDataSource(dataSource) {
  if (dataSource === "live") {
    return "api";
  }
  return dataSource;
}

export function useReportPageDataSource(dataSource) {
  const { setPageDataSource } = usePageChrome();
  const normalized = normalizePageDataSource(dataSource);

  useEffect(() => {
    setPageDataSource(normalized || null);
    return () => setPageDataSource(null);
  }, [normalized, setPageDataSource]);
}

/** Renderless helper for class components. */
export function PageDataSourceReporter({ dataSource }) {
  useReportPageDataSource(dataSource);
  return null;
}
