import React, { Component } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import {
  getProjectCalendarMilestones,
  getProjectScheduleWindow,
} from "./projectDetailsTab.utils";

const PHASE_COPY = {
  upcoming: { label: "Upcoming", hint: "Before planned start" },
  active: { label: "In window", hint: "Between start and due" },
  complete: { label: "Past due", hint: "After estimated completion" },
  unscheduled: { label: "Partial", hint: "One side of the window missing" },
};

class ProjectDetailsCalendar extends Component {
  renderScheduleWindow = (window) => {
    if (!window) return null;
    const phase = PHASE_COPY[window.phase] || PHASE_COPY.unscheduled;

    return (
      <section className={classNames("lux-pd-calendar__window", `is-${window.phase}`)}>
        <header className="lux-pd-calendar__window-head">
          <div>
            <span className="lux-pd-calendar__window-eyebrow">Delivery window</span>
            <strong>{phase.label}</strong>
            <span className="lux-pd-calendar__window-hint">{phase.hint}</span>
          </div>
          {window.durationDays != null && (
            <div className="lux-pd-calendar__window-duration">
              <span>Duration</span>
              <strong>
                {window.durationDays} day{window.durationDays === 1 ? "" : "s"}
              </strong>
            </div>
          )}
        </header>

        <div className="lux-pd-calendar__window-range" aria-label="Estimated schedule range">
          <div className="lux-pd-calendar__window-point">
            <span>Start</span>
            <strong>{window.startLabel}</strong>
          </div>
          <span className="lux-pd-calendar__window-arrow" aria-hidden="true">
            <i className="fe fe-arrow-right" />
          </span>
          <div className="lux-pd-calendar__window-point is-end">
            <span>Due</span>
            <strong>{window.endLabel}</strong>
          </div>
        </div>

        {window.progressPct != null && (
          <div className="lux-pd-calendar__window-progress">
            <div className="lux-pd-calendar__window-progress-meta">
              <span>
                {window.phase === "upcoming"
                  ? "Not started yet"
                  : window.phase === "complete"
                    ? "Window complete"
                    : `${window.progressPct}% through the window`}
              </span>
              {window.remainingDays != null && (
                <em>
                  {window.remainingDays < 0
                    ? `${Math.abs(window.remainingDays)}d overdue`
                    : window.remainingDays === 0
                      ? "Due today"
                      : `${window.remainingDays}d remaining`}
                </em>
              )}
            </div>
            <div
              className="lux-pd-calendar__window-bar"
              role="progressbar"
              aria-valuenow={window.progressPct}
              aria-valuemin={0}
              aria-valuemax={100}
            >
              <span style={{ width: `${window.progressPct}%` }} />
            </div>
          </div>
        )}
      </section>
    );
  };

  renderMilestone = (event) => (
    <li key={event.id} className={classNames("lux-pd-calendar__event", `is-${event.tone}`)}>
      <span className="lux-pd-calendar__event-rail" aria-hidden="true" />
      <span className="lux-pd-calendar__event-icon" aria-hidden="true">
        <i className={event.icon} />
      </span>
      <div className="lux-pd-calendar__event-body">
        <div className="lux-pd-calendar__event-top">
          <strong>{event.label}</strong>
          {event.relative && (
            <span className="lux-pd-calendar__event-relative">{event.relative}</span>
          )}
        </div>
        {event.hint && <p className="lux-pd-calendar__event-hint">{event.hint}</p>}
        <div className="lux-pd-calendar__event-meta">
          <time dateTime={event.date}>{event.display}</time>
          {event.weekday && <span>{event.weekday}</span>}
        </div>
      </div>
    </li>
  );

  render() {
    const { projectInfo } = this.props;
    if (!projectInfo) return null;

    const milestones = getProjectCalendarMilestones(projectInfo);
    const scheduleWindow = getProjectScheduleWindow(projectInfo);
    const hasSchedule = !!(projectInfo.estStartTime || projectInfo.estCompletionTime);
    const phase = scheduleWindow ? PHASE_COPY[scheduleWindow.phase] : null;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-calendar"
        tone="calendar"
        eyebrow="Schedule"
        title="Project calendar"
        subtitle="Key dates from the project record — delivery window, milestones, and a link to your full workspace calendar."
        stats={[
          {
            key: "milestones",
            label: "Milestones",
            value: milestones.length,
            hint: "From project info",
            tone: "violet",
          },
          {
            key: "range",
            label: "Window",
            value: hasSchedule ? (phase ? phase.label : "Set") : "—",
            hint: hasSchedule ? "Start & due" : "Not scheduled",
            tone: hasSchedule ? "mint" : "slate",
          },
          {
            key: "days",
            label: "Duration",
            value:
              scheduleWindow && scheduleWindow.durationDays != null
                ? `${scheduleWindow.durationDays}d`
                : "—",
            hint: "Estimated span",
            tone: "sky",
          },
        ]}
      >
        <div className="lux-pd-calendar">
          {milestones.length > 0 ? (
            <>
              {this.renderScheduleWindow(scheduleWindow)}

              <section className="lux-pd-calendar__milestones" aria-label="Project milestones">
                <header className="lux-pd-calendar__section-head">
                  <span className="lux-pd-calendar__section-icon" aria-hidden="true">
                    <i className="fe fe-map-pin" />
                  </span>
                  <div>
                    <strong>Milestone timeline</strong>
                    <span>Chronological dates recorded on this project</span>
                  </div>
                </header>
                <ul className="lux-pd-calendar__timeline">
                  {milestones.map(this.renderMilestone)}
                </ul>
              </section>

              <aside className="lux-pd-calendar__footer-card">
                <span className="lux-pd-calendar__footer-icon" aria-hidden="true">
                  <i className="fe fe-calendar" />
                </span>
                <div>
                  <strong>Need the full schedule?</strong>
                  <span>
                    Open the workspace calendar for team availability, work items, and holidays.
                  </span>
                </div>
                <Link to="/project/calendar" className="lux-pd-calendar__footer-btn">
                  Open calendar
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </Link>
              </aside>
            </>
          ) : (
            <LuxRegisterEmptyState
              variant="holidays"
              eyebrow="No data"
              title="No calendar events"
              description="Estimated start, due date, and audit timestamps are not set on this project yet."
              hints={[
                "Set dates when editing the project",
                "Deliverable due dates appear on the deliverables board",
              ]}
              className="lux-pd-tab__empty"
            />
          )}
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsCalendar;
