import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { CALIBRATION_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceInsightPanel } from "views/performance/components/PerformanceLuxShared";
import CalibrationBoardPanel from "views/performance/components/CalibrationBoardPanel";

class CalibrationPage extends Component {
  state = { loading: true, board: null, insights: [], kpiCards: [], dataSource: null };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true });
    try {
      const [overview, boardResult] = await Promise.all([
        performanceManagementService.getOverview({}),
        performanceManagementService.getCalibrationBoard({}),
      ]);
      this.setState({
        loading: false,
        dataSource: boardResult.source,
        board: boardResult.payload || null,
        insights: (overview.payload && overview.payload.insights) || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, board: null });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Calibration" />;
    }

    const { loading, board, insights, kpiCards, dataSource } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={CALIBRATION_PAGE_META}
        pageId="calibration"
        shellTitle="Calibration"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
      >
        <PerformanceInsightPanel insights={insights} />
        <CalibrationBoardPanel board={board} loading={loading} />
      </PerformanceLuxPage>
    );
  }
}

export default CalibrationPage;
