import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { accessUtils } from "_helpers";
import { SIDEBAR_GROUPS, isSidebarGroupVisible } from "config/sidebar-menu.config";
import { mergeMenuAccessControl } from "config/navigation-access.utils";
import { resolveActivePersona } from "config/persona-navigation.utils";
import envconfig from "env.config";

export const NAVIGATION_MENU_CHANGED = "famstack-navigation-menu-changed";

/**
 * F01-T6: Optional backend menu endpoint with client fallback.
 */
export const navigationService = {
  getMenu,
  loadMergedMenuAccess,
};

async function getMenuFromApi() {
  const response = await axiosUtils.get(urlConfig.NAVIGATION_MENU);
  return response && response.payload ? response.payload : response;
}

function getClientMenu(menuAccessControl, activePersona) {
  const persona = activePersona || resolveActivePersona(menuAccessControl);
  return {
    source: "client",
    persona,
    menuAccessControl,
    groups: SIDEBAR_GROUPS.filter((group) =>
      isSidebarGroupVisible(group, menuAccessControl, persona)
    ).map((group) => ({
      id: group.id,
      label: group.menuName,
      icon: group.icon,
    })),
  };
}

async function getMenu(menuAccessControl, activePersona) {
  if (envconfig.USE_NAVIGATION_API === true) {
    try {
      const apiMenu = await getMenuFromApi();
      if (apiMenu && (apiMenu.groups || apiMenu.menuAccessControl)) {
        const clientMenu = accessUtils.getMenuAccessControl();
        const mergedAccess = mergeMenuAccessControl(clientMenu, apiMenu.menuAccessControl);
        return {
          ...apiMenu,
          menuAccessControl: mergedAccess,
          source: "api",
        };
      }
    } catch (e) {
      console.warn("[Navigation] API unavailable, using client menu.", e);
    }
  }
  return getClientMenu(menuAccessControl, activePersona);
}

async function loadMergedMenuAccess(menuAccessControl, activePersona) {
  const menu = await getMenu(menuAccessControl, activePersona);
  if (typeof window !== "undefined") {
    window.dispatchEvent(
      new CustomEvent(NAVIGATION_MENU_CHANGED, {
        detail: { menuAccessControl: menu.menuAccessControl || menuAccessControl },
      })
    );
  }
  return menu;
}

export default navigationService;
