import moment from "moment";
import { isEffectiveApprovalReminderEnabled } from "./approvalDelegation.config";

export function canUseApprovalReminder(permission) {
  if (!isEffectiveApprovalReminderEnabled()) {
    return false;
  }
  return !permission || permission.approvalReminderEnabled !== false;
}

export function formatReminderCooldownTooltip(eligibility) {
  if (!eligibility || eligibility.canRemind !== false) {
    return null;
  }
  if (eligibility.nextReminderAt) {
    const next = moment(eligibility.nextReminderAt);
    if (next.isValid()) {
      return `Reminder already sent. Try again after ${next.format("D MMM YYYY, h:mm a")}.`;
    }
  }
  return eligibility.message || "Reminder already sent recently. Try again later.";
}

export function formatReminderStatusMessage(eligibility, loading) {
  if (loading) {
    return "Checking reminder availability…";
  }
  if (!eligibility) {
    return null;
  }
  if (eligibility.canRemind === false) {
    return formatReminderCooldownTooltip(eligibility);
  }
  return "Your manager and any assigned delegates will receive an email.";
}

export function buildReminderRequest(requestType, referenceId, employeeId) {
  return {
    requestType: requestType,
    referenceId: referenceId,
    employeeId: employeeId,
  };
}
