import React, { Component } from "react";
import { npdService } from "_services/npd/npd.service";
import NpdLuxPage, {
  NpdActionButton,
  NpdLuxPanel,
} from "views/npd/components/NpdLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class NpdGatesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    ideas: [],
    selectedIdeaRef: "",
    gates: [],
    gateName: "Concept review",
    linkedProjectId: "",
    deciding: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("NPD stage gates");
    }
    this.loadIdeas();
  }

  loadIdeas = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await npdService.listIdeas();
    if (result.source === "api" && Array.isArray(result.payload)) {
      const ideas = result.payload;
      const selectedIdeaRef = ideas.length ? ideas[0].ideaRef : "";
      this.setState({ loading: false, ideas, selectedIdeaRef }, () => {
        if (selectedIdeaRef) this.loadGates(selectedIdeaRef);
      });
    } else {
      this.setState({
        loading: false,
        ideas: [],
        loadError: result.error || new Error("Unable to load ideas"),
      });
    }
  };

  loadGates = async (ideaRef) => {
    const result = await npdService.listGates(ideaRef);
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ gates: result.payload });
    } else {
      this.setState({ gates: [], loadError: result.error || new Error("Unable to load gates") });
    }
  };

  onSelectIdea = (e) => {
    const selectedIdeaRef = e.target.value;
    this.setState({ selectedIdeaRef }, () => this.loadGates(selectedIdeaRef));
  };

  configure = async (e) => {
    e.preventDefault();
    const { selectedIdeaRef, gateName, linkedProjectId } = this.state;
    if (!selectedIdeaRef || !gateName) return;
    const result = await npdService.configureGates(selectedIdeaRef, {
      linkedProjectId: linkedProjectId || undefined,
      gates: [{ gateName, gateOrder: 1 }],
    });
    if (result.source === "api") this.loadGates(selectedIdeaRef);
    else this.setState({ loadError: result.error || new Error("Configure failed") });
  };

  decide = async (gateRef, approve) => {
    this.setState({ deciding: true });
    const { selectedIdeaRef, linkedProjectId } = this.state;
    const body = {
      decisionComment: approve ? "Approved" : "Rejected",
      linkedProjectId: linkedProjectId || undefined,
    };
    const result = approve
      ? await npdService.approveGate(gateRef, body)
      : await npdService.rejectGate(gateRef, body);
    this.setState({ deciding: false });
    if (result.source === "api") this.loadGates(selectedIdeaRef);
    else this.setState({ loadError: result.error || new Error("Decision failed") });
  };

  render() {
    const {
      loading,
      loadError,
      ideas,
      selectedIdeaRef,
      gates,
      gateName,
      linkedProjectId,
      deciding,
    } = this.state;
    return (
      <NpdLuxPage
        testId="npd-gates-page"
        dataSource={ideas.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "violet",
          icon: "fe fe-git-branch",
          eyebrow: "Projects · NPD",
          titleLead: "NPD stage",
          titleAccent: "gates",
          lede: "Configure and decide stage gates for product ideas.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load gates">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <NpdLuxPanel title="Select idea" icon="fe fe-lightbulb">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && ideas.length === 0 ? (
            <LuxRegisterEmptyState title="No ideas" description="Create an idea before configuring gates." showCreate={false} />
          ) : (
            <select className="form-control" value={selectedIdeaRef} onChange={this.onSelectIdea}>
              {ideas.map((i) => (
                <option key={i.ideaRef} value={i.ideaRef}>
                  {i.ideaRef} — {i.title} ({i.status})
                </option>
              ))}
            </select>
          )}
        </NpdLuxPanel>
        <NpdLuxPanel title="Configure gate" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.configure}>
            <div className="form-row">
              <div className="col-md-4">
                <input
                  className="form-control"
                  placeholder="Gate name"
                  value={gateName}
                  onChange={(e) => this.setState({ gateName: e.target.value })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Linked project id (optional)"
                  value={linkedProjectId}
                  onChange={(e) => this.setState({ linkedProjectId: e.target.value })}
                />
              </div>
              <div className="col-md-2">
                <NpdActionButton type="submit">Configure gate</NpdActionButton>
              </div>
            </div>
          </form>
        </NpdLuxPanel>
        <NpdLuxPanel title="Gates" meta={`${gates.length} gate${gates.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {gates.length === 0 ? (
            <LuxRegisterEmptyState title="No gates" description="Configure a gate for the selected idea." showCreate={false} />
          ) : (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Name</th>
                    <th>Order</th>
                    <th>Status</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {gates.map((g) => (
                    <tr key={g.gateRef}>
                      <td>{g.gateRef}</td>
                      <td>{g.gateName}</td>
                      <td>{g.gateOrder}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(g.status || "pending").toLowerCase()}`}>
                          {g.status || "Pending"}
                        </span>
                      </td>
                      <td>
                        {g.status === "PENDING" && (
                          <>
                            <NpdActionButton
                              type="button"
                              variant="secondary"
                              className="lux-onb-action--compact mr-1"
                              disabled={deciding}
                              onClick={() => this.decide(g.gateRef, true)}
                            >
                              Approve
                            </NpdActionButton>
                            <NpdActionButton
                              type="button"
                              variant="ghost"
                              className="lux-onb-action--compact"
                              disabled={deciding}
                              onClick={() => this.decide(g.gateRef, false)}
                            >
                              Reject
                            </NpdActionButton>
                          </>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </NpdLuxPanel>
      </NpdLuxPage>
    );
  }
}

export default NpdGatesPage;
