import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  DELIVERABLE_STATUS_OPTIONS,
  getDeliverableStatusMeta,
  getDeliverableStatusSelectValue,
  getDeliverableActivityPct,
  isDeliverableOverdue,
  formatDeliverableMemberCount,
} from "./deliverableList.utils";

class DeliverableListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  stopRowClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveTask(this.props.task.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  renderMenuItem = (item) => (
    <button
      key={item.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(item.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", item.tone && `is-${item.tone}`)}>
        <i className={item.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy">
        <strong>{item.label}</strong>
      </span>
    </button>
  );

  getMenuSections = () => {
    const { task, permission, projectId } = this.props;
    const primary = [];
    if (permission.viewEnabled) {
      primary.push({
        key: "view",
        icon: "fe fe-eye",
        label: "View deliverable",
        onClick: () => this.props.onViewTask(task.id, projectId),
      });
    }
    if (task.active && permission.editEnabled && task.status !== "COMPLETED" && task.status !== "CLOSED") {
      primary.push({
        key: "edit",
        icon: "fe fe-edit-2",
        label: "Edit deliverable",
        onClick: () => this.props.handleEditTask(task.id, projectId, task.userTeamId),
      });
    }
    if (permission.duplicateEnabled) {
      primary.push({
        key: "duplicate",
        icon: "fe fe-copy",
        label: "Duplicate",
        onClick: () => this.props.handleDuplicateTask(task.id, projectId, task.userTeamId),
      });
    }

    const secondary = [];
    if (permission.deleteEnabled) {
      secondary.push({
        key: "delete",
        icon: task.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: task.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeleteTask(task.id, !task.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  canEdit = () => {
    const { task, permission } = this.props;
    return (
      task.active &&
      permission.editEnabled &&
      task.status !== "COMPLETED" &&
      task.status !== "CLOSED"
    );
  };

  renderMemberStack = (task) => {
    const count = formatDeliverableMemberCount(task);
    if (!count) {
      return <span className="lux-deliverable-row__members-empty">—</span>;
    }
    const ids = task.taskActivityEmployeeIds.slice(0, 4);
    return (
      <div className="lux-deliverable-row__members" title={`${count} team member${count === 1 ? "" : "s"}`}>
        <ul className="lux-deliverable-row__avatars">
          {ids.map((employeeId) => (
            <li key={employeeId}>
              <img src="/assets/images/male.jpg" alt="" onError={(e) => { e.target.src = "/assets/images/male.jpg"; }} />
            </li>
          ))}
        </ul>
        {count > 4 && <span className="lux-deliverable-row__members-more">+{count - 4}</span>}
      </div>
    );
  };

  render() {
    const { task, permission } = this.props;
    const { menuOpen } = this.state;
    const statusMeta = getDeliverableStatusMeta(task.status);
    const activityPct = getDeliverableActivityPct(task);
    const overdue = isDeliverableOverdue(task);
    const deliverableLabel = task.name || task.itemIdUserTeamPrefix;
    const { primary, secondary } = this.getMenuSections();
    const totalActivities = Number(task.taskActivityTotalCount) || 0;
    const doneActivities = Number(task.completedTaskActivityCount) || 0;

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-bid-list__item lux-deliverable-row", {
          "is-deleted": task.deleted,
          "is-inactive": !task.active,
          "is-overdue": overdue,
          "is-menu-open": menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <span className="lux-bid-list__accent" aria-hidden="true" />

        <div className="lux-bid-list__col lux-bid-list__col--index">
          <span className="lux-deliverable-row__index">{this.props.rowIndex}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--id">
          <span className="lux-bid-list__ref">{task.itemIdUserTeamPrefix}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--name lux-deliverable-row__name-col">
          <NavLink
            to={`/project/deliverable/${task.itemIdUserTeamPrefix}`}
            className="lux-deliverable-row__name"
            title={deliverableLabel}
          >
            <span className="lux-deliverable-row__name-text">{deliverableLabel}</span>
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          {task.description && (
            <p className="lux-deliverable-row__description" title={task.description}>
              {task.description}
            </p>
          )}
          <div className="lux-deliverable-row__tags">
            {task.deleted && (
              <span className="lux-bid-list__deleted-badge">
                <i className="fe fe-trash-2" aria-hidden="true" />
                Deleted
              </span>
            )}
            {!task.active && (
              <span className="lux-deliverable-row__badge is-inactive">
                <i className="fe fe-pause-circle" aria-hidden="true" />
                Inactive
              </span>
            )}
            {overdue && (
              <span className="lux-deliverable-row__badge is-overdue">
                <i className="fe fe-alert-circle" aria-hidden="true" />
                Past due
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--category">
          <span className="lux-deliverable-row__category">{task.category || "—"}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--members">
          {this.renderMemberStack(task)}
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--dates lux-deliverable-row__dates-col">
          <div className="lux-deliverable-row__dates">
            <span className="lux-deliverable-row__date is-start">
              <em>Start</em>
              {dateUtils.convertDateFormat(task.estStartTime) || "—"}
            </span>
            <span className="lux-deliverable-row__date is-end">
              <em>Due</em>
              {dateUtils.convertDateFormat(task.estCompletionTime) || "—"}
            </span>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--progress">
          <div className="lux-deliverable-row__progress">
            <div className="lux-deliverable-row__progress-head">
              <strong>{activityPct}%</strong>
              <span>
                {doneActivities}/{totalActivities} work items
              </span>
            </div>
            <div className="lux-deliverable-row__progress-track" aria-hidden="true">
              <span className="lux-deliverable-row__progress-fill" style={{ width: `${activityPct}%` }} />
            </div>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--status is-center">
          <div className={classNames("lux-bid-list__status-select lux-deliverable-row__status", `is-${statusMeta.tone}`)}>
            <SelectInput
              options={DELIVERABLE_STATUS_OPTIONS}
              value={getDeliverableStatusSelectValue(task.status)}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={!permission.allowStatusChange}
              itemId={task.id}
              onChange={this.props.handleUpdateStatus}
              className="lux-bid-list__status-input"
            />
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--actions">
          <div className="lux-deliverable-row__actions">
            {permission.archiveEnabled && (
              <label className="lux-deliverable-row__toggle" title={task.active ? "Deactivate" : "Activate"}>
                <input
                  type="checkbox"
                  checked={!!task.active}
                  onChange={() => this.props.handleActivateTask(task.id, !task.active)}
                />
                <span className="lux-deliverable-row__toggle-ui" />
              </label>
            )}
            {permission.viewEnabled && (
              <button
                type="button"
                className="lux-deliverable-row__action"
                title="View deliverable"
                aria-label={`View ${deliverableLabel}`}
                onClick={(event) => {
                  this.stopRowClick(event);
                  this.props.onViewTask(task.id, this.props.projectId);
                }}
              >
                <i className="fe fe-eye" aria-hidden="true" />
              </button>
            )}
            {this.canEdit() && (
              <button
                type="button"
                className="lux-deliverable-row__action"
                title="Edit deliverable"
                aria-label={`Edit ${deliverableLabel}`}
                onClick={(event) => {
                  this.stopRowClick(event);
                  this.props.handleEditTask(task.id, this.props.projectId, task.userTeamId);
                }}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            <button
              ref={this.menuTriggerRef}
              type="button"
              className="lux-deliverable-row__action lux-deliverable-row__action--menu"
              onClick={this.toggleMenu}
              aria-expanded={menuOpen}
              aria-haspopup="menu"
              aria-label={`More actions for ${deliverableLabel}`}
            >
              <i className="fe fe-more-horizontal" aria-hidden="true" />
            </button>
            <LuxListRowMenuPortal open={menuOpen} anchorRef={this.menuTriggerRef} className="lux-bid-list__menu-panel">
              <header className="lux-emp-card__menu-head">
                <span className="lux-emp-card__menu-head-icon" aria-hidden="true">
                  <i className="fe fe-layers" />
                </span>
                <div>
                  <span className="lux-emp-card__menu-eyebrow">Deliverable</span>
                  <strong title={deliverableLabel}>{deliverableLabel}</strong>
                </div>
                <button
                  type="button"
                  className="lux-emp-card__menu-close"
                  onClick={this.runMenuAction(null)}
                  aria-label="Close menu"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </header>
              <div className="lux-emp-card__menu-body">
                {primary.map((entry) => this.renderMenuItem(entry))}
                {secondary.length > 0 && primary.length > 0 && (
                  <div className="lux-emp-card__menu-divider" aria-hidden="true" />
                )}
                {secondary.map((entry) => this.renderMenuItem(entry))}
              </div>
            </LuxListRowMenuPortal>
          </div>
        </div>
      </article>
    );
  }
}

export default DeliverableListRow;
