import React from "react";
import { PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";

export default function CalibrationBoardPanel({ board, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  const session = (board && board.session) || null;
  const distribution = (board && board.distribution) || [];
  const rows = (board && board.rows) || [];

  return (
    <div className="lux-perf-page-grid">
      <PerformanceLuxPanel
        title="Rating distribution"
        meta={session ? session.name : "Calibration curve vs target"}
        icon="fe fe-bar-chart-2"
        accent="violet"
        featured
      >
        <div className="lux-perf-density-bars">
          {distribution.map((bucket) => {
            const max = Math.max(bucket.count, bucket.target, 1);
            const countPct = Math.round((bucket.count / max) * 100);
            const targetPct = Math.round((bucket.target / max) * 100);
            return (
              <div key={bucket.rating} className="lux-perf-density-row">
                <span>Rating {bucket.rating}</span>
                <div className="lux-perf-density-row__tracks">
                  <span className="lux-perf-density-row__track">
                    <span className="lux-perf-density-row__fill is-actual" style={{ width: `${countPct}%` }} />
                  </span>
                  <span className="lux-perf-density-row__track is-target">
                    <span className="lux-perf-density-row__fill is-target" style={{ width: `${targetPct}%` }} />
                  </span>
                </div>
                <strong>{bucket.count}/{bucket.target}</strong>
              </div>
            );
          })}
        </div>
      </PerformanceLuxPanel>

      <PerformanceLuxPanel title="Calibration roster" meta="Proposed ratings before finalization" icon="fe fe-sliders" accent="indigo">
        <div className="lux-perf-register">
          {rows.map((row, index) => (
            <article key={row.id} className="lux-perf-register__row">
              <span className="lux-perf-register__index">{index + 1}</span>
              <div className="lux-perf-register__main">
                <h3>{row.employeeName}</h3>
                <p>Manager: {row.managerName}</p>
                <div className="lux-perf-register__meta">
                  <span>Proposed: {row.proposedRating != null ? row.proposedRating : "—"}</span>
                  <span>Status: {row.status}</span>
                </div>
              </div>
            </article>
          ))}
        </div>
      </PerformanceLuxPanel>
    </div>
  );
}
