import { validationUtils } from "_helpers";

export function isEmptyFieldValue(value) {
  if (value === undefined || value === null) return true;
  if (typeof value === "string" && value.trim() === "") return true;
  if (Array.isArray(value) && value.length === 0) return true;
  return false;
}

/** Mandatory enabled fields on this step (intersection of step fields + fieldConfig). */
export function getWizardStepMandatoryFieldNames(fieldConfig, stepFieldNames) {
  if (!fieldConfig || !stepFieldNames || !stepFieldNames.length) {
    return [];
  }
  const allowed = new Set(stepFieldNames);
  return fieldConfig
    .filter((field) => field.enabled && field.mandatory && allowed.has(field.name))
    .map((field) => field.name);
}

/**
 * Validate only a subset of fields (wizard steps). Reusable across create panels.
 */
export function isValidRequestForFieldNames(fieldConfig, request, formErrors, fieldNames) {
  if (!fieldConfig || !fieldNames || !fieldNames.length) {
    return true;
  }
  const allowed = new Set(fieldNames);
  const stepErrors = {};
  Object.keys(formErrors || {}).forEach((key) => {
    if (allowed.has(key) && formErrors[key]) {
      stepErrors[key] = true;
    }
  });
  const stepConfig = fieldConfig.filter((field) => allowed.has(field.name));

  let isValid = validationUtils.isValidRequest(stepConfig, request || {}, stepErrors);
  if (isValid) {
    stepConfig.forEach((field) => {
      if (field.enabled && field.mandatory && isEmptyFieldValue(request && request[field.name])) {
        isValid = false;
      }
    });
  }
  return isValid;
}

export const CREATE_ENTRY_MODES = Object.freeze({
  FULL: "full",
  WIZARD: "wizard",
});

export const WIZARD_STEP_STATUS = Object.freeze({
  PENDING: "pending",
  ACTIVE: "active",
  COMPLETE: "complete",
  ATTENTION: "attention",
  OPTIONAL: "optional",
});

const WIZARD_STATUS_LABELS = {
  [WIZARD_STEP_STATUS.PENDING]: "Pending",
  [WIZARD_STEP_STATUS.ACTIVE]: "In progress",
  [WIZARD_STEP_STATUS.COMPLETE]: "Complete",
  [WIZARD_STEP_STATUS.ATTENTION]: "Needs attention",
  [WIZARD_STEP_STATUS.OPTIONAL]: "Not required",
};

export function getWizardStatusLabel(status) {
  return WIZARD_STATUS_LABELS[status] || "Pending";
}

/**
 * Derive per-step status. "Complete" only when mandatory fields on that step are filled.
 * Steps with no mandatory fields use "Optional" / pending — never auto-complete.
 */
export function resolveWizardStepStatuses({
  steps,
  activeIndex,
  fieldConfig,
  request,
  formErrors,
  visitedSteps,
  hasFormError,
}) {
  if (!steps || !steps.length) return [];

  return steps.map((step, index) => {
    const mandatoryNames = getWizardStepMandatoryFieldNames(fieldConfig, step.fieldNames);
    const hasMandatory = mandatoryNames.length > 0;
    const visited =
      visitedSteps &&
      (visitedSteps.has ? visitedSteps.has(index) : visitedSteps[index]);

    const isMandatoryComplete =
      hasMandatory &&
      isValidRequestForFieldNames(fieldConfig, request, formErrors, mandatoryNames);

    if (hasMandatory && isMandatoryComplete) {
      return { ...step, index, status: WIZARD_STEP_STATUS.COMPLETE, hasMandatory: true };
    }

    if (!hasMandatory) {
      if (index === activeIndex) {
        return { ...step, index, status: WIZARD_STEP_STATUS.ACTIVE, hasMandatory: false };
      }
      if (visited) {
        return { ...step, index, status: WIZARD_STEP_STATUS.OPTIONAL, hasMandatory: false };
      }
      return { ...step, index, status: WIZARD_STEP_STATUS.PENDING, hasMandatory: false };
    }

    if (index === activeIndex) {
      if (hasFormError) {
        return { ...step, index, status: WIZARD_STEP_STATUS.ATTENTION, hasMandatory: true };
      }
      return { ...step, index, status: WIZARD_STEP_STATUS.ACTIVE, hasMandatory: true };
    }
    if (visited) {
      return { ...step, index, status: WIZARD_STEP_STATUS.ATTENTION, hasMandatory: true };
    }
    return { ...step, index, status: WIZARD_STEP_STATUS.PENDING, hasMandatory: true };
  });
}

/** Progress counts only steps that have mandatory fields and are complete. */
export function summarizeWizardProgress(stepStatuses) {
  if (!stepStatuses || !stepStatuses.length) {
    return { complete: 0, requiredTotal: 0, optionalTotal: 0, percent: 0 };
  }

  const requiredSteps = stepStatuses.filter((s) => s.hasMandatory);
  const optionalTotal = stepStatuses.length - requiredSteps.length;
  const requiredTotal = requiredSteps.length;
  const complete = requiredSteps.filter(
    (s) => s.status === WIZARD_STEP_STATUS.COMPLETE
  ).length;

  return {
    complete,
    requiredTotal,
    optionalTotal,
    percent: requiredTotal > 0 ? Math.round((complete / requiredTotal) * 100) : 0,
  };
}
