const AXIOS_STATUS_MESSAGE = /^Request failed with status code \d+$/i;
const OBJECT_STRING = "[object Object]";
const NOT_FOUND_MESSAGE = "Item not available";
const NETWORK_ERROR_MESSAGE =
  "Unable to reach the server. Check your connection and try again.";
const TIMEOUT_ERROR_MESSAGE = "The request timed out. Please try again.";

const STATUS_MESSAGES = {
  401: "Your session has expired. Please sign in again.",
  403: "You don't have permission to access this. Contact your administrator if you need access.",
  404: NOT_FOUND_MESSAGE,
  429: "Too many requests. Please wait a moment and try again.",
  500: "Something went wrong on our end. Please try again later.",
  502: "The server is temporarily unavailable. Please try again.",
  503: "The service is temporarily unavailable. Please try again.",
  504: "The request timed out. Please try again.",
};

function isAxiosStatusMessage(message) {
  return typeof message === "string" && AXIOS_STATUS_MESSAGE.test(message.trim());
}

function isBlankOrObjectString(message) {
  if (message == null) {
    return true;
  }
  if (typeof message !== "string") {
    return false;
  }
  const trimmed = message.trim();
  return !trimmed || trimmed === OBJECT_STRING;
}

function stripErrorPrefix(message) {
  if (typeof message !== "string") {
    return "";
  }
  return message.replace(/^(Error|AxiosError):\s*/i, "").trim();
}

function isRawNetworkFailureMessage(message) {
  if (typeof message !== "string") {
    return false;
  }
  const trimmed = stripErrorPrefix(message);
  if (!trimmed) {
    return false;
  }
  return (
    /^network error$/i.test(trimmed) ||
    /^failed to fetch$/i.test(trimmed) ||
    /^load failed$/i.test(trimmed) ||
    /^network.?request.?failed$/i.test(trimmed)
  );
}

function isRawTimeoutMessage(message) {
  if (typeof message !== "string") {
    return false;
  }
  const trimmed = stripErrorPrefix(message);
  if (!trimmed) {
    return false;
  }
  const lower = trimmed.toLowerCase();
  return (
    /timeout of \d+ms exceeded/i.test(lower) ||
    /^timeout$/i.test(lower) ||
    lower.includes("etimedout") ||
    lower === "econnaborted" ||
    /^request timed out/i.test(lower) ||
    /^the request timed out/i.test(lower)
  );
}

function isTimeoutConnectivityError(error) {
  if (!error) {
    return false;
  }
  if (typeof error === "string") {
    return isRawTimeoutMessage(error);
  }
  if (error.code === "ECONNABORTED") {
    return true;
  }
  return isRawTimeoutMessage(error.message);
}

/**
 * True when the client could not reach the API (offline, DNS, CORS, BE down).
 */
export function isApiNetworkError(error) {
  if (!error) {
    return false;
  }
  if (typeof error === "string") {
    return isRawNetworkFailureMessage(error) || isRawTimeoutMessage(error);
  }
  if (Array.isArray(error)) {
    return false;
  }
  if (error.response) {
    return false;
  }
  if (error.code === "ERR_NETWORK" || error.code === "ECONNABORTED") {
    return true;
  }
  return (
    isRawNetworkFailureMessage(error.message) || isRawTimeoutMessage(error.message)
  );
}

function connectivityMessageFor(error) {
  if (isTimeoutConnectivityError(error)) {
    return TIMEOUT_ERROR_MESSAGE;
  }
  return NETWORK_ERROR_MESSAGE;
}

function normalizeNotFoundMessage(message) {
  if (typeof message !== "string") {
    return message;
  }
  const trimmed = message.trim();
  if (!trimmed) {
    return message;
  }
  if (/^not found$/i.test(trimmed) || /^item not available$/i.test(trimmed)) {
    return NOT_FOUND_MESSAGE;
  }
  return message;
}

function extractMessageFromErrorEntry(entry) {
  if (entry == null) {
    return null;
  }
  if (typeof entry === "string") {
    return entry;
  }
  if (typeof entry === "object" && typeof entry.message === "string") {
    return entry.message;
  }
  return null;
}

function extractCodeFromErrorEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  if (typeof entry.code === "string") {
    return entry.code;
  }
  return null;
}

function extractFromErrorList(errorList) {
  if (!Array.isArray(errorList) || errorList.length === 0) {
    return { message: null, code: null };
  }
  const first = errorList[0];
  return {
    message: extractMessageFromErrorEntry(first),
    code: extractCodeFromErrorEntry(first),
  };
}

function extractPayloadMessage(data) {
  if (!data || typeof data !== "object") {
    return null;
  }

  const payloadError = data.payload && data.payload.error;
  if (payloadError) {
    if (Array.isArray(payloadError)) {
      return extractFromErrorList(payloadError).message;
    }
    if (typeof payloadError === "string") {
      return payloadError;
    }
  }

  if (data.error) {
    if (Array.isArray(data.error)) {
      return extractFromErrorList(data.error).message;
    }
    if (typeof data.error === "string") {
      return data.error;
    }
  }

  if (typeof data.message === "string" && data.message.trim()) {
    return data.message;
  }

  return null;
}

function extractPayloadCode(data) {
  if (!data || typeof data !== "object") {
    return null;
  }
  if (data.payload && data.payload.error) {
    const fromPayload = extractFromErrorList(
      Array.isArray(data.payload.error) ? data.payload.error : [data.payload.error]
    ).code;
    if (fromPayload) {
      return fromPayload;
    }
  }
  if (data.error) {
    return extractFromErrorList(Array.isArray(data.error) ? data.error : [data.error])
      .code;
  }
  return null;
}

export function getApiErrorStatus(error) {
  if (!error) {
    return null;
  }
  if (error.response && error.response.status) {
    return error.response.status;
  }
  if (typeof error.status === "number") {
    return error.status;
  }
  return null;
}

export function getApiErrorCode(error) {
  if (!error) {
    return null;
  }

  if (Array.isArray(error)) {
    return extractFromErrorList(error).code;
  }

  if (error.response && error.response.data) {
    const fromResponse = extractPayloadCode(error.response.data);
    if (fromResponse) {
      return fromResponse;
    }
  }

  if (error.error) {
    const fromErrorField = extractFromErrorList(
      Array.isArray(error.error) ? error.error : [error.error]
    ).code;
    if (fromErrorField) {
      return fromErrorField;
    }
  }

  if (typeof error.code === "string" && error.code === "NOT_FOUND") {
    return error.code;
  }

  return null;
}

export function isApiForbiddenError(error) {
  return getApiErrorStatus(error) === 403;
}

export function isTeamFeatureDisabledError(error) {
  const message = getApiErrorMessage(error, "");
  return /disabled for this team/i.test(message);
}

/**
 * Props for LuxInlineAlert on module pages (tone/title aligned to error type).
 */
export function getLuxInlineAlertProps(
  error,
  fallback = "Something went wrong. Please try again."
) {
  const message = getApiErrorMessage(error, fallback);
  if (isApiNetworkError(error) || isRawNetworkFailureMessage(message) || isRawTimeoutMessage(message)) {
    return {
      message,
      tone: "warning",
      title: "Connection problem",
    };
  }
  if (isTeamFeatureDisabledError(error)) {
    const workGraphGuidance = /work graph/i.test(message)
      ? " Enable workGraphEnabled under Application Config → Tracopus Workspace Modules for this team, then refresh."
      : "";
    return {
      message: `${String(message).replace(/\.\s*$/, "")}.${workGraphGuidance}`.trim(),
      tone: "info",
      title: "Not enabled for this team",
    };
  }
  if (isApiNotFoundError(error)) {
    return {
      message,
      tone: "info",
      title: API_NOT_FOUND_MESSAGE,
    };
  }
  if (isApiForbiddenError(error)) {
    return {
      message,
      tone: "warning",
      title: "Access restricted",
    };
  }
  return {
    message,
    tone: "danger",
    title: "Unable to load data",
  };
}

export function isApiNotFoundError(error) {
  if (!error) {
    return false;
  }

  const code = getApiErrorCode(error);
  if (code === "NOT_FOUND") {
    return true;
  }

  const status = getApiErrorStatus(error);
  if (status === 404) {
    return true;
  }

  const message = getApiErrorMessage(error, "");
  if (!message) {
    return false;
  }
  const normalized = message.replace(/^Error:\s*/i, "").trim();
  return (
    /^not found$/i.test(normalized) ||
    /^item not available$/i.test(normalized)
  );
}

export function getApiErrorMessage(
  error,
  fallback = "Something went wrong. Please try again."
) {
  if (!error) {
    return fallback;
  }

  if (typeof error === "string") {
    if (isBlankOrObjectString(error) || isAxiosStatusMessage(error)) {
      return fallback;
    }
    if (isRawNetworkFailureMessage(error) || isRawTimeoutMessage(error)) {
      return connectivityMessageFor(error);
    }
    return normalizeNotFoundMessage(error);
  }

  if (Array.isArray(error)) {
    const fromList = extractFromErrorList(error);
    if (fromList.code === "NOT_FOUND") {
      return NOT_FOUND_MESSAGE;
    }
    if (fromList.message && !isBlankOrObjectString(fromList.message) && !isAxiosStatusMessage(fromList.message)) {
      if (isRawNetworkFailureMessage(fromList.message) || isRawTimeoutMessage(fromList.message)) {
        return connectivityMessageFor(fromList.message);
      }
      return normalizeNotFoundMessage(fromList.message);
    }
    return fallback;
  }

  if (isApiNetworkError(error)) {
    return connectivityMessageFor(error);
  }

  const payloadMessage =
    error.response && extractPayloadMessage(error.response.data);
  if (
    payloadMessage &&
    !isBlankOrObjectString(payloadMessage) &&
    !isAxiosStatusMessage(payloadMessage)
  ) {
    const code = extractPayloadCode(error.response.data);
    if (code === "NOT_FOUND" || /^not found$/i.test(payloadMessage.trim())) {
      return NOT_FOUND_MESSAGE;
    }
    return normalizeNotFoundMessage(payloadMessage);
  }

  if (Array.isArray(error.error)) {
    const fromErrorField = extractFromErrorList(error.error);
    if (fromErrorField.code === "NOT_FOUND") {
      return NOT_FOUND_MESSAGE;
    }
    if (
      fromErrorField.message &&
      !isBlankOrObjectString(fromErrorField.message) &&
      !isAxiosStatusMessage(fromErrorField.message)
    ) {
      return normalizeNotFoundMessage(fromErrorField.message);
    }
  }

  if (
    error.message &&
    typeof error.message === "string" &&
    !isBlankOrObjectString(error.message) &&
    !isAxiosStatusMessage(error.message)
  ) {
    if (isRawNetworkFailureMessage(error.message) || isRawTimeoutMessage(error.message)) {
      return connectivityMessageFor(error);
    }
    return normalizeNotFoundMessage(error.message);
  }

  const status = getApiErrorStatus(error);
  if (status && STATUS_MESSAGES[status]) {
    return STATUS_MESSAGES[status];
  }

  if (error.errorMessage && typeof error.errorMessage === "string") {
    if (isRawNetworkFailureMessage(error.errorMessage) || isRawTimeoutMessage(error.errorMessage)) {
      return connectivityMessageFor(error.errorMessage);
    }
    return normalizeNotFoundMessage(error.errorMessage);
  }

  if (error.error && typeof error.error === "string") {
    if (isRawNetworkFailureMessage(error.error) || isRawTimeoutMessage(error.error)) {
      return connectivityMessageFor(error.error);
    }
    return normalizeNotFoundMessage(error.error);
  }

  return fallback;
}

export function normalizeApiError(error, fallback) {
  if (Array.isArray(error)) {
    const message = getApiErrorMessage(error, fallback);
    const normalized = new Error(message);
    normalized.status = 412;
    normalized.code = getApiErrorCode(error);
    normalized.error = error;
    return normalized;
  }

  if (!error || typeof error === "string") {
    const message = getApiErrorMessage(error, fallback);
    return message === error ? error : new Error(message);
  }

  const message = getApiErrorMessage(error, fallback);
  if (error.message === message) {
    return error;
  }

  const normalized = new Error(message);
  normalized.response = error.response;
  normalized.config = error.config;
  normalized.isAxiosError = error.isAxiosError === true;
  normalized.code = getApiErrorCode(error) || error.code;
  normalized.status = getApiErrorStatus(error);
  normalized.error = error.error;
  return normalized;
}

export const API_NOT_FOUND_MESSAGE = NOT_FOUND_MESSAGE;
export const API_NETWORK_ERROR_MESSAGE = NETWORK_ERROR_MESSAGE;
export const API_TIMEOUT_ERROR_MESSAGE = TIMEOUT_ERROR_MESSAGE;
