import React, { Component } from "react";
import classNames from "classnames/bind";
import { industryTemplateService } from "_services/industryTemplates/industryTemplates.service";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminLuxPage,
  AdminPanelHead,
} from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function parsePayload(payloadJson) {
  if (!payloadJson) return null;
  if (typeof payloadJson === "object") return payloadJson;
  try {
    return JSON.parse(payloadJson);
  } catch (e) {
    return null;
  }
}

function asList(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === "object") return Object.keys(value);
  if (value == null || value === "") return [];
  return [value];
}

function countItems(value) {
  if (Array.isArray(value)) return value.length;
  if (value && typeof value === "object") return Object.keys(value).length;
  return value ? 1 : 0;
}

function ChipList({ items, emptyLabel = "None defined" }) {
  const list = asList(items);
  if (!list.length) {
    return <p className="lux-itpl-muted">{emptyLabel}</p>;
  }
  return (
    <ul className="lux-itpl-chip-list">
      {list.slice(0, 24).map((item) => {
        const label =
          typeof item === "string"
            ? item
            : item && (item.name || item.code || item.key || item.id)
              ? String(item.name || item.code || item.key || item.id)
              : JSON.stringify(item);
        return (
          <li key={label} className="lux-itpl-chip">
            {label}
          </li>
        );
      })}
      {list.length > 24 ? (
        <li className="lux-itpl-chip is-muted">+{list.length - 24} more</li>
      ) : null}
    </ul>
  );
}

class IndustryTemplateDetailPage extends Component {
  state = {
    loading: true,
    loadError: null,
    template: null,
    showRaw: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Industry template");
    }
    this.load();
  }

  load = async () => {
    const ref =
      (this.props.match && this.props.match.params && this.props.match.params.ref) ||
      (this.props.params && this.props.params.ref);
    this.setState({ loading: true, loadError: null });
    const result = await industryTemplateService.getTemplate(ref);
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, template: result.payload });
    } else {
      this.setState({
        loading: false,
        template: null,
        loadError: result.error || new Error("Unable to load template"),
      });
    }
  };

  renderPayloadSections = (payload) => {
    if (!payload) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No structured payload"
          description="This pack does not expose a parseable payloadJson yet."
        />
      );
    }

    const sections = [
      {
        id: "access",
        title: "Roles & personas",
        subtitle: "Access posture seeded by this pack",
        icon: "fe fe-shield",
        blocks: [
          { label: "Roles", items: payload.roles },
          { label: "Personas", items: payload.personas },
          { label: "Modules", items: payload.modules },
        ],
      },
      {
        id: "delivery",
        title: "Workflows & checklists",
        subtitle: "Operational defaults for delivery work",
        icon: "fe fe-git-branch",
        blocks: [
          { label: "Workflows", items: payload.workflows },
          { label: "Checklists", items: payload.checklists },
        ],
      },
      {
        id: "lifecycle",
        title: "Project lifecycle",
        subtitle: "Stage and gate expectations",
        icon: "fe fe-layers",
        blocks: [{ label: "Lifecycle", items: payload.projectLifecycle }],
      },
      {
        id: "insight",
        title: "Reports & dashboards",
        subtitle: "Analytics defaults for the vertical",
        icon: "fe fe-bar-chart-2",
        blocks: [{ label: "Reports", items: payload.reports }],
      },
      {
        id: "config",
        title: "App Config targets",
        subtitle: "Allowlisted keys written on commit",
        icon: "fe fe-settings",
        blocks: [{ label: "Keys", items: payload.appConfigKeys }],
      },
    ];

    return (
      <div className="lux-itpl-section-grid lux-itpl-section-grid--compact">
        {sections.map((section) => {
          const total = section.blocks.reduce((sum, block) => sum + countItems(block.items), 0);
          return (
            <section
              key={section.id}
              className="lux-hrms-dash__panel lux-itpl-section lux-itpl-section--compact"
            >
              <AdminPanelHead
                title={section.title}
                subtitle={section.subtitle}
                actions={
                  <span className="lux-itpl-pill is-indigo">
                    <i className={section.icon} aria-hidden="true" /> {total}
                  </span>
                }
              />
              <div className="lux-itpl-section__body">
                {section.blocks.map((block) => (
                  <div key={block.label} className="lux-itpl-section__block">
                    <h4>{block.label}</h4>
                    <ChipList items={block.items} />
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>
    );
  };

  render() {
    const { loading, loadError, template, showRaw } = this.state;
    const payload = template ? parsePayload(template.payloadJson) : null;
    const applyHref = template
      ? `/admin/industry-templates/apply?templateRef=${encodeURIComponent(template.templateRef || "")}`
      : "/admin/industry-templates/apply";

    const kpiCards = template
      ? [
          {
            id: "pack",
            label: "Pack",
            value: template.industryPack || "—",
            hint: "Vertical",
            tone: "indigo",
            icon: "fe fe-briefcase",
          },
          {
            id: "version",
            label: "Version",
            value: template.version || "—",
            hint: "Catalog revision",
            tone: "blue",
            icon: "fe fe-git-commit",
          },
          {
            id: "status",
            label: "Status",
            value: template.status || "—",
            hint: "Publish state",
            tone: "green",
            icon: "fe fe-check-circle",
          },
          {
            id: "keys",
            label: "Config keys",
            value: countItems(payload && payload.appConfigKeys),
            hint: "Apply targets",
            tone: "amber",
            icon: "fe fe-key",
          },
        ]
      : undefined;

    const insights = template
      ? [
          {
            id: "safe",
            tone: "amber",
            icon: "fe fe-shield",
            title: "Apply is gated",
            copy: "Preview and draft before App Config commit. Overwrites need approval.",
            path: applyHref,
          },
          {
            id: "scope",
            tone: "indigo",
            icon: "fe fe-layers",
            title: "Team-scoped apply",
            copy: "Wizard targets the active user team when committing defaults.",
          },
          {
            id: "catalog",
            tone: "blue",
            icon: "fe fe-package",
            title: "Back to catalog",
            copy: "Browse other industry packs.",
            path: "/admin/industry-templates",
          },
        ]
      : [];

    return (
      <AdminLuxPage
        testId="industry-template-detail-page"
        className="lux-register-page lux-itpl-page lux-itpl-page--detail"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-package",
          eyebrow: "Admin · Industry templates",
          titleLead: template ? template.name || "Template" : "Industry",
          titleAccent: template ? "pack" : "template",
          lede: template
            ? `${template.industryPack || "Pack"} · allowlisted App Config seeds · v${template.version || "—"}`
            : "Industry template pack detail.",
        }}
        dataSource="api"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <AdminActionButton to="/admin/industry-templates" variant="ghost" icon="fe fe-arrow-left">
              Catalog
            </AdminActionButton>
            <AdminActionButton to={applyHref} variant="primary" icon="fe fe-play">
              Apply wizard
            </AdminActionButton>
          </>
        }
      >
        {loading ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact"
            title="Loading template"
            description="Fetching industry template pack detail."
          />
        ) : null}
        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load template."
          onDismiss={() => this.setState({ loadError: null })}
        />
        {template && (
          <>
            <AdminInsightStrip insights={insights} className="lux-itpl-insights" />

            <section className="lux-hrms-dash__panel lux-itpl-hero-panel">
              <AdminPanelHead
                title="Pack overview"
                subtitle={template.description || "Structured defaults for this industry vertical."}
                actions={
                  <AdminActionButton
                    type="button"
                    variant="ghost"
                    icon={showRaw ? "fe fe-eye-off" : "fe fe-code"}
                    onClick={() => this.setState({ showRaw: !showRaw })}
                  >
                    {showRaw ? "Hide raw JSON" : "View raw JSON"}
                  </AdminActionButton>
                }
              />
              <div className="lux-itpl-hero-panel__meta">
                <span className="lux-itpl-pill is-indigo">{template.industryPack || "—"}</span>
                <span className="lux-itpl-pill is-slate">v{template.version || "—"}</span>
                <span
                  className={classNames(
                    "lux-itpl-pill",
                    `is-${String(template.status || "").toUpperCase() === "PUBLISHED" ? "green" : "amber"}`
                  )}
                >
                  {template.status || "UNKNOWN"}
                </span>
                <code className="lux-itpl-ref">{template.templateRef}</code>
              </div>
              {showRaw ? (
                <pre className="lux-itpl-raw">{JSON.stringify(payload || template, null, 2)}</pre>
              ) : null}
            </section>

            {this.renderPayloadSections(payload)}
          </>
        )}
      </AdminLuxPage>
    );
  }
}

export default IndustryTemplateDetailPage;
