import React, { useCallback, useEffect, useMemo, useState } from "react";
import classNames from "classnames/bind";
import {
  isTimesheetApproved,
  isTimesheetPayrollProcessed,
  isTimesheetReopened,
  isTimesheetWeekLocked,
  wasTimesheetPreviouslyApproved,
} from "_helpers/timesheetWorkflow.utils";
import TimesheetBatchReopenPicker, {
  summarizeBatchReopenOption,
} from "./TimesheetBatchReopenPicker";
import {
  readBatchReopenCollapsed,
  readBatchReopenSelection,
  writeBatchReopenCollapsed,
  writeBatchReopenSelection,
} from "./timesheetBatchReopen.storage";

function TimesheetLockBanner({
  timeSheetData,
  employeeId,
  canUnlock,
  unlockInProgress,
  onUnlock,
  canReopen,
  reopenInProgress,
  onReopen,
  reopenOptions,
}) {
  const locked = timeSheetData && isTimesheetWeekLocked(timeSheetData);
  const approved = timeSheetData && isTimesheetApproved(timeSheetData);
  const reopened =
    timeSheetData &&
    isTimesheetReopened(timeSheetData) &&
    wasTimesheetPreviouslyApproved(timeSheetData);
  const options = Array.isArray(reopenOptions) ? reopenOptions : [];
  const weekId = timeSheetData && timeSheetData.weekId;
  const resolvedEmployeeId =
    employeeId != null ? employeeId : timeSheetData && timeSheetData.employeeId;

  const [selectedSubmissionId, setSelectedSubmissionId] = useState("");
  const [collapsed, setCollapsed] = useState(() => readBatchReopenCollapsed());

  const batchDayCount = useMemo(
    () =>
      options.reduce(
        (total, option) => total + ((option.activityDates && option.activityDates.length) || 0),
        0
      ),
    [options]
  );

  const persistSelection = useCallback(
    (submissionId) => {
      if (submissionId == null || submissionId === "") {
        return;
      }
      writeBatchReopenSelection(resolvedEmployeeId, weekId, submissionId);
    },
    [resolvedEmployeeId, weekId]
  );

  const handleSelectSubmission = useCallback(
    (submissionId) => {
      setSelectedSubmissionId(String(submissionId));
      persistSelection(submissionId);
    },
    [persistSelection]
  );

  useEffect(() => {
    if (!options.length) {
      setSelectedSubmissionId("");
      return;
    }
    const storedSelection = readBatchReopenSelection(resolvedEmployeeId, weekId);
    const storedIsValid =
      storedSelection &&
      options.some((opt) => String(opt.submissionId) === String(storedSelection));
    const fallbackSelection = String(options[0].submissionId);
    const nextSelection = storedIsValid ? String(storedSelection) : fallbackSelection;

    setSelectedSubmissionId((current) => {
      if (current && options.some((opt) => String(opt.submissionId) === current)) {
        return current;
      }
      if (!storedIsValid) {
        writeBatchReopenSelection(resolvedEmployeeId, weekId, nextSelection);
      }
      return nextSelection;
    });
  }, [options, resolvedEmployeeId, weekId]);

  if (!locked && !approved && !reopened && !(options.length > 0 && canReopen)) {
    return null;
  }

  const payrollProcessed = isTimesheetPayrollProcessed(timeSheetData);
  const partialBatchOnly = !locked && !approved && !reopened && options.length > 0 && canReopen;
  const showReopenRemaining = reopened && canReopen && onReopen && options.length > 0;
  const showReopen =
    ((approved && canReopen && onReopen) ||
      (partialBatchOnly && onReopen) ||
      showReopenRemaining) &&
    !locked;
  const showUnlock = locked && canUnlock && onUnlock;
  const inProgress = showReopen ? reopenInProgress : unlockInProgress;
  const canAct = showReopen || showUnlock;
  const hasBatchPicker = options.length >= 1;
  const showRichBatchPicker = showReopen && hasBatchPicker;
  const reopenLabel =
    options.length >= 1 ? "Reopen selected batch" : "Reopen week";

  const selectedOption =
    options.find((option) => String(option.submissionId) === String(selectedSubmissionId)) ||
    options[0] ||
    null;
  const selectedBatchLabel = selectedOption ? summarizeBatchReopenOption(selectedOption) : null;

  const toggleCollapsed = () => {
    setCollapsed((current) => {
      const next = !current;
      writeBatchReopenCollapsed(next);
      return next;
    });
  };

  let ariaLabel = "Timesheet lock notice";
  let title = "Timesheet locked";
  let body = "This week is locked for compliance. Edits are blocked until a manager reopens it.";
  let icon = "fe-lock";

  if (payrollProcessed) {
    ariaLabel = "Timesheet payroll notice";
    title = "Payroll processed — week locked";
    body = "This week has been included in payroll. Edits are blocked until a manager reopens it.";
    icon = "fe-dollar-sign";
  } else if (reopened) {
    ariaLabel = "Timesheet reopened notice";
    title = "Previously approved timesheet reopened";
    body = showReopenRemaining
      ? "Some days were reopened for corrections. You can reopen other approved batches, or edit draft days and resubmit."
      : "This week was approved earlier and has been reopened for corrections. Update hours, save your draft, then resubmit for approval.";
    icon = "fe-rotate-ccw";
  } else if (approved) {
    ariaLabel = "Timesheet approved notice";
    title = "Timesheet approved";
    body = canAct
      ? options.length > 0
        ? "Editing and Submit are blocked. Reopen a submission batch to correct those days, then save and resubmit."
        : "Editing and Submit are blocked. Reopen this week to correct hours, then save and resubmit."
      : "Editing and Submit are blocked. Only the person who approved this timesheet can reopen it.";
    icon = "fe-check-circle";
  } else if (partialBatchOnly) {
    ariaLabel = "Partial timesheet batches notice";
    title = "Approved day batches";
    body = canAct
      ? "This week is still open for other days. Reopen an approved batch to correct those hours, then save and resubmit."
      : "Approved batches are locked until a manager reopens them.";
    icon = "fe-layers";
  }

  const handleAction = () => {
    if (!canAct) {
      return;
    }
    if (showReopen) {
      if (options.length >= 1) {
        const submissionId = selectedSubmissionId || options[0].submissionId;
        onReopen(submissionId);
        return;
      }
      onReopen();
      return;
    }
    onUnlock && onUnlock();
  };

  if (showRichBatchPicker && collapsed) {
    return (
      <section
        className={classNames(
          "lux-ts-lock-banner",
          "lux-ts-lock-banner--collapsed",
          "is-rich-batch",
          {
            "is-partial-batch": partialBatchOnly,
            "is-approved": approved && !locked,
            "is-reopened": reopened && !locked && !approved,
          }
        )}
        aria-label={ariaLabel}
        data-testid="timesheet-lock-banner"
      >
        <button
          type="button"
          className="lux-ts-lock-banner__collapsed-bar"
          onClick={toggleCollapsed}
          aria-expanded="false"
          aria-label={`${title}. Click to expand.`}
          data-testid="timesheet-batch-reopen-expand"
        >
          <span className="lux-ts-lock-banner__collapsed-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
          <span className="lux-ts-lock-banner__collapsed-copy">
            <strong>{title}</strong>
            <em>
              {options.length} batch{options.length === 1 ? "" : "es"} · {batchDayCount} day
              {batchDayCount === 1 ? "" : "s"} approved
              {selectedBatchLabel ? ` · Selected: ${selectedBatchLabel}` : ""}
            </em>
          </span>
          <span className="lux-ts-lock-banner__count">{options.length}</span>
          <span className="lux-ts-lock-banner__collapsed-expand">
            Expand
            <i className="fe fe-chevron-down" aria-hidden="true" />
          </span>
        </button>
      </section>
    );
  }

  return (
    <section
      className={classNames("lux-ts-lock-banner", {
        "is-payroll": payrollProcessed,
        "is-approved": approved && !locked,
        "is-reopened": reopened && !locked && !approved,
        "is-partial-batch": partialBatchOnly,
        "is-rich-batch": showRichBatchPicker,
      })}
      aria-label={ariaLabel}
      data-testid="timesheet-lock-banner"
    >
      {showRichBatchPicker ? (
        <header className="lux-ts-lock-banner__head">
          <div className="lux-ts-lock-banner__head-main">
            <div className="lux-ts-lock-banner__icon" aria-hidden="true">
              <i className={`fe ${icon}`} />
            </div>
            <div className="lux-ts-lock-banner__copy">
              {partialBatchOnly ? (
                <span className="lux-ts-lock-banner__eyebrow">Partial week · locked batches</span>
              ) : null}
              <h3>{title}</h3>
              <p>{body}</p>
              {partialBatchOnly ? (
                <div className="lux-ts-lock-banner__stats" aria-label="Approved batch summary">
                  <span className="lux-ts-lock-banner__stat">
                    <i className="fe fe-layers" aria-hidden="true" />
                    {options.length} batch{options.length === 1 ? "" : "es"}
                  </span>
                  <span className="lux-ts-lock-banner__stat">
                    <i className="fe fe-calendar" aria-hidden="true" />
                    {batchDayCount} day{batchDayCount === 1 ? "" : "s"} approved
                  </span>
                  {selectedBatchLabel ? (
                    <span className="lux-ts-lock-banner__stat is-selected">
                      <i className="fe fe-check-circle" aria-hidden="true" />
                      {selectedBatchLabel}
                    </span>
                  ) : null}
                </div>
              ) : null}
            </div>
          </div>
          <div className="lux-ts-lock-banner__head-actions">
            <span className="lux-ts-lock-banner__count">{options.length}</span>
            <button
              type="button"
              className="lux-ts-lock-banner__toggle"
              onClick={toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse batch reopen"
              data-testid="timesheet-batch-reopen-collapse"
            >
              Collapse
            </button>
          </div>
        </header>
      ) : (
        <div className="lux-ts-lock-banner__hero">
          <div className="lux-ts-lock-banner__icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </div>
          <div className="lux-ts-lock-banner__copy">
            <strong>{title}</strong>
            <p>{body}</p>
          </div>
          <div className="lux-ts-lock-banner__hero-actions">
            {canAct ? (
              <button
                type="button"
                className={classNames("lux-ts-lock-banner__btn", { "is-loading": inProgress })}
                disabled={inProgress}
                onClick={handleAction}
                data-testid="timesheet-reopen-week"
              >
                {showReopen ? reopenLabel : "Unlock week"}
              </button>
            ) : null}
          </div>
        </div>
      )}
      {showRichBatchPicker ? (
        <TimesheetBatchReopenPicker
          options={options}
          selectedSubmissionId={selectedSubmissionId}
          onSelect={handleSelectSubmission}
          disabled={inProgress}
          title={partialBatchOnly ? "Pick a batch to reopen" : "Choose batch to reopen"}
          showReopenAction={canAct}
          onReopen={handleAction}
          reopenLabel={reopenLabel}
        />
      ) : null}
    </section>
  );
}

export default TimesheetLockBanner;
