import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  AnalyticsEvents,
  trackDelegationAction,
} from "config/analytics-events.config";

export const approvalDelegationService = {
  listMine,
  listActing,
  create,
  update,
  revoke,
};

async function listMine(delegatorId) {
  return axiosUtils.get(`${urlConfig.APPROVAL_DELEGATIONS_API_PATH}/mine?delegatorId=${delegatorId}`);
}

async function listActing(delegateId) {
  return axiosUtils.get(`${urlConfig.APPROVAL_DELEGATIONS_API_PATH}/acting?delegateId=${delegateId}`);
}

async function create(delegatorId, payload) {
  const result = await axiosUtils.post(
    `${urlConfig.APPROVAL_DELEGATIONS_API_PATH}?delegatorId=${delegatorId}`,
    payload
  );
  trackDelegationAction(AnalyticsEvents.DELEGATION_CREATE, result && result.id);
  return result;
}

async function update(delegatorId, delegationId, payload) {
  const result = await axiosUtils.put(
    `${urlConfig.APPROVAL_DELEGATIONS_API_PATH}/${delegationId}?delegatorId=${delegatorId}`,
    payload
  );
  trackDelegationAction(AnalyticsEvents.DELEGATION_UPDATE, delegationId);
  return result;
}

async function revoke(delegatorId, delegationId) {
  const result = await axiosUtils.patch(
    `${urlConfig.APPROVAL_DELEGATIONS_API_PATH}/${delegationId}/revoke?delegatorId=${delegatorId}`
  );
  trackDelegationAction(AnalyticsEvents.DELEGATION_REVOKE, delegationId);
  return result;
}
