import React, { Component } from "react";
import { REVENUE_RECOGNITION_SCHEDULES_META } from "config/finance-intelligence-nav.config";
import { formatFinanceUsd } from "config/finance-intelligence.utils";
import { revenueRecognitionService } from "_services/revenueRecognition.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceField,
  FinanceFormGrid,
  FinanceInsightPanel,
  FinanceLuxPanel,
  FinanceQuickNav,
  FinanceRegisterPrimary,
  FinanceRegisterWrap,
  FinanceRevRecSectionTabs,
  FinanceToolbar,
  REV_REC_QUICK_LINKS,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class RevenueRecognitionSchedulesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    rows: [],
    query: "",
    createForm: {
      policyRef: "",
      projectId: "",
      purchaseOrderId: "",
      invoiceId: "",
      billingPlanRef: "",
      taskActivityId: "",
      totalAmount: "",
      startPeriodKey: "2026-07",
      currency: "USD",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Rev-rec schedules");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await revenueRecognitionService.listSchedules();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load schedules"),
      });
    }
  };

  handleFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleGenerate = async (event) => {
    event.preventDefault();
    const { createForm } = this.state;
    if (
      !createForm.policyRef ||
      !createForm.projectId ||
      !createForm.purchaseOrderId ||
      !createForm.invoiceId ||
      !createForm.billingPlanRef ||
      !createForm.totalAmount
    ) {
      return;
    }
    this.setState({ saving: true });
    const result = await revenueRecognitionService.generateSchedule({
      policyRef: createForm.policyRef,
      projectId: Number(createForm.projectId),
      purchaseOrderId: Number(createForm.purchaseOrderId),
      invoiceId: Number(createForm.invoiceId),
      billingPlanRef: createForm.billingPlanRef,
      taskActivityId: createForm.taskActivityId ? Number(createForm.taskActivityId) : null,
      totalAmount: Number(createForm.totalAmount),
      startPeriodKey: createForm.startPeriodKey,
      currency: createForm.currency || "USD",
      createDraftEntries: true,
    });
    this.setState({ saving: false });
    if (result.source === "api" && result.payload) {
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Generate failed") });
    }
  };

  getFiltered = () => {
    const { rows, query } = this.state;
    const q = (query || "").trim().toLowerCase();
    if (!q) return rows;
    return rows.filter((row) => {
      const hay = [
        row.scheduleRef,
        row.policyRef,
        row.projectId,
        row.purchaseOrderId,
        row.invoiceId,
        row.billingPlanRef,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, saving, rows, createForm, query } = this.state;
    const filtered = this.getFiltered();
    const totalLines = rows.reduce((sum, row) => sum + (Number(row.lineCount) || 0), 0);
    const totalAmount = rows.reduce((sum, row) => sum + (Number(row.totalAmount) || 0), 0);
    const kpiCards = [
      {
        id: "schedules",
        label: "Schedules",
        value: rows.length,
        hint: "Active plans",
        tone: "green",
        icon: "fe fe-calendar",
      },
      {
        id: "lines",
        label: "Lines",
        value: totalLines,
        hint: "Recognition periods",
        tone: "indigo",
        icon: "fe fe-list",
      },
      {
        id: "amount",
        label: "Scheduled",
        value: formatFinanceUsd(totalAmount),
        hint: "Total contract value",
        tone: "violet",
        icon: "fe fe-dollar-sign",
      },
      {
        id: "entries",
        label: "Next",
        value: "Entries",
        hint: "Approve drafts",
        tone: "amber",
        icon: "fe fe-check-square",
      },
    ];

    const fields = [
      ["policyRef", "Policy ref", true, "From policies register"],
      ["projectId", "Project ID", true, "Canonical Project"],
      ["purchaseOrderId", "PO ID", true, "Purchase Contract / PO"],
      ["invoiceId", "Invoice ID", true, "Platform invoice"],
      ["billingPlanRef", "Billing plan", true, "Milestone plan ref"],
      ["totalAmount", "Total amount", true, "Currency amount"],
      ["startPeriodKey", "Start period", false, "YYYY-MM"],
      ["taskActivityId", "Task activity", false, "Optional work item"],
    ];

    return (
      <FinanceLuxPage
        testId="rev-rec-schedules-page"
        pageMeta={REVENUE_RECOGNITION_SCHEDULES_META}
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><FinanceActionButton
              to="/finance/revenue-recognition/entries"
              icon="fe fe-check-square"
              variant="primary"
            >
              Review entries
            </FinanceActionButton>
          </>}
      >
        <FinanceRevRecSectionTabs active="/finance/revenue-recognition/schedules" />
        <FinanceQuickNav
          links={REV_REC_QUICK_LINKS}
          eyebrow="Recognition workflow"
          title="Schedules require live Project / PO links"
        />
        <FinanceInsightPanel
          insights={[
            {
              id: "source",
              tone: "green",
              icon: "fe fe-link",
              title: "Source-linked only",
              copy: "Every schedule ties to Project, Purchase Order, billing plan, and invoice — no isolated amounts.",
            },
            {
              id: "draft",
              tone: "amber",
              icon: "fe fe-file-plus",
              title: "Draft entries",
              copy: "Generate creates draft recognition entries ready for approval.",
              path: "/finance/revenue-recognition/entries",
            },
            {
              id: "policy",
              tone: "violet",
              icon: "fe fe-sliders",
              title: "Need a policy ref?",
              copy: "Create or copy a policy reference from the policies register first.",
              path: "/finance/revenue-recognition/policies",
            },
          ]}
        />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load schedules."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <FinanceLuxPanel
          title="Generate schedule"
          meta="Creates draft recognition lines from policy"
          icon="fe fe-zap"
          accent="green"
        >
          <form className="lux-finance-form" onSubmit={this.handleGenerate}>
            <FinanceFormGrid columns={4}>
              {fields.map(([key, label, required, hint]) => (
                <FinanceField key={key} label={label} hint={hint}>
                  <input
                    className="form-control"
                    value={createForm[key]}
                    onChange={(e) => this.handleFormChange({ [key]: e.target.value })}
                    required={required}
                    data-testid={`rrs-${key}`}
                  />
                </FinanceField>
              ))}
            </FinanceFormGrid>
            <div className="lux-finance-form__actions">
              <FinanceActionButton type="submit" icon="fe fe-play" variant="primary" disabled={saving}>
                {saving ? "Generating…" : "Generate + drafts"}
              </FinanceActionButton>
            </div>
          </form>
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Schedule register"
          meta={`${filtered.length} of ${rows.length} schedule${rows.length === 1 ? "" : "s"}`}
          icon="fe fe-list"
          accent="indigo"
        >
          <FinanceToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search ref, project, PO…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          />

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading schedules"
              description="Fetching recognition schedules."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No schedules yet" : "No matching schedules"}
              description={
                rows.length === 0
                  ? `Generate a schedule for team ${commonUtils.getCurrentUserTeamId()} with a policy and Project / PO links.`
                  : "Try a different search."
              }
              showCreate={false}
            />
          ) : (
            <FinanceRegisterWrap>
              <table className="lux-finance-register" data-testid="rev-rec-schedules-table">
                <thead>
                  <tr>
                    <th>Schedule</th>
                    <th>Policy</th>
                    <th>Project</th>
                    <th>PO</th>
                    <th>Invoice</th>
                    <th>Billing</th>
                    <th>Amount</th>
                    <th>Lines</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((row) => (
                    <tr key={row.scheduleRef || row.id}>
                      <td>
                        <FinanceRegisterPrimary
                          title={row.scheduleRef || `Schedule ${row.id}`}
                          meta={row.currency || "USD"}
                          icon="fe fe-calendar"
                          tone="green"
                        />
                      </td>
                      <td>
                        <code className="lux-finance-code">{row.policyRef || "—"}</code>
                      </td>
                      <td>{row.projectId || "—"}</td>
                      <td>{row.purchaseOrderId || "—"}</td>
                      <td>{row.invoiceId || "—"}</td>
                      <td>
                        <span className="lux-finance-chip">{row.billingPlanRef || "—"}</span>
                      </td>
                      <td>
                        <strong>{formatFinanceUsd(row.totalAmount)}</strong>
                      </td>
                      <td>{row.lineCount != null ? row.lineCount : "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </FinanceRegisterWrap>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default RevenueRecognitionSchedulesPage;
