import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isMyWorkQueueEnabled,
  buildMyWorkQueueMetrics,
  buildMyWorkInsights,
  filterMyWorkItems,
  MY_WORK_CATEGORIES,
} from "config/workspace.config";
import { workspaceService } from "_services/workspace.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import MyWorkRegister from "views/workspace/components/MyWorkRegister";
import {
  WorkspaceActionButton,
  WorkspaceKpiStrip,
  WorkspacePanelHead,
} from "views/workspace/components/WorkspaceLuxShared";
import WorkspaceSavedViewBar from "views/workspace/components/WorkspaceSavedViewBar";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class MyWorkPage extends Component {
  state = {
    items: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "OPEN",
    categoryFilter: "ALL",
    query: "",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("My work");
    this.loadQueue();
  }

  loadQueue = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await workspaceService.getMyWorkQueue();
      this.setState({
        items: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load your work queue.",
        items: [],
      });
    }
  };

  getFilteredItems = () => {
    const { items, statusFilter, categoryFilter, query } = this.state;
    return filterMyWorkItems(items, {
      status: statusFilter,
      category: categoryFilter,
      query,
    });
  };

  renderInsights = () => {
    const { items, loading } = this.state;
    if (loading) {
      return null;
    }
    const insights = buildMyWorkInsights(items);
    if (insights.length === 0) {
      return null;
    }
    return (
      <div className="lux-my-work-insights" role="list">
        {insights.map((insight) => (
          <Link
            key={insight.id}
            to={insight.path}
            className={classNames("lux-hrms-dash__alert lux-my-work-insight", `is-${insight.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__alert-icon" aria-hidden="true"><i className={insight.icon} /></span>
            <span className="lux-my-work-insight__copy">
              <strong>{insight.title}</strong>
              <small>{insight.copy}</small>
            </span>
            <i className="fe fe-chevron-right lux-my-work-insight__chevron" aria-hidden="true" />
          </Link>
        ))}
      </div>
    );
  };

  render() {
    if (!isMyWorkQueueEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="My work"
          reason="My work queue is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, categoryFilter, query } = this.state;
    const filteredItems = this.getFilteredItems();
    const metrics = buildMyWorkQueueMetrics(this.state.items);
    const kpiCards = [
      { id: "open", label: "Open items", value: metrics.open, hint: "Needs your action", tone: "amber", icon: "fe fe-check-square" },
      { id: "high", label: "High priority", value: metrics.highPriority, hint: "Due soon", tone: "rose", icon: "fe fe-alert-triangle" },
      { id: "categories", label: "Work types", value: metrics.categories, hint: "Active categories", tone: "primary", icon: "fe fe-grid" },
      { id: "total", label: "Queue total", value: metrics.total, hint: `${metrics.dueSoon} with due dates`, tone: "slate", icon: "fe fe-layers" },
    ];

    return (
      <div className="lux-my-work-page lux-register-page">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.myWork}
          actions={
            <>
              <WorkspaceActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="primary">
                Approvals
              </WorkspaceActionButton>
              <WorkspaceActionButton to="/people/timesheet" icon="fe fe-clock" variant="ghost">
                Timesheet
              </WorkspaceActionButton>
            </>
          }
        />

        <div className="lux-register-page__body">
        <WorkspaceKpiStrip cards={kpiCards} loading={loading} />
        {loadError && (
          <div className="lux-employee-360__error" role="alert">
            {loadError}
          </div>
        )}
        {this.renderInsights()}

        <section className="lux-hrms-dash__panel lux-my-work-panel">
          <WorkspacePanelHead
            title="Work queue"
            subtitle="Filter by status, category, or search across titles and due dates"
          />

          <WorkspaceSavedViewBar
            surface="MY_WORK"
            currentFilters={{ status: statusFilter, category: categoryFilter, query }}
            onApply={(nextFilters) =>
              this.setState({
                statusFilter: nextFilters.status || "OPEN",
                categoryFilter: nextFilters.category || "ALL",
                query: nextFilters.query || "",
              })
            }
          />

          <div className="lux-my-work-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search work items"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filteredItems.length}</strong> item(s)
              </span>
            </div>
            <div className="lux-my-work-panel__filters">
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {["OPEN", "ALL"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === value })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "OPEN" ? "Open" : "All"}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Category</span>
                <div className="lux-hrms-dash__filter-group">
                  <button
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", { "is-active": categoryFilter === "ALL" })}
                    onClick={() => this.setState({ categoryFilter: "ALL" })}
                  >
                    All
                  </button>
                  {Object.values(MY_WORK_CATEGORIES).map((cat) => (
                    <button
                      key={cat.id}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": categoryFilter === cat.id })}
                      onClick={() => this.setState({ categoryFilter: cat.id })}
                    >
                      {cat.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading work queue"
                description="Aggregating your open tasks and approvals."
              />
            ) : filteredItems.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-check-circle"
                title="Queue clear"
                description="No work items match your filters. Try broadening status or category."
              />
            ) : (
              <MyWorkRegister items={filteredItems} />
            )}
          </div>
        </section>
        </div>
      </div>
    );
  }
}

export default MyWorkPage;
