import React from "react";
import classNames from "classnames/bind";

function LuxCreateSectionCard({ icon, title, hint, description, children, className }) {
  return (
    <section className={classNames("lux-create-section", className)}>
      <header className="lux-create-section__head">
        <span className="lux-create-section__icon" aria-hidden="true">
          <i className={icon || "fe fe-layers"} />
        </span>
        <div className="lux-create-section__copy">
          <h3 className="lux-create-section__title">{title}</h3>
          {hint && <p className="lux-create-section__hint">{hint}</p>}
        </div>
      </header>
      <div className="lux-create-section__body">
        {description && (
          <p className="lux-create-section__description">{description}</p>
        )}
        {children}
      </div>
    </section>
  );
}

export default LuxCreateSectionCard;
