import React, { Component } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { isStaffingAiEnabled, shouldUseStaffingAiApi } from "config/staffing-ai.config";
import { getEmployeeInitials } from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";

export default class StaffingAiRecommendationsPanel extends Component {
  state = {
    brief: null,
    loading: false,
    source: "client",
  };

  componentDidMount() {
    this.loadBrief();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.request && prevProps.request.id;
    const nextId = this.props.request && this.props.request.id;
    if (prevId !== nextId) {
      this.loadBrief();
    }
  }

  loadBrief = async () => {
    const { request } = this.props;
    if (!request || !isStaffingAiEnabled()) {
      return;
    }

    this.setState({ loading: true });
    try {
      if (shouldUseStaffingAiApi()) {
        const result = await resourcePlanningService.getStaffingRecommendations(request.id);
        if (result.payload) {
          this.setState({
            brief: result.payload,
            loading: false,
            source: result.source || "api",
          });
          return;
        }
      }
      const result = await resourcePlanningService.getStaffingRecommendations(request.id, request);
      this.setState({
        brief: result.payload,
        loading: false,
        source: result.source || "client",
      });
    } catch (e) {
      this.setState({ brief: null, loading: false });
    }
  };

  renderCandidate = (candidate) => (
    <li key={candidate.id} className={classNames("lux-staffing-ai__candidate", `is-${candidate.tone}`)}>
      <span className="lux-staffing-ai__candidate-avatar" aria-hidden="true">
        {getEmployeeInitials(candidate.employeeName)}
      </span>
      <div className="lux-staffing-ai__candidate-copy">
        <strong>{candidate.employeeName}</strong>
        <span>{candidate.role}</span>
        <small>{candidate.rationale}</small>
        {candidate.matchedSkills && candidate.matchedSkills.length > 0 && (
          <span className="lux-staffing-ai__candidate-skills">
            {candidate.matchedSkills.join(" · ")}
          </span>
        )}
      </div>
      <div className="lux-staffing-ai__candidate-score">
        <strong>{candidate.matchScore}%</strong>
        <span>{candidate.availabilityPct}% free</span>
      </div>
    </li>
  );

  render() {
    if (!isStaffingAiEnabled()) {
      return null;
    }

    const { request, compact } = this.props;
    const { brief, loading, source } = this.state;

    if (!request) {
      return null;
    }

    if (loading && !brief) {
      return (
        <section className="lux-staffing-ai lux-staffing-ai--loading" aria-busy="true">
          <header className="lux-staffing-ai__head">
            <span className="lux-staffing-ai__icon" aria-hidden="true">
              <i className="fe fe-zap" />
            </span>
            <div>
              <h3>Staffing intelligence</h3>
              <p>Ranking bench and skill matches…</p>
            </div>
          </header>
        </section>
      );
    }

    if (!brief) {
      return null;
    }

    const confidencePct = Math.round((brief.confidence || 0) * 100);

    return (
      <section className={classNames("lux-staffing-ai", { "is-compact": compact })}>
        <header className="lux-staffing-ai__head">
          <span className="lux-staffing-ai__icon" aria-hidden="true">
            <i className="fe fe-zap" />
          </span>
          <div>
            <h3>Staffing intelligence</h3>
            <p>Ranked matches from bench, skills, and availability.</p>
          </div>
          <span className="lux-staffing-ai__badge">
            {source === "api" ? "Live" : source === "mock" ? "Demo" : "Unavailable"}
          </span>
        </header>

        <p className="lux-staffing-ai__headline">{brief.headline}</p>
        <p className="lux-staffing-ai__summary">{brief.summary}</p>
        <p className="lux-staffing-ai__rec">{brief.recommendation}</p>
        {brief.nextBestAction && <p className="lux-staffing-ai__action">{brief.nextBestAction}</p>}

        <div className="lux-staffing-ai__meta">
          <span>Confidence {confidencePct}%</span>
        </div>

        {brief.candidates && brief.candidates.length > 0 && (
          <ol className="lux-staffing-ai__candidates">{brief.candidates.map(this.renderCandidate)}</ol>
        )}

        {(brief.evidence || []).length > 0 && !compact && (
          <ul className="lux-staffing-ai__evidence">
            {brief.evidence.map((row) => (
              <li key={row}>{row}</li>
            ))}
          </ul>
        )}

        <div className="lux-staffing-ai__links">
          <Link to="/resources/bench" className="lux-staffing-ai__link">
            Bench register
            <i className="fe fe-arrow-right" aria-hidden="true" />
          </Link>
          <Link to="/resources/skills" className="lux-staffing-ai__link">
            Skills matrix
            <i className="fe fe-arrow-right" aria-hidden="true" />
          </Link>
        </div>

        <p className="lux-staffing-ai__disclaimer">{brief.disclaimer}</p>
      </section>
    );
  }
}
