export function isNavItemEnabled(menuAccessControl, flagModule, flag) {
  if (!menuAccessControl || !flagModule || !flag) {
    return true;
  }
  const mod = menuAccessControl[flagModule];
  if (!mod) {
    return false;
  }
  return mod[flag] !== false;
}

export function shouldShowPlannedRailItem(item) {
  if (!item || item.type !== "planned") {
    return false;
  }
  return shouldShowPlannedMenuItems();
}

export function resolveModuleRootRedirect(prefix, menuAccessControl) {
  const rule = MODULE_ROOT_REDIRECTS.find((r) => r.prefix === prefix);
  if (!rule || !menuAccessControl) {
    return null;
  }
  const mod = menuAccessControl[rule.requiresModule];
  if (!mod || mod.active !== true) {
    return null;
  }
  if (prefix === "/finance") {
    if (mod.dashboardEnabled) {
      return FINANCE_CANONICAL_ROUTES[FINANCE_ROUTE_IDS.DASHBOARD];
    }
    const sales = menuAccessControl.salesModules;
    if (sales && sales.bidrequestsEnabled) {
      return FINANCE_CANONICAL_ROUTES[FINANCE_ROUTE_IDS.BID_REQUESTS];
    }
    if (menuAccessControl.projectModules && menuAccessControl.projectModules.accountsEnabled) {
      return FINANCE_CANONICAL_ROUTES[FINANCE_ROUTE_IDS.ACCOUNTS];
    }
  }
  return rule.to;
}

export function isHeaderRailPath(pathname) {
  const path = (pathname || "").split("?")[0];
  return HEADER_RAIL_PATHS.has(path);
}

