import React, { Component } from "react";
import classNames from "classnames/bind";
import {
  getTaskBoardCardMeta,
  getTaskBoardStatusMeta,
} from "./taskboard.utils";

export default class TaskBoardListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { confirmRemove: false };
  }

  handleRemoveWorkItem = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveWorkItem(this.props.workItem.id, true);
      this.setState({ confirmRemove: false });
    } else {
      this.setState({ confirmRemove: true });
    }
  };

  canStart = (workItem) => {
    const st = String(workItem.status || "").toUpperCase();
    return st !== "INPROGRESS" && st !== "COMPLETED" && st !== "CLOSED";
  };

  canComplete = (workItem) => {
    const st = String(workItem.status || "").toUpperCase();
    return st !== "COMPLETED" && st !== "CLOSED";
  };

  render() {
    const { workItem, slNo, permission } = this.props;
    const meta = getTaskBoardCardMeta(workItem, permission);
    const statusMeta = getTaskBoardStatusMeta(workItem.status);

    return (
      <article
        className={classNames("lux-taskboard-list__item", `is-stage-${meta.column.key}`, {
          "is-overdue": meta.isOverdue,
          "is-deleted": workItem.deleted,
          "is-paused": meta.isPaused,
        })}
        role="listitem"
      >
        <span className="lux-taskboard-list__accent" aria-hidden="true" />

        <div className="lux-taskboard-list__col lux-taskboard-list__col--index">
          <span className="lux-taskboard-list__index">{slNo}</span>
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--task">
          <strong className="lux-taskboard-list__title">{workItem.name}</strong>
          {workItem.description && (
            <p className="lux-taskboard-list__desc">{workItem.description}</p>
          )}
          <div className="lux-taskboard-list__task-meta">
            {meta.itemRef && <span className="lux-taskboard-list__ref">{meta.itemRef}</span>}
            {meta.isProject && meta.projectName && (
              <span className="lux-taskboard-list__line">
                <i className="fe fe-briefcase" aria-hidden="true" />
                {meta.projectName}
              </span>
            )}
            {meta.taskName && (
              <span className="lux-taskboard-list__line">
                <i className="fe fe-layers" aria-hidden="true" />
                {meta.taskName}
              </span>
            )}
          </div>
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--column">
          <span className={classNames("lux-taskboard-list__column-pill", `is-${meta.column.tone}`)}>
            <i className={`fe ${meta.column.icon}`} aria-hidden="true" />
            {meta.column.name}
          </span>
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--category">
          <span className="lux-taskboard-list__category-pill">
            {workItem.taskActCategory || "Other"}
          </span>
          {meta.isProject ? (
            <span className="lux-taskboard-list__scope-pill is-billable">Billable</span>
          ) : (
            <span className="lux-taskboard-list__scope-pill">Non-project</span>
          )}
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--schedule">
          <div className="lux-taskboard-list__schedule-grid">
            <div>
              <em>Start</em>
              <strong>{meta.scheduleLabel}</strong>
            </div>
            <div className={classNames({ "is-warn": meta.isOverdue })}>
              <em>Due</em>
              <strong>{meta.dueLabel || "—"}</strong>
            </div>
            {meta.durationLabel && (
              <div>
                <em>{meta.stage === 4 ? "Logged" : "Est."}</em>
                <strong>{meta.durationLabel}</strong>
              </div>
            )}
          </div>
          {meta.assignee && (
            <span className="lux-taskboard-list__owner">
              <i className="fe fe-user" aria-hidden="true" />
              {meta.assignee}
            </span>
          )}
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--status is-center">
          <span className={classNames("lux-taskboard-list__status-pill", `is-${statusMeta.tone}`)}>
            {statusMeta.label}
          </span>
          {meta.isOverdue && <span className="lux-taskboard-list__overdue-tag">Overdue</span>}
          {meta.isPaused && <span className="lux-taskboard-list__paused-tag">Paused</span>}
        </div>

        <div className="lux-taskboard-list__col lux-taskboard-list__col--actions">
          <div className="lux-taskboard-list__actions" role="group" aria-label="Task actions">
            {this.canStart(workItem) && (
              <button
                type="button"
                className="lux-taskboard-list__icon-btn is-play"
                aria-label="Start — move to in progress"
                title="Start — move to in progress"
                onClick={() =>
                  this.props.showTaskStatusUpdateModel(workItem, "INPROGRESS", false, () => {})
                }
              >
                <i className="fe fe-play" aria-hidden="true" />
              </button>
            )}
            {this.canComplete(workItem) && (
              <button
                type="button"
                className="lux-taskboard-list__icon-btn is-done"
                aria-label="Mark complete"
                title="Mark complete"
                onClick={() =>
                  this.props.showTaskStatusUpdateModel(workItem, "COMPLETED", false, () => {})
                }
              >
                <i className="fe fe-check" aria-hidden="true" />
              </button>
            )}
            {permission.workItemDeleteEnabled && (
              <button
                type="button"
                className={classNames("lux-taskboard-list__icon-btn is-delete", {
                  "is-restore": workItem.deleted,
                })}
                aria-label={workItem.deleted ? "Restore task" : "Delete task"}
                title={workItem.deleted ? "Restore task" : "Delete task"}
                onClick={() =>
                  this.props.handleDeleteWorkItem(workItem.id, !workItem.deleted)
                }
              >
                <i className={workItem.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2"} aria-hidden="true" />
              </button>
            )}
            {permission.workItemRemoveEnabled && (
              <button
                type="button"
                className={classNames("lux-taskboard-list__icon-btn is-remove", {
                  "is-confirm": this.state.confirmRemove,
                })}
                aria-label={this.state.confirmRemove ? "Confirm remove from board" : "Remove from board"}
                title={this.state.confirmRemove ? "Confirm remove from board" : "Remove from board"}
                onClick={this.handleRemoveWorkItem}
              >
                <i className={this.state.confirmRemove ? "fe fe-check" : "fe fe-x"} aria-hidden="true" />
              </button>
            )}
          </div>
        </div>
      </article>
    );
  }
}
