import React from "react";
import classNames from "classnames/bind";
import { getAgendaGroups } from "./customCalendar.utils";
import { formatEventTimeRange, getCalendarEventStatusMeta } from "./userCalendar.utils";

export default function LuxCustomCalendarAgenda({
  date,
  events,
  selectedEvent,
  onSelectEvent,
}) {
  const groups = getAgendaGroups(events, date);

  if (!groups.length) {
    return (
      <div className="lux-custom-cal lux-custom-cal--agenda lux-custom-cal--agenda-empty">
        <p>No events in this period.</p>
      </div>
    );
  }

  return (
    <div className="lux-custom-cal lux-custom-cal--agenda">
      {groups.map((group) => (
        <section
          key={group.day.format("YYYY-MM-DD")}
          className={classNames("lux-custom-cal__agenda-day", { "is-today": group.isToday })}
        >
          <header className="lux-custom-cal__agenda-day-head">
            <span className="lux-custom-cal__agenda-day-label">{group.label}</span>
            {group.isToday && <span className="lux-custom-cal__today-pill">Today</span>}
            <span className="lux-custom-cal__agenda-day-count">{group.events.length}</span>
          </header>
          <ul className="lux-custom-cal__agenda-list">
            {group.events.map((event) => {
              const meta = getCalendarEventStatusMeta(event.status);
              const isSelected = selectedEvent && selectedEvent.id === event.id;
              return (
                <li key={event.id}>
                  <button
                    type="button"
                    className={classNames("lux-custom-cal__agenda-item", `is-${meta.tone}`, {
                      "is-selected": isSelected,
                    })}
                    onClick={(e) => {
                      e.stopPropagation();
                      if (onSelectEvent) onSelectEvent(event);
                    }}
                  >
                    <span className="lux-custom-cal__agenda-item-time">
                      {formatEventTimeRange(event)}
                    </span>
                    <span className="lux-custom-cal__agenda-item-body">
                      <strong>{event.title}</strong>
                      {event.desc && <span>{event.desc}</span>}
                    </span>
                    <span className={classNames("lux-custom-cal__agenda-badge", `is-${meta.tone}`)}>
                      {meta.label}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>
        </section>
      ))}
    </div>
  );
}
