import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import { userActions } from '_actions';
import { connect } from 'react-redux';
import PropTypes from "prop-types";
import { store, returnUrlUtils } from '_helpers';
import { validationUtils } from "_helpers";
import {
  applyRememberMePreference,
  getRememberedEmail,
  isRememberMeEnabled,
  setRememberMeEnabled,
} from '_helpers/authStorage.utils';
import LoginPageFooter from './LoginPageFooter';
import AuthPageShell from './components/AuthPageShell';
import AuthLoginCard from './components/AuthLoginCard';
import { MicrosoftLoginSection } from './components/MicrosoftLoginSection';

class LoginPage extends Component {
  emailInputRef = React.createRef();

  componentDidMount() {
    const from = this.props.location && this.props.location.state && this.props.location.state.from;
    if (from) {
      returnUrlUtils.saveReturnUrl(from);
    }
    if (this.emailInputRef.current) {
      this.emailInputRef.current.focus();
    }
  }

  componentDidUpdate(prevProps) {
    const hadError = prevProps.authentication && prevProps.authentication.error;
    const hasError = this.props.authentication && this.props.authentication.error;
    if (!hadError && hasError) {
      this.setState({ password: "" });
    }
  }

  constructor() {
    super();
    const rememberMe = isRememberMeEnabled();
    this.state = {
      passwordType: 'password',
      submitted: false,
      invalidEmail: false,
      rememberMe,
      email: rememberMe ? getRememberedEmail() : "",
      password: "",
      errors: {
        email: "",
        password: ""
      }
    };
  }

  togglePasswordType = () => {
    this.setState({
      passwordType: this.state.passwordType === 'text' ? 'password' : 'text'
    })
  }

  onRememberMeChange = (e) => {
    const rememberMe = e.target.checked;
    setRememberMeEnabled(rememberMe);
    this.setState({ rememberMe });
  }

  onSubmit = (e) => {
    e.preventDefault();
    this.setState({ invalidEmail: false, submitted: true });
    if (this.state.email && validationUtils.validateEmail(this.state.email)) {
      if (this.state.password) {
        applyRememberMePreference(this.state.rememberMe, this.state.email);
        store.dispatch(this.props.login(this.state.email, this.state.password, "FS"), null);
      }
    } else {
      this.setState({ invalidEmail: true });
    }
  }

  onChange = (e) => {
    this.setState({ submitted: false, invalidEmail: false });
    const { name, value } = e.target;
    this.setState({ [name]: value });
  }

  render() {
    const loggingIn = !!(this.props.authentication && this.props.authentication.loggingIn);
    const showEmailFormatError = this.state.submitted && this.state.invalidEmail;
    const showEmailRequired = this.state.submitted && !this.state.email;
    const showPasswordRequired = this.state.submitted && !this.state.password;

    return (
      <div data-testid="page-login">
        <AuthPageShell>
        <AuthLoginCard
          eyebrow="Welcome back"
          title="Sign in to your account"
          subtitle="Use your work email and password, or continue with Microsoft SSO"
        >
          {this.props.authentication.error && (
            <div className="auth-login__alert alert alert-danger" role="alert" aria-live="assertive">
              {this.props.authentication.errorMessage}
            </div>
          )}
          <form onSubmit={this.onSubmit} noValidate>
            <div className="form-group">
              <label className="form-label" htmlFor="inputEmail">Email</label>
              <div className="passwordinputcontainer auth-login__field">
                <span className="input-icon-addon"><i className="fe fe-mail" aria-hidden="true" /></span>
                <input
                  ref={this.emailInputRef}
                  type="email"
                  className={`form-control passwordinput${showEmailRequired || showEmailFormatError ? ' is-invalid' : ''}`}
                  id="inputEmail"
                  placeholder="you@company.com"
                  name="email"
                  value={this.state.email}
                  onChange={this.onChange}
                  autoComplete="email"
                  autoFocus
                  disabled={loggingIn}
                  aria-invalid={showEmailRequired || showEmailFormatError}
                  aria-describedby={showEmailRequired || showEmailFormatError ? 'email-error' : undefined}
                />
              </div>
              {showEmailRequired &&
                <div id="email-error" className="invalid-feedback" style={{ display: 'block' }}>Email is required</div>
              }
              {showEmailFormatError && !!this.state.email &&
                <div id="email-error" className="invalid-feedback" style={{ display: 'block' }}>Enter a valid email address</div>
              }
            </div>
            <div className="form-group">
              <label className="form-label auth-login__label-row" htmlFor="inputPassword">
                <span>Password</span>
                <Link
                  to="/user/forgotpassword"
                  className="auth-login__link"
                  data-ga-action="click_forgot_password"
                  data-ga-category="auth"
                  data-ga-label="Login page"
                >
                  Forgot password?
                </Link>
              </label>
              <div className="passwordinputcontainer auth-login__field">
                <span className="input-icon-addon"><i className="fe fe-lock" aria-hidden="true" /></span>
                <input
                  type={this.state.passwordType}
                  className={`form-control passwordinput${showPasswordRequired ? ' is-invalid' : ''}`}
                  id="inputPassword"
                  placeholder="Enter your password"
                  name="password"
                  value={this.state.password}
                  onChange={this.onChange}
                  autoComplete="current-password"
                  disabled={loggingIn}
                  aria-invalid={showPasswordRequired}
                  aria-describedby={showPasswordRequired ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  className="passwordshoweye"
                  onClick={this.togglePasswordType}
                  aria-label={this.state.passwordType === 'text' ? 'Hide password' : 'Show password'}
                  disabled={loggingIn}
                >
                  <i className={`fe ${this.state.passwordType === 'text' ? 'fe-eye-off' : 'fe-eye'}`} aria-hidden="true" />
                </button>
              </div>
              {showPasswordRequired &&
                <div id="password-error" className="invalid-feedback" style={{ display: 'block' }}>Password is required</div>
              }
            </div>
            <div className="form-group auth-login__remember">
              <label className="custom-control custom-checkbox">
                <input
                  type="checkbox"
                  className="custom-control-input"
                  checked={this.state.rememberMe}
                  onChange={this.onRememberMeChange}
                  disabled={loggingIn}
                  id="rememberMe"
                />
                <span className="custom-control-label">Remember me on this device</span>
              </label>
            </div>
            <div className="form-footer auth-login__actions">
              <button
                type="submit"
                className="btn btn-primary btn-block auth-login__submit"
                disabled={loggingIn}
                aria-busy={loggingIn}
                data-ga-action="login_submit"
                data-ga-category="auth"
                data-ga-label="Sign in"
              >
                {loggingIn && (
                  <span className="spinner-border spinner-border-sm mr-1" aria-hidden="true" />
                )}
                {loggingIn ? 'Signing in…' : 'Sign in'}
              </button>
              <span className="auth-login__or" aria-hidden="true">or</span>
              <div className="auth-login__sso">
                <MicrosoftLoginSection
                  rememberMe={this.state.rememberMe}
                  emailHint={this.state.email}
                  disabled={loggingIn}
                />
              </div>
            </div>
          </form>
        </AuthLoginCard>
        <LoginPageFooter />
      </AuthPageShell>
      </div>
    );
  }
}

LoginPage.propTypes = {
  login: PropTypes.func.isRequired,
  authentication: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  authentication: state.authentication,
});

const mapDispatchToProps = () => ({
  login: userActions.login
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(LoginPage);
