import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  NTPL_APPLY_PIPELINE,
  NTPL_RELATED_LINKS,
  buildNotificationTemplateMetrics,
  enrichNotificationTemplateRows,
  filterNotificationTemplates,
  isNotificationTemplatesAdminEnabled,
  isSystemNotificationTemplate,
} from "config/notification-template.config";
import { notificationTemplateService } from "_services/notificationTemplate.service";
import {
  AdminActionButton,
  AdminLuxPage,
  AdminPanelLink,
} from "views/admin/components/AdminLuxShared";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import NotificationTemplateRegister from "views/admin/components/NotificationTemplateRegister";
import NotificationTemplateDrawer from "views/admin/components/NotificationTemplateDrawer";
import "views/hrms/leaveLuxForms.css";
import "views/admin/components/NotificationTemplateDrawer.css";

class NotificationTemplatesPage extends Component {
  state = {
    templates: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    sourceFilter: "ALL",
    channelFilter: "ALL",
    selected: null,
    drawerOpen: false,
    previewHtml: "",
    previewLoading: false,
    showPreview: false,
    showDeleteConfirm: false,
    saving: false,
    sendTestEmail: "",
    sendTestLoading: false,
    sendTestMessage: null,
    formError: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Notification templates");
    this.loadTemplates();
  }

  loadTemplates = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await notificationTemplateService.listTemplates();
      this.setState({
        templates: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load notification templates.",
        templates: [],
      });
    }
  };

  getFilteredTemplates = () => {
    const { templates, query, sourceFilter, channelFilter } = this.state;
    return filterNotificationTemplates(templates, {
      query,
      source: sourceFilter,
      channel: channelFilter,
    });
  };

  closeDrawer = () => {
    if (this.state.saving || this.state.sendTestLoading) return;
    this.setState({
      drawerOpen: false,
      selected: null,
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  openTemplate = (row) => {
    this.setState({
      drawerOpen: true,
      selected: {
        ...row,
        htmlTemplate: row.htmlTemplate || "",
        subject: row.subject || "",
        enabled: row.enabled !== false,
      },
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  cloneToOverride = (row) => {
    const source = row || this.state.selected;
    if (!source || !isSystemNotificationTemplate(source)) {
      return;
    }
    this.setState({
      drawerOpen: true,
      selected: {
        eventType: source.eventType,
        channel: source.channel || "EMAIL",
        subject: source.subject || "",
        htmlTemplate: "",
        textTemplate: "",
        classpathTemplateName: source.classpathTemplateName,
        enabled: true,
        systemDefault: false,
        source: "org-override",
      },
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  handleFieldChange = (field, value) => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ selected: { ...selected, [field]: value } });
  };

  toggleEnabled = (enabled) => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ selected: { ...selected, enabled } });
  };

  saveTemplate = async () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ saving: true, formError: null, loadError: null });
    try {
      await notificationTemplateService.saveTemplate(selected);
      await this.loadTemplates();
      this.setState({
        saving: false,
        drawerOpen: false,
        selected: null,
        previewHtml: "",
        showPreview: false,
        showDeleteConfirm: false,
      });
    } catch (e) {
      this.setState({ saving: false, formError: "Unable to save template." });
    }
  };

  requestDelete = () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected) || !selected.templateRef) return;
    this.setState({ showDeleteConfirm: true });
  };

  confirmDelete = async () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected) || !selected.templateRef) return;
    this.setState({ saving: true, formError: null, loadError: null });
    try {
      await notificationTemplateService.deleteTemplate(selected.templateRef);
      await this.loadTemplates();
      this.setState({
        saving: false,
        drawerOpen: false,
        selected: null,
        previewHtml: "",
        showPreview: false,
        showDeleteConfirm: false,
      });
    } catch (e) {
      this.setState({ saving: false, formError: "Unable to delete template." });
    }
  };

  previewTemplate = async () => {
    const { selected } = this.state;
    if (!selected) return;
    this.setState({ previewLoading: true, formError: null });
    try {
      const result = await notificationTemplateService.previewTemplate(selected);
      const html = (result.payload && (result.payload.html || result.payload.text)) || "";
      this.setState({
        previewHtml: html,
        previewLoading: false,
        showPreview: true,
      });
    } catch (e) {
      this.setState({ previewLoading: false, formError: "Unable to preview template." });
    }
  };

  sendTest = async () => {
    const { selected, sendTestEmail } = this.state;
    if (!selected) return;
    this.setState({ sendTestLoading: true, sendTestMessage: null, formError: null, loadError: null });
    try {
      const result = await notificationTemplateService.sendTestTemplate({
        ...selected,
        toEmail: (sendTestEmail || "").trim() || undefined,
      });
      const payload = (result && result.payload) || {};
      this.setState({
        sendTestLoading: false,
        sendTestMessage: payload.message
          ? `${payload.message} → ${payload.toEmail || ""}`
          : "Send-test completed.",
      });
    } catch (e) {
      this.setState({
        sendTestLoading: false,
        sendTestMessage: null,
        formError: (e && e.message) || "Send-test failed (mail may be disabled).",
      });
    }
  };

  render() {
    if (!isNotificationTemplatesAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Notification templates"
          reason="Notification template administration is not enabled for your organization."
        />
      );
    }

    const filtered = this.getFilteredTemplates();
    const metrics = buildNotificationTemplateMetrics(this.state.templates);
    const enriched = enrichNotificationTemplateRows(this.state.templates);
    const {
      selected,
      drawerOpen,
      previewHtml,
      previewLoading,
      showPreview,
      showDeleteConfirm,
      saving,
      loading,
      dataSource,
      sendTestEmail,
      sendTestLoading,
      sendTestMessage,
      query,
      sourceFilter,
      channelFilter,
      loadError,
      formError,
    } = this.state;

    const busy = saving || sendTestLoading;
    const nextOverride = enriched.find((row) => !row.system) || enriched.find((row) => row.system);

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.notificationTemplates}
        dataSource={dataSource}
        loading={loading}
        testId="page-admin-notification-templates"
        className="lux-admin-page lux-ntpl-page lux-leave-page"
        onRefresh={this.loadTemplates}
        refreshLoading={loading}
      >
        <AdminInsightsSummary
          storageKey="famstack-notification-templates-summary-expanded"
          domainClass="lux-admin-summary--ntpl"
          loading={loading}
          eyebrow="Messaging catalog"
          eyebrowIcon="fe-mail"
          title="Notification template insights"
          compactTitle={`${metrics.total} templates · ${metrics.overrides} overrides · ${metrics.families} families`}
          collapsedLine={`${metrics.system} system · ${metrics.disabled} disabled · ${
            dataSource === "api" ? "live merge" : "catalog"
          }`}
          subtitle="Classpath defaults merge with org overrides. Open any row in the drawer to view, clone, or edit."
          kpis={[
            {
              key: "total",
              label: "Templates",
              value: metrics.total,
              hint: `${metrics.families} families`,
              tone: "blue",
              icon: "fe fe-mail",
            },
            {
              key: "system",
              label: "System",
              value: metrics.system,
              hint: "Read-only defaults",
              tone: "sky",
              icon: "fe fe-package",
            },
            {
              key: "overrides",
              label: "Overrides",
              value: metrics.overrides,
              hint: "Org layered",
              tone: metrics.overrides ? "violet" : "slate",
              icon: "fe fe-edit-3",
            },
            {
              key: "disabled",
              label: "Disabled",
              value: metrics.disabled,
              hint: "Not dispatching",
              tone: metrics.disabled ? "amber" : "green",
              icon: "fe fe-slash",
            },
          ]}
          highlights={[
            {
              key: "email",
              label: "Email channel",
              value: metrics.email,
              hint: "EMAIL templates",
              tone: "indigo",
              icon: "fe fe-at-sign",
            },
            {
              key: "live",
              label: "Catalog",
              value: dataSource === "api" ? "Live" : "Merged",
              hint: "Classpath + org",
              tone: "green",
              icon: "fe fe-database",
            },
          ]}
          attention={
            loading
              ? []
              : nextOverride
                ? [
                    {
                      id: "next",
                      eyebrow: nextOverride.system ? "System" : "Override",
                      stat: nextOverride.family.label,
                      title: nextOverride.eventType || "Template",
                      copy: nextOverride.subject || "Open the drawer to view or edit this template.",
                      hint: nextOverride.system
                        ? "View is read-only — clone to override."
                        : "Edit applies on next dispatch.",
                      icon: nextOverride.system ? "fe fe-eye" : "fe fe-edit-2",
                      tone: nextOverride.system ? "sky" : "violet",
                    },
                  ]
                : []
          }
          mixInsights={[
            {
              key: "source-mix",
              icon: "fe fe-layers",
              title: "Source mix",
              subtitle: "System defaults vs org overrides",
              mix: [
                {
                  key: "system",
                  label: "System",
                  count: metrics.system,
                  pct: Math.round((metrics.system / Math.max(metrics.total, 1)) * 100),
                  tone: "sky",
                },
                {
                  key: "override",
                  label: "Overrides",
                  count: metrics.overrides,
                  pct: Math.round((metrics.overrides / Math.max(metrics.total, 1)) * 100),
                  tone: "violet",
                },
              ],
            },
          ]}
          series={[
            {
              id: "catalog-slice",
              title: "Catalog slice",
              subtitle: "Recent templates",
              rows: enriched.slice(0, 6).map((row) => ({
                key: row.templateRef || row.eventType,
                label: row.eventType || row.templateRef,
                icon: row.family.icon,
                tone: row.enabled ? row.family.tone : "amber",
                value: row.enabled ? 1 : 0,
                pct: row.enabled ? 100 : 28,
                meta: row.sourceLabel,
              })),
            },
          ]}
          testId="notification-templates-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--ntpl lux-admin-atelier--compact"
          data-testid="notification-templates-atelier"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-mail" />
              </span>
              <div className="lux-admin-atelier__masthead-copy">
                <div className="lux-admin-atelier__title-row">
                  <p className="lux-admin-atelier__eyebrow">Messaging studio</p>
                  <h2 className="lux-admin-atelier__title">Template catalog</h2>
                </div>
                <p className="lux-admin-atelier__lede">
                  {dataSource === "api"
                    ? "Live merged catalog — click View / Edit to open the drawer"
                    : "Merged classpath defaults + org overrides — click View / Edit to open the drawer"}
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/audit">Audit</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{filtered.length}</strong>
                <em>shown</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__body">
            <AdminLoadAlert
              error={loadError}
              fallback="Unable to load notification templates."
              onDismiss={() => this.setState({ loadError: null })}
            />

            <div className="lux-ntpl-pipeline" data-testid="ntpl-pipeline">
              <header className="lux-ntpl-pipeline__head">
                <div>
                  <p className="lux-ntpl-eyebrow">How it works</p>
                  <h3>From catalog to dispatch</h3>
                  <p>
                    System defaults stay read-only. Clone to override, preview with masking, then
                    dispatch uses the layered org template.
                  </p>
                </div>
              </header>
              <ol className="lux-ntpl-pipeline__steps">
                {NTPL_APPLY_PIPELINE.map((step, index) => (
                  <li key={step.id} className="lux-ntpl-pipeline__step">
                    <span className="lux-ntpl-pipeline__index" aria-hidden="true">
                      {index + 1}
                    </span>
                    <span className="lux-ntpl-pipeline__icon" aria-hidden="true">
                      <i className={step.icon} />
                    </span>
                    <div>
                      <strong>{step.label}</strong>
                      <em>{step.copy}</em>
                    </div>
                  </li>
                ))}
              </ol>
            </div>

            <div className="lux-ntpl-related" role="list" aria-label="Related admin consoles">
              {NTPL_RELATED_LINKS.map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  className={classNames("lux-ntpl-related__card", `is-${item.tone}`)}
                  role="listitem"
                >
                  <span className="lux-ntpl-related__icon" aria-hidden="true">
                    <i className={item.icon} />
                  </span>
                  <span className="lux-ntpl-related__copy">
                    <strong>{item.title}</strong>
                    <em>{item.copy}</em>
                  </span>
                  <i className="fe fe-arrow-right lux-ntpl-related__chevron" aria-hidden="true" />
                </Link>
              ))}
            </div>

            <div className="lux-admin-atelier__stage-card lux-ntpl-stage">
              <div className="lux-ntpl-toolbar">
                <div className="lux-ntpl-toolbar__copy">
                  <p className="lux-ntpl-eyebrow">Catalog</p>
                  <h3>Merged templates</h3>
                  <p>
                    Search by event, subject, family, or ref. Open a row to view system defaults or
                    edit org overrides in the drawer.
                  </p>
                </div>
                <div className="lux-ntpl-toolbar__controls">
                  <label className="lux-ntpl-search">
                    <i className="fe fe-search" aria-hidden="true" />
                    <input
                      type="search"
                      value={query}
                      placeholder="Search event, subject, family, or ref"
                      onChange={(e) => this.setState({ query: e.target.value })}
                      data-testid="ntpl-search"
                      aria-label="Search notification templates"
                    />
                  </label>
                  <div className="lux-ntpl-chips" role="group" aria-label="Filter by source">
                    {[
                      { id: "ALL", label: "All" },
                      { id: "SYSTEM", label: "System" },
                      { id: "OVERRIDE", label: "Overrides" },
                    ].map((item) => (
                      <button
                        key={item.id}
                        type="button"
                        className={classNames("lux-ntpl-filter", {
                          "is-active": sourceFilter === item.id,
                        })}
                        onClick={() => this.setState({ sourceFilter: item.id })}
                      >
                        {item.label}
                      </button>
                    ))}
                  </div>
                  <div className="lux-ntpl-chips" role="group" aria-label="Filter by channel">
                    {[
                      { id: "ALL", label: "All channels" },
                      { id: "EMAIL", label: "Email" },
                    ].map((item) => (
                      <button
                        key={item.id}
                        type="button"
                        className={classNames("lux-ntpl-filter", {
                          "is-active": channelFilter === item.id,
                        })}
                        onClick={() => this.setState({ channelFilter: item.id })}
                      >
                        {item.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {loading ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Templates"
                  title="Loading catalog"
                  description="Fetching the merged notification catalog."
                />
              ) : filtered.length === 0 ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Templates"
                  icon="fe fe-mail"
                  title="No templates"
                  description="Adjust filters or refresh the live catalog."
                />
              ) : (
                <NotificationTemplateRegister
                  templates={filtered}
                  onView={this.openTemplate}
                  onEdit={this.openTemplate}
                  onClone={this.cloneToOverride}
                />
              )}
            </div>
          </div>
        </section>

        <NotificationTemplateDrawer
          open={drawerOpen}
          selected={selected}
          busy={busy}
          saving={saving}
          previewHtml={previewHtml}
          previewLoading={previewLoading}
          showPreview={showPreview}
          showDeleteConfirm={showDeleteConfirm}
          sendTestEmail={sendTestEmail}
          sendTestLoading={sendTestLoading}
          sendTestMessage={sendTestMessage}
          formError={formError}
          onClose={this.closeDrawer}
          onChange={this.handleFieldChange}
          onToggleEnabled={this.toggleEnabled}
          onClone={() => this.cloneToOverride()}
          onSave={this.saveTemplate}
          onRequestDelete={this.requestDelete}
          onCancelDelete={() => this.setState({ showDeleteConfirm: false })}
          onConfirmDelete={this.confirmDelete}
          onPreview={this.previewTemplate}
          onClosePreview={() => this.setState({ showPreview: false })}
          onSendTestEmailChange={(value) =>
            this.setState({ sendTestEmail: value, sendTestMessage: null })
          }
          onSendTest={this.sendTest}
        />
      </AdminLuxPage>
    );
  }
}

export default NotificationTemplatesPage;
