/**
 * Auth persistence helpers.
 *
 * Auth tokens always live in localStorage so they are shared across tabs.
 * Remember me = keep session after browser restart + remember email.
 * Unchecked = same-tab/new-tab session via localStorage, but cleared on the
 * next cold browser start (session cookie marker is gone).
 */
const REMEMBER_KEY = "fs.rememberMe";
const REMEMBERED_EMAIL_KEY = "fs.rememberedEmail";
const SESSION_COOKIE = "fs.authSession";
const AUTH_KEYS = ["cu", "ac", "authToken", "authRefreshToken", "loginType"];

export function isRememberMeEnabled() {
  const raw = localStorage.getItem(REMEMBER_KEY);
  // Default true so existing localStorage sessions keep working.
  if (raw == null) return true;
  return raw === "true";
}

export function setRememberMeEnabled(enabled) {
  localStorage.setItem(REMEMBER_KEY, enabled ? "true" : "false");
}

export function getRememberedEmail() {
  return localStorage.getItem(REMEMBERED_EMAIL_KEY) || "";
}

export function setRememberedEmail(email) {
  const trimmed = String(email || "").trim();
  if (trimmed) {
    localStorage.setItem(REMEMBERED_EMAIL_KEY, trimmed);
  } else {
    localStorage.removeItem(REMEMBERED_EMAIL_KEY);
  }
}

function hasBrowserSessionMarker() {
  if (typeof document === "undefined") return false;
  return document.cookie.split(";").some((part) => part.trim().startsWith(`${SESSION_COOKIE}=`));
}

function setBrowserSessionMarker() {
  if (typeof document === "undefined") return;
  // Session cookie: cleared when the browser process exits.
  document.cookie = `${SESSION_COOKIE}=1; path=/; SameSite=Lax`;
}

function clearBrowserSessionMarker() {
  if (typeof document === "undefined") return;
  document.cookie = `${SESSION_COOKIE}=; path=/; Max-Age=0; SameSite=Lax`;
}

/** Move any legacy tab-scoped auth into shared localStorage. */
function migrateSessionAuthToLocal() {
  AUTH_KEYS.forEach((key) => {
    const sessionVal = sessionStorage.getItem(key);
    if (sessionVal == null) return;
    if (localStorage.getItem(key) == null) {
      localStorage.setItem(key, sessionVal);
    }
    sessionStorage.removeItem(key);
  });
}

/**
 * Call once on app boot (before PrivateRoute auth checks).
 * Migrates legacy sessionStorage auth and enforces Remember-me semantics.
 */
export function ensureAuthSession() {
  migrateSessionAuthToLocal();
  if (isRememberMeEnabled()) {
    clearBrowserSessionMarker();
    return;
  }
  if (!hasBrowserSessionMarker()) {
    // Cold browser start without Remember me — drop durable tokens.
    clearAuthStorage();
  }
}

export function authSetItem(key, value) {
  localStorage.setItem(key, value);
  sessionStorage.removeItem(key);
}

export function authGetItem(key) {
  const fromLocal = localStorage.getItem(key);
  if (fromLocal != null) return fromLocal;
  const fromSession = sessionStorage.getItem(key);
  if (fromSession != null) {
    localStorage.setItem(key, fromSession);
    sessionStorage.removeItem(key);
    return fromSession;
  }
  return null;
}

export function authRemoveItem(key) {
  sessionStorage.removeItem(key);
  localStorage.removeItem(key);
}

export function clearAuthStorage() {
  AUTH_KEYS.forEach((key) => authRemoveItem(key));
  clearBrowserSessionMarker();
}

/** Apply remember preference before writing auth payload. */
export function applyRememberMePreference(enabled, email) {
  setRememberMeEnabled(!!enabled);
  migrateSessionAuthToLocal();
  if (enabled) {
    setRememberedEmail(email);
    clearBrowserSessionMarker();
  } else {
    setRememberedEmail("");
    setBrowserSessionMarker();
  }
}
