import React from "react";
import classNames from "classnames/bind";

const MODULE_ICONS = {
  delivery: "fe fe-layers",
  people: "fe fe-users",
  service: "fe fe-life-buoy",
  finance: "fe fe-dollar-sign",
  approvals: "fe fe-check-circle",
  ai: "fe fe-cpu",
  knowledge: "fe fe-book-open",
};

export default function KnowledgeArticleRegister({ articles, loading }) {
  if (loading) {
    return (
      <div className="lux-krca-register lux-krca-register--loading">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-krca-skeleton lux-krca-skeleton--row" />
        ))}
      </div>
    );
  }

  const rows = articles || [];
  if (!rows.length) {
    return (
      <div className="lux-krca-empty">
        <i className="fe fe-database" aria-hidden="true" />
        <p>No articles match your search.</p>
      </div>
    );
  }

  return (
    <div className="lux-krca-register">
      {rows.map((row, index) => (
        <article key={row.id} className={classNames("lux-krca-register__row", row.tone && `is-${row.tone}`)}>
          <span className="lux-krca-register__index" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className="lux-krca-register__rail" aria-hidden="true">
            <i className={MODULE_ICONS[row.module] || "fe fe-file-text"} />
          </span>
          <div className="lux-krca-register__main lux-krca-register__main--static">
            <span className="lux-krca-register__eyebrow">{row.module} · {row.status}</span>
            <h3>{row.title}</h3>
            <p>{row.snippet}</p>
            <div className="lux-krca-register__meta">
              {(row.tags || []).map((tag) => (
                <span key={tag} className="lux-krca-tag">{tag}</span>
              ))}
              <span>{row.viewCount} views</span>
              <span>{row.authorName}</span>
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}
