export function getSetupPhaseMeta(phaseId) {
  return SETUP_CHECKLIST_PHASES.find((row) => row.id === phaseId) || SETUP_CHECKLIST_PHASES[0];
}

export function enrichSetupChecklistItem(row) {
  const base = row && typeof row === "object" ? row : {};
  const id = String(base.id || "").trim();
  const enrichment = SETUP_CHECKLIST_ENRICHMENT[id] || {
    phase: "foundation",
    summary: base.label || "Implementation step",
    automation: "manual",
    automationHint: "Complete this step from the related admin console.",
    docs: [],
    actions: [],
  };
  return {
    id,
    label: base.label || enrichment.summary || id,
    done: Boolean(base.done),
    ...enrichment,
  };
}

export function enrichSetupChecklistItems(items) {
  return (Array.isArray(items) ? items : []).map(enrichSetupChecklistItem);
}

export function groupSetupChecklistByPhase(items) {
  const enriched = enrichSetupChecklistItems(items);
  return SETUP_CHECKLIST_PHASES.map((phase) => {
    const phaseItems = enriched.filter((row) => row.phase === phase.id);
    const done = phaseItems.filter((row) => row.done).length;
    return {
      ...phase,
      items: phaseItems,
      done,
      total: phaseItems.length,
      complete: phaseItems.length > 0 && done === phaseItems.length,
    };
  }).filter((phase) => phase.total > 0);
}

export function buildSetupChecklistProgress(items) {
  const enriched = enrichSetupChecklistItems(items);
  const total = enriched.length;
  const done = enriched.filter((row) => row.done).length;
  const remaining = Math.max(total - done, 0);
  const automatable = enriched.filter((row) => row.automation === "automate").length;
  const assisted = enriched.filter((row) => row.automation === "assisted").length;
  const manual = enriched.filter((row) => row.automation === "manual" || !row.automation).length;
  const nextOpen = enriched.find((row) => !row.done) || null;
  const pct = total ? Math.round((done / total) * 100) : 0;
  return {
    total,
    done,
    remaining,
    complete: total > 0 && remaining === 0,
    automatable,
    assisted,
    manual,
    nextOpen,
    pct,
  };
}
