function resolveUserTeamId() {
  const teamId = commonUtils.getCurrentUserTeamId();
  if (teamId != null && teamId !== "") {
    return teamId;
  }
  const user = commonUtils.getCurrentUser() || {};
  if (user.userTeamId != null) {
    return user.userTeamId;
  }
  if (user.defaultUserTeamDetails && user.defaultUserTeamDetails.id != null) {
    return user.defaultUserTeamDetails.id;
  }
  return null;
}

function currentUserContext() {
  return {
    userTeamId: resolveUserTeamId(),
    actorId: commonUtils.getCurrentUserId(),
    actorName: commonUtils.getCurrentUserName() || "Employee",
  };
}

function assertUserTeamId(userTeamId) {
  if (userTeamId == null || userTeamId === "" || String(userTeamId) === "undefined") {
    throw new Error("User team is not available for lifecycle API calls.");
  }
  return userTeamId;
}

function wrapApiPayload(payload) {
  return { payload: payload == null ? null : payload, source: "api" };
}

function assertServiceResponse(response, actionLabel) {
  if (!response || typeof response === "string") {
    throw new Error(
      typeof response === "string" && response.trim()
        ? response
        : `${actionLabel} failed — empty API response.`
    );
  }
  if (response.payload === undefined && response.error) {
    throw new Error(
      Array.isArray(response.error)
        ? response.error[0] && response.error[0].message
          ? response.error[0].message
          : String(response.error[0])
        : String(response.error)
    );
  }
  return response;
}

async function listOnboardingCases(userTeamId) {
  const resolvedTeamId = assertUserTeamId(
    userTeamId != null ? userTeamId : currentUserContext().userTeamId
  );
  const response = await axiosUtils.get(
    `${urlConfig.ONBOARDING_API_PATH}/cases?userTeamId=${resolvedTeamId}`
  );
  return wrapApiPayload(response.payload || []);
}

async function getOnboardingCase(caseId) {
      const userTeamId = assertUserTeamId(currentUserContext().userTeamId);
    const response = await axiosUtils.get(
      `${urlConfig.ONBOARDING_API_PATH}/cases/${encodeURIComponent(caseId)}?userTeamId=${userTeamId}`
    );
    return wrapApiPayload(response.payload);
  
}

async function completeOnboardingTask(caseId, taskId, actorName = "HR Admin", userTeamId) {
  const { actorId } = currentUserContext();
  const resolvedTeamId = assertUserTeamId(
    userTeamId != null ? userTeamId : currentUserContext().userTeamId
  );
  const response = await axiosUtils.patch(
    `${urlConfig.ONBOARDING_API_PATH}/cases/${encodeURIComponent(caseId)}/tasks/${encodeURIComponent(taskId)}/complete?userTeamId=${resolvedTeamId}&actorId=${actorId}&actorName=${encodeURIComponent(actorName)}`
  );
  return wrapApiPayload(response.payload || { success: true, caseId, taskId });
}

