async function convertOnboardingCase(caseId, userAccessId, employeeUserTeamId, employeeManagerId) {
  const { actorId } = currentUserContext();
  const userTeamId = assertUserTeamId(currentUserContext().userTeamId);
  const resolvedEmployeeTeamId = assertUserTeamId(employeeUserTeamId);
  if (!actorId) {
    throw new Error("Your user session is missing an employee id.");
  }
  if (!userAccessId) {
    throw new Error("Select an employee access role before creating the record.");
  }
  if (!resolvedEmployeeTeamId) {
    throw new Error("Select a default user team before creating the record.");
  }

  const managerQuery =
    employeeManagerId != null && employeeManagerId !== ""
      ? `&employeeManagerId=${Number(employeeManagerId)}`
      : "";
  const raw = await axiosUtils.post(
    `${urlConfig.ONBOARDING_API_PATH}/cases/${encodeURIComponent(caseId)}/convert?userTeamId=${userTeamId}&actorId=${actorId}&userAccessId=${userAccessId}&employeeUserTeamId=${resolvedEmployeeTeamId}${managerQuery}`,
    {
      userTeamId,
      actorId,
      userAccessId,
      employeeUserTeamId: resolvedEmployeeTeamId,
      employeeManagerId:
        employeeManagerId != null && employeeManagerId !== ""
          ? Number(employeeManagerId)
          : null,
    }
  );
  const response = assertServiceResponse(raw, "Convert to employee");
  const payload = response.payload;

  if (!payload || payload.success === false) {
    const blockerText =
      payload && Array.isArray(payload.blockers) && payload.blockers.length
        ? payload.blockers.join(" ")
        : null;
    throw new Error(
      (payload && payload.message) ||
        blockerText ||
        "Convert to employee was declined by the server."
    );
  }

  return wrapApiPayload(payload);
}

