async function rejectLifecycleApprovalTask(caseId, taskId, lifecycle, comment, userTeamId) {
  const { actorId, actorName } = currentUserContext();
  const resolvedTeamId = assertUserTeamId(
    userTeamId != null ? userTeamId : currentUserContext().userTeamId
  );
  const basePath =
    lifecycle === "offboarding" ? urlConfig.OFFBOARDING_API_PATH : urlConfig.ONBOARDING_API_PATH;
  const response = await axiosUtils.patch(
    `${basePath}/cases/${encodeURIComponent(caseId)}/tasks/${encodeURIComponent(taskId)}/reject?userTeamId=${resolvedTeamId}&actorId=${actorId}&actorName=${encodeURIComponent(actorName)}`,
    { comment: comment || null }
  );
  return wrapApiPayload(response.payload || { success: true, caseId, taskId });
}

