async function createOnboardingTemplate(request) {
  const result = await (async () => {
      const { actorId } = currentUserContext();
      const userTeamId = assertUserTeamId(currentUserContext().userTeamId);
      const response = assertServiceResponse(
        await axiosUtils.post(
          `${urlConfig.ONBOARDING_API_PATH}/templates?userTeamId=${userTeamId}&actorId=${actorId}`,
          request
        ),
        "Create onboarding template"
      );
      return wrapApiPayload(response.payload);
    })();
  if (!result || !result.payload || !result.payload.code) {
    throw new Error("Onboarding template was not saved.");
  }
  return result;
}

