import React from "react";
import PropTypes from "prop-types";
import { PublicClientApplication } from "@azure/msal-browser";
import { MsalProvider } from "@azure/msal-react";
import { msalConfig } from "_helpers/microsoftAuthConfig";
import { MicrosoftSignInButton } from "./fragments/MicrosoftSignInButton";

const msalInstance = new PublicClientApplication(msalConfig);

export const MicrosoftLoginSection = ({ rememberMe, emailHint, disabled }) => {
    return (
        <MsalProvider instance={msalInstance}>
           <MicrosoftSignInButton
             rememberMe={rememberMe}
             emailHint={emailHint}
             disabled={disabled}
           />
        </MsalProvider>
    )
}

MicrosoftLoginSection.propTypes = {
  rememberMe: PropTypes.bool,
  emailHint: PropTypes.string,
  disabled: PropTypes.bool,
};

MicrosoftLoginSection.defaultProps = {
  rememberMe: true,
  emailHint: "",
  disabled: false,
};
