import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";

const MENU_GAP = 6;
const VIEWPORT_PAD = 12;
const ESTIMATED_PANEL_HEIGHT = 280;
const PORTAL_Z_INDEX = 10050;

/**
 * Renders a list-row action menu in document.body with fixed positioning
 * so it is not clipped by overflow containers (main layout, list scroll areas).
 */
class LuxListRowMenuPortal extends Component {
  constructor(props) {
    super(props);
    this.panelRef = React.createRef();
    this.state = { coords: null };
  }

  componentDidMount() {
    if (this.props.open) {
      this.schedulePosition();
    }
    window.addEventListener("scroll", this.handleReposition, true);
    window.addEventListener("resize", this.handleReposition);
  }

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.schedulePosition();
    }
    if (!this.props.open && prevProps.open) {
      this.setState({ coords: null });
    }
  }

  componentWillUnmount() {
    window.removeEventListener("scroll", this.handleReposition, true);
    window.removeEventListener("resize", this.handleReposition);
  }

  schedulePosition = () => {
    requestAnimationFrame(() => {
      requestAnimationFrame(this.updatePosition);
    });
  };

  handleReposition = () => {
    if (this.props.open) {
      this.updatePosition();
    }
  };

  updatePosition = () => {
    const anchor = this.props.anchorRef && this.props.anchorRef.current;
    if (!anchor) {
      return;
    }

    const rect = anchor.getBoundingClientRect();
    const panel = this.panelRef.current;
    const panelWidth = panel ? panel.offsetWidth : 248;
    const panelHeight = panel
      ? panel.offsetHeight
      : ESTIMATED_PANEL_HEIGHT;

    let top = rect.bottom + MENU_GAP;
    let left = rect.right - panelWidth;

    const spaceBelow = window.innerHeight - rect.bottom - VIEWPORT_PAD;
    if (
      spaceBelow < panelHeight + MENU_GAP &&
      rect.top > panelHeight + MENU_GAP
    ) {
      top = rect.top - panelHeight - MENU_GAP;
    }

    left = Math.max(
      VIEWPORT_PAD,
      Math.min(left, window.innerWidth - panelWidth - VIEWPORT_PAD)
    );
    top = Math.max(
      VIEWPORT_PAD,
      Math.min(top, window.innerHeight - panelHeight - VIEWPORT_PAD)
    );

    const next = { top, left };
    const changed =
      !this.state.coords ||
      this.state.coords.top !== next.top ||
      this.state.coords.left !== next.left;

    if (changed) {
      this.setState({ coords: next }, () => {
        if (panel && panel.offsetHeight !== panelHeight) {
          requestAnimationFrame(this.updatePosition);
        }
      });
    }
  };

  render() {
    const { open, className, children } = this.props;
    if (!open) {
      return null;
    }

    const positioned = Boolean(this.state.coords);
    const coords = this.state.coords || { top: 0, left: 0 };

    return createPortal(
      <div
        ref={this.panelRef}
        className={classNames(
          "lux-emp-card__menu-panel",
          "lux-list-row-menu-portal",
          className
        )}
        style={{
          position: "fixed",
          top: coords.top,
          left: coords.left,
          right: "auto",
          zIndex: PORTAL_Z_INDEX,
          visibility: positioned ? "visible" : "hidden",
        }}
        role="menu"
      >
        {children}
      </div>,
      document.body
    );
  }
}

export default LuxListRowMenuPortal;
