import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  isAnalyticsPlatformEnabled,
  isScheduledReportsDeliveryEnabled,
} from "config/analytics-platform.config";
import { SCHEDULED_REPORTS_PAGE_META } from "config/analytics-platform-nav.config";
import { analyticsPlatformService } from "_services/analyticsPlatform.service";
import AnalyticsLuxPage, { AnalyticsActionButton, AnalyticsLuxPanel } from "views/analytics/components/AnalyticsLuxShared";
import ScheduledReportsPanel from "views/analytics/components/ScheduledReportsPanel";

class ScheduledReportsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    schedules: [],
    savedReports: [],
    exportJobs: [],
  };

  componentDidMount() {
    if (!isScheduledReportsDeliveryEnabled()) {
      this.setState({ loading: false });
      return;
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [schedulesResult, reportsResult, jobsResult] = await Promise.all([
        analyticsPlatformService.listScheduledReports(),
        analyticsPlatformService.listSavedReports(),
        analyticsPlatformService.listExportJobs(),
      ]);
      this.setState({
        loading: false,
        schedules: schedulesResult.payload || [],
        savedReports: reportsResult.payload || [],
        exportJobs: jobsResult.payload || [],
        dataSource: schedulesResult.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load scheduled reports.",
      });
    }
  };

  handleSaveSchedule = async (payload) => {
    const result = await analyticsPlatformService.saveScheduledReport(payload);
    const schedulesResult = await analyticsPlatformService.listScheduledReports();
    this.setState({ schedules: schedulesResult.payload || [] });
    return result;
  };

  handleQueueExport = async (payload) => {
    const result = await analyticsPlatformService.queueExportJob(payload);
    const jobsResult = await analyticsPlatformService.listExportJobs();
    this.setState({ exportJobs: jobsResult.payload || [] });
    return result;
  };

  render() {
    if (!isAnalyticsPlatformEnabled()) {
      return <PersonaAccessDenied featureLabel="Scheduled reports" />;
    }

    if (!isScheduledReportsDeliveryEnabled()) {
      return (
        <div className="lux-analytics-page p-4" data-testid="page-analytics-scheduled-reports-deferred">
          <LuxRegisterEmptyState
            eyebrow="Analytics"
            title="Scheduled report delivery deferred"
            description="Schedule CRUD and email/in-app delivery are not enabled in production until delivery proof (message IDs, run history, failure/retry) is complete. This route is fail-closed and not advertised in primary navigation."
            hints={[
              "Use Analytics Hub exports for on-demand reports",
              "Delivery unlocks only after ANA-004 staging evidence is signed",
            ]}
            showCreate={false}
          />
        </div>
      );
    }

    const { loading, loadError, dataSource, schedules, savedReports, exportJobs } = this.state;
    const meta = SCHEDULED_REPORTS_PAGE_META;

    return (
      <AnalyticsLuxPage
        testId="page-analytics-scheduled-reports"
        pageMeta={meta}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        dataSource={dataSource}
        kpiCards={[
          { id: "schedules", label: "Schedules", value: String(schedules.length), hint: "Active cadence", icon: "fe fe-clock", tone: "amber" },
          { id: "reports", label: "Linked reports", value: String(savedReports.length), hint: "Saved definitions", icon: "fe fe-edit-3", tone: "indigo" },
          { id: "jobs", label: "Export jobs", value: String(exportJobs.length), hint: "Queue history", icon: "fe fe-upload-cloud", tone: "blue" },
          {
            id: "active",
            label: "Active",
            value: String(schedules.filter((row) => row.status === "ACTIVE").length),
            hint: "Delivering now",
            icon: "fe fe-check-circle",
            tone: "green",
          },
        ]}
        demoLabel="Demo scheduled reports"
        loading={loading}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <AnalyticsActionButton to="/analytics/hub" icon="fe fe-grid" variant="ghost">
              Analytics hub
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/report-builder" icon="fe fe-edit-3" variant="primary">
              Report builder
            </AnalyticsActionButton>
          </>
        }
      >
        {loadError ? (
          <AnalyticsLuxPanel title="Scheduled reports load issue" meta={loadError} accent="rose">
            <AnalyticsActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadData}>
              Retry
            </AnalyticsActionButton>
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsLuxPanel
          title={meta.panelTitle}
          meta={meta.panelMeta}
          icon="fe fe-clock"
          accent="indigo"
        >
          <ScheduledReportsPanel
            schedules={schedules}
            savedReports={savedReports}
            exportJobs={exportJobs}
            loading={loading}
            onSaveSchedule={this.handleSaveSchedule}
            onQueueExport={this.handleQueueExport}
          />
        </AnalyticsLuxPanel>
      </AnalyticsLuxPage>
    );
  }
}

export default ScheduledReportsPage;
