import React, { Component } from "react";
import { writeOffsService } from "_services/writeOffs.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";

class WriteOffsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    rows: [],
    createForm: {
      invoiceId: "",
      amount: "",
      reason: "",
      projectId: "",
      currency: "USD",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Write-offs");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await writeOffsService.listWriteOffs();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load write-offs"),
      });
    }
  };

  handleFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleCreate = async (event) => {
    event.preventDefault();
    const { createForm } = this.state;
    if (!createForm.invoiceId || !createForm.amount || !createForm.reason) {
      return;
    }
    this.setState({ saving: true });
    const result = await writeOffsService.createWriteOff({
      invoiceId: Number(createForm.invoiceId),
      amount: Number(createForm.amount),
      reason: createForm.reason,
      currency: createForm.currency || "USD",
      projectId: createForm.projectId ? Number(createForm.projectId) : null,
    });
    this.setState({ saving: false });
    if (result.source === "api" && result.payload) {
      this.setState({
        createForm: {
          invoiceId: "",
          amount: "",
          reason: "",
          projectId: "",
          currency: "USD",
        },
      });
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  handleSubmit = async (ref, userTeamId) => {
    await writeOffsService.submitWriteOff(ref, userTeamId);
    this.loadData();
  };

  handleApprove = async (ref, userTeamId) => {
    await writeOffsService.approveWriteOff(ref, userTeamId);
    this.loadData();
  };

  render() {
    const { loading, loadError, saving, rows, createForm } = this.state;
    return (
      <FinanceLuxPage
        testId="write-offs-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-slash",
          eyebrow: "Finance",
          titleLead: "Write",
          titleAccent: "offs",
          lede: "Request and approve invoice write-offs. Reason and approval are required.",
        }}
        dataSource="api"
        demoLabel={null}
        loading={loading}
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load write-offs."
          onDismiss={() => this.setState({ loadError: null })}
        />
        <FinanceLuxPanel title="Create write-off">
          <form onSubmit={this.handleCreate} className="d-flex flex-wrap gap-2 align-items-end">
            <label className="small mb-0">
              Invoice ID
              <input
                className="form-control form-control-sm"
                value={createForm.invoiceId}
                onChange={(e) => this.handleFormChange({ invoiceId: e.target.value })}
                required
                data-testid="wo-invoice-id"
              />
            </label>
            <label className="small mb-0">
              Amount
              <input
                type="number"
                step="0.01"
                min="0.01"
                className="form-control form-control-sm"
                value={createForm.amount}
                onChange={(e) => this.handleFormChange({ amount: e.target.value })}
                required
                data-testid="wo-amount"
              />
            </label>
            <label className="small mb-0">
              Project ID (optional)
              <input
                className="form-control form-control-sm"
                value={createForm.projectId}
                onChange={(e) => this.handleFormChange({ projectId: e.target.value })}
              />
            </label>
            <label className="small mb-0 flex-grow-1">
              Reason
              <input
                className="form-control form-control-sm"
                value={createForm.reason}
                onChange={(e) => this.handleFormChange({ reason: e.target.value })}
                required
                data-testid="wo-reason"
              />
            </label>
            <FinanceActionButton type="submit" variant="primary" disabled={saving}>
              {saving ? "Saving…" : "Create draft"}
            </FinanceActionButton>
          </form>
        </FinanceLuxPanel>
        <FinanceLuxPanel title="Write-offs" className="mt-3">
          {loading ? (
            <p className="text-muted small mb-0">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-muted small mb-0">No write-offs for team {commonUtils.getCurrentUserTeamId()}.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-sm" data-testid="write-offs-table">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Invoice</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th>Reason</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.writeOffRef || row.id}>
                      <td>{row.writeOffRef}</td>
                      <td>{row.invoiceId}</td>
                      <td>
                        {row.currency || "USD"} {row.amount}
                      </td>
                      <td>{row.status}</td>
                      <td>{row.reason}</td>
                      <td className="text-nowrap">
                        {row.status === "DRAFT" && (
                          <button
                            type="button"
                            className="btn btn-link btn-sm p-0 me-2"
                            onClick={() => this.handleSubmit(row.writeOffRef, row.userTeamId)}
                          >
                            Submit
                          </button>
                        )}
                        {row.status === "SUBMITTED" && (
                          <button
                            type="button"
                            className="btn btn-link btn-sm p-0"
                            onClick={() => this.handleApprove(row.writeOffRef, row.userTeamId)}
                          >
                            Approve
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default WriteOffsPage;
