import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPortfolioControlTowerEnabled } from "config/portfolio-control-tower.config";
import { portfolioControlTowerService } from "_services/portfolioControlTower.service";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import PortfolioLuxPage, { PortfolioLuxPanel } from "views/project/components/PortfolioLuxShared";
import PortfolioScenarioPanel from "views/project/components/PortfolioScenarioPanel";
import { PORTFOLIO_PAGE_VARIANTS } from "config/portfolio-control-tower-nav.config";

const DEFAULT_PORTFOLIO_ID = "pf-enterprise";

class PortfolioScenarioPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    rollup: null,
    executiveMetrics: [],
    scenarios: [],
    comparison: null,
    selectedScenarioId: null,
    selectedPortfolioId: DEFAULT_PORTFOLIO_ID,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async (scenarioId) => {
    this.setState({ loading: true, loadError: null });
    try {
      const portfolioId = this.state.selectedPortfolioId || DEFAULT_PORTFOLIO_ID;
      const [rollupResult, metricsResult, scenariosResult] = await Promise.all([
        portfolioControlTowerService.getPortfolioRollup(portfolioId),
        portfolioControlTowerService.getExecutiveMetrics(),
        portfolioControlTowerService.listScenarios({ portfolioId }),
      ]);
      const scenarios = scenariosResult.payload || [];
      const activeScenarioId = scenarioId || this.state.selectedScenarioId || (scenarios[0] && scenarios[0].id);
      let comparison = null;
      if (activeScenarioId) {
        const comparisonResult = await portfolioControlTowerService.getScenarioComparison(portfolioId, activeScenarioId);
        comparison = comparisonResult.payload;
      }
      this.setState({
        loading: false,
        rollup: rollupResult.payload,
        executiveMetrics: metricsResult.payload || [],
        scenarios,
        comparison,
        selectedScenarioId: activeScenarioId,
        dataSource: rollupResult.source || scenariosResult.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load portfolio scenarios.",
      });
    }
  };

  handleSelectScenario = async (scenarioId) => {
    const portfolioId = this.state.selectedPortfolioId || DEFAULT_PORTFOLIO_ID;
    try {
      const comparisonResult = await portfolioControlTowerService.getScenarioComparison(portfolioId, scenarioId);
      this.setState({ selectedScenarioId: scenarioId, comparison: comparisonResult.payload });
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to load scenario comparison." });
    }
  };

  handleSaveScenario = async (payload) => {
    const result = await portfolioControlTowerService.saveScenario(payload);
    await this.loadData(result.payload.id);
    return result;
  };

  render() {
    if (!isPortfolioControlTowerEnabled()) {
      return <PersonaAccessDenied featureLabel="Portfolio scenario planning" />;
    }

    const { loading, loadError, rollup, executiveMetrics, dataSource, scenarios, comparison, selectedPortfolioId } = this.state;

    return (
      <PortfolioLuxPage
        variant={PORTFOLIO_PAGE_VARIANTS.SCENARIOS}
        dataSource={dataSource}
        demoLabel="Demo portfolio scenarios"
        loading={loading}
        rollup={rollup}
        executiveMetrics={executiveMetrics}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <ResourcesActionButton to="/project/portfolio" icon="fe fe-briefcase" variant="ghost">
              Control tower
            </ResourcesActionButton>
            <ResourcesActionButton to="/analytics/executive-control-tower" icon="fe fe-bar-chart-2" variant="primary">
              Executive view
            </ResourcesActionButton>
          </>
        }
      >
        {loadError ? (
          <PortfolioLuxPanel title="Scenario load issue" meta={loadError} accent="rose">
            <button type="button" className="lux-onb-action lux-onb-action--primary" onClick={() => this.loadData()}>
              Retry
            </button>
          </PortfolioLuxPanel>
        ) : null}

        <PortfolioLuxPanel
          title="Portfolio scenario planning"
          meta="Compare baseline health, slippage, risk, and margin against saved what-if trajectories"
          icon="fe fe-git-branch"
          accent="violet"
          className="lux-portfolio-lux__panel--featured"
        >
          <PortfolioScenarioPanel
            portfolioId={selectedPortfolioId}
            scenarios={scenarios}
            comparison={comparison}
            loading={loading}
            onSelectScenario={this.handleSelectScenario}
            onSaveScenario={this.handleSaveScenario}
          />
        </PortfolioLuxPanel>
      </PortfolioLuxPage>
    );
  }
}

export default PortfolioScenarioPage;
