import React, { Component } from "react";
import { connect } from "react-redux";
import { purchaseOrderActions, dashboardActions, projectActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { accessUtils } from "_helpers";
import { projectConstants } from "_constants";
import PurchaseOrderDetailsGeneral from "./components/PurchaseOrderDetailsGeneral";
import PurchaseOrderDetailsHeader from "./components/PurchaseOrderDetailsHeader";
import ProjectListPageTableSection from "./components/ProjectListPageTableSection";
import ViewProjectDetailsSidebar from "./components/modal/ViewProjectDetailsSidebar";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxDetailPageSkeleton from "views/common/fragments/LuxDetailPageSkeleton";

class PurchaseOrderDetailsPage extends Component {
  constructor() {
    super();
    this.state = {
      selectedMenuName: "details",
      permission: accessUtils.getPurchaseOrderAccessControl(),
      permissionProjects: accessUtils.getProjectAccessControl(),
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      `${this.props.routeProp.name} : ${this.props.match.params.purchaseOrderId}`
    );
    if (
      !this.props.purchaseOrderInfo ||
      this.props.purchaseOrderInfo.id !== this.props.match.params.purchaseOrderId
    ) {
      const purchaseOrderId = commonUtils.removeNameIntial(this.props.match.params.purchaseOrderId);
      store.dispatch(this.props.getPurchaseOrderInfo(purchaseOrderId));
      this.setState({ purchaseOrderId });
    }
  }

  onCloseViewProject = () => {
    store.dispatch({ type: projectConstants.CLOSE_PROJECT_VIEW_WINDOW });
  };

  onSelectMenu = (menuName) => {
    this.setState({ selectedMenuName: menuName });
    if (menuName === "projects") {
      this.invokeProjectListService();
    }
  };

  invokeProjectListService = () => {
    if (!this.props.purchaseOrderInfo) return;
    store.dispatch(
      this.props.getProjectsByPurchaseOrder({
        userTeamIds:
          this.state.permission.showAllPurchaseOrderProjects === false
            ? commonUtils.getCurrentUserTeamIds()
            : [],
        purchaseOrderNumber: this.props.purchaseOrderInfo.id,
        currentUserId: commonUtils.getCurrentUserId(),
      })
    );
  };

  render() {
    const { purchaseOrderInfo, isLoading } = this.props;
    const { permission, permissionProjects, selectedMenuName } = this.state;
    const hasAccess =
      purchaseOrderInfo &&
      commonUtils.hasAccess(purchaseOrderInfo, permission.allowAccessToOtherUserTeamPurchaseOrder);
    const readOnly = !hasAccess || (purchaseOrderInfo && purchaseOrderInfo.deleted);

    return (
      <div
        className="lux-po-detail-page lux-bid-detail-page pd-page lux-hrms-dash"
        data-testid="page-finance-purchase-contract-detail"
      >
        {isLoading && (
          <div className="lux-bid-detail-page__loading">
            <LuxDetailPageSkeleton ariaLabel="Loading purchase contract" />
          </div>
        )}

        {!isLoading && purchaseOrderInfo && hasAccess && (
          <>
            <PurchaseOrderDetailsHeader
              selectedMenu={selectedMenuName}
              onSelectMenu={this.onSelectMenu}
            />

            {selectedMenuName === "projects" ? (
              <div className="lux-po-detail-page__projects">
                <ProjectListPageTableSection
                  items={this.props.projectItems}
                  isLoading={this.props.loadingPOProjects}
                  invokeProjectListService={this.invokeProjectListService}
                  permission={{
                    ...permissionProjects,
                    editEnabled: false,
                    duplicateEnabled: false,
                  }}
                />
              </div>
            ) : (
              <PurchaseOrderDetailsGeneral
                item={purchaseOrderInfo}
                permission={permission}
                readOnly={readOnly}
                projectStatistics={this.props.projectStatisticsByCategory}
                statisticsItemId={purchaseOrderInfo.purchaseOrderNumber}
                loadProjectStatistics={this.props.getProjectStatisticsByCategory}
              />
            )}
          </>
        )}

        {!purchaseOrderInfo && !isLoading && (
          <LuxRegisterEmptyState
            variant="purchase-contracts"
            eyebrow="Contract portfolio"
            title="No purchase contract details found"
            description="You may not have permission to view this contract, or it may have been removed."
            hints={[
              "Confirm the contract ID in the URL",
              "Return to the register and open the contract from the list",
            ]}
          />
        )}

        <ViewProjectDetailsSidebar
          show={this.props.isShowProjectViewSidebar}
          onCloseViewProject={this.onCloseViewProject}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  purchaseOrderInfo: state.purchaseOrders.selectedPurchaseOrderInfo,
  isLoading: state.purchaseOrders.loading,
  projectStatisticsByCategory: state.dashboard.projectStatisticsByCategory,
  isShowProjectViewSidebar: state.projects.isShowProjectViewSidebar,
  projectItems: state.projects.projectItems,
  loadingPOProjects: state.projects.loadingPOProjects,
});

const mapDispatchToProps = () => ({
  getPurchaseOrderInfo: purchaseOrderActions.getPurchaseOrderInfo,
  getProjectStatisticsByCategory: dashboardActions.getProjectStatisticsByCategory,
  getProjectsByPurchaseOrder: projectActions.getProjectsByPurchaseOrder,
});

export default connect(mapStateToProps, mapDispatchToProps)(PurchaseOrderDetailsPage);
