import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import CountUp from "react-countup";
import {
  formatCurrency,
  getFinancialYearLabel,
  INVOICE_DASHBOARD_SCOPE,
  INVOICE_STATUS_ORDER,
} from "./invoice.utils";
import InvoiceOutstandingPanel from "./InvoiceOutstandingPanel";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-invoice-summary-expanded";

class InvoicePageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY),
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  getStatusFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ALL";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  renderMixBar = (segments) => {
    if (!segments || !segments.length) {
      return <div className="lux-inv-summary__bar lux-inv-summary__bar--empty">No invoices yet</div>;
    }

    return (
      <div className="lux-inv-summary__bar" role="img" aria-label="Invoice status breakdown">
        {segments.map((segment) => (
          <span
            key={segment.status}
            className={classNames("lux-inv-summary__bar-segment", `is-${segment.tone}`)}
            style={{ width: `${Math.max(segment.pct, segment.count > 0 ? 4 : 0)}%` }}
            title={`${segment.label}: ${segment.count} (${segment.pct}%)`}
          />
        ))}
      </div>
    );
  };

  renderMixLegend = (segments) => (
    <ul className="lux-inv-summary__legend">
      {segments.map((segment) => (
        <li key={segment.status}>
          <span className={classNames("lux-inv-summary__legend-dot", `is-${segment.tone}`)} />
          <span className="lux-inv-summary__legend-label">{segment.label}</span>
          <strong>{segment.count}</strong>
          <span className="lux-inv-summary__legend-pct">{segment.pct}%</span>
        </li>
      ))}
    </ul>
  );

  renderFilterChips = (statusFilter, compact) => (
    <div
      className={classNames("lux-inv-summary__filters", {
        "lux-inv-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter by status"
    >
      {[
        { value: "ALL", label: "All" },
        ...INVOICE_STATUS_ORDER.map((status) => ({
          value: status,
          label: status.charAt(0) + status.slice(1).toLowerCase(),
        })),
      ].map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-inv-summary__filter-chip", {
            "is-active": statusFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  buildContextLine = (stat, visibleCount, filterOptions, dashboardScope) => {
    const parts = [];
    if (dashboardScope === INVOICE_DASHBOARD_SCOPE.ALL) {
      parts.push("All loaded invoices");
    } else if (stat.fyLabel) {
      parts.push(stat.fyLabel);
    }
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    } else {
      parts.push(`${stat.total} invoice${stat.total === 1 ? "" : "s"}`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    if (stat.recentMonthLabel) {
      parts.push(`latest period ${stat.recentMonthLabel}`);
    }
    return parts.join(" · ");
  };

  renderFyScopeChips = () => {
    const {
      dashboardScope,
      selectedFyStartYear,
      availableFinancialYears,
      onDashboardScopeChange,
    } = this.props;

    return (
      <div
        className="lux-inv-summary__fy-scope"
        role="group"
        aria-label="Dashboard financial year scope"
      >
        <button
          type="button"
          className={classNames("lux-inv-summary__fy-chip", {
            "is-active": dashboardScope === INVOICE_DASHBOARD_SCOPE.ALL,
          })}
          onClick={() => onDashboardScopeChange(INVOICE_DASHBOARD_SCOPE.ALL)}
        >
          All loaded
        </button>
        <button
          type="button"
          className={classNames("lux-inv-summary__fy-chip", {
            "is-active": dashboardScope === INVOICE_DASHBOARD_SCOPE.CURRENT_FY,
          })}
          onClick={() => onDashboardScopeChange(INVOICE_DASHBOARD_SCOPE.CURRENT_FY)}
        >
          Current FY
        </button>
        {(availableFinancialYears || []).map((startYear) => (
          <button
            key={startYear}
            type="button"
            className={classNames("lux-inv-summary__fy-chip", {
              "is-active":
                dashboardScope === INVOICE_DASHBOARD_SCOPE.FY &&
                selectedFyStartYear === startYear,
            })}
            onClick={() => onDashboardScopeChange(INVOICE_DASHBOARD_SCOPE.FY, startYear)}
          >
            {getFinancialYearLabel(startYear)}
          </button>
        ))}
      </div>
    );
  };

  renderMonthlyInsights = (insights, canViewAmounts) => (
    <div className="lux-inv-summary__monthly-kpis">
      <div className="lux-inv-summary__monthly-kpi">
        <span className="lux-inv-summary__monthly-kpi-label">Active months</span>
        <strong className="lux-inv-summary__monthly-kpi-value">{insights.activeMonths}</strong>
      </div>
      <div className="lux-inv-summary__monthly-kpi">
        <span className="lux-inv-summary__monthly-kpi-label">Period total</span>
        <strong className="lux-inv-summary__monthly-kpi-value">
          {canViewAmounts ? formatCurrency(insights.fyTotalAmount, { compact: true }) : "—"}
        </strong>
      </div>
      <div className="lux-inv-summary__monthly-kpi">
        <span className="lux-inv-summary__monthly-kpi-label">Peak month</span>
        <strong className="lux-inv-summary__monthly-kpi-value">
          {insights.peakLabel || "—"}
        </strong>
      </div>
      <div className="lux-inv-summary__monthly-kpi">
        <span className="lux-inv-summary__monthly-kpi-label">Avg / active mo.</span>
        <strong className="lux-inv-summary__monthly-kpi-value">
          {canViewAmounts && insights.activeMonths
            ? formatCurrency(insights.avgAmountPerMonth, { compact: true })
            : "—"}
        </strong>
      </div>
    </div>
  );

  renderMonthlyBreakdown = (stat, canViewAmounts) => {
    const rows = stat.monthlyBreakdown || [];
    const insights = stat.monthlyInsights || {};
    const activeRows = rows.filter((row) => row.count > 0);

    if (!rows.length) {
      return <p className="lux-inv-summary__monthly-empty">No monthly billing in this scope.</p>;
    }

    const maxAmount = Math.max(...rows.map((row) => row.amount), 1);

    return (
      <div className="lux-inv-summary__monthly-body">
        {this.renderMonthlyInsights(insights, canViewAmounts)}

        <div
          className="lux-inv-summary__monthly-grid"
          role="img"
          aria-label="Monthly invoice volume by billing period"
          style={
            stat.fyStartYear == null
              ? { gridTemplateColumns: `repeat(${Math.min(rows.length, 12)}, minmax(0, 1fr))` }
              : undefined
          }
        >
          {rows.map((row) => {
            const barHeight = row.amount > 0 ? Math.max((row.amount / maxAmount) * 100, 12) : 4;
            return (
              <div
                key={row.sortKey || row.label}
                className={classNames("lux-inv-summary__monthly-cell", {
                  "is-active": row.count > 0,
                  "is-peak": row.isPeak,
                  "is-recent": row.isRecent,
                })}
                title={
                  row.count > 0
                    ? `${row.label}: ${row.count} invoice${row.count === 1 ? "" : "s"}${
                        canViewAmounts ? ` · ${formatCurrency(row.amount)}` : ""
                      }`
                    : `${row.label}: no billing`
                }
              >
                <div className="lux-inv-summary__monthly-cell-bar" aria-hidden="true">
                  <span style={{ height: `${barHeight}%` }} />
                </div>
                <span className="lux-inv-summary__monthly-cell-month">
                  {row.shortLabel || row.label}
                </span>
                <span className="lux-inv-summary__monthly-cell-count">
                  {row.count > 0 ? row.count : "·"}
                </span>
              </div>
            );
          })}
        </div>

        <div className="lux-inv-summary__monthly-legend">
          <span className="lux-inv-summary__monthly-legend-item is-recent">
            <i className="fe fe-calendar" aria-hidden="true" />
            Latest period
          </span>
          <span className="lux-inv-summary__monthly-legend-item is-peak">
            <i className="fe fe-trending-up" aria-hidden="true" />
            Peak billing
          </span>
        </div>

        {activeRows.length > 0 ? (
          <ul className="lux-inv-summary__monthly-detail">
            {[...activeRows]
              .sort((a, b) => b.amount - a.amount)
              .slice(0, 4)
              .map((row) => (
                <li key={`detail-${row.sortKey || row.label}`}>
                  <span className="lux-inv-summary__monthly-detail-label">{row.label}</span>
                  <span className="lux-inv-summary__monthly-detail-meta">
                    <strong>{row.count}</strong>
                    <em>{canViewAmounts ? formatCurrency(row.amount, { compact: true }) : "—"}</em>
                  </span>
                </li>
              ))}
          </ul>
        ) : (
          <p className="lux-inv-summary__monthly-empty">No invoices billed in this period yet.</p>
        )}
      </div>
    );
  };

  renderMetric = (label, value, suffix, tone, icon) => {
    const { isLoading } = this.props;
    return (
      <div className={classNames("lux-inv-summary__metric", tone && `is-${tone}`)}>
        <div className="lux-inv-summary__metric-icon">
          <i className={`fe ${icon}`} aria-hidden="true" />
        </div>
        <div className="lux-inv-summary__metric-copy">
          <span className="lux-inv-summary__metric-label">{label}</span>
          <strong className="lux-inv-summary__metric-value">
            {isLoading ? (
              <Skeleton width={56} height={18} />
            ) : (
              <>
                <CountUp end={value} duration={0.8} separator="," decimals={suffix ? 2 : 0} />
                {suffix}
              </>
            )}
          </strong>
        </div>
      </div>
    );
  };

  render() {
    const {
      stat,
      visibleCount,
      filterOptions,
      isLoading,
      canViewAmounts,
      dashboardScope,
      listFyFilterEnabled,
      onToggleListFyFilter,
      outstanding,
      onFocusPending,
    } = this.props;
    const { expanded } = this.state;
    const statusFilter = this.getStatusFilter();
    const contextLine = this.buildContextLine(stat, visibleCount, filterOptions, dashboardScope);

    return (
      <section
        className={classNames("lux-inv-summary", { "is-collapsed": !expanded })}
        aria-label="Billing overview"
      >
        <div className="lux-inv-summary__header-bar">
          <div className="lux-inv-summary__header-main">
            <LuxSummaryEyebrow variant="invoices" className="lux-inv-summary__eyebrow">
              Billing intelligence
            </LuxSummaryEyebrow>
            <h2 className="lux-inv-summary__title">
              {isLoading ? (
                <Skeleton width={180} height={22} />
              ) : (
                <>
                  {stat.total} invoice{stat.total === 1 ? "" : "s"}
                  {canViewAmounts && stat.totalAmount > 0 && (
                    <span className="lux-inv-summary__title-amount">
                      {formatCurrency(stat.totalAmount, { compact: true })} total
                    </span>
                  )}
                </>
              )}
            </h2>
            {!expanded && (
              <p className="lux-inv-summary__collapsed-line">{contextLine}</p>
            )}
          </div>
          <button
            type="button"
            className="lux-inv-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
          >
            {getSummaryToggleLabel(expanded)}
            <i className={`fe fe-chevron-${expanded ? "up" : "down"}`} aria-hidden="true" />
          </button>
        </div>

        {expanded && (
          <div className="lux-inv-summary__body">
            <div className="lux-inv-summary__scope-bar">
              {this.renderFyScopeChips()}
              {dashboardScope !== INVOICE_DASHBOARD_SCOPE.ALL && (
                <label className="lux-inv-summary__list-fy-toggle">
                  <input
                    type="checkbox"
                    checked={listFyFilterEnabled === true}
                    onChange={(e) => onToggleListFyFilter && onToggleListFyFilter(e.target.checked)}
                  />
                  <span>Also filter invoice list to {stat.fyLabel || "this FY"}</span>
                </label>
              )}
            </div>

            <p className="lux-inv-summary__context">{contextLine}</p>

            <div className="lux-inv-summary__hero">
              <div className="lux-inv-summary__hero-main">
                <span className="lux-inv-summary__hero-label">Portfolio value</span>
                <div className="lux-inv-summary__hero-value">
                  {isLoading ? (
                    <Skeleton width={140} height={36} />
                  ) : canViewAmounts ? (
                    <>
                      <CountUp
                        end={stat.totalAmount}
                        duration={1}
                        separator=","
                        decimals={2}
                        prefix="₹"
                      />
                      <span className="lux-inv-summary__hero-sub">
                        avg {formatCurrency(stat.avgAmount)} per invoice
                      </span>
                    </>
                  ) : (
                    <span className="lux-inv-summary__hero-masked">—</span>
                  )}
                </div>
                <div className="lux-inv-summary__hero-stats">
                  <span>
                    <i className="fe fe-users" aria-hidden="true" />
                    {isLoading ? "—" : `${stat.totalUsers} billed users`}
                  </span>
                  <span>
                    <i className="fe fe-calendar" aria-hidden="true" />
                    {isLoading
                      ? "—"
                      : stat.recentMonthLabel
                        ? `${stat.recentMonthCount} in ${stat.recentMonthLabel}`
                        : "No billing period"}
                  </span>
                </div>
              </div>

              <div className="lux-inv-summary__hero-cards">
                <div className="lux-inv-summary__flow-card is-outstanding">
                  <span>Outstanding</span>
                  <strong>
                    {isLoading || !canViewAmounts
                      ? "—"
                      : formatCurrency(stat.outstandingAmount, { compact: true })}
                  </strong>
                  <small>{stat.pendingCount + stat.approvedCount + stat.draftCount} open</small>
                </div>
                <div className="lux-inv-summary__flow-card is-collected">
                  <span>Collected</span>
                  <strong>
                    {isLoading || !canViewAmounts
                      ? "—"
                      : formatCurrency(stat.collectedAmount, { compact: true })}
                  </strong>
                  <small>{stat.paidCount + stat.closedCount} settled</small>
                </div>
              </div>
            </div>

            <div className="lux-inv-summary__metrics">
              {this.renderMetric("Pending", stat.pendingCount, null, "blue", "fe-clock")}
              {this.renderMetric("Approved", stat.approvedCount, null, "amber", "fe-check-circle")}
              {this.renderMetric("Paid", stat.paidCount, null, "green", "fe-dollar-sign")}
              {this.renderMetric("Closed", stat.closedCount, null, "violet", "fe-lock")}
            </div>

            {(dashboardScope === INVOICE_DASHBOARD_SCOPE.CURRENT_FY ||
              dashboardScope === INVOICE_DASHBOARD_SCOPE.FY) && (
              <InvoiceOutstandingPanel
                outstanding={outstanding}
                isLoading={isLoading}
                canViewAmounts={canViewAmounts}
                dashboardScope={dashboardScope}
                onFocusPending={onFocusPending}
              />
            )}

            <div className="lux-inv-summary__panels">
              <div className="lux-inv-summary__panels-main">
                <div className="lux-inv-summary__panel">
                  <div className="lux-inv-summary__panel-head">
                    <h3>Status distribution</h3>
                    {this.renderFilterChips(statusFilter, true)}
                  </div>
                  {isLoading ? (
                    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
                      <Skeleton height={10} borderRadius={999} />
                    </SkeletonTheme>
                  ) : (
                    <>
                      {this.renderMixBar(stat.statusMix)}
                      {this.renderMixLegend(stat.statusMix)}
                    </>
                  )}
                </div>

                <div className="lux-inv-summary__panel lux-inv-summary__panel--amounts">
                  <div className="lux-inv-summary__panel-head">
                    <h3>Revenue by status</h3>
                  </div>
                  <ul className="lux-inv-summary__amount-list">
                    {INVOICE_STATUS_ORDER.map((status) => {
                      const segment = stat.statusMix.find((s) => s.status === status);
                      const count = segment ? segment.count : 0;
                      const amount = segment ? segment.amount : 0;
                      const tone = segment ? segment.tone : "slate";
                      if (!count && !isLoading) return null;
                      return (
                        <li key={status} className={classNames("is-" + tone)}>
                          <span>{status.charAt(0) + status.slice(1).toLowerCase()}</span>
                          <strong>{count}</strong>
                          <em>{canViewAmounts ? formatCurrency(amount, { compact: true }) : "—"}</em>
                        </li>
                      );
                    })}
                    {!stat.statusMix.length && !isLoading && (
                      <li className="is-empty">No revenue data yet</li>
                    )}
                  </ul>
                </div>
              </div>

              <div className="lux-inv-summary__panel lux-inv-summary__panel--monthly">
                <div className="lux-inv-summary__panel-head lux-inv-summary__panel-head--monthly">
                  <div className="lux-inv-summary__panel-title-wrap">
                    <h3>
                      {stat.fyLabel ? `${stat.fyLabel} billing rhythm` : "Monthly billing"}
                    </h3>
                    <span className="lux-inv-summary__panel-hint">
                      {stat.fyStartYear != null
                        ? "Apr – Mar · volume by billing month"
                        : "Recent billing periods"}
                    </span>
                  </div>
                  {stat.recentMonthLabel && !isLoading && (
                    <span className="lux-inv-summary__monthly-badge">
                      Latest {stat.recentMonthLabel}
                    </span>
                  )}
                </div>
                {isLoading ? (
                  <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
                    <Skeleton height={220} borderRadius={12} />
                  </SkeletonTheme>
                ) : (
                  this.renderMonthlyBreakdown(stat, canViewAmounts)
                )}
              </div>
            </div>

            <div className="lux-inv-summary__footer-filters">
              {this.renderFilterChips(statusFilter, false)}
            </div>
          </div>
        )}
      </section>
    );
  }
}

export default InvoicePageSummary;
