import dateUtils from "_helpers/date.utils";
import { formatEventTimeRange } from "./userCalendar.utils";

export const CALENDAR_VIEWS = ["month", "week", "day", "agenda"];
export const HOUR_START = 0;
export const HOUR_END = 24;
export const SLOT_MINUTES = 30;
export const HOUR_HEIGHT_PX = 52;
export const MONTH_CELL_EVENT_LIMIT = 3;

export function getPeriodLabel(date, view) {
  const anchor = dateUtils.convertDateToMoment(date) || dateUtils.getCurrentTime();
  const { start, end } = getVisibleRange(anchor, view);

  if (view === "month") return anchor.format("MMMM YYYY");
  if (view === "day") return anchor.format("dddd, MMM D, YYYY");
  if (view === "agenda") {
    return `${start.format("MMM D")} – ${end.format("MMM D, YYYY")}`;
  }
  return `${start.format("MMM D")} – ${end.format("MMM D, YYYY")}`;
}

export function getVisibleRange(anchor, view) {
  const m = dateUtils.convertDateToMoment(anchor).clone();
  switch (view) {
    case "month":
      return { start: m.clone().startOf("month"), end: m.clone().endOf("month") };
    case "week":
      return { start: m.clone().startOf("week"), end: m.clone().endOf("week") };
    case "day":
      return { start: m.clone().startOf("day"), end: m.clone().endOf("day") };
    case "agenda":
      return { start: m.clone().startOf("day"), end: m.clone().endOf("month") };
    default:
      return { start: m.clone().startOf("week"), end: m.clone().endOf("week") };
  }
}

export function getMonthGridDays(anchorDate) {
  const anchor = dateUtils.convertDateToMoment(anchorDate);
  const monthStart = anchor.clone().startOf("month");
  const gridStart = monthStart.clone().startOf("week");
  const days = [];
  for (let i = 0; i < 42; i += 1) {
    const day = gridStart.clone().add(i, "days");
    days.push({
      date: day.toDate(),
      moment: day,
      isCurrentMonth: day.isSame(monthStart, "month"),
      isToday: day.isSame(dateUtils.getCurrentTime(), "day"),
      isWeekend: day.day() === 0 || day.day() === 6,
    });
  }
  return days;
}

export function getWeekDays(anchorDate) {
  const start = dateUtils.convertDateToMoment(anchorDate).clone().startOf("week");
  return [...Array(7)].map((_, i) => {
    const day = start.clone().add(i, "days");
    return {
      date: day.toDate(),
      moment: day,
      isToday: day.isSame(dateUtils.getCurrentTime(), "day"),
      isWeekend: day.day() === 0 || day.day() === 6,
    };
  });
}

export function getDayMeta(anchorDate) {
  const m = dateUtils.convertDateToMoment(anchorDate).clone().startOf("day");
  return {
    date: m.toDate(),
    moment: m,
    isToday: m.isSame(dateUtils.getCurrentTime(), "day"),
    isWeekend: m.day() === 0 || m.day() === 6,
  };
}

export function eventOverlapsDay(event, dayMoment) {
  const dayStart = dayMoment.clone().startOf("day");
  const dayEnd = dayMoment.clone().endOf("day");
  const start = dateUtils.convertDateToMoment(event.start);
  const end = dateUtils.convertDateToMoment(event.end || event.start);
  return start.isBefore(dayEnd) && end.isAfter(dayStart);
}

export function getEventsForDay(events, dayMoment) {
  return (events || [])
    .filter((ev) => eventOverlapsDay(ev, dayMoment))
    .sort((a, b) => a.start - b.start);
}

export function getAgendaGroups(events, anchorDate) {
  const { start, end } = getVisibleRange(anchorDate, "agenda");
  const groups = [];
  const cursor = start.clone();

  while (cursor.isSameOrBefore(end, "day")) {
    const dayEvents = getEventsForDay(events, cursor);
    if (dayEvents.length > 0) {
      groups.push({
        day: cursor.clone(),
        date: cursor.toDate(),
        label: cursor.format("ddd, MMM D"),
        isToday: cursor.isSame(dateUtils.getCurrentTime(), "day"),
        events: dayEvents,
      });
    }
    cursor.add(1, "day");
  }

  return groups;
}

export function getTimeSlots() {
  const slots = [];
  for (let h = HOUR_START; h < HOUR_END; h += 1) {
    slots.push({
      hour: h,
      label: dateUtils.getCurrentTime().clone().startOf("day").add(h, "hours").format("h a"),
    });
  }
  return slots;
}

/** Position timed events in a single day column (week/day views). */
export function layoutDayTimedEvents(events, dayMoment) {
  const dayStart = dayMoment.clone().startOf("day");
  const dayEvents = getEventsForDay(events, dayMoment).filter((ev) => !ev.allDay);

  const laidOut = dayEvents.map((event) => {
    const start = dateUtils.convertDateToMoment(event.start);
    const end = dateUtils.convertDateToMoment(event.end || event.start);
    const clampedStart = start.isBefore(dayStart) ? dayStart.clone() : start;
    const clampedEnd = end.isAfter(dayStart.clone().endOf("day"))
      ? dayStart.clone().endOf("day")
      : end;

    const startMinutes = clampedStart.diff(dayStart, "minutes");
    const durationMinutes = Math.max(clampedEnd.diff(clampedStart, "minutes"), SLOT_MINUTES);

    const top = (startMinutes / 60) * HOUR_HEIGHT_PX;
    const height = Math.max((durationMinutes / 60) * HOUR_HEIGHT_PX, 28);

    return {
      event,
      top,
      height,
      startMinutes,
      endMinutes: startMinutes + durationMinutes,
    };
  });

  return assignOverlapColumns(laidOut);
}

export function getDayAllDayEvents(events, dayMoment) {
  return getEventsForDay(events, dayMoment).filter((ev) => ev.allDay);
}

function assignOverlapColumns(items) {
  if (!items.length) return [];

  const sorted = items.slice().sort((a, b) => a.startMinutes - b.startMinutes);
  const active = [];
  const placed = [];

  sorted.forEach((item) => {
    for (let i = active.length - 1; i >= 0; i -= 1) {
      if (active[i].endMinutes <= item.startMinutes) active.splice(i, 1);
    }
    const used = new Set(active.map((a) => a.column));
    let column = 0;
    while (used.has(column)) column += 1;
    const entry = { ...item, column };
    active.push(entry);
    placed.push(entry);
  });

  placed.forEach((item) => {
    const overlapping = placed.filter(
      (other) =>
        other.startMinutes < item.endMinutes && other.endMinutes > item.startMinutes
    );
    item.columns = Math.max(...overlapping.map((o) => o.column + 1), 1);
  });

  return placed;
}

export function getNowIndicatorTop(dayMoment) {
  const now = dateUtils.getCurrentTime();
  if (!now.isSame(dayMoment, "day")) return null;
  const dayStart = dayMoment.clone().startOf("day");
  const minutes = now.diff(dayStart, "minutes");
  if (minutes < 0 || minutes > HOUR_END * 60) return null;
  return (minutes / 60) * HOUR_HEIGHT_PX;
}

export function formatShortTime(date) {
  return dateUtils.convertDateToMoment(date).format("h:mm a");
}

export function formatEventTimeShort(event) {
  if (event.allDay) return "All day";
  return formatEventTimeRange(event);
}
