import React, { Component } from "react";

import { validationUtils } from "_helpers";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import LuxCreateModeSwitch from "views/common/create/LuxCreateModeSwitch";
import LuxCreateWizardNav from "views/common/create/LuxCreateWizardNav";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import CreateEmployeeForm from "./CreateEmployeeForm";
import {
  CREATE_ENTRY_MODES,
  getWizardStepMandatoryFieldNames,
  isValidRequestForFieldNames,
  resolveWizardStepStatuses,
} from "views/common/create/createPanel.utils";
import { CREATE_EMPLOYEE_WIZARD_STEPS } from "./createEmployee.wizardSteps";

class CreateEmployeeSidebarSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
      enabledExitDateUpdateButton: false,
      entryMode: CREATE_ENTRY_MODES.WIZARD,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
    };
  }

  componentDidMount() {
    this.initializeRequest();
  }
  onResetFormError = () => {
    this.setState({
      hasFormError: false
    })
  }

  initializeRequest = () => {
    let userTeamId = commonUtils.getCurrentUserTeamId();
    let employeeRequest = this.props.editMode || this.props.readOnly ? { ...this.props.selectedEmployeeInfo } : { userTeamId: userTeamId }
    this.setState({
      employeeRequest: employeeRequest
    });
  }

  getSortedTeamNames = (teamDetails) => {
    if (!teamDetails || teamDetails.length === 0) return null;
    return [...teamDetails]
      .sort((a, b) => (a.name || "").localeCompare(b.name || "", undefined, { sensitivity: "base" }))
      .map((team) => team.name);
  }

  onFormError = (fieldName, hasError) => {
    this.setState(prevState => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError
      }
    }))
  }

  onChange = (fieldName, value) => {
    this.onResetFormError()
    if (fieldName === 'userTeamId') {
      store.dispatch(this.props.getModuleConfig(value));
      store.dispatch(this.props.getProjectTeamAccounts(value));
    }

    this.setState(prevState => ({
      employeeRequest: {
        ...prevState.employeeRequest,
        [fieldName]: value
      }
    }))

    if (fieldName === 'exitDate') {
      this.setState({
        enabledExitDateUpdateButton: true
      })
    }
  }

  onEffectiveDateDateChange = (selectedDate) => {
    this.onChange("effectiveDate", selectedDate);
  }
  handleSubmit = (isCreateAnotherEnabled) => {

    let isValid = validationUtils.isValidRequest(this.props.fieldConfig, this.state.employeeRequest, this.state.formErrors);
    //console.log("Validating form  request, isValid - " + isValid);
    //console.log(this.state.employeeRequest);
    //console.log(this.state.formErrors)
    if (isValid) {
      this.props.handleSubmit(this.state.employeeRequest, this.props.editMode, isCreateAnotherEnabled, !this.props.editMode ? this.initializeRequest : null);
    } else {
      this.setState({
        hasFormError: true
      })
    }
  }
  handleUpdateUserExitDate = () => {
    this.props.handleUpdateUserExitDate(this.state.employeeRequest.id, this.state.employeeRequest.exitDate);
  };

  isWizardMode = () => this.state.entryMode === CREATE_ENTRY_MODES.WIZARD;

  getWizardStep = () => CREATE_EMPLOYEE_WIZARD_STEPS[this.state.wizardStep];

  isSectionVisible = (sectionKey) => {
    if (!this.isWizardMode()) return true;
    const step = this.getWizardStep();
    return step && step.sections.includes(sectionKey);
  };

  markWizardStepVisited = (stepIndex) => {
    this.setState((prev) => {
      const visitedWizardSteps = new Set(prev.visitedWizardSteps);
      visitedWizardSteps.add(stepIndex);
      return { visitedWizardSteps };
    });
  };

  handleEntryModeChange = (entryMode) => {
    this.setState({
      entryMode,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
      hasFormError: false,
    });
  };

  handleWizardStepSelect = (wizardStep) => {
    this.markWizardStepVisited(wizardStep);
    this.setState({ wizardStep, hasFormError: false });
  };

  validateWizardStep = (stepIndex) => {
    const step = CREATE_EMPLOYEE_WIZARD_STEPS[stepIndex];
    if (!step) return true;
    const mandatoryNames = getWizardStepMandatoryFieldNames(
      this.props.fieldConfig,
      step.fieldNames
    );
    if (!mandatoryNames.length) return true;
    return isValidRequestForFieldNames(
      this.props.fieldConfig,
      this.state.employeeRequest,
      this.state.formErrors,
      mandatoryNames
    );
  };

  handleWizardNext = () => {
    if (!this.validateWizardStep(this.state.wizardStep)) {
      this.setState({ hasFormError: true });
      return;
    }
    const nextStep = Math.min(
      this.state.wizardStep + 1,
      CREATE_EMPLOYEE_WIZARD_STEPS.length - 1
    );
    this.markWizardStepVisited(this.state.wizardStep);
    this.markWizardStepVisited(nextStep);
    this.setState({
      wizardStep: nextStep,
      hasFormError: false,
    });
  };

  handleWizardBack = () => {
    const prevStep = Math.max(this.state.wizardStep - 1, 0);
    this.markWizardStepVisited(prevStep);
    this.setState({
      wizardStep: prevStep,
      hasFormError: false,
    });
  };

  getWizardStepStatuses = () =>
    resolveWizardStepStatuses({
      steps: CREATE_EMPLOYEE_WIZARD_STEPS,
      activeIndex: this.state.wizardStep,
      fieldConfig: this.props.fieldConfig,
      request: this.state.employeeRequest,
      formErrors: this.state.formErrors,
      visitedSteps: this.state.visitedWizardSteps,
      hasFormError: this.state.hasFormError,
    });

  renderToolbar = () => (
    <LuxCreateModeSwitch
      mode={this.state.entryMode}
      onChange={this.handleEntryModeChange}
      disabled={this.props.isProcessing}
    />
  );

  render() {
    const wizardMode = this.isWizardMode();
    const wizardStep = this.getWizardStep();
    const stepStatuses = wizardMode ? this.getWizardStepStatuses() : [];

    return (
      <>
        {this.state.employeeRequest && (
          <div className="lux-create-panel__workflow">
            <div className="lux-create-panel__chrome">{this.renderToolbar()}</div>

            <div
              className={
                wizardMode
                  ? "lux-create-panel__workspace lux-create-panel__workspace--wizard"
                  : "lux-create-panel__workspace"
              }
            >
              {wizardMode && (
                <LuxCreateWizardNav
                  stepStatuses={stepStatuses}
                  activeIndex={this.state.wizardStep}
                  onSelect={this.handleWizardStepSelect}
                  disabled={this.props.isProcessing}
                  layout="rail"
                />
              )}

              <div className="lux-create-panel__canvas">
                <div className="lux-create-panel__scroll">
                  <div className="lux-create-panel__form-grid lux-create-form">
                    <CreateEmployeeForm
                      employeeRequest={this.state.employeeRequest}
                      readOnly={this.props.readOnly}
                      editMode={this.props.editMode}
                      fieldConfig={this.props.fieldConfig}
                      createConfig={this.props.createConfig}
                      projectAppConfig={this.props.projectAppConfig}
                      allEmployees={this.props.allEmployees}
                      allSubRoles={this.props.allSubRoles}
                      allTeams={this.props.allTeams}
                      allProjectTeamAccounts={this.props.allProjectTeamAccounts}
                      onChange={this.onChange}
                      onFormError={this.onFormError}
                      permission={this.props.permission}
                      isPageView={this.props.isPageView}
                      enabledExitDateUpdateButton={this.state.enabledExitDateUpdateButton}
                      onUpdateExitDate={this.handleUpdateUserExitDate}
                      getSortedTeamNames={this.getSortedTeamNames}
                      isSectionVisible={this.isSectionVisible}
                    />
                  </div>
                </div>
              </div>
            </div>

            {!this.props.readOnly && (
              <LuxCreateFooter
                handleSubmit={this.handleSubmit}
                editMode={this.props.editMode}
                initializeRequest={this.initializeRequest}
                isProcessing={this.props.isProcessing}
                hasFormError={this.state.hasFormError}
                onResetFormError={this.onResetFormError}
                effectiveUpdateDateEnabled={true}
                onEffectiveDateDateChange={this.onEffectiveDateDateChange}
                mappingObject={this.state.employeeRequest}
                wizardMode={wizardMode}
                wizardStepIndex={this.state.wizardStep}
                wizardStepCount={CREATE_EMPLOYEE_WIZARD_STEPS.length}
                onWizardBack={this.handleWizardBack}
                onWizardNext={this.handleWizardNext}
                canWizardNext={wizardStep ? this.validateWizardStep(this.state.wizardStep) : true}
                createButtonLabel={this.props.editMode ? "Save changes" : "Create employee"}
              />
            )}
          </div>
        )}
      </>
    );
  }
}

export default CreateEmployeeSidebarSection;
