import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import { accessUtils } from "_helpers";
import classNames from "classnames/bind";

export const ProjectDetailViewNameConst = Object.freeze({
    GENERAL: Symbol("general"),
    DASHBOARD: Symbol("dashboard"),
    ACTIVITY: Symbol("activity"),
    CALENDAR: Symbol("calendar"),
    MEMBERS: Symbol("members"),
    NOTIFICATION: Symbol("notification"),
    FILES: Symbol("files"),
    FEEDBACK: Symbol("feedback"),
});

class ProjectDetailsHeader extends Component {
    isActive = (view) => this.props.activeView === view;

    renderNavButton = (view, label, icon) => (
        <button
            type="button"
            className={classNames("pd-nav__item", { "is-active": this.isActive(view) })}
            onClick={() => this.props.headerSelect(view)}
        >
            <i className={icon} />
            <span>{label}</span>
        </button>
    );

    render() {
        const item = this.props.projectInfo;
        const deliverablesEnabled = item && item.status !== "NEW" && item.status !== "ASSIGNED";
        const feedbackEnabled = accessUtils.getFeedbackRequestAccessControl().viewEnabled === true;

        return (
            <nav className="pd-nav" aria-label="Project sections">
                {this.renderNavButton(ProjectDetailViewNameConst.GENERAL, "Overview", "fe fe-grid")}
                {this.renderNavButton(ProjectDetailViewNameConst.DASHBOARD, "Dashboard", "fe fe-pie-chart")}
                {this.renderNavButton(ProjectDetailViewNameConst.ACTIVITY, "Activity", "fe fe-activity")}
                {this.renderNavButton(ProjectDetailViewNameConst.MEMBERS, "Team", "fe fe-users")}
                {this.renderNavButton(ProjectDetailViewNameConst.FILES, "Files", "fe fe-paperclip")}
                {this.renderNavButton(ProjectDetailViewNameConst.CALENDAR, "Calendar", "fe fe-calendar")}
                {this.renderNavButton(ProjectDetailViewNameConst.NOTIFICATION, "Alerts", "fe fe-bell")}
                {deliverablesEnabled ? (
                    <NavLink
                        to={`/project/deliverables/${item.itemIdUserTeamPrefix}`}
                        className="pd-nav__item pd-nav__item--link"
                    >
                        <i className="fe fe-layers" />
                        <span>Deliverables</span>
                    </NavLink>
                ) : (
                    <span className="pd-nav__item is-disabled" title="Available after project is assigned">
                        <i className="fe fe-layers" />
                        <span>Deliverables</span>
                    </span>
                )}
                {feedbackEnabled &&
                    this.renderNavButton(ProjectDetailViewNameConst.FEEDBACK, "Feedback", "fe fe-message-circle")
                }
            </nav>
        );
    }
}

export default ProjectDetailsHeader;
