import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AI_RECOMMENDATION_STATUSES } from "config/ai-work-intelligence.config";
import { formatConfidencePercent } from "config/ai-work-intelligence.utils";
import { canRunAgent } from "config/ai-work-intelligence-security.utils";
import { AiActionButton, AiConfidenceBadge } from "views/ai/components/AiLuxShared";

export default function AgentRegistryPanel({
  agents = [],
  recommendations = [],
  activePersona,
  selectedAgentId,
  onSelectAgent,
  onRunAgent,
  runningAgentId,
  loading,
}) {
  if (loading) {
    return <div className="lux-ai-intel-registry__skeleton" aria-busy="true" />;
  }

  if (!agents.length) {
    return (
      <div className="lux-ai-intel-registry__empty">
        <span className="lux-ai-intel-registry__empty-icon" aria-hidden="true">
          <i className="fe fe-cpu" />
        </span>
        <strong>No agents available</strong>
        <p>Enable AI work intelligence or adjust persona permissions to view the agent registry.</p>
      </div>
    );
  }

  const pendingByAgent = recommendations.reduce((acc, rec) => {
    if (rec.status === AI_RECOMMENDATION_STATUSES.DRAFT) {
      acc[rec.agentId] = (acc[rec.agentId] || 0) + 1;
    }
    return acc;
  }, {});

  return (
    <div className="lux-ai-intel-registry lux-ai-intel-registry--grid">
      {agents.map((agent) => {
        const canRun = canRunAgent(activePersona, agent);
        const pending = pendingByAgent[agent.id] || 0;
        const acceptance = Math.round((agent.acceptanceRate || 0) * (agent.acceptanceRate <= 1 ? 100 : 1));
        const tone = agent.tone || "violet";
        return (
          <article
            key={agent.id}
            className={classNames("lux-ai-intel-agent-card", `is-${tone}`, {
              "is-selected": selectedAgentId === agent.id,
            })}
          >
            <span className="lux-ai-intel-agent-card__glow" aria-hidden="true" />
            <header className="lux-ai-intel-agent-card__head">
              <span className="lux-ai-intel-agent-card__icon" aria-hidden="true">
                <i className={agent.icon || "fe fe-cpu"} />
              </span>
              <div className="lux-ai-intel-agent-card__titles">
                <strong>{agent.name}</strong>
                <small>{agent.module || agent.domain || "AI agent"}</small>
              </div>
              <span className={classNames("lux-ai-intel-status", `is-${agent.status}`)}>
                {agent.status}
              </span>
            </header>

            <p className="lux-ai-intel-agent-card__lede">{agent.description}</p>

            <div className="lux-ai-intel-agent-card__metric-grid">
              <div className="lux-ai-intel-agent-card__metric">
                <span>Acceptance</span>
                <strong>{acceptance}%</strong>
              </div>
              <div className="lux-ai-intel-agent-card__metric">
                <span>Runs</span>
                <strong>{agent.runCount || 0}</strong>
              </div>
              <div className={classNames("lux-ai-intel-agent-card__metric", pending > 0 && "is-alert")}>
                <span>Pending</span>
                <strong>{pending}</strong>
              </div>
            </div>

            {(agent.evidenceTemplates || []).length ? (
              <div className="lux-ai-intel-agent-card__evidence">
                {(agent.evidenceTemplates || []).slice(0, 3).map((label) => (
                  <span key={label} className="lux-ai-intel-chip is-violet">
                    {label}
                  </span>
                ))}
              </div>
            ) : null}

            <footer className="lux-ai-intel-agent-card__foot">
              <div className="lux-ai-intel-agent-card__confidence">
                <AiConfidenceBadge
                  band={{ tone: "success", label: "Model confidence" }}
                  confidence={agent.confidence || 0.8}
                />
                <span className="lux-ai-intel-agent-card__last-run">
                  {agent.lastRun || "No recent run"}
                </span>
              </div>
              <div className="lux-ai-intel-agent-card__actions">
                <AiActionButton
                  variant="primary"
                  disabled={!canRun || runningAgentId === agent.id}
                  onClick={() => onRunAgent(agent.id)}
                >
                  {runningAgentId === agent.id ? "Running…" : "Run agent"}
                </AiActionButton>
                <AiActionButton variant="ghost" onClick={() => onSelectAgent(agent.id)}>
                  View drafts
                </AiActionButton>
                {agent.route ? (
                  <Link to={agent.route} className="lux-onb-action lux-ai-intel-action lux-onb-action--ghost">
                    Open workspace
                  </Link>
                ) : null}
              </div>
            </footer>
          </article>
        );
      })}
    </div>
  );
}

export function AgentRunHistoryRegister({ runs = [], loading }) {
  if (loading) {
    return <div className="lux-ai-intel-register__skeleton" aria-busy="true" />;
  }
  if (!runs.length) {
    return (
      <div className="lux-ai-intel-register__empty-card">
        <i className="fe fe-clock" aria-hidden="true" />
        <strong>No agent runs yet</strong>
        <p>Run an agent from the registry to populate execution history.</p>
      </div>
    );
  }
  return (
    <div className="lux-ai-intel-register-wrap">
      <table className="lux-ai-intel-register">
        <thead>
          <tr>
            <th>Agent</th>
            <th>Summary</th>
            <th>Confidence</th>
            <th>Recs</th>
            <th>Triggered by</th>
            <th>When</th>
          </tr>
        </thead>
        <tbody>
          {runs.map((run) => (
            <tr key={run.id}>
              <td>
                <div className="lux-ai-intel-register__title">{run.agentName}</div>
                <div className="lux-ai-intel-register__meta">{run.status}</div>
              </td>
              <td>{run.summary}</td>
              <td>{formatConfidencePercent(run.confidence)}</td>
              <td>{run.recommendationCount}</td>
              <td>{run.triggeredBy}</td>
              <td>{run.startedAt ? new Date(run.startedAt).toLocaleString() : "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
