import {
  buildMyWorkQueueMetrics,
  buildNotificationMetrics,
  formatNotificationTimestamp,
  getMyWorkCategoryMeta,
  getNotificationTypeMeta,
} from "config/workspace.config";

export const HEADER_WORK_POPOVER_LIMIT = 8;
export const HEADER_NOTIFICATION_POPOVER_LIMIT = 8;

function priorityRank(priority) {
  return String(priority || "").toUpperCase() === "HIGH" ? 0 : 1;
}

export function sortMyWorkForHeader(items) {
  return [...(items || [])]
    .filter((row) => row.status === "OPEN")
    .sort((a, b) => {
      const pr = priorityRank(a.priority) - priorityRank(b.priority);
      if (pr !== 0) return pr;
      if (a.category === "APPROVAL" && b.category !== "APPROVAL") return -1;
      if (b.category === "APPROVAL" && a.category !== "APPROVAL") return 1;
      return String(a.title || "").localeCompare(String(b.title || ""));
    });
}

export function sortNotificationsForHeader(items) {
  return [...(items || [])]
    .filter((row) => row.status === "UNREAD")
    .sort((a, b) => {
      const pr = priorityRank(a.priority) - priorityRank(b.priority);
      if (pr !== 0) return pr;
      if (a.type === "APPROVAL" && b.type !== "APPROVAL") return -1;
      if (b.type === "APPROVAL" && a.type !== "APPROVAL") return 1;
      return new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime();
    });
}

export function buildHeaderWorkBadge(items) {
  const metrics = buildMyWorkQueueMetrics(items);
  return {
    count: metrics.open,
    urgent:
      metrics.highPriority > 0 ||
      (items || []).some((row) => row.status === "OPEN" && row.category === "APPROVAL"),
    approvalCount: (items || []).filter((row) => row.status === "OPEN" && row.category === "APPROVAL").length,
  };
}

export function buildHeaderNotificationBadge(items) {
  const metrics = buildNotificationMetrics(items);
  return {
    count: metrics.unread,
    urgent: metrics.highPriority > 0,
    approvalCount: (items || []).filter(
      (row) => row.status === "UNREAD" && row.type === "APPROVAL"
    ).length,
  };
}

export const HEADER_APPROVALS_PATH = "/workspace/approvals";

export function resolveHeaderNavigationPath(item, { isWork = false } = {}) {
  if (!item) {
    return isWork ? "/workspace/my-work" : "/workspace/notifications";
  }
  if (item.isApproval || (isWork ? item.category === "APPROVAL" : item.type === "APPROVAL")) {
    return HEADER_APPROVALS_PATH;
  }
  return item.path || (isWork ? "/workspace/my-work" : "/workspace/notifications");
}

export function mapMyWorkToHeaderItem(item) {
  const categoryMeta = getMyWorkCategoryMeta(item.category);
  const isHigh = String(item.priority).toUpperCase() === "HIGH";
  const isApproval = item.category === "APPROVAL";
  return {
    id: item.id,
    title: item.title,
    hint: item.subtitle || item.dueLabel || categoryMeta.label,
    meta: isHigh ? "High priority" : item.dueLabel || null,
    icon: item.icon || categoryMeta.icon,
    iconTone: isHigh || isApproval ? "danger" : categoryMeta.tone,
    urgent: isHigh || isApproval,
    isApproval,
    path: resolveHeaderNavigationPath({ ...item, isApproval }, { isWork: true }),
  };
}

export function mapNotificationToHeaderItem(row) {
  const typeMeta = getNotificationTypeMeta(row.type);
  const isHigh = String(row.priority).toUpperCase() === "HIGH";
  const isApproval = row.type === "APPROVAL";
  return {
    id: row.id,
    title: row.title,
    hint: row.body || row.actorName || typeMeta.label,
    meta: formatNotificationTimestamp(row.createdAt),
    icon: row.icon || typeMeta.icon,
    iconTone: isHigh || isApproval ? "danger" : row.tone || typeMeta.tone,
    urgent: isHigh || (isApproval && row.status === "UNREAD"),
    isApproval,
    path: resolveHeaderNavigationPath({ ...row, isApproval }),
    raw: row,
  };
}
