import React from "react";
import { Redirect } from "react-router-dom";
import { commonUtils } from "_helpers";

/**
 * Redirects legacy /people/employees/360 menu entry to the current user's 360 view.
 */
function Employee360LauncherPage() {
  const employeeId = commonUtils.getCurrentUserId();
  if (!employeeId) {
    return <Redirect to="/people/employees" />;
  }
  return <Redirect to={`/people/employees/${employeeId}/360`} />;
}

export default Employee360LauncherPage;
