import React from "react";
import moment from "moment";
import PayrollLuxDrawerShell from "views/payroll/components/PayrollLuxDrawerShell";
import {
  PayrollDrawerBanner,
  PayrollDrawerCard,
  PayrollDrawerField,
  PayrollDrawerGroupPicker,
  PayrollDrawerMeta,
  PayrollDrawerStatStrip,
  PayrollDrawerStepRail,
} from "views/payroll/components/PayrollLuxDrawerShared";
import { PayrollActionButton, PayrollLifecycleStepper, PayrollStatusBadge } from "views/payroll/components/PayrollLuxShared";
import { formatPayrollDate } from "config/payroll.utils";

const DEFAULT_FORM = {
  name: "",
  groupId: "",
  periodStart: "",
  periodEnd: "",
  payDate: "",
};

const WIZARD_STEPS = [
  { id: "identity", label: "Run setup", hint: "Name & cohort" },
  { id: "period", label: "Pay period", hint: "Window & pay date" },
  { id: "review", label: "Review", hint: "Create draft" },
];

const DRAWER_LINKS = [
  { to: "/payroll/groups", label: "Payroll groups", hint: "Frequency & lock windows", icon: "fe fe-users" },
  { to: "/admin/payroll-config", label: "Payroll config", hint: "Readiness checklist", icon: "fe fe-sliders" },
];

function buildRunDefaultsFromGroup(group) {
  if (!group) {
    return {};
  }
  const start = moment().startOf("month");
  const end = moment().endOf("month");
  return {
    name: `${group.name} — ${start.format("MMM YYYY")}`,
    periodStart: start.format("YYYY-MM-DD"),
    periodEnd: end.format("YYYY-MM-DD"),
    payDate: group.nextPayDate
      ? moment(group.nextPayDate).format("YYYY-MM-DD")
      : end.clone().add(3, "days").format("YYYY-MM-DD"),
  };
}

function getActiveStep(form) {
  if (!form.groupId || !form.name.trim()) {
    return "identity";
  }
  if (!form.periodStart || !form.periodEnd || !form.payDate) {
    return "period";
  }
  return "review";
}

function countPeriodDays(form) {
  if (!form.periodStart || !form.periodEnd) {
    return null;
  }
  const start = moment(form.periodStart);
  const end = moment(form.periodEnd);
  if (!start.isValid() || !end.isValid() || end.isBefore(start)) {
    return null;
  }
  return end.diff(start, "days") + 1;
}

export default class PayrollRunWizardDrawer extends React.Component {
  state = {
    form: { ...DEFAULT_FORM },
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ form: { ...DEFAULT_FORM }, saving: false, error: null });
    }
  }

  handleChange = (field) => (event) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: event.target.value },
      error: null,
    }));
  };

  handleGroupSelect = (groupId) => {
    const { groups } = this.props;
    const group = (groups || []).find((row) => row.id === groupId);
    const defaults = buildRunDefaultsFromGroup(group);

    this.setState((prev) => ({
      form: {
        ...prev.form,
        groupId,
        name: prev.form.name.trim() ? prev.form.name : defaults.name || prev.form.name,
        periodStart: prev.form.periodStart || defaults.periodStart || "",
        periodEnd: prev.form.periodEnd || defaults.periodEnd || "",
        payDate: prev.form.payDate || defaults.payDate || "",
      },
      error: null,
    }));
  };

  handleSubmit = async (event) => {
    event.preventDefault();
    const { form } = this.state;
    const { groups, onSubmit } = this.props;
    if (!form.name.trim() || !form.groupId) {
      this.setState({ error: "Run name and payroll group are required." });
      return;
    }
    if (!form.periodStart || !form.periodEnd || !form.payDate) {
      this.setState({ error: "Period start, period end, and pay date are required." });
      return;
    }
    const group = (groups || []).find((row) => row.id === form.groupId);
    this.setState({ saving: true, error: null });
    try {
      await onSubmit({
        ...form,
        groupName: group ? group.name : "",
      });
      this.props.onClose();
    } catch (e) {
      this.setState({ saving: false, error: "Unable to create payroll run." });
    }
  };

  render() {
    const { open, onClose, groups } = this.props;
    const { form, saving, error } = this.state;
    if (!open) {
      return null;
    }

    const selectedGroup = (groups || []).find((row) => row.id === form.groupId);
    const activeStep = getActiveStep(form);
    const periodDays = countPeriodDays(form);
    const stats = selectedGroup
      ? [
          { label: "Employees", value: selectedGroup.employeeCount || 0, hint: "In payroll group", tone: "green" },
          { label: "Frequency", value: selectedGroup.payFrequency || "—", hint: selectedGroup.currency || "Currency", tone: "blue" },
          {
            label: "Next pay",
            value: selectedGroup.nextPayDate ? formatPayrollDate(selectedGroup.nextPayDate) : "—",
            hint: selectedGroup.currentPeriod || "Current period",
            tone: "amber",
          },
        ]
      : [];

    const footer = (
      <>
        <PayrollActionButton variant="ghost" onClick={onClose} disabled={saving}>
          Cancel
        </PayrollActionButton>
        <PayrollActionButton type="submit" form="payroll-run-wizard-form" variant="primary" disabled={saving}>
          {saving ? "Creating…" : "Create draft run"}
        </PayrollActionButton>
      </>
    );

    return (
      <PayrollLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="green"
        wide
        icon="fe-play-circle"
        eyebrow="Payroll run wizard"
        title="New payroll run"
        subtitle="Define the cohort, pay window, and pay date. The run starts in Draft — calculate and approve from the run detail page."
        badges={
          <>
            <PayrollStatusBadge status="Draft" />
            <span>Canonical source: PayrollRunModel</span>
          </>
        }
        quickLinks={DRAWER_LINKS}
        footer={footer}
      >
        <form id="payroll-run-wizard-form" onSubmit={this.handleSubmit}>
          <PayrollDrawerStepRail steps={WIZARD_STEPS} activeStep={activeStep} />

          {error && (
            <div className="lux-employee-360__error" role="alert">
              {error}
            </div>
          )}

          <PayrollDrawerBanner icon="fe-shield" tone="info">
            Draft runs do not post paychecks. After creation, run readiness validation, calculation, approval, and lock
            from the payroll run workspace.
          </PayrollDrawerBanner>

          <PayrollDrawerCard title="Run identity" subtitle="Choose the payroll cohort and a recognizable run label">
            <PayrollDrawerField label="Run name" hint="Shown in the register, approvals, and audit trail">
              <input
                type="text"
                value={form.name}
                onChange={this.handleChange("name")}
                placeholder="e.g. US Monthly — Jun 2026"
                required
                data-testid="payroll-run-name"
              />
            </PayrollDrawerField>

            <PayrollDrawerField label="Payroll group" hint="Employee cohort, frequency, and lock rules">
              <PayrollDrawerGroupPicker groups={groups} value={form.groupId} onChange={this.handleGroupSelect} />
            </PayrollDrawerField>
          </PayrollDrawerCard>

          {selectedGroup ? <PayrollDrawerStatStrip stats={stats} /> : null}

          <PayrollDrawerCard title="Pay period" subtitle="Align dates with the group’s current period and statutory pay day">
            <div className="lux-payroll-drawer__date-grid">
              <PayrollDrawerField label="Period start">
                <input type="date" value={form.periodStart} onChange={this.handleChange("periodStart")} required />
              </PayrollDrawerField>
              <PayrollDrawerField label="Period end">
                <input type="date" value={form.periodEnd} onChange={this.handleChange("periodEnd")} required />
              </PayrollDrawerField>
              <PayrollDrawerField label="Pay date" hint="Funds release / payslip date">
                <input type="date" value={form.payDate} onChange={this.handleChange("payDate")} required />
              </PayrollDrawerField>
            </div>
            {periodDays != null && (
              <PayrollDrawerBanner icon="fe-calendar" tone="success">
                {periodDays} day pay window · Pay date {formatPayrollDate(form.payDate)}
              </PayrollDrawerBanner>
            )}
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Lifecycle preview" subtitle="After creation the run follows the standard payroll pipeline" className="is-review">
            <PayrollLifecycleStepper status="Draft" />
            <PayrollDrawerMeta
              items={[
                { label: "Run name", value: form.name.trim() || "—" },
                { label: "Group", value: selectedGroup ? selectedGroup.name : "—" },
                { label: "Period", value: form.periodStart && form.periodEnd ? `${formatPayrollDate(form.periodStart)} → ${formatPayrollDate(form.periodEnd)}` : "—" },
                { label: "Initial status", value: "Draft" },
              ]}
            />
          </PayrollDrawerCard>
        </form>
      </PayrollLuxDrawerShell>
    );
  }
}
