import React, { useEffect } from "react";
import { Link, withRouter } from "react-router-dom";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { GovernanceKpiStrip } from "views/project/components/ProjectGovernanceLuxShared";
import {
  KNOWLEDGE_MODULE_NAV,
  getKnowledgeModuleNavActiveId,
} from "config/knowledge-rca-nav.config";

function KnowledgeModuleNav({ activeId }) {
  return (
    <LuxSegmentNav
      items={KNOWLEDGE_MODULE_NAV}
      activeId={activeId}
      ariaLabel="Knowledge and RCA modules"
      testId="knowledge-module-nav"
    />
  );
}

function KnowledgeLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo knowledge data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  pageHeaderNameChangeHandler,
  shellTitle,
  location,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "violet",
    icon: "fe fe-book-open",
    eyebrow: "Learning",
    titleLead: "Knowledge",
    titleAccent: "& RCA",
    lede: "Lessons, root causes, and institutional memory.",
  };
  const activeNavId = getKnowledgeModuleNavActiveId((location && location.pathname) || "");

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div className={classNames("lux-register-page", "lux-krca-module", "lux-krca-lux", meta.tone && `is-${meta.tone}`)}>
      <div className="lux-krca-lux__ambient" aria-hidden="true">
        <span className="lux-krca-lux__orb lux-krca-lux__orb--a" />
        <span className="lux-krca-lux__orb lux-krca-lux__orb--b" />
        <span className="lux-krca-lux__orb lux-krca-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={<KnowledgeModuleNav activeId={activeNavId} />}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-krca-lux__kpi-strip" />
        ) : null}

        <div className="lux-krca-lux__content">{children}</div>
      </div>
    </div>
  );
}

export default withRouter(KnowledgeLuxPage);

export function KnowledgeActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-krca-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function KnowledgeLuxPanel({ title, meta, icon, accent, actions, children, featured, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-krca-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-krca-lux__panel--featured",
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-krca-lux__panel-head">
        <div className="lux-krca-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-krca-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-krca-lux__panel-body">{children}</div>
    </section>
  );
}

export function KnowledgeInsightPanel({ insights, loading }) {
  return <AdminInsightStrip insights={insights} loading={loading} className="lux-krca-lux__insights" />;
}

export function LessonStatusBadge({ status }) {
  const label = status === "in_review" ? "In review" : status;
  return <span className={classNames("lux-krca-badge", `lux-krca-badge--${status || "draft"}`)}>{label}</span>;
}

export function RcaStatusBadge({ status }) {
  const label = status === "in_review" ? "In review" : status;
  return <span className={classNames("lux-krca-badge", "lux-krca-badge--rca", `lux-krca-badge--${status || "draft"}`)}>{label}</span>;
}
