import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { accessUtils } from "_helpers";
import { isPayrollManagementEnabled } from "config/payroll.config";
import { normalizeDeductionSchedule } from "config/employee-finance.config";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

const EMPTY_FORM = {
  employeeId: "",
  employeeName: "",
  label: "",
  amountUsd: "",
  frequency: "Monthly",
  remainingInstallments: "",
  nextDeductionDate: "",
};

class DeductionsPage extends Component {
  state = {
    deductions: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    showForm: false,
    editingId: null,
    form: { ...EMPTY_FORM },
    saving: false,
    saveError: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Deductions");
    this.loadDeductions();
  }

  loadDeductions = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.listDeductions();
      this.setState({
        deductions: (result.payload || []).map((row) => normalizeDeductionSchedule(row)).filter(Boolean),
        loading: false,
        dataSource: result.source,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load deduction schedules.", deductions: [] });
    }
  };

  openCreateForm = () => {
    this.setState({ showForm: true, editingId: null, form: { ...EMPTY_FORM }, saveError: null });
  };

  openEditForm = (row) => {
    this.setState({
      showForm: true,
      editingId: row.id,
      saveError: null,
      form: {
        employeeId: row.employeeId || "",
        employeeName: row.employeeName || "",
        label: row.label || "",
        amountUsd: row.amountUsd != null ? String(row.amountUsd) : "",
        frequency: row.frequency || "Monthly",
        remainingInstallments: row.remainingInstallments != null ? String(row.remainingInstallments) : "",
        nextDeductionDate: row.nextDeductionDate || "",
      },
    });
  };

  closeForm = () => {
    this.setState({ showForm: false, editingId: null, form: { ...EMPTY_FORM }, saveError: null });
  };

  onFormChange = (field) => (event) => {
    this.setState((prev) => ({ form: { ...prev.form, [field]: event.target.value } }));
  };

  buildPayload = () => {
    const { form } = this.state;
    const payload = {
      employeeId: form.employeeId.trim(),
      employeeName: form.employeeName.trim(),
      label: form.label.trim(),
      frequency: form.frequency.trim() || "Monthly",
      status: "ACTIVE",
    };
    if (form.amountUsd !== "") {
      payload.amountUsd = Number(form.amountUsd);
    }
    if (form.remainingInstallments !== "") {
      payload.remainingInstallments = Number(form.remainingInstallments);
    }
    if (form.nextDeductionDate.trim()) {
      payload.nextDeductionDate = form.nextDeductionDate.trim();
    }
    return payload;
  };

  handleSave = async () => {
    const { editingId } = this.state;
    const payload = this.buildPayload();
    if (!payload.employeeId || !payload.label) {
      this.setState({ saveError: "Employee ID and label are required." });
      return;
    }
    this.setState({ saving: true, saveError: null });
    try {
      if (editingId) {
        await payrollService.updateDeduction(editingId, payload);
      } else {
        await payrollService.createDeduction(payload);
      }
      this.closeForm();
      await this.loadDeductions();
    } catch (e) {
      this.setState({ saving: false, saveError: "Unable to save deduction schedule." });
      return;
    }
    this.setState({ saving: false });
  };

  getFiltered = () => {
    const q = this.state.query.trim().toLowerCase();
    if (!q) return this.state.deductions;
    return this.state.deductions.filter((row) =>
      [row.employeeName, row.label, row.id].filter(Boolean).join(" ").toLowerCase().includes(q)
    );
  };

  render() {
    const permission = accessUtils.getAccessControll("payrollModules") || {};
    if (!isPayrollManagementEnabled() || permission.deductionsEnabled === false) {
      return <PersonaAccessDenied moduleName="Deductions" reason="Payroll deductions are not enabled." />;
    }

    const filtered = this.getFiltered();
    const active = filtered.filter((row) => (row.remainingInstallments || 0) > 0);
    const kpiCards = [
      { id: "total", label: "Schedules", value: filtered.length, hint: "Employee deduction rows", tone: "primary", icon: "fe fe-minus-circle" },
      { id: "active", label: "Active", value: active.length, hint: "Remaining installments", tone: "green", icon: "fe fe-activity" },
    ];

    return (
      <PayrollLuxPage
        testId="page-payroll-deductions"
        dataSource={this.state.dataSource}
        pageMeta={DENSE_PAGE_META.deductions}
        loading={this.state.loading}
        kpiCards={kpiCards}
        onRefresh={this.loadDeductions}
        refreshLoading={this.state.loading}
        heroActions={<><PayrollActionButton to="/payroll/employee-finance" icon="fe fe-briefcase" variant="ghost">
              Employee finance
            </PayrollActionButton>
          </>}
      >
        {this.state.loadError && <div className="lux-employee-360__error" role="alert">{this.state.loadError}</div>}

        {this.state.showForm && (
          <section className="lux-hrms-dash__panel lux-payroll-panel mb-3" data-testid="deduction-form-panel">
            <PayrollPanelHead
              title={this.state.editingId ? "Edit deduction" : "New deduction"}
              subtitle="Writes to ts_employee_deduction_model via payroll API"
            />
            <div className="lux-hrms-dash__panel-body">
              {this.state.saveError && <div className="lux-employee-360__error mb-2" role="alert">{this.state.saveError}</div>}
              <div className="row">
                <div className="col-md-4 mb-2">
                  <label className="form-label">Employee ID</label>
                  <input className="form-control" value={this.state.form.employeeId} onChange={this.onFormChange("employeeId")} />
                </div>
                <div className="col-md-4 mb-2">
                  <label className="form-label">Employee name</label>
                  <input className="form-control" value={this.state.form.employeeName} onChange={this.onFormChange("employeeName")} />
                </div>
                <div className="col-md-4 mb-2">
                  <label className="form-label">Label</label>
                  <input className="form-control" value={this.state.form.label} onChange={this.onFormChange("label")} />
                </div>
                <div className="col-md-3 mb-2">
                  <label className="form-label">Amount (USD)</label>
                  <input type="number" className="form-control" value={this.state.form.amountUsd} onChange={this.onFormChange("amountUsd")} />
                </div>
                <div className="col-md-3 mb-2">
                  <label className="form-label">Frequency</label>
                  <input className="form-control" value={this.state.form.frequency} onChange={this.onFormChange("frequency")} />
                </div>
                <div className="col-md-3 mb-2">
                  <label className="form-label">Remaining installments</label>
                  <input type="number" className="form-control" value={this.state.form.remainingInstallments} onChange={this.onFormChange("remainingInstallments")} />
                </div>
                <div className="col-md-3 mb-2">
                  <label className="form-label">Next deduction date</label>
                  <input type="date" className="form-control" value={this.state.form.nextDeductionDate} onChange={this.onFormChange("nextDeductionDate")} />
                </div>
              </div>
              <div className="lux-admin-toolbar mt-2">
                <PayrollActionButton icon="fe fe-check" variant="primary" onClick={this.handleSave} disabled={this.state.saving}>
                  {this.state.saving ? "Saving…" : "Save"}
                </PayrollActionButton>
                <PayrollActionButton icon="fe fe-x" onClick={this.closeForm}>Cancel</PayrollActionButton>
              </div>
            </div>
          </section>
        )}

        <section className="lux-hrms-dash__panel lux-payroll-panel mb-3">
          <PayrollPanelHead
            title="Manage deductions"
            subtitle="Create schedules here or in Employee finance — payroll runs consume the same source"
          />
          <div className="lux-hrms-dash__panel-body">
            <div className="lux-admin-toolbar">
              <PayrollActionButton icon="fe fe-plus" variant="primary" onClick={this.openCreateForm}>Add deduction</PayrollActionButton>
              <PayrollActionButton to="/payroll/employee-finance" icon="fe fe-briefcase">Open employee finance</PayrollActionButton>
              <PayrollActionButton to="/payroll/runs" icon="fe fe-play">Payroll run preview</PayrollActionButton>
            </div>
          </div>
        </section>

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead title="Deduction register" subtitle="ts_employee_deduction_model child records — not isolated payroll truth" />
          <div className="lux-admin-toolbar">
            <input
              type="search"
              className="form-control"
              placeholder="Search employee or deduction label"
              value={this.state.query}
              onChange={(e) => this.setState({ query: e.target.value })}
            />
          </div>
          <div className="lux-hrms-dash__panel-body">
            {this.state.loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading" description="Fetching deduction schedules." />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState icon="fe fe-minus-circle" title="No deductions" description="No active deduction schedules for this org." />
            ) : (
              <div className="table-responsive">
                <table className="table table-hover">
                  <thead>
                    <tr>
                      <th>Employee</th>
                      <th>Label</th>
                      <th>Amount</th>
                      <th>Frequency</th>
                      <th>Remaining</th>
                      <th>Next date</th>
                      <th />
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((row) => (
                      <tr key={row.id || `${row.employeeId}-${row.label}`}>
                        <td>
                          {row.employeeId ? (
                            <Link to={`/payroll/employee-finance?employeeId=${encodeURIComponent(row.employeeId)}`}>
                              {row.employeeName || row.employeeId}
                            </Link>
                          ) : (
                            row.employeeName || "—"
                          )}
                        </td>
                        <td>{row.label}</td>
                        <td>{row.amountUsd != null ? `$${row.amountUsd}` : "—"}</td>
                        <td>{row.frequency || "—"}</td>
                        <td>{row.remainingInstallments != null ? row.remainingInstallments : "—"}</td>
                        <td>{row.nextDeductionDate || "—"}</td>
                        <td>
                          {row.id && (
                            <PayrollActionButton
                              variant="ghost"
                              className="lux-onb-action--sm"
                              onClick={() => this.openEditForm(row)}
                            >
                              Edit
                            </PayrollActionButton>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default DeductionsPage;
