import {
  ADVANCE_STATUSES,
  BENEFIT_PLAN_STATUSES,
  COMPENSATION_CHANGE_STATUSES,
  LOAN_STATUSES,
  normalizeBenefitEnrollment,
  normalizeBenefitPlan,
  normalizeCompensationChange,
  normalizeDeductionSchedule,
  normalizeEmployeeAdvance,
  normalizeEmployeeFinanceProfile,
  normalizeEmployeeLoan,
} from "config/employee-finance.config";
import { maskEmployeeFinanceProfiles } from "config/employee-finance-security.utils";

export function filterBenefitPlans(rows = [], filters = {}) {
  let next = [...rows];
  if (filters.status && filters.status !== "ALL") {
    next = next.filter((row) => row.status === filters.status);
  }
  if (filters.category && filters.category !== "ALL") {
    next = next.filter((row) => row.category === filters.category);
  }
  if (filters.query) {
    const q = String(filters.query).toLowerCase();
    next = next.filter(
      (row) =>
        (row.name || "").toLowerCase().includes(q) ||
        (row.code || "").toLowerCase().includes(q) ||
        (row.provider || "").toLowerCase().includes(q)
    );
  }
  return next.map((row) => normalizeBenefitPlan(row)).filter(Boolean);
}

export function filterCompensationChanges(rows = [], filters = {}) {
  let next = [...rows];
  if (filters.status && filters.status !== "ALL") {
    next = next.filter((row) => row.status === filters.status);
  }
  if (filters.changeType && filters.changeType !== "ALL") {
    next = next.filter((row) => row.changeType === filters.changeType);
  }
  if (filters.query) {
    const q = String(filters.query).toLowerCase();
    next = next.filter(
      (row) =>
        (row.employeeName || "").toLowerCase().includes(q) ||
        (row.department || "").toLowerCase().includes(q)
    );
  }
  return next.map((row) => normalizeCompensationChange(row)).filter(Boolean);
}

export function filterEmployeeFinanceProfiles(rows = [], filters = {}) {
  let next = [...rows];
  if (filters.query) {
    const q = String(filters.query).toLowerCase();
    next = next.filter(
      (row) =>
        (row.employeeName || "").toLowerCase().includes(q) ||
        (row.department || "").toLowerCase().includes(q) ||
        (row.costCenter || "").toLowerCase().includes(q)
    );
  }
  if (filters.hasOpenBalance) {
    next = next.filter((row) => (row.openAdvanceUsd || 0) > 0 || (row.openLoanUsd || 0) > 0);
  }
  return next.map((row) => normalizeEmployeeFinanceProfile(row)).filter(Boolean);
}

export function buildBenefitsOverview(plans = [], enrollments = [], options = {}) {
  const rows = filterBenefitPlans(plans, options.filters || {});
  const activePlans = rows.filter((row) => row.status === BENEFIT_PLAN_STATUSES.ACTIVE);
  const totalEnrolled = enrollments.filter((row) => row.status === "ENROLLED").length;
  const employerSpend = activePlans.reduce((sum, row) => sum + (row.employerContributionUsd || 0) * (row.enrolledCount || 0), 0);

  return {
    plans: rows,
    enrollments: enrollments.map((row) => normalizeBenefitEnrollment(row)).filter(Boolean),
    kpiCards: [
      { id: "plans", label: "Active plans", value: String(activePlans.length), hint: "Benefit catalog", icon: "fe fe-heart", tone: "green" },
      { id: "enrolled", label: "Enrollments", value: String(totalEnrolled), hint: "Employees covered", icon: "fe fe-users", tone: "blue" },
      { id: "employer", label: "Employer contrib.", value: `$${employerSpend.toLocaleString()}`, hint: "Monthly modeled", icon: "fe fe-dollar-sign", tone: "indigo" },
      { id: "draft", label: "Draft plans", value: String(rows.filter((row) => row.status === BENEFIT_PLAN_STATUSES.DRAFT).length), hint: "Pending launch", icon: "fe fe-edit", tone: "amber" },
    ],
    insights: buildBenefitsInsights(rows, enrollments),
  };
}

export function buildCompensationOverview(changes = [], options = {}) {
  const rows = filterCompensationChanges(changes, options.filters || {});
  const pending = rows.filter((row) => row.status === COMPENSATION_CHANGE_STATUSES.PENDING_APPROVAL);
  const effective = rows.filter((row) =>
    [COMPENSATION_CHANGE_STATUSES.APPROVED, COMPENSATION_CHANGE_STATUSES.EFFECTIVE].includes(row.status)
  );

  return {
    changes: rows,
    kpiCards: [
      { id: "pending", label: "Pending approval", value: String(pending.length), hint: "Needs HR/payroll action", icon: "fe fe-clock", tone: "amber" },
      { id: "effective", label: "Effective changes", value: String(effective.length), hint: "Approved or live", icon: "fe fe-check-circle", tone: "green" },
      { id: "merit", label: "Merit cycle", value: String(rows.filter((row) => row.changeType === "MERIT").length), hint: "In current scope", icon: "fe fe-trending-up", tone: "indigo" },
      { id: "promo", label: "Promotions", value: String(rows.filter((row) => row.changeType === "PROMOTION").length), hint: "Title or band moves", icon: "fe fe-award", tone: "violet" },
    ],
    insights: buildCompensationInsights(rows),
  };
}

export function buildEmployeeFinanceOverview(
  profiles = [],
  advances = [],
  loans = [],
  deductions = [],
  options = {}
) {
  const filtered = filterEmployeeFinanceProfiles(profiles, options.filters || {});
  const rows = maskEmployeeFinanceProfiles(filtered, options.viewerPersona || "ADMIN");
  const openAdvances = advances.filter((row) => row.status === ADVANCE_STATUSES.APPROVED || row.status === ADVANCE_STATUSES.PENDING);
  const activeLoans = loans.filter((row) => row.status === LOAN_STATUSES.ACTIVE);
  const avgMargin =
    rows.filter((row) => row.marginPct != null).reduce((sum, row) => sum + row.marginPct, 0) /
    Math.max(1, rows.filter((row) => row.marginPct != null).length);
  const allocations = options.costAllocations || [];

  return {
    profiles: rows,
    advances: advances.map((row) => normalizeEmployeeAdvance(row)).filter(Boolean),
    loans: loans.map((row) => normalizeEmployeeLoan(row)).filter(Boolean),
    deductions: deductions.map((row) => normalizeDeductionSchedule(row)).filter(Boolean),
    kpiCards: [
      { id: "profiles", label: "Finance profiles", value: String(rows.length), hint: "Employees in scope", icon: "fe fe-users", tone: "violet" },
      { id: "advances", label: "Open advances", value: String(openAdvances.length), hint: "Pending or approved", icon: "fe fe-credit-card", tone: "amber" },
      { id: "loans", label: "Active loans", value: String(activeLoans.length), hint: "Repayment schedules", icon: "fe fe-layers", tone: "blue" },
      { id: "margin", label: "Avg margin", value: `${Math.round(avgMargin)}%`, hint: "Billable cost signal", icon: "fe fe-pie-chart", tone: "green" },
    ],
    insights: buildEmployeeFinanceInsights(rows, openAdvances, activeLoans),
    marginSeries: buildMarginSeries(rows),
    costToRevenue: buildCostToRevenueAnalytics(allocations, rows),
    marginRiskFlags: buildMarginRiskFlags(rows, allocations),
  };
}

export function buildCostToRevenueAnalytics(allocations = [], profiles = []) {
  const projectMap = new Map();
  allocations.forEach((row) => {
    const key = row.projectId || row.projectName;
    const existing = projectMap.get(key) || {
      projectId: row.projectId,
      projectName: row.projectName,
      billableRevenueUsd: 0,
      loadedCostUsd: 0,
      allocatedHours: 0,
      employeeCount: new Set(),
    };
    existing.billableRevenueUsd += row.billableRevenueUsd || 0;
    existing.loadedCostUsd += row.loadedCostUsd || 0;
    existing.allocatedHours += row.allocatedHours || 0;
    existing.employeeCount.add(row.employeeId);
    projectMap.set(key, existing);
  });

  const projects = [...projectMap.values()].map((row) => {
    const marginPct =
      row.billableRevenueUsd > 0
        ? Math.round(((row.billableRevenueUsd - row.loadedCostUsd) / row.billableRevenueUsd) * 100)
        : null;
    return {
      projectId: row.projectId,
      projectName: row.projectName,
      billableRevenueUsd: row.billableRevenueUsd,
      loadedCostUsd: row.loadedCostUsd,
      allocatedHours: row.allocatedHours,
      employeeCount: row.employeeCount.size,
      marginPct,
    };
  });

  const totalRevenue = projects.reduce((sum, row) => sum + row.billableRevenueUsd, 0);
  const totalCost = projects.reduce((sum, row) => sum + row.loadedCostUsd, 0);
  const portfolioMargin = totalRevenue > 0 ? Math.round(((totalRevenue - totalCost) / totalRevenue) * 100) : null;

  return {
    projects: projects.sort((a, b) => (a.marginPct || 0) - (b.marginPct || 0)),
    summary: {
      totalRevenueUsd: totalRevenue,
      totalCostUsd: totalCost,
      portfolioMarginPct: portfolioMargin,
      employeeProfiles: profiles.length,
      projectCount: projects.length,
    },
  };
}

export function buildMarginRiskFlags(profiles = [], allocations = []) {
  const flags = [];
  profiles
    .filter((row) => row.marginPct != null && row.marginPct < 20)
    .forEach((row) => {
      const projectHits = allocations.filter((alloc) => alloc.employeeId === row.employeeId);
      const worstProject = projectHits.sort((a, b) => (a.marginPct || 0) - (b.marginPct || 0))[0];
      flags.push({
        id: `margin-${row.employeeId}`,
        employeeId: row.employeeId,
        employeeName: row.employeeName,
        marginPct: row.marginPct,
        severity: row.marginPct < 15 ? "HIGH" : "MEDIUM",
        confidencePct: row.marginPct < 15 ? 92 : 78,
        riskType: "MARGIN_COMPRESSION",
        recommendation: worstProject
          ? `Review ${worstProject.projectName} staffing mix — loaded cost is eroding billable margin.`
          : "Reconcile billing and loaded cost rates before the next project financial lock.",
        evidence: worstProject
          ? `${worstProject.allocatedHours}h allocated · ${worstProject.marginPct}% project margin`
          : `Employee margin at ${row.marginPct}% vs 20% threshold`,
        projectName: worstProject ? worstProject.projectName : null,
        flaggedAt: row.updatedAt || new Date().toISOString().slice(0, 10),
      });
    });
  return flags;
}

function buildBenefitsInsights(plans, enrollments) {
  const insights = [];
  const sunset = plans.filter((row) => row.status === BENEFIT_PLAN_STATUSES.SUNSET);
  if (sunset.length) {
    insights.push({
      id: "sunset",
      tone: "amber",
      icon: "fe fe-alert-circle",
      title: `${sunset.length} plan${sunset.length === 1 ? "" : "s"} sunsetting`,
      copy: "Review enrollment migrations before effective end dates.",
      path: "/payroll/benefits",
    });
  }
  const pending = enrollments.filter((row) => row.status === "PENDING");
  if (pending.length) {
    insights.push({
      id: "pending-enroll",
      tone: "blue",
      icon: "fe fe-inbox",
      title: `${pending.length} enrollment${pending.length === 1 ? "" : "s"} pending`,
      copy: "Confirm coverage tiers and effective dates with employees.",
      path: "/payroll/benefits",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Benefits catalog stable",
      copy: "No sunset or enrollment blockers in the current filter.",
      path: "/payroll/benefits",
    });
  }
  return insights;
}

function buildCompensationInsights(changes) {
  const insights = [];
  const pending = changes.filter((row) => row.status === COMPENSATION_CHANGE_STATUSES.PENDING_APPROVAL);
  if (pending.length) {
    insights.push({
      id: "pending",
      tone: "amber",
      icon: "fe fe-clock",
      title: `${pending.length} compensation change${pending.length === 1 ? "" : "s"} awaiting approval`,
      copy: "Route through payroll and HR sign-off before effective dates.",
      path: "/payroll/compensation",
    });
  }
  const largeIncreases = changes.filter(
    (row) =>
      row.currentBaseUsd != null &&
      row.proposedBaseUsd != null &&
      row.proposedBaseUsd - row.currentBaseUsd >= 15000
  );
  if (largeIncreases.length) {
    insights.push({
      id: "large-increase",
      tone: "violet",
      icon: "fe fe-trending-up",
      title: "High-impact compensation moves",
      copy: `${largeIncreases[0].employeeName} and peers have material base increases — verify budget alignment.`,
      path: "/finance/project-financials",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Compensation queue healthy",
      copy: "No pending approvals or budget alerts in the current scope.",
      path: "/payroll/compensation",
    });
  }
  return insights;
}

