import { commonUtils } from "_helpers";

export const FEEDBACK_HERO_TYPES = ["overallstarrating"];
export const FEEDBACK_FOOTER_TYPES = ["reaction"];
export const FEEDBACK_FULL_WIDTH_TYPES = [
  "longstring",
  "starrating",
  "multiopitonrating",
  "reaction",
];

export function getQuestionLayoutSpan(type) {
  if (FEEDBACK_HERO_TYPES.includes(type)) return "hero";
  if (FEEDBACK_FULL_WIDTH_TYPES.includes(type)) return "full";
  return "half";
}

export function sortQuestions(questionDataList) {
  return commonUtils.sortArrayOfObjectsByKey(questionDataList || [], "index", true);
}

export function partitionFeedbackQuestions(questionDataList) {
  const sorted = sortQuestions(questionDataList);
  return {
    hero: sorted.filter((q) => FEEDBACK_HERO_TYPES.includes(q.type)),
    body: sorted.filter(
      (q) => !FEEDBACK_HERO_TYPES.includes(q.type) && !FEEDBACK_FOOTER_TYPES.includes(q.type)
    ),
    footer: sorted.filter((q) => FEEDBACK_FOOTER_TYPES.includes(q.type)),
  };
}

export function countAnsweredQuestions(questionDataList) {
  const list = questionDataList || [];
  const mandatory = list.filter((q) => q.mandatory === true);
  const answered = list.filter((q) => {
    const answer = q.answer;
    if (answer === false) return true;
    if (answer === 0) return false;
    return answer != null && String(answer).trim() !== "";
  });
  const mandatoryAnswered = mandatory.filter((q) => {
    const answer = q.answer;
    if (answer === false) return true;
    if (answer === 0) return false;
    return answer != null && String(answer).trim() !== "";
  });
  return {
    total: list.length,
    answered: answered.length,
    mandatoryTotal: mandatory.length,
    mandatoryAnswered: mandatoryAnswered.length,
  };
}

export function validateFeedbackAnswers(questionDataList) {
  return !(questionDataList || []).some((question) => {
    if (question.mandatory !== true) return false;
    const answer = question.answer;
    if (answer === false) return false;
    if (answer === 0) return true;
    return answer == null || String(answer).trim() === "";
  });
}
