import React from "react";
import classNames from "classnames/bind";
import { getFileMimeMeta } from "./fileManager.utils";

export default function FileManagerRecentStrip({ items, onOpenItem }) {
  if (!items || items.length === 0) return null;

  return (
    <section className="lux-file-recent" aria-label="Recently accessed">
      <header className="lux-file-recent__head">
        <div className="lux-file-recent__title-wrap">
          <span className="lux-file-recent__eyebrow">Quick access</span>
          <h3 className="lux-file-recent__title">Recently accessed</h3>
        </div>
        <span className="lux-file-recent__count">{items.length} items</span>
      </header>
      <div className="lux-file-recent__track" role="list">
        {items.map((item) => {
          const meta = getFileMimeMeta(item.mimeKind);
          return (
            <button
              key={item.id}
              type="button"
              className={classNames("lux-file-recent__card", `is-${meta.tone}`)}
              role="listitem"
              onClick={() => onOpenItem && onOpenItem(item)}
            >
              <span className={classNames("lux-file-recent__icon", `is-${meta.tone}`)} aria-hidden="true">
                <i className={meta.icon} />
              </span>
              <span className="lux-file-recent__name" title={item.name}>
                {item.name}
              </span>
              <span className="lux-file-recent__meta">
                {item.type === "folder"
                  ? item.sizeBytes
                    ? `${item.sizeLabel} · folder`
                    : "Folder"
                  : item.sizeLabel}
              </span>
              {item.starred && (
                <span className="lux-file-recent__star" aria-label="Starred">
                  <i className="fe fe-star" />
                </span>
              )}
            </button>
          );
        })}
      </div>
    </section>
  );
}
