import React, { Component } from "react";
import { Link } from "react-router-dom";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingInsightPanel,
  RecruitingLuxPanel,
  RecruitingQuickNav,
  RecruitingStatusBadge,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import {
  buildRecruitingInsights,
  buildRecruitingKpiCards,
  buildRecruitingPipelineStages,
  filterActiveCandidates,
  filterOpenInterviews,
  filterPendingOffers,
  filterPendingRequisitions,
  pickRecruitingActionRows,
} from "views/recruiting/recruitingDashboard.utils";

class RecruitingDashboardPage extends Component {
  state = {
    loading: true,
    loadError: null,
    summary: null,
    requisitions: [],
    candidates: [],
    interviews: [],
    offers: [],
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Recruiting dashboard");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [summaryResult, reqResult, candResult, intResult, offResult] = await Promise.all([
        recruitingService.dashboardSummary(),
        recruitingService.listRequisitions(),
        recruitingService.listCandidates(),
        recruitingService.listInterviews(),
        recruitingService.listOffers(),
      ]);

      if (summaryResult.source !== "api" || !summaryResult.payload) {
        throw summaryResult.error || new Error("Unable to load ATS dashboard");
      }

      this.setState({
        loading: false,
        summary: summaryResult.payload,
        requisitions: reqResult.source === "api" && Array.isArray(reqResult.payload) ? reqResult.payload : [],
        candidates: candResult.source === "api" && Array.isArray(candResult.payload) ? candResult.payload : [],
        interviews: intResult.source === "api" && Array.isArray(intResult.payload) ? intResult.payload : [],
        offers: offResult.source === "api" && Array.isArray(offResult.payload) ? offResult.payload : [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        summary: null,
        loadError: error,
        requisitions: [],
        candidates: [],
        interviews: [],
        offers: [],
      });
    }
  };

  renderActivityList(rows, renderRow, emptyCopy) {
    if (!rows.length) {
      return <p className="text-muted mb-0">{emptyCopy}</p>;
    }

    return (
      <ul className="lux-recruiting-activity-list">
        {rows.map(renderRow)}
      </ul>
    );
  }

  render() {
    const { loading, loadError, summary, requisitions, candidates, interviews, offers } = this.state;
    const kpiCards = buildRecruitingKpiCards(summary);
    const pipelineStages = buildRecruitingPipelineStages(summary);
    const pipelineTotal = pipelineStages.reduce((sum, stage) => sum + stage.count, 0);
    const insights = buildRecruitingInsights(summary, { requisitions });

    const pendingReqs = pickRecruitingActionRows(filterPendingRequisitions(requisitions));
    const activeCandidates = pickRecruitingActionRows(filterActiveCandidates(candidates));
    const openInterviews = pickRecruitingActionRows(filterOpenInterviews(interviews));
    const pendingOffers = pickRecruitingActionRows(filterPendingOffers(offers));

    return (
      <RecruitingLuxPage
        testId="recruiting-dashboard-page"
        dataSource={summary ? "api" : loadError ? "api-error" : null}
        loading={loading}
        onRefresh={this.load}
        kpiCards={kpiCards}
        pageMeta={{
          titleLead: "Recruiting",
          titleAccent: "dashboard",
          lede: "Live ATS pipeline summary for your team — requisitions through accepted offers.",
        }}
        heroActions={
          <>
            <RecruitingActionButton to="/recruiting/requisitions" icon="fe fe-plus" variant="secondary">
              New requisition
            </RecruitingActionButton>
            <RecruitingActionButton to="/recruiting/candidates" icon="fe fe-user-plus" variant="secondary">
              Add candidate
            </RecruitingActionButton>
            <RecruitingActionButton to="/recruiting/interviews" icon="fe fe-calendar">
              Schedule interview
            </RecruitingActionButton>
          </>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load dashboard">
            {String(loadError.message || loadError)}{" "}
            <button type="button" className="lux-onb-action lux-onb-action--ghost lux-onb-action--compact" onClick={this.load}>
              Retry
            </button>
          </LuxInlineAlert>
        ) : null}

        {!loading && !summary && !loadError ? (
          <LuxRegisterEmptyState
            title="No ATS summary yet"
            description="Create requisitions and candidates to populate the recruiting dashboard."
            showCreate={false}
          />
        ) : null}

        {summary ? (
          <>
            <RecruitingInsightPanel insights={insights} />

            <RecruitingLuxPanel
              title="Pipeline by stage"
              meta={`${pipelineTotal} candidate${pipelineTotal === 1 ? "" : "s"} across live ATS stages.`}
              icon="fe fe-activity"
              actions={
                <RecruitingActionButton to="/recruiting/candidates" variant="ghost" className="lux-onb-action--compact">
                  View candidates
                </RecruitingActionButton>
              }
            >
              {pipelineTotal === 0 ? (
                <p className="text-muted mb-0">
                  No candidates in the pipeline yet.{" "}
                  <Link to="/recruiting/candidates">Add a candidate</Link> to start tracking stages.
                </p>
              ) : (
                <div className="lux-recruiting-pipeline" data-testid="recruiting-pipeline-stages">
                  {pipelineStages.map((stage) => (
                    <div key={stage.stage} className="lux-recruiting-pipeline__row">
                      <span className="lux-recruiting-pipeline__label">{stage.label}</span>
                      <div className="lux-recruiting-pipeline__track" aria-hidden="true">
                        <span
                          className="lux-recruiting-pipeline__fill"
                          style={{ width: `${Math.max(stage.pct, stage.count > 0 ? 8 : 0)}%` }}
                        />
                      </div>
                      <span className="lux-recruiting-pipeline__count">{stage.count}</span>
                    </div>
                  ))}
                </div>
              )}
            </RecruitingLuxPanel>

            <div className="lux-recruiting-activity-grid">
              <RecruitingLuxPanel
                title="Requisitions needing action"
                meta="Draft, open, or submitted headcount."
                icon="fe fe-file-text"
                actions={
                  <RecruitingActionButton to="/recruiting/requisitions" variant="ghost" className="lux-onb-action--compact">
                    All requisitions
                  </RecruitingActionButton>
                }
              >
                {this.renderActivityList(
                  pendingReqs,
                  (row) => (
                    <li key={row.requisitionRef || row.id}>
                      <div>
                        <strong>{row.title || row.requisitionRef || "Requisition"}</strong>
                        <span>{row.requisitionRef || "—"}</span>
                      </div>
                      <RecruitingStatusBadge status={row.status} />
                    </li>
                  ),
                  "No requisitions awaiting action."
                )}
              </RecruitingLuxPanel>

              <RecruitingLuxPanel
                title="Active candidates"
                meta="Excludes hired, rejected, and withdrawn."
                icon="fe fe-users"
                actions={
                  <RecruitingActionButton to="/recruiting/candidates" variant="ghost" className="lux-onb-action--compact">
                    All candidates
                  </RecruitingActionButton>
                }
              >
                {this.renderActivityList(
                  activeCandidates,
                  (row) => (
                    <li key={row.candidateRef || row.id}>
                      <div>
                        <strong>{row.name || row.candidateRef || "Candidate"}</strong>
                        <span>{row.email || row.source || "—"}</span>
                      </div>
                      <RecruitingStatusBadge status={row.stage} label={row.stage} />
                    </li>
                  ),
                  "No active candidates in the pipeline."
                )}
              </RecruitingLuxPanel>

              <RecruitingLuxPanel
                title="Open interviews"
                meta="Rounds not yet marked completed."
                icon="fe fe-calendar"
                actions={
                  <RecruitingActionButton to="/recruiting/interviews" variant="ghost" className="lux-onb-action--compact">
                    All interviews
                  </RecruitingActionButton>
                }
              >
                {this.renderActivityList(
                  openInterviews,
                  (row) => (
                    <li key={row.interviewRef || row.id}>
                      <div>
                        <strong>{row.candidateRef || row.interviewRef || "Interview"}</strong>
                        <span>{row.scheduledAt || row.roundType || "—"}</span>
                      </div>
                      <RecruitingStatusBadge status={row.status} />
                    </li>
                  ),
                  "No open interview rounds."
                )}
              </RecruitingLuxPanel>

              <RecruitingLuxPanel
                title="Offers in flight"
                meta="Pending approval or candidate decision."
                icon="fe fe-award"
                actions={
                  <RecruitingActionButton to="/recruiting/offers" variant="ghost" className="lux-onb-action--compact">
                    All offers
                  </RecruitingActionButton>
                }
              >
                {this.renderActivityList(
                  pendingOffers,
                  (row) => (
                    <li key={row.offerRef || row.id}>
                      <div>
                        <strong>{row.candidateRef || row.offerRef || "Offer"}</strong>
                        <span>{row.requisitionRef || "—"}</span>
                      </div>
                      <RecruitingStatusBadge status={row.status} />
                    </li>
                  ),
                  "No offers awaiting action."
                )}
              </RecruitingLuxPanel>
            </div>

            <RecruitingQuickNav />
          </>
        ) : null}
      </RecruitingLuxPage>
    );
  }
}

export default RecruitingDashboardPage;
