import React, { Component } from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import StudyTypeData from "./StudyTypeData";

class BidRequestTargetGroupField extends Component {
  constructor(props) {
    super(props);
    this.state = { popoverOpen: false };
    this.triggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.popoverOpen) return;
    const dialog = document.getElementById("lux-bid-tg-popover-dialog");
    if (
      this.triggerRef.current &&
      !this.triggerRef.current.contains(event.target) &&
      dialog &&
      !dialog.contains(event.target)
    ) {
      this.setState({ popoverOpen: false });
    }
  };

  openPopover = () => {
    if (!this.props.readOnly) {
      this.setState({ popoverOpen: true });
    }
  };

  closePopover = () => {
    this.setState({ popoverOpen: false });
  };

  getSelectedTypes = () => {
    const { bidRequest, studyTypeConfig } = this.props;
    if (!bidRequest || !bidRequest.studyTypes || !studyTypeConfig) return [];
    return studyTypeConfig.filter((item) =>
      bidRequest.studyTypes.includes(item.value)
    );
  };

  renderSummaryChips = () => {
    const selected = this.getSelectedTypes();
    if (!selected.length) {
      return (
        <span className="lux-bid-tg-field__empty">
          No target groups selected — open the editor to choose types and descriptions.
        </span>
      );
    }
    return (
      <ul className="lux-bid-tg-field__chips" aria-label="Selected target groups">
        {selected.map((type) => (
          <li key={type.value} className="lux-bid-tg-field__chip">
            {type.label}
          </li>
        ))}
      </ul>
    );
  };

  renderPopover = () => {
    if (!this.state.popoverOpen || this.props.readOnly) return null;

    const {
      bidRequest,
      fieldConfig,
      createConfig,
      studyTypeConfig,
      onChange,
      onFormError,
    } = this.props;
    const selectedStudyTypes = this.getSelectedTypes();

    return (
      <>
        <button
          type="button"
          className="lux-bid-tg-popover__backdrop"
          aria-label="Close target group editor"
          onClick={this.closePopover}
        />
        <div
          id="lux-bid-tg-popover-dialog"
          className="lux-bid-tg-popover"
          role="dialog"
          aria-labelledby="lux-bid-tg-popover-title"
        >
          <header className="lux-bid-tg-popover__head">
            <div>
              <h4 id="lux-bid-tg-popover-title">Target group (TG) configuration</h4>
              <p>
                Select target groups for the study, then complete each TG description below.
              </p>
            </div>
            <button
              type="button"
              className="lux-bid-tg-popover__close"
              onClick={this.closePopover}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>
          <div className="lux-bid-tg-popover__body">
            <CustomInput
              readOnly={this.props.readOnly}
              type="select"
              label="What is the TG for the study with TG description"
              name="studyTypes"
              fieldConfig={fieldConfig}
              mappingObject={bidRequest}
              onChange={onChange}
              placeholder="Select target groups…"
              options={studyTypeConfig}
              onFormError={onFormError}
              multi={true}
              menuPortal={true}
            />
            {bidRequest.studyTypes && bidRequest.studyTypes.length > 0 && (
              <StudyTypeData
                name="studyTypesData"
                readOnly={this.props.readOnly}
                studyTypesData={bidRequest.studyTypesData}
                selectedStudyTypes={selectedStudyTypes}
                onChange={onChange}
                fieldConfig={fieldConfig}
                onFormError={onFormError}
                createConfig={createConfig}
              />
            )}
          </div>
          <footer className="lux-bid-tg-popover__foot">
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--primary"
              onClick={this.closePopover}
            >
              Done
            </button>
          </footer>
        </div>
      </>
    );
  };

  renderReadOnlyBody = () => {
    const selected = this.getSelectedTypes();
    if (!selected.length) return null;
    return (
      <div className="lux-bid-tg-field__readonly-detail">
        <StudyTypeData
          name="studyTypesData"
          readOnly={true}
          studyTypesData={this.props.bidRequest.studyTypesData}
          selectedStudyTypes={selected}
          onChange={this.props.onChange}
          fieldConfig={this.props.fieldConfig}
          onFormError={this.props.onFormError}
          createConfig={this.props.createConfig}
        />
      </div>
    );
  };

  render() {
    const { readOnly, fieldConfig, bidRequest } = this.props;
    const selectedCount = (bidRequest.studyTypes && bidRequest.studyTypes.length) || 0;
    const isMandatory =
      fieldConfig &&
      fieldConfig.some((f) => f.name === "studyTypes" && f.mandatory);

    return (
      <div className="lux-bid-tg-field" ref={this.triggerRef}>
        <div className="lux-bid-tg-field__label-row">
          <label className="lux-bid-tg-field__label">
            Target group (TG)
            {isMandatory && <span className="lux-bid-tg-field__required">*</span>}
          </label>
          {!readOnly && (
            <button
              type="button"
              className={classNames("lux-bid-tg-field__edit-btn", {
                "is-open": this.state.popoverOpen,
              })}
              onClick={this.openPopover}
            >
              <i className="fe fe-sliders" aria-hidden="true" />
              {selectedCount > 0 ? "Edit configuration" : "Configure target groups"}
            </button>
          )}
        </div>

        <div
          className={classNames("lux-bid-tg-field__surface", {
            "is-filled": selectedCount > 0,
            "is-clickable": !readOnly,
          })}
          onClick={!readOnly ? this.openPopover : undefined}
          onKeyDown={
            !readOnly
              ? (e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    this.openPopover();
                  }
                }
              : undefined
          }
          role={!readOnly ? "button" : undefined}
          tabIndex={!readOnly ? 0 : undefined}
        >
          <div className="lux-bid-tg-field__surface-head">
            <span className="lux-bid-tg-field__count">
              <strong>{selectedCount}</strong>
              <span>target group{selectedCount === 1 ? "" : "s"}</span>
            </span>
            {!readOnly && <i className="fe fe-chevron-right lux-bid-tg-field__chevron" aria-hidden="true" />}
          </div>
          {this.renderSummaryChips()}
        </div>

        {readOnly && this.renderReadOnlyBody()}
        {this.renderPopover()}
      </div>
    );
  }
}

export default BidRequestTargetGroupField;
