import React from "react";
import classNames from "classnames";
import { usePersonaContext } from "hooks/usePersonaContext";

const SCOPE_ICONS = {
  SELF: "fe fe-user",
  TEAM: "fe fe-users",
  DEPARTMENT: "fe fe-grid",
  PROJECT: "fe fe-layers",
  PROGRAM: "fe fe-git-branch",
  PORTFOLIO: "fe fe-briefcase",
  PAYROLL_GROUP: "fe fe-credit-card",
  FINANCE_ORG: "fe fe-dollar-sign",
  ORG: "fe fe-globe",
  ADMIN: "fe fe-shield",
};

function normalizeLabel(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/**
 * P00-T5: Read-only data-scope indicator (self, team, org, etc.).
 * Not interactive — persona switching lives on PersonaSwitcher.
 */
function ScopeBadge({ className, showPersona = false }) {
  const { scopeLabel, scopeType, activePersonaLabel, isLoading } = usePersonaContext();

  if (isLoading || !scopeType || !scopeLabel) {
    return null;
  }

  const personaDuplicatesScope =
    normalizeLabel(activePersonaLabel) === normalizeLabel(scopeLabel);

  // Header already shows persona via PersonaSwitcher — skip redundant "Admin Admin".
  if (!showPersona && personaDuplicatesScope) {
    return null;
  }

  let displayText;
  let title;
  if (showPersona) {
    displayText = personaDuplicatesScope
      ? `${activePersonaLabel} · data scope`
      : `${activePersonaLabel} · ${scopeLabel}`;
    title = `${activePersonaLabel} · ${scopeLabel} data scope`;
  } else {
    displayText = scopeLabel;
    title = `Data scope: ${scopeLabel}. This is informational, not a switcher.`;
  }

  return (
    <span
      className={classNames("lux-scope-badge", className)}
      role="status"
      aria-label={title}
      title={title}
    >
      <i className={SCOPE_ICONS[scopeType] || "fe fe-eye"} aria-hidden="true" />
      {!showPersona && <span className="lux-scope-badge__prefix">Scope</span>}
      <span className="lux-scope-badge__value">{displayText}</span>
    </span>
  );
}

export default ScopeBadge;
