import React from "react";
import classNames from "classnames/bind";
import { buildApprovalAnalyticsMetrics } from "config/approval-analytics.utils";

function AnalyticsCard({ label, value, hint, tone }) {
  return (
    <article className={classNames("lux-hrms-dash__kpi lux-appr-kpi", tone && `is-${tone}`)}>
      <span className="lux-hrms-dash__kpi-label">{label}</span>
      <strong className="lux-hrms-dash__kpi-value">{value}</strong>
      {hint && <span className="lux-hrms-dash__kpi-hint">{hint}</span>}
    </article>
  );
}

function DomainBar({ row, maxCount }) {
  const widthPct = maxCount ? Math.round((row.count / maxCount) * 100) : 0;
  return (
    <div className="lux-appr-analytics__bar-row">
      <div className="lux-appr-analytics__bar-label">
        <span>{row.label}</span>
        <strong>{row.count}</strong>
      </div>
      <div className="lux-appr-analytics__bar-track" aria-hidden="true">
        <span
          className={classNames("lux-appr-analytics__bar-fill", row.tone && `is-${row.tone}`)}
          style={{ width: `${widthPct}%` }}
        />
      </div>
    </div>
  );
}

export default function UniversalApprovalAnalyticsPanel({ items, loading }) {
  const metrics = buildApprovalAnalyticsMetrics(items || []);
  const maxDomain = metrics.domainBreakdown.reduce((max, row) => Math.max(max, row.count), 0);

  if (loading) {
    return (
      <div className="lux-appr-analytics lux-appr-analytics--loading" aria-busy="true">
        Loading approval analytics…
      </div>
    );
  }

  return (
    <div className="lux-appr-analytics">
      <div className="lux-hrms-dash__kpi-strip lux-appr-kpi-strip" role="list">
        <AnalyticsCard label="Pending" value={metrics.pending} hint="Open decisions" tone="amber" />
        <AnalyticsCard label="Overdue" value={metrics.overdue} hint="Past due date" tone="rose" />
        <AnalyticsCard label="Due soon" value={metrics.dueSoon} hint="Next 48 hours" tone="amber" />
        <AnalyticsCard label="On track" value={metrics.onTrack} hint="Within SLA window" tone="green" />
        <AnalyticsCard label="Approved" value={metrics.approved} hint="Completed this period" tone="green" />
        <AnalyticsCard label="Rejected" value={metrics.rejected} hint="Declined requests" tone="slate" />
      </div>

      <div className="lux-appr-analytics__grid">
        <section className="lux-hrms-dash__panel lux-appr-analytics__panel">
          <header className="lux-hrms-dash__panel-head">
            <h2 className="lux-hrms-dash__panel-title">Pending by domain</h2>
            <p className="lux-hrms-dash__panel-sub">Where approval bottlenecks are forming.</p>
          </header>
          <div className="lux-hrms-dash__panel-body">
            {metrics.domainBreakdown.length === 0 ? (
              <p className="lux-appr-analytics__empty">No pending approvals to analyze.</p>
            ) : (
              metrics.domainBreakdown.map((row) => (
                <DomainBar key={row.domain} row={row} maxCount={maxDomain} />
              ))
            )}
          </div>
        </section>

        <section className="lux-hrms-dash__panel lux-appr-analytics__panel">
          <header className="lux-hrms-dash__panel-head">
            <h2 className="lux-hrms-dash__panel-title">SLA signals</h2>
            <p className="lux-hrms-dash__panel-sub">Queue health and delegation load.</p>
          </header>
          <div className="lux-hrms-dash__panel-body lux-appr-analytics__signals">
            <div className="lux-appr-analytics__signal">
              <span>Bottleneck domain</span>
              <strong>{metrics.bottleneckDomain}</strong>
              <em>{metrics.bottleneckCount} pending</em>
            </div>
            <div className="lux-appr-analytics__signal">
              <span>Acting as delegate</span>
              <strong>{metrics.delegatePending}</strong>
              <em>Pending delegate items</em>
            </div>
            <div className="lux-appr-analytics__signal">
              <span>SLA posture</span>
              <strong>
                {metrics.overdue > 0 ? "At risk" : metrics.dueSoon > 0 ? "Watch" : "Healthy"}
              </strong>
              <em>Based on due dates and priority</em>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}
