/**
 * F01-T2: Module icon rail + context submenu panel (same total sidebar width).
 */

import envconfig from "env.config";
import { getUiSettings } from "_helpers/settings.utils";
import {
  SIDEBAR_GROUPS,
  isSidebarGroupVisible,
  pathMatchesSidebarGroup,
} from "config/sidebar-menu.config";
import { resolveActivePersona } from "config/persona-navigation.utils";

export function isModuleMenuRailLayoutEnabled() {
  if (envconfig.USE_MODULE_MENU_RAIL !== true) {
    return false;
  }
  const settings = getUiSettings();
  return settings.moduleMenuRail !== false;
}

export function getVisibleSidebarGroups(menuAccessControl, activePersona) {
  const persona = activePersona || resolveActivePersona(menuAccessControl);
  return SIDEBAR_GROUPS.filter((group) =>
    isSidebarGroupVisible(group, menuAccessControl, persona)
  );
}

export function resolveActiveModuleId(pathname, menuAccessControl, activePersona) {
  const visibleGroups = getVisibleSidebarGroups(menuAccessControl, activePersona);
  const path = (pathname || "").split("?")[0];

  for (let i = visibleGroups.length - 1; i >= 0; i -= 1) {
    const group = visibleGroups[i];
    if (pathMatchesSidebarGroup(path, group)) {
      return group.id;
    }
  }

  return visibleGroups[0] ? visibleGroups[0].id : null;
}

export function findSidebarGroupById(groupId) {
  return SIDEBAR_GROUPS.find((group) => group.id === groupId) || null;
}
