import React, { Component } from "react";
import classNames from "classnames/bind";
import Select from "react-select";
import { commonUtils } from "_helpers";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import { findTreeNodeById } from "./appConfigTree.utils";

function flattenRoles(nodes, roles = []) {
  if (!nodes) return roles;
  nodes.forEach((node) => {
    if (node && node.id != null) {
      roles.push({ id: node.id, name: node.name });
    }
    if (node.nodes) {
      flattenRoles(node.nodes, roles);
    }
  });
  return roles;
}

class RoleMemberAddRow extends Component {
  constructor() {
    super();
    this.state = { employee: null };
  }

  handleAdd = () => {
    if (!this.state.employee) return;
    this.props.onAddEmployees(this.state.employee);
    this.setState({ employee: null });
  };

  render() {
    const options =
      this.props.allEmployees &&
      commonUtils.convertObjectToSelectObject(this.props.allEmployees);

    return (
      <div className="lux-ac-role-panel__add">
        <div className="lux-ac-role-panel__add-copy">
          <strong>Add member</strong>
          <span>Assign an employee to this role group</span>
        </div>
        <div className="lux-ac-role-panel__add-controls">
          <Select
            value={this.state.employee}
            isSearchable
            isClearable
            className="lux-ac-role-panel__select"
            classNamePrefix="lux-ac-role-select"
            isMulti={false}
            menuPlacement="auto"
            placeholder="Search employees..."
            onChange={(selectedOption) => this.setState({ employee: selectedOption })}
            options={options || []}
          />
          <button
            type="button"
            className="lux-ac-role-panel__add-btn"
            onClick={this.handleAdd}
            disabled={!this.state.employee}
          >
            Add
          </button>
        </div>
      </div>
    );
  }
}

class ApplicationConfigRoleBar extends Component {
  constructor() {
    super();
    this.state = {
      showPanel: false,
      selectedRoleId: null,
      selectedEmployeesIdsRoles: [],
      filterText: "",
    };
    this.panelRef = React.createRef();
    this.triggerRef = React.createRef();
  }

  componentDidMount() {
    this.syncRoleMembers();
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.selectedMenu &&
      this.props.selectedMenu &&
      prevProps.selectedMenu.id !== this.props.selectedMenu.id
    ) {
      this.syncRoleMembers();
    }

    if (prevProps.allEmployees !== this.props.allEmployees && !this.state.showPanel) {
      this.syncRoleMembers();
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.showPanel) return;
    const panel = this.panelRef.current;
    const trigger = this.triggerRef.current;
    if (
      panel &&
      !panel.contains(event.target) &&
      trigger &&
      !trigger.contains(event.target)
    ) {
      this.closePanel();
    }
  };

  syncRoleMembers = () => {
    const roleId = this.props.selectedMenu && this.props.selectedMenu.id;
    const selectedIds = [];

    this.props.allEmployees &&
      this.props.allEmployees
        .filter((emp) => emp.userRole === roleId)
        .forEach((employeeItem) => {
          selectedIds.push({
            id: employeeItem.id,
            name: employeeItem.name,
            userRole: employeeItem.userRole,
            updated: false,
          });
        });

    this.setState({
      selectedRoleId: roleId,
      selectedEmployeesIdsRoles: commonUtils.sortArrayOfObjects(selectedIds, true),
    });
  };

  getRoleName = () => {
    const { roles, selectedMenu } = this.props;
    const node = roles && findTreeNodeById(roles, selectedMenu.id);
    return (node && node.name) || selectedMenu.name || `Role #${selectedMenu.id}`;
  };

  getRoleOptions = () => {
    const roles = flattenRoles(this.props.roles && this.props.roles.nodes);
    return roles.map((role) => ({ value: role.id, label: role.name }));
  };

  getAvailableEmployees = () => {
    if (!this.props.allEmployees) return [];
    const selectedIds = this.state.selectedEmployeesIdsRoles.map((item) => item.id);
    return this.props.allEmployees.filter((employee) => !selectedIds.includes(employee.id));
  };

  getPendingCount = () =>
    this.state.selectedEmployeesIdsRoles.filter((employee) => employee.updated).length;

  togglePanel = () => {
    if (this.state.showPanel) {
      this.closePanel();
      return;
    }
    this.syncRoleMembers();
    this.setState({ showPanel: true, filterText: "" });
  };

  closePanel = () => {
    this.syncRoleMembers();
    this.setState({ showPanel: false, filterText: "" });
  };

  onFilterTextChange = (event) => {
    this.setState({ filterText: event.target.value });
  };

  onChangeRole = (employeeId, newUserRole) => {
    this.setState((prevState) => ({
      selectedEmployeesIdsRoles: prevState.selectedEmployeesIdsRoles.map((employeeItem) =>
        employeeItem.id === employeeId
          ? {
              ...employeeItem,
              updated: employeeItem.userRole !== newUserRole,
              newUserRole,
            }
          : employeeItem
      ),
    }));
  };

  onAddEmployees = (employee) => {
    this.setState((prevState) => ({
      selectedEmployeesIdsRoles: [
        ...prevState.selectedEmployeesIdsRoles,
        {
          id: employee.id,
          name: employee.name,
          newUserRole: this.props.selectedMenu.id,
          updated: true,
          new: true,
        },
      ],
    }));
  };

  onRemoveEmployee = (employeeId) => {
    this.setState((prevState) => ({
      selectedEmployeesIdsRoles: prevState.selectedEmployeesIdsRoles.filter(
        (employee) => employee.id !== employeeId
      ),
    }));
  };

  handleUpdateEmployeeRoles = () => {
    const updates = this.state.selectedEmployeesIdsRoles
      .filter((employee) => employee.updated === true)
      .map((employee) => ({
        id: employee.id,
        userRole: employee.newUserRole,
      }));

    if (updates.length === 0) return;

    this.props.onUpdateEmployeeRoles(updates, () => {
      this.setState({ showPanel: false, filterText: "" });
      this.syncRoleMembers();
    });
  };

  renderMemberRow = (employee, roleOptions) => {
    const assignedRoleId = employee.newUserRole || employee.userRole;
    const assignedRole = roleOptions.find((role) => role.value === assignedRoleId);

    return (
      <li
        key={employee.id}
        className={classNames("lux-ac-role-panel__member", {
          "is-new": employee.new,
          "is-updated": employee.updated,
        })}
      >
        <div className="lux-ac-role-panel__member-main">
          <span className="lux-ac-role-panel__member-avatar" aria-hidden="true">
            {(employee.name || "?").charAt(0).toUpperCase()}
          </span>
          <div className="lux-ac-role-panel__member-copy">
            <strong>{employee.name}</strong>
            {employee.new ? (
              <span className="lux-ac-role-panel__member-tag">New assignment</span>
            ) : employee.updated ? (
              <span className="lux-ac-role-panel__member-tag is-changed">Pending change</span>
            ) : (
              <span className="lux-ac-role-panel__member-tag is-current">In this role</span>
            )}
          </div>
        </div>
        <div className="lux-ac-role-panel__member-actions">
          {!employee.new ? (
            <SelectInput
              className="lux-ac-role-panel__role-select"
              value={assignedRoleId}
              isReadOnly={false}
              itemId={employee.id}
              onChange={this.onChangeRole}
              options={roleOptions}
            />
          ) : (
            <span className="lux-ac-role-panel__assigned-role">
              {assignedRole ? assignedRole.label : "This role"}
            </span>
          )}
          {employee.new && (
            <button
              type="button"
              className="lux-ac-role-panel__remove-btn"
              title="Remove"
              onClick={() => this.onRemoveEmployee(employee.id)}
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          )}
        </div>
      </li>
    );
  };

  render() {
    const { selectedMenu } = this.props;
    const roleName = this.getRoleName();
    const memberCount = this.state.selectedEmployeesIdsRoles.length;
    const pendingCount = this.getPendingCount();
    const roleOptions = this.getRoleOptions();
    const filteredMembers = this.state.selectedEmployeesIdsRoles.filter(
      (employee) =>
        !this.state.filterText ||
        commonUtils.stringContainsString(employee.name, this.state.filterText)
    );

    return (
      <div className="lux-ac-role-bar">
        <div className="lux-ac-role-bar__context">
          <span className="lux-ac-role-bar__eyebrow">Role group</span>
          <div className="lux-ac-role-bar__title-row">
            <strong className="lux-ac-role-bar__title">{roleName}</strong>
            <span className="lux-ac-role-bar__id">#{selectedMenu.id}</span>
          </div>
          <p className="lux-ac-role-bar__hint">
            Add employees to this role or reassign members across role groups.
          </p>
        </div>

        <div className="lux-ac-role-bar__actions">
          <div className="lux-ac-role-bar__action-wrap" ref={this.triggerRef}>
            <button
              type="button"
              className={classNames("lux-ac-role-bar__members-btn", {
                "is-open": this.state.showPanel,
              })}
              onClick={this.togglePanel}
              aria-expanded={this.state.showPanel}
            >
              <span className="lux-ac-role-bar__members-icon" aria-hidden="true">
                <i className="fe fe-users" />
              </span>
              <span className="lux-ac-role-bar__members-copy">
                <span className="lux-ac-role-bar__members-label">Members</span>
                <span className="lux-ac-role-bar__members-sub">
                  {memberCount} in this role
                </span>
              </span>
              <span className="lux-ac-role-bar__count">{memberCount}</span>
            </button>

            {this.state.showPanel && (
              <div className="lux-ac-role-panel" ref={this.panelRef}>
                <div className="lux-ac-role-panel__header">
                  <div>
                    <span className="lux-ac-role-panel__eyebrow">Role members</span>
                    <strong>{roleName}</strong>
                    <span className="lux-ac-role-panel__meta">
                      {memberCount} assigned · {this.getAvailableEmployees().length} available to add
                    </span>
                  </div>
                  <button
                    type="button"
                    className="lux-ac-role-panel__close"
                    onClick={this.closePanel}
                    aria-label="Close members panel"
                  >
                    <i className="fe fe-x" aria-hidden="true" />
                  </button>
                </div>

                <label className="lux-ac-role-panel__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    value={this.state.filterText}
                    onChange={this.onFilterTextChange}
                    placeholder="Filter members..."
                    aria-label="Filter role members"
                  />
                </label>

                <div className="lux-ac-role-panel__body">
                  <ul className="lux-ac-role-panel__list">
                    {filteredMembers.length > 0 ? (
                      filteredMembers.map((employee) =>
                        this.renderMemberRow(employee, roleOptions)
                      )
                    ) : (
                      <li className="lux-ac-role-panel__empty">
                        {this.state.filterText
                          ? "No members match your filter."
                          : "No employees are assigned to this role yet."}
                      </li>
                    )}
                  </ul>

                  <RoleMemberAddRow
                    allEmployees={this.getAvailableEmployees()}
                    onAddEmployees={this.onAddEmployees}
                  />
                </div>

                <div className="lux-ac-role-panel__footer">
                  <button
                    type="button"
                    className="lux-ac-role-panel__cancel"
                    onClick={this.closePanel}
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    className="lux-ac-role-panel__save"
                    onClick={this.handleUpdateEmployeeRoles}
                    disabled={pendingCount === 0}
                  >
                    {pendingCount > 0 ? `Save ${pendingCount} change${pendingCount === 1 ? "" : "s"}` : "Save changes"}
                  </button>
                </div>
              </div>
            )}
          </div>

          <button
            type="button"
            className="lux-ac-role-bar__refresh-btn"
            onClick={this.props.onRefreshRoles}
            title="Refresh role definitions and membership data"
          >
            <i className="fe fe-refresh-cw" aria-hidden="true" />
            <span>Refresh roles</span>
          </button>
        </div>
      </div>
    );
  }
}

export default ApplicationConfigRoleBar;
