import {
  ONBOARDING_STATUSES,
  OFFBOARDING_STATUSES,
  ONBOARDING_TASK_CATEGORIES,
  OFFBOARDING_TASK_CATEGORIES,
  TASK_STATUSES,
} from "config/onboarding.config";

export function resolveStatusMeta(statusId, lifecycle = "onboarding") {
  const catalog = lifecycle === "offboarding" ? OFFBOARDING_STATUSES : ONBOARDING_STATUSES;
  return catalog.find((item) => item.id === statusId) || { id: statusId, label: statusId, tone: "neutral" };
}

export function resolveTaskStatusMeta(statusId) {
  return TASK_STATUSES.find((item) => item.id === statusId) || { id: statusId, label: statusId, tone: "neutral" };
}

export function computeCaseProgress(tasks = []) {
  if (!tasks.length) {
    return { completed: 0, total: 0, pct: 0, overdue: 0 };
  }
  const total = tasks.length;
  const completed = tasks.filter((task) => task.status === "completed" || task.status === "skipped").length;
  const overdue = tasks.filter((task) => isTaskOverdue(task)).length;
  const pct = Math.round((completed / total) * 100);
  return { completed, total, pct, overdue };
}

export function isTaskOverdue(task) {
  if (!task || !task.dueDate) {
    return false;
  }
  if (task.status === "completed" || task.status === "skipped") {
    return false;
  }
  const due = new Date(task.dueDate);
  if (Number.isNaN(due.getTime())) {
    return false;
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  due.setHours(0, 0, 0, 0);
  return due < today;
}

export function filterCasesByStatus(cases, statusFilter) {
  if (!statusFilter || statusFilter === "ALL") {
    return cases;
  }
  return cases.filter((item) => item.status === statusFilter);
}

export function filterCasesByDepartment(cases, departmentFilter) {
  if (!departmentFilter || departmentFilter === "ALL") {
    return cases;
  }
  return cases.filter((item) => item.department === departmentFilter);
}

export function groupTasksByCategory(tasks, categories) {
  const groups = (categories || []).map((category) => ({
    ...category,
    tasks: (tasks || []).filter((task) => task.category === category.id),
  }));
  const known = new Set((categories || []).map((category) => category.id));
  const otherTasks = (tasks || []).filter((task) => !known.has(task.category));
  if (otherTasks.length) {
    groups.push({ id: "Other", label: "Other", icon: "fe fe-more-horizontal", tasks: otherTasks });
  }
  return groups.filter((group) => group.tasks.length > 0);
}

export function buildOnboardingQueueMetrics(cases = []) {
  const active = cases.filter((item) => item.status === "in_progress" || item.status === "ready").length;
  const overdueTasks = cases.reduce((sum, item) => sum + (item.overdueCount || 0), 0);
  const ready = cases.filter((item) => item.status === "ready").length;
  const avgReadiness = cases.length
    ? Math.round(cases.reduce((sum, item) => sum + (item.readinessPct || 0), 0) / cases.length)
    : 0;
  return { active, overdueTasks, ready, avgReadiness };
}

export function buildOffboardingQueueMetrics(cases = []) {
  const active = cases.filter((item) => item.status === "in_progress").length;
  const blocked = cases.filter((item) => item.status === "blocked").length;
  const dueThisWeek = cases.filter((item) => item.dueSoon === true).length;
  const avgProgress = cases.length
    ? Math.round(cases.reduce((sum, item) => sum + (item.readinessPct || 0), 0) / cases.length)
    : 0;
  return { active, blocked, dueThisWeek, avgProgress };
}

/** Single-case KPI metrics for lifecycle detail pages. */
export function buildLifecycleCaseMetrics(caseData, progress, lifecycle = "onboarding") {
  const prog = progress || computeCaseProgress((caseData && caseData.tasks) || []);
  const readiness = (caseData && caseData.readinessPct != null)
    ? caseData.readinessPct
    : prog.pct || 0;
  const pendingTasks = Math.max(0, prog.total - prog.completed);

  if (lifecycle === "offboarding") {
    return {
      readiness,
      tasksComplete: prog.completed,
      taskTotal: prog.total,
      overdueTasks: prog.overdue,
      pendingTasks,
      blocked: caseData && caseData.status === "blocked" ? 1 : 0,
      dueSoon: caseData && caseData.dueSoon ? 1 : 0,
    };
  }

  return {
    readiness,
    tasksComplete: prog.completed,
    taskTotal: prog.total,
    overdueTasks: prog.overdue,
    pendingTasks,
    ready: caseData && caseData.status === "ready" ? 1 : 0,
  };
}

export function canConvertOnboardingCase(caseData) {
  if (!caseData || caseData.employeeId) {
    return false;
  }
  if (caseData.status === "cancelled" || caseData.status === "completed") {
    return false;
  }
  if (caseData.status === "ready") {
    return Boolean(caseData.candidateName && (caseData.email || caseData.candidateEmail));
  }
  const tasks = caseData.tasks || [];
  const requiredTasks = tasks.filter((task) => task.required !== false);
  if (!requiredTasks.length) {
    return false;
  }
  return requiredTasks.every(
    (task) => task.status === "completed" || task.status === "skipped"
  );
}

export function getConvertBlockers(caseData) {
  const blockers = [];
  if (!caseData) {
    return ["Case not loaded"];
  }
  if (caseData.employeeId) {
    blockers.push("Employee record already linked to this case");
  }
  if (!caseData.candidateName) {
    blockers.push("Candidate name is required");
  }
  if (!caseData.email && !caseData.candidateEmail) {
    blockers.push("Candidate email is required");
  }
  if (caseData.status === "cancelled") {
    blockers.push("Cancelled cases cannot be converted");
  }
  const tasks = caseData.tasks || [];
  const requiredTasks = tasks.filter((task) => task.required !== false);
  const incomplete = requiredTasks.filter(
    (task) => task.status !== "completed" && task.status !== "skipped"
  );
  if (caseData.status !== "ready" && incomplete.length) {
    blockers.push("All required checklist tasks must be completed first");
  }
  return blockers;
}

export function isConvertSuccessPayload(payload) {
  return Boolean(payload && (payload.success === true || payload.employeeId != null));
}

export function extractConvertErrorMessage(error, payload) {
  if (payload && Array.isArray(payload.blockers) && payload.blockers.length) {
    return payload.blockers.join(" ");
  }
  if (payload && payload.message) {
    return payload.message;
  }
  if (typeof error === "string" && error.trim()) {
    return error;
  }
  if (error && error.message) {
    return error.message;
  }
  return "Unable to create employee record.";
}

export function buildConvertPreviewFromCase(caseData) {
  if (!caseData) {
    return null;
  }
  const blockers = getConvertBlockers(caseData);
  return {
    caseId: caseData.id,
    name: caseData.candidateName,
    email: caseData.email || caseData.candidateEmail,
    designation: caseData.role,
    department: caseData.department,
    location: caseData.location,
    dateOfJoin: caseData.startDate,
    managerName: caseData.manager,
    managerId: caseData.managerId != null ? caseData.managerId : null,
    userTeamId: caseData.userTeamId != null ? caseData.userTeamId : null,
    existingEmployeeId: caseData.employeeId || null,
    canConvert: blockers.length === 0,
    blockers,
  };
}

export function isSettlementTask(task) {
  if (!task) {
    return false;
  }
  const title = (task.title || "").toLowerCase();
  return task.category === "Payroll" || title.includes("settlement");
}

export function refreshOffboardingTaskBlockers(tasks = []) {
  const list = Array.isArray(tasks) ? tasks.map((task) => ({ ...task })) : [];
  return list.map((task) => {
    const deps = resolveTaskDependencies(task, list);
    if (!deps.length) {
      return task;
    }
    const allSatisfied = deps.every((dep) => dep.satisfied);
    const isDone = task.status === "completed" || task.status === "skipped";
    if (isDone) {
      return task;
    }
    if (allSatisfied && task.status === "blocked") {
      return { ...task, status: "pending", blockedReason: null, blockedAt: null };
    }
    if (
      !allSatisfied &&
      (isSettlementTask(task) || task.status === "blocked" || (task.required && deps.length > 0))
    ) {
      const pendingTitles = deps.filter((dep) => !dep.satisfied).map((dep) => dep.title);
      return {
        ...task,
        status: "blocked",
        blockedReason: `Complete ${pendingTitles.join(", ")} before proceeding.`,
        blockedAt: task.blockedAt || new Date().toISOString().slice(0, 10),
      };
    }
    return task;
  });
}

export function getOffboardingSettlementBlockers(caseData) {
  const blockers = [];
  if (!caseData) {
    return ["Case not loaded"];
  }
  const tasks = caseData.tasks || [];
  tasks
    .filter(isSettlementTask)
    .forEach((task) => {
      if (task.status === "blocked" && task.blockedReason) {
        blockers.push(task.blockedReason);
        return;
      }
      if (task.status !== "completed" && task.status !== "skipped") {
        const deps = resolveTaskDependencies(task, tasks);
        const pending = deps.filter((dep) => !dep.satisfied);
        if (pending.length) {
          blockers.push(`${task.title}: waiting on ${pending.map((dep) => dep.title).join(", ")}`);
        }
      }
    });

  const openAccess = tasks.filter(
    (task) => task.category === "Access" && task.status !== "completed" && task.status !== "skipped"
  );
  if (openAccess.length) {
    blockers.push(
      `${openAccess.length} access revocation task${openAccess.length === 1 ? "" : "s"} still open`
    );
  }

  const openAssets = tasks.filter(
    (task) => task.category === "Assets" && task.status !== "completed" && task.status !== "skipped"
  );
  if (openAssets.length) {
    blockers.push(
      `${openAssets.length} asset return task${openAssets.length === 1 ? "" : "s"} still open`
    );
  }

  return [...new Set(blockers)];
}

export function buildOffboardingSettlementPreview(caseData) {
  if (!caseData) {
    return null;
  }
  const tasks = caseData.tasks || [];
  const settlementTasks = tasks.filter(isSettlementTask);
  const blockers = getOffboardingSettlementBlockers(caseData);
  const settlementComplete = settlementTasks.every(
    (task) => task.status === "completed" || task.status === "skipped"
  );
  const requiredDone = tasks
    .filter((task) => task.required !== false)
    .every((task) => task.status === "completed" || task.status === "skipped");

  return {
    caseId: caseData.id,
    employeeName: caseData.employeeName,
    settlementTasks: settlementTasks.map((task) => ({
      id: task.id,
      title: task.title,
      status: task.status,
      blockedReason: task.blockedReason || null,
    })),
    blockers,
    canFinalize: blockers.length === 0 && settlementComplete && requiredDone,
    settlementComplete,
    requiredTasksComplete: requiredDone,
  };
}

export function formatLifecycleAuditEvent(event) {
  if (!event) {
    return { at: "", label: "Activity", detail: null };
  }
  const labels = {
    ONBOARDING_CASE_CREATED: "Case created",
    OFFBOARDING_CASE_CREATED: "Exit case opened",
    TASK_COMPLETED: "Task completed",
    EMPLOYEE_CONVERTED: "Converted to employee",
    DOCUMENT_SUBMITTED: "Document submitted",
    OFFBOARDING_COMPLETED: "Offboarding completed",
  };
  return {
    at: event.createdAt || "—",
    label: labels[event.eventType] || event.eventType || "Activity",
    detail: event.comment || null,
  };
}

export function getOnboardingCasePath(caseId) {
  return `/people/onboarding/${caseId}`;
}

export function getOffboardingCasePath(caseId) {
  return `/people/offboarding/${caseId}`;
}

export function formatLifecycleDate(dateStr) {
  if (!dateStr) {
    return null;
  }
  const date = new Date(dateStr);
  if (Number.isNaN(date.getTime())) {
    return dateStr;
  }
  return date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

export function getCaseSubjectName(caseData, lifecycle = "onboarding") {
  if (!caseData) {
    return null;
  }
  return lifecycle === "offboarding" ? caseData.employeeName : caseData.candidateName;
}

export function getCaseMilestoneDate(caseData, lifecycle = "onboarding") {
  if (!caseData) {
    return null;
  }
  return lifecycle === "offboarding" ? caseData.lastDay : caseData.startDate;
}

export function getDueDateDelta(task) {
  if (!task || !task.dueDate) {
    return null;
  }
  const due = new Date(task.dueDate);
  if (Number.isNaN(due.getTime())) {
    return null;
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  due.setHours(0, 0, 0, 0);
  const diffDays = Math.round((due - today) / (1000 * 60 * 60 * 24));
  if (diffDays < 0) {
    return { label: `${Math.abs(diffDays)} day${Math.abs(diffDays) === 1 ? "" : "s"} overdue`, tone: "danger" };
  }
  if (diffDays === 0) {
    return { label: "Due today", tone: "warning" };
  }
  if (diffDays === 1) {
    return { label: "Due tomorrow", tone: "warning" };
  }
  return { label: `Due in ${diffDays} days`, tone: "neutral" };
}

export function resolveTaskDependencies(task, allTasks = []) {
  const dependsOn = Array.isArray(task.dependsOn) ? task.dependsOn : [];
  return dependsOn.map((depId) => {
    const depTask = allTasks.find((item) => item.id === depId);
    return {
      id: depId,
      title: depTask ? depTask.title : depId,
      status: depTask ? depTask.status : "unknown",
      satisfied: depTask
        ? depTask.status === "completed" || depTask.status === "skipped"
        : false,
    };
  });
}

export function buildLifecycleCategoryReadiness(cases = [], categories = []) {
  const totals = {};
  (categories || []).forEach((category) => {
    totals[category.id] = { completed: 0, total: 0, label: category.label };
  });

  (cases || []).forEach((caseItem) => {
    (caseItem.tasks || []).forEach((task) => {
      if (!totals[task.category]) {
        totals[task.category] = { completed: 0, total: 0, label: task.category };
      }
      totals[task.category].total += 1;
      if (task.status === "completed" || task.status === "skipped") {
        totals[task.category].completed += 1;
      }
    });
  });

  return Object.entries(totals)
    .filter(([, value]) => value.total > 0)
    .map(([id, value]) => ({
      id,
      label: value.label,
      completed: value.completed,
      total: value.total,
      pct: Math.round((value.completed / value.total) * 100),
    }))
    .sort((a, b) => a.pct - b.pct);
}

export function buildLifecycleStatusMix(cases = [], statusCatalog = []) {
  const counts = {};
  (statusCatalog || []).forEach((status) => {
    counts[status.id] = 0;
  });

  (cases || []).forEach((caseItem) => {
    if (counts[caseItem.status] != null) {
      counts[caseItem.status] += 1;
    }
  });

  const total = cases.length || 0;
  return (statusCatalog || [])
    .map((status) => ({
      id: status.id,
      label: status.label,
      count: counts[status.id] || 0,
      pct: total ? Math.round(((counts[status.id] || 0) / total) * 100) : 0,
    }))
    .filter((item) => item.count > 0);
}

export function buildLifecycleQueueInsights(cases = [], lifecycle = "onboarding") {
  const categories =
    lifecycle === "offboarding" ? OFFBOARDING_TASK_CATEGORIES : ONBOARDING_TASK_CATEGORIES;
  const statusCatalog =
    lifecycle === "offboarding" ? OFFBOARDING_STATUSES : ONBOARDING_STATUSES;
  const categoryReadiness = buildLifecycleCategoryReadiness(cases, categories);
  const statusMix = buildLifecycleStatusMix(cases, statusCatalog);

  const productivityScore = cases.length
    ? Math.round(cases.reduce((sum, item) => sum + (item.readinessPct || 0), 0) / cases.length)
    : 0;

  const documentCategory = lifecycle === "offboarding" ? null : "Documents";
  const accessCategory = lifecycle === "offboarding" ? "Access" : "IT";
  const documentRow = categoryReadiness.find((item) => item.id === documentCategory);
  const accessRow = categoryReadiness.find((item) => item.id === accessCategory);

  const overdueTasks = (cases || []).reduce((sum, item) => sum + (item.overdueCount || 0), 0);

  return {
    categoryReadiness,
    statusMix,
    productivityScore,
    documentCompletionPct: documentRow ? documentRow.pct : null,
    accessReadinessPct: accessRow ? accessRow.pct : null,
    overdueTasks,
    caseCount: cases.length,
  };
}

export function isSelfServiceTask(task) {
  if (!task) {
    return false;
  }
  return task.selfService === true || task.assigneeType === "candidate";
}

export function getSelfServiceAssigneeName(caseData, user) {
  if (!caseData) {
    return null;
  }
  if (user && user.name) {
    return user.name.trim();
  }
  return caseData.candidateName || null;
}

export function filterSelfServiceTasks(tasks = [], assigneeName) {
  return (tasks || []).filter((task) => {
    if (!isSelfServiceTask(task)) {
      return false;
    }
    if (!assigneeName || !task.owner) {
      return true;
    }
    return task.owner.trim().toLowerCase() === assigneeName.trim().toLowerCase();
  });
}

export function resolveSelfServiceOnboardingCase(cases = [], user, { demoFallbackCaseId } = {}) {
  if (!cases.length) {
    return null;
  }

  const email = user && (user.email || user.mail || user.userEmail)
    ? String(user.email || user.mail || user.userEmail).trim().toLowerCase()
    : "";
  const name = user && user.name ? user.name.trim().toLowerCase() : "";

  const activeCases = cases.filter(
    (item) => item.status !== "completed" && item.status !== "cancelled"
  );

  if (email) {
    const byEmail = activeCases.find((item) => {
      const candidateEmail = (item.email || item.candidateEmail || "").trim().toLowerCase();
      return candidateEmail && candidateEmail === email;
    });
    if (byEmail) {
      return byEmail;
    }
  }

  if (name) {
    const byName = activeCases.find((item) => {
      const candidateName = (item.candidateName || "").trim().toLowerCase();
      return candidateName && candidateName === name;
    });
    if (byName) {
      return byName;
    }
  }

  if (demoFallbackCaseId) {
    return activeCases.find((item) => item.id === demoFallbackCaseId) || null;
  }

  return null;
}

export function buildSelfServiceMetrics(tasks = []) {
  const actionNeeded = tasks.filter(
    (task) =>
      task.status !== "completed" &&
      task.status !== "skipped" &&
      task.status !== "blocked"
  ).length;
  const overdue = tasks.filter((task) => isTaskOverdue(task)).length;
  const completed = tasks.filter(
    (task) => task.status === "completed" || task.status === "skipped"
  ).length;
  const dueSoon = tasks.filter((task) => {
    if (task.status === "completed" || task.status === "skipped" || !task.dueDate) {
      return false;
    }
    const due = new Date(task.dueDate);
    if (Number.isNaN(due.getTime())) {
      return false;
    }
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    due.setHours(0, 0, 0, 0);
    const diffDays = Math.round((due - today) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 && diffDays <= 3;
  }).length;
  const progress = computeCaseProgress(tasks);

  return {
    actionNeeded,
    overdue,
    completed,
    dueSoon,
    total: tasks.length,
    readinessPct: progress.pct,
  };
}

export function filterSelfServiceTasksByStatus(tasks, statusFilter) {
  if (!statusFilter || statusFilter === "ALL") {
    return tasks;
  }
  if (statusFilter === "ACTION") {
    return tasks.filter(
      (task) =>
        task.status !== "completed" &&
        task.status !== "skipped" &&
        task.status !== "blocked"
    );
  }
  if (statusFilter === "COMPLETED") {
    return tasks.filter(
      (task) => task.status === "completed" || task.status === "skipped"
    );
  }
  return tasks;
}

export function canSelfServiceCompleteTask(task, allTasks = []) {
  if (!task || task.status === "completed" || task.status === "skipped" || task.status === "blocked") {
    return false;
  }
  const dependencies = resolveTaskDependencies(task, allTasks);
  return dependencies.every((dep) => dep.satisfied);
}

export function getSelfServiceActionLabel(task) {
  if (!task) {
    return "Mark complete";
  }
  const title = (task.title || "").toLowerCase();
  if (title.includes("policy") || title.includes("acknowledgment")) {
    return "Acknowledge & complete";
  }
  if (title.includes("bank") || title.includes("deposit") || title.includes("tax")) {
    return "Submit details";
  }
  if (title.includes("upload") || title.includes("id")) {
    return "Confirm upload";
  }
  if (title.includes("training") || title.includes("security")) {
    return "Complete module";
  }
  return "Mark complete";
}

export function buildTaskActivityTimeline(task) {
  if (Array.isArray(task.activity) && task.activity.length) {
    return task.activity;
  }

  const events = [];
  if (task.createdAt) {
    events.push({ at: task.createdAt, actor: task.owner || "System", action: "Task created" });
  }
  if (task.startedAt) {
    events.push({ at: task.startedAt, actor: task.owner || "System", action: "Work started" });
  }
  if (task.status === "blocked" && task.blockedReason) {
    events.push({
      at: task.blockedAt || task.dueDate,
      actor: task.owner || "System",
      action: `Blocked — ${task.blockedReason}`,
    });
  }
  if (task.completedAt) {
    events.push({
      at: task.completedAt,
      actor: task.completedBy || task.owner || "System",
      action: task.status === "skipped" ? "Marked skipped" : "Marked complete",
    });
  }
  return events;
}
