import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import {
  getEmployeeInitials,
  getProficiencyTone,
  getSkillCategoryMeta,
} from "config/resource-planning.utils";

function ProficiencyMeter({ score, level }) {
  const tone = getProficiencyTone(String(level || "").toUpperCase());
  const pct = Math.max(0, Math.min(100, (score || 0) * 25));
  return (
    <div className="lux-res-card__meter">
      <div className={classNames("lux-res-card__meter-track", `is-${tone}`)}>
        <span style={{ width: `${Math.max(pct, score ? 8 : 0)}%` }} />
      </div>
      <em className={classNames("lux-res-card__level", `is-${tone}`)}>{level}</em>
    </div>
  );
}

export default function SkillsMatrixRegister({ rows, loading }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-res-queue" aria-label="Skills proficiency register">
      <ul className="lux-res-queue__list">
        {rows.map((row) => {
          const categoryMeta = getSkillCategoryMeta(row.skillCategory);
          const proficiencyTone = getProficiencyTone(
            String(row.proficiencyLevel || row.proficiencyLabel || "").toUpperCase()
          );
          const isGap = (row.proficiencyScore || 0) <= 1;
          const initials = getEmployeeInitials(row.employeeName);

          return (
            <li key={row.id}>
              <article
                className={classNames("lux-res-card", `is-tone-${categoryMeta.tone || "violet"}`, {
                  "is-gap": isGap,
                  "is-certified": row.certified,
                })}
              >
                <span className="lux-res-card__accent" aria-hidden="true" />

                <span
                  className={classNames("lux-res-card__avatar", `is-${proficiencyTone}`)}
                  aria-hidden="true"
                >
                  {initials}
                </span>

                <div className="lux-res-card__main">
                  <div className="lux-res-card__title-row">
                    <strong className="lux-res-card__title">{row.employeeName || "—"}</strong>
                    {row.certified ? (
                      <span className="lux-res-card__flag is-green">
                        <i className="fe fe-award" aria-hidden="true" />
                        Certified
                      </span>
                    ) : null}
                    {isGap ? (
                      <span className="lux-res-card__flag is-rose">
                        <i className="fe fe-trending-up" aria-hidden="true" />
                        Upskill
                      </span>
                    ) : null}
                  </div>

                  <div className="lux-res-card__project">
                    <i className={categoryMeta.icon || "fe fe-code"} aria-hidden="true" />
                    <span>
                      <b>{row.skillName}</b>
                      {row.skillCategory ? ` · ${row.skillCategory}` : ""}
                    </span>
                  </div>

                  {row.notes ? <p className="lux-res-card__notes">{row.notes}</p> : null}

                  <div className="lux-res-card__meta">
                    <span className={classNames("lux-res-card__chip", categoryMeta.tone && `is-${categoryMeta.tone}`)}>
                      <i className={categoryMeta.icon || "fe fe-tag"} aria-hidden="true" />
                      {row.skillCategory || "Skill"}
                    </span>
                    <span className="lux-res-card__chip is-count">
                      <i className="fe fe-clock" aria-hidden="true" />
                      {row.yearsExperience != null ? `${row.yearsExperience} yrs` : "—"}
                    </span>
                    <span className="lux-res-card__chip is-muted">
                      <i className="fe fe-calendar" aria-hidden="true" />
                      {row.lastUsedDate ? `Used ${row.lastUsedDate}` : "No last used"}
                    </span>
                    {row.employeeId ? (
                      <Link
                        className="lux-res-card__chip is-link"
                        to={`/people/employees/${row.employeeId}/360`}
                      >
                        <i className="fe fe-user" aria-hidden="true" />
                        Employee 360
                      </Link>
                    ) : null}
                  </div>

                  <ProficiencyMeter score={row.proficiencyScore} level={row.proficiencyLabel} />
                </div>

                <div className="lux-res-card__aside">
                  <span className={classNames("lux-res-card__priority", `is-${proficiencyTone}`)}>
                    {row.proficiencyLabel || "—"}
                  </span>
                  <span className="lux-res-card__status is-slate">
                    {row.yearsExperience != null ? `${row.yearsExperience}y exp` : "Profile"}
                  </span>
                </div>
              </article>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
